-- full_schema.sql — COMPLETE public schema, generated by scripts/backup-schema.mjs
-- ============================================================================
-- Do not hand-edit: regenerate with `npm run backup:schema`.
--
-- WHY: the Supabase organisation is on the FREE plan and the backups endpoint
-- returns an EMPTY list. There are no automated backups of this database. This
-- file is the schema half of the answer; data is NOT in here (see below).
--
-- Contents: 9 extensions · 0 enums · 257 tables ·
-- 1182 constraints · 335 indexes · 613 functions ·
-- 254 triggers · 332 policies · explicit REVOKEs for the closed perimeter.
--
-- WHAT THIS DOES NOT COVER, so nobody mistakes it for a full backup:
--   · no table DATA — tenants, users, documents, conversations are all absent
--   · no auth.users — accounts do not come back from this file
--   · no storage objects, no vault secrets, no edge-function code
--   · no pg_cron schedules
-- Restoring this yields an EMPTY, correctly-shaped, correctly-secured database.
-- ============================================================================

-- ── Extensions ──────────────────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "hypopg" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "index_advisor" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA vault;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA public;

-- ── Enum types ──────────────────────────────────────────────────────────────

-- ── Functions ───────────────────────────────────────────────────────────────
-- BEFORE the tables, and this ordering is load-bearing. Found by running an
-- actual restore, not by reading the file: connectors has
--   CONSTRAINT connectors_base_url_safe_check CHECK (is_safe_external_url(base_url))
-- so a CHECK constraint depends on a function. With functions emitted last the
-- restore died on table 40-odd of 257. The file looked completely fine.
--
-- Functions in turn reference tables that do not exist yet, so body validation
-- is deferred: LANGUAGE sql bodies are parsed at CREATE time unless this is off.
-- pg_dump does the same thing for the same reason.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public._assert_caller_tenant(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- An unauthenticated PostgREST caller is NOT a trusted server caller, even
  -- though both present a NULL auth.uid(). Distinguish them by the request role.
  IF coalesce(
       nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
       '') = 'anon' THEN
    RAISE EXCEPTION 'not_authorized_for_tenant';
  END IF;
  IF auth.uid() IS NULL THEN RETURN; END IF;   -- service role / cron / psql
  IF p_tenant_id IS NULL OR public.auth_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'not_authorized_for_tenant';
  END IF;
END$function$;

CREATE OR REPLACE FUNCTION public._assert_conv_member(p_conversation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select tenant_id into v_tenant from de_conversations where id = p_conversation_id;
  if v_tenant is null then raise exception 'conversation_not_found'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  return v_tenant;
end;
$function$;

CREATE OR REPLACE FUNCTION public.access_permission_level(p_permission text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_permission
    when 'search' then 1
    when 'read' then 2
    when 'ingest' then 3
    when 'write_back' then 4
    else 0
  end;
$function$;

CREATE OR REPLACE FUNCTION public.acknowledge_de_performance_review(p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_performance_reviews;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can acknowledge a review';
  end if;
  update de_performance_reviews set status = 'acknowledged', acknowledged_by = auth.uid(), acknowledged_at = now()
  where id = p_review_id and tenant_id = v_tenant
  returning * into v_row;
  if v_row.id is null then raise exception 'review not found in this workspace'; end if;
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_group_member(p_group_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_group int; v_name text; v_who text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;

  -- THE GUARD THIS FUNCTION EXISTS FOR. Membership confers everything the group
  -- holds, so adding somebody to a group is a grant of that level. Without this
  -- check a knowledge manager adds themselves to any group holding
  -- workspace_admin and has it a second later — laundering straight around
  -- mig 356's escalation guard.
  v_group := public.knowledge_group_max_level(p_group_id);
  IF v_group > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: "%" carries access above your level, so you cannot add people to it', v_name;
  END IF;

  -- The person must be a real, active member of THIS workspace.
  SELECT coalesce(full_name, 'a teammate') INTO v_who FROM profiles
   WHERE user_id = p_user_id AND tenant_id = v_tenant AND coalesce(is_active, true);
  IF v_who IS NULL THEN RAISE EXCEPTION 'that person is not a member of this workspace'; END IF;

  INSERT INTO knowledge_principal_group_members (tenant_id, group_id, user_id, added_by)
  VALUES (v_tenant, p_group_id, p_user_id, auth.uid())
  ON CONFLICT (group_id, user_id) DO NOTHING;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Added %s to the group "%s"', v_who, v_name), 'access_control',
    jsonb_build_object('group_id', p_group_id, 'user_id', p_user_id));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.add_tenant_ip_allowlist_entry(p_tenant_id uuid, p_ip_range text, p_label text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_cidr cidr;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can add an IP range';
  end if;

  begin
    v_cidr := p_ip_range::cidr;
  exception when others then
    raise exception '"%" is not a valid IP address or CIDR range (e.g. 192.168.1.0/24)', p_ip_range;
  end;

  insert into tenant_ip_allowlist_entries (tenant_id, ip_range, label, created_by)
  values (p_tenant_id, v_cidr, coalesce(trim(p_label), ''), auth.uid())
  returning id into v_id;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('IP range added to allowlist: %s', v_cidr),
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_entry_added', 'entry_id', v_id, 'ip_range', v_cidr::text)
  );

  return jsonb_build_object('id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.advance_de_lifecycle(p_de_id uuid, p_to_stage text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_readiness jsonb;
  v_ok boolean;
  v_actor_name text;
  v_expected_from text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can advance an employee''s lifecycle';
  end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_de.lifecycle_status in ('retired', 'archived') then
    raise exception 'this employee is retired — its lifecycle is closed';
  end if;
  if v_de.lifecycle_status = 'paused' then
    raise exception 'this employee is paused — use resume first';
  end if;

  v_expected_from := case p_to_stage
    when 'configured' then 'designed'
    when 'trained'    then 'configured'
    when 'tested'     then 'trained'
    when 'certified'  then 'tested'
    when 'published'  then 'certified'
    when 'assigned'   then 'published'
    when 'active'     then 'assigned'
    else null
  end;
  if v_expected_from is null then
    raise exception 'stage "%" is not reachable through advance (pause/resume/retire have their own controls)', p_to_stage;
  end if;
  if v_de.lifecycle_status <> v_expected_from then
    raise exception 'cannot advance to "%" from "%" — the chain is designed → configured → trained → tested → certified → published → assigned → active', p_to_stage, v_de.lifecycle_status;
  end if;

  v_readiness := compute_de_lifecycle_readiness(p_de_id);
  v_ok := case p_to_stage
    when 'configured' then (v_readiness->'criteria'->'configured'->>'identity_complete')::boolean
    when 'trained'    then (v_readiness->'criteria'->'trained'->>'control_fabric_grant')::boolean
                       and (v_readiness->'criteria'->'trained'->>'knowledge_in_scope')::boolean
                       and (v_readiness->'criteria'->'trained'->>'active_guardrails')::boolean
    when 'tested'     then (v_readiness->'criteria'->'tested'->>'knowledge_embedded')::boolean
    when 'certified'  then (v_readiness->'criteria'->'certified'->>'golden_qa_passed')::boolean
    when 'published'  then (v_readiness->'criteria'->'published'->>'certified_by_human')::boolean
    when 'assigned'   then (v_readiness->'criteria'->'assigned'->>'has_work_channel')::boolean
    when 'active'     then (v_readiness->'criteria'->'active'->>'first_live_execution')::boolean
  end;
  if not coalesce(v_ok, false) then
    return jsonb_build_object('ok', false, 'blocked', true, 'readiness', v_readiness,
      'reason', format('Entry criteria for "%s" are not met yet — see readiness.', p_to_stage));
  end if;

  if p_to_stage = 'certified' and (p_note is null or trim(p_note) = '') then
    raise exception 'certification requires a note stating what was reviewed';
  end if;

  select full_name into v_actor_name from profiles where user_id = auth.uid();

  update digital_employees set
    lifecycle_status = p_to_stage,
    status = case when p_to_stage in ('assigned', 'active') then 'active' else status end,
    updated_at = now()
  where id = p_de_id;

  insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_id, actor_label, note, criteria_snapshot)
  values (v_tenant, p_de_id, v_de.lifecycle_status, p_to_stage, auth.uid(), coalesce(v_actor_name, 'A workspace admin'), p_note, v_readiness);

  -- §9.5 (migration 129): the lifecycle checkpoint also issues the
  -- durable, expiring workspace certification.
  if p_to_stage = 'certified' then
    insert into de_certifications (tenant_id, de_id, cert_type, scope, note, issued_by, issued_by_name, expires_at)
    values (v_tenant, p_de_id, 'workspace', 'Pre-launch lifecycle certification', trim(p_note), auth.uid(),
            coalesce(v_actor_name, 'A workspace admin'), now() + interval '180 days');
  end if;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor_name, 'A workspace admin'), 'human',
    format('%s advanced to %s%s', v_de.name, p_to_stage,
      case when p_note is not null and p_note <> '' then format(' — "%s"', left(p_note, 160)) else '' end),
    'config_change',
    jsonb_build_object('kind', 'lifecycle_advance', 'de_id', p_de_id, 'from', v_de.lifecycle_status, 'to', p_to_stage)
  );

  return jsonb_build_object('ok', true, 'stage', p_to_stage);
end;
$function$;

CREATE OR REPLACE FUNCTION public.ai_apply_change(p_session_id uuid, p_kind text, p_target_id uuid, p_patch jsonb, p_summary text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant  uuid := public.auth_tenant_id();
  v_user    uuid := auth.uid();
  v_before  jsonb;
  v_after   jsonb;
  v_table   text;
  v_target  uuid := p_target_id;
  v_change  uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- The boundary the model cannot argue its way past.
  IF NOT public.ai_change_is_auto_appliable(p_kind) THEN
    RAISE EXCEPTION 'change_kind_requires_human_review: %', p_kind;
  END IF;

  -- Session must belong to this caller (prevents cross-user replay).
  IF p_session_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM ai_sessions s
    WHERE s.id = p_session_id AND s.tenant_id = v_tenant AND s.user_id = v_user
  ) THEN
    RAISE EXCEPTION 'session_not_found';
  END IF;

  IF p_kind = 'knowledge.create' THEN
    v_table := 'knowledge_docs';
    INSERT INTO knowledge_docs (tenant_id, title, content, source, tags, visibility)
    VALUES (
      v_tenant,
      coalesce(p_patch->>'title', 'Untitled'),
      coalesce(p_patch->>'content', ''),
      'ai_assistant',
      CASE WHEN jsonb_exists(p_patch, 'tags')
           THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'tags'))
           ELSE '{}'::text[] END,
      'tenant'
    )
    RETURNING id, to_jsonb(knowledge_docs.*) INTO v_target, v_after;

  ELSIF p_kind = 'knowledge.edit' THEN
    v_table := 'knowledge_docs';
    SELECT to_jsonb(k.*) INTO v_before FROM knowledge_docs k
    WHERE k.id = v_target AND k.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'knowledge_doc_not_found'; END IF;
    UPDATE knowledge_docs SET
      title   = coalesce(p_patch->>'title', title),
      content = coalesce(p_patch->>'content', content),
      updated_at = now()
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(knowledge_docs.*) INTO v_after;

  ELSIF p_kind = 'playbook.draft_steps' THEN
    v_table := 'playbook_definitions';
    SELECT to_jsonb(d.*) INTO v_before FROM playbook_definitions d
    WHERE d.id = v_target AND d.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'playbook_not_found'; END IF;
    -- Draft-only: a published playbook is customer-affecting, so the
    -- assistant may never overwrite one in place.
    IF (v_before->>'status') = 'published' THEN
      RAISE EXCEPTION 'published_playbook_requires_human_review';
    END IF;
    UPDATE playbook_definitions SET
      steps = coalesce(p_patch->'steps', steps),
      name  = coalesce(p_patch->>'name', name),
      description = coalesce(p_patch->>'description', description),
      updated_at = now()
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(playbook_definitions.*) INTO v_after;

  ELSIF p_kind = 'de.describe' THEN
    v_table := 'digital_employees';
    SELECT to_jsonb(d.*) INTO v_before FROM digital_employees d
    WHERE d.id = v_target AND d.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'de_not_found'; END IF;
    -- Identity/description ONLY. Deliberately cannot touch trust level,
    -- reply mode, lifecycle, model, or any guardrail-adjacent column.
    UPDATE digital_employees SET
      name              = coalesce(p_patch->>'name', name),
      persona_name      = coalesce(p_patch->>'persona_name', persona_name),
      description       = coalesce(p_patch->>'description', description),
      purpose_statement = coalesce(p_patch->>'purpose_statement', purpose_statement)
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(digital_employees.*) INTO v_after;
  END IF;

  INSERT INTO ai_change_log (
    tenant_id, session_id, change_kind, target_table, target_id,
    summary, before_state, after_state, applied_by
  ) VALUES (
    v_tenant, p_session_id, p_kind, v_table, v_target,
    coalesce(nullif(p_summary, ''), p_kind), v_before, v_after, v_user
  ) RETURNING id INTO v_change;

  -- Auto-applied changes are still audited like everything else.
  PERFORM append_audit_event(
    v_tenant, 'Workspace Assistant', 'de',
    format('Auto-applied: %s', coalesce(nullif(p_summary, ''), p_kind)),
    'config_change',
    jsonb_build_object('change_id', v_change, 'kind', p_kind, 'target_id', v_target, 'undoable_until', now() + interval '120 hours')
  );

  RETURN jsonb_build_object(
    'ok', true, 'change_id', v_change, 'target_id', v_target,
    'undoable_until', (now() + interval '120 hours')::text
  );
END$function$;

CREATE OR REPLACE FUNCTION public.ai_change_is_auto_appliable(p_kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p_kind IN (
    'knowledge.create',        -- add a knowledge document
    'knowledge.edit',          -- edit a knowledge document's title/content
    'playbook.draft_steps',    -- save DRAFT steps (never publish)
    'de.describe'              -- name / description / purpose / persona only
  );
$function$;

CREATE OR REPLACE FUNCTION public.ai_list_undoable(p_limit integer DEFAULT 20)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(json_agg(row_to_json(x)), '[]'::json) FROM (
    SELECT id, change_kind, summary, target_table, target_id,
           applied_at::text, expires_at::text
    FROM ai_change_log
    WHERE tenant_id = public.auth_tenant_id()
      AND undone_at IS NULL AND now() < expires_at
    ORDER BY applied_at DESC
    LIMIT greatest(1, least(p_limit, 100))
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.ai_undo_change(p_change_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_user   uuid := auth.uid();
  v_row    ai_change_log;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_row FROM ai_change_log
  WHERE id = p_change_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'change_not_found'; END IF;
  IF v_row.undone_at IS NOT NULL THEN RAISE EXCEPTION 'already_undone'; END IF;
  IF now() > v_row.expires_at THEN RAISE EXCEPTION 'undo_window_expired'; END IF;

  IF v_row.before_state IS NULL THEN
    -- The change created the row; undo = remove it.
    IF v_row.target_table = 'knowledge_docs' THEN
      DELETE FROM knowledge_docs WHERE id = v_row.target_id AND tenant_id = v_tenant;
    END IF;
  ELSIF v_row.target_table = 'knowledge_docs' THEN
    UPDATE knowledge_docs SET
      title = v_row.before_state->>'title',
      content = v_row.before_state->>'content',
      updated_at = now()
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  ELSIF v_row.target_table = 'playbook_definitions' THEN
    UPDATE playbook_definitions SET
      steps = v_row.before_state->'steps',
      name = v_row.before_state->>'name',
      description = v_row.before_state->>'description',
      updated_at = now()
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  ELSIF v_row.target_table = 'digital_employees' THEN
    UPDATE digital_employees SET
      name = v_row.before_state->>'name',
      persona_name = v_row.before_state->>'persona_name',
      description = v_row.before_state->>'description',
      purpose_statement = v_row.before_state->>'purpose_statement'
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  END IF;

  UPDATE ai_change_log SET undone_at = now(), undone_by = v_user WHERE id = p_change_id;

  PERFORM append_audit_event(
    v_tenant, 'Workspace Assistant', 'human',
    format('Undone: %s', v_row.summary), 'config_change',
    jsonb_build_object('change_id', p_change_id, 'kind', v_row.change_kind)
  );

  RETURN jsonb_build_object('ok', true, 'restored', v_row.target_table);
END$function$;

CREATE OR REPLACE FUNCTION public.alert_cert_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_fp text; v_pass role_certifications; v_name text; v_fresh boolean;
begin
  select * into v_pass from role_certifications
    where de_id = NEW.id and status = 'passed'
    order by evaluated_at desc nulls last, created_at desc limit 1;
  if v_pass.id is null then return NEW; end if;

  v_fp := public.de_config_fingerprint_row(NEW);
  -- Same predicate as the gate: fresh iff ANY passing cert matches.
  v_fresh := exists (select 1 from role_certifications c
                      where c.de_id = NEW.id and c.status = 'passed'
                        and c.config_fingerprint is not distinct from v_fp);
  if v_fresh then
    if v_pass.stale_alerted then
      update role_certifications set stale_alerted = false where id = v_pass.id;
    end if;
    return NEW;
  end if;
  if v_pass.stale_alerted then return NEW; end if;

  v_name := coalesce(NEW.persona_name, NEW.name, 'this employee');
  insert into activity_events (tenant_id, actor, actor_type, event_type, text, confidence)
  values (NEW.tenant_id, coalesce(NEW.persona_name, NEW.name, 'DE'), 'system', 'certification_stale',
    format('Configuration changed for %s after it was certified (%s%% on %s). Its certification is now STALE and no longer vouches for the current setup — re-run its evaluation or simulation and re-certify before relying on it or promoting it again.',
           v_name, v_pass.score_pct, coalesce(v_pass.evaluated_at::date::text, 'a prior run')),
    coalesce(v_pass.score_pct, 0));
  update role_certifications set stale_alerted = true where id = v_pass.id;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.analytics_action_volume(p_tenant_id uuid, p_days integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'window_days', p_days,
    'total', (select count(*) from action_executions where tenant_id = p_tenant_id
                and created_at >= now() - make_interval(days => greatest(1, p_days))),
    'by_decision', coalesce((select jsonb_object_agg(decision, c) from
       (select decision, count(*) c from action_executions where tenant_id = p_tenant_id
          and created_at >= now() - make_interval(days => greatest(1, p_days)) group by decision) d), '{}'::jsonb)
  );
$function$;

CREATE OR REPLACE FUNCTION public.analytics_de_workload(p_tenant_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'objectives_by_status', coalesce((select jsonb_object_agg(status, c) from
       (select status, count(*) c from de_objectives where tenant_id = p_tenant_id and de_id = p_de_id group by status) s), '{}'::jsonb),
    'work_items_by_status', coalesce((select jsonb_object_agg(status, c) from
       (select status, count(*) c from de_work_items where tenant_id = p_tenant_id and de_id = p_de_id group by status) w), '{}'::jsonb)
  );
$function$;

CREATE OR REPLACE FUNCTION public.append_audit_event_internal(p_tenant_id uuid, p_actor text, p_actor_type text, p_action text, p_category text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_prev text;
  v_now  timestamptz := clock_timestamp();
begin
  perform pg_advisory_xact_lock(hashtext('audit_' || p_tenant_id::text));
  select hash into v_prev from audit_events
    where tenant_id = p_tenant_id
    order by created_at desc, id desc limit 1;
  v_prev := coalesce(v_prev, '');
  insert into audit_events (tenant_id, actor, actor_type, action, category, detail, prev_hash, hash, created_at)
  values (p_tenant_id, p_actor, p_actor_type, p_action, p_category, coalesce(p_detail, '{}'::jsonb), v_prev,
          encode(digest(v_prev || p_tenant_id::text || coalesce(p_action, '') ||
                        coalesce(p_detail::text, '{}') || v_now::text, 'sha256'), 'hex'),
          v_now);
end;
$function$;

CREATE OR REPLACE FUNCTION public.append_browser_task_step(p_task_id uuid, p_step jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  UPDATE computer_use_tasks
     SET status = CASE WHEN status = 'claimed' THEN 'running' ELSE status END,
         audit = coalesce(audit, '[]'::jsonb) || jsonb_build_array(coalesce(p_step, '{}'::jsonb)),
         updated_at = now()
   WHERE id = p_task_id AND status IN ('claimed','running');
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_account_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r account_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM account_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind'))
    RETURNING id INTO v_act;

  ELSIF r.op = 'set_next_step' THEN
    UPDATE customer_accounts
       SET attributes = coalesce(attributes,'{}'::jsonb)
             || jsonb_build_object('next_step', r.composed->>'next_step', 'next_step_date', r.composed->>'next_step_date'),
           updated_at = now()
     WHERE id = r.account_id AND tenant_id = r.tenant_id;
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;

  ELSIF r.op = 'update_status' THEN
    SELECT status INTO v_before FROM customer_accounts WHERE id = r.account_id AND tenant_id = r.tenant_id;
    UPDATE customer_accounts SET status = r.composed->>'to_status', updated_at = now()
     WHERE id = r.account_id AND tenant_id = r.tenant_id;
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'stage_changed',
            'Status ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_status'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_status')) RETURNING id INTO v_act;
  END IF;

  UPDATE account_writeback_requests
     SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act)
   WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_config_template(p_tenant_id uuid, p_template_key text)
 RETURNS TABLE(type text, id uuid, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY SELECT NULL::TEXT, NULL::UUID, NULL::TEXT WHERE FALSE;
END$function$;

CREATE OR REPLACE FUNCTION public.apply_continuity_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r continuity_writeback_requests; c continuity_cases;
  v_before text; v_actor text; v_terminal boolean; v_category text;
BEGIN
  SELECT * INTO r FROM continuity_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;
  SELECT * INTO c FROM continuity_cases WHERE objective_id = r.objective_id;
  IF c.objective_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'case_not_found'); END IF;
  v_actor := CASE WHEN r.de_id IS NOT NULL THEN 'de' ELSE 'human' END;

  IF r.op = 'log_activity' THEN
    INSERT INTO continuity_case_events (tenant_id, objective_id, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, c.motion, v_actor, r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind'));

  ELSIF r.op = 'set_next_step' THEN
    UPDATE continuity_cases
       SET next_step = r.composed->>'next_step',
           next_step_date = nullif(r.composed->>'next_step_date','')::date,
           updated_at = now()
     WHERE objective_id = r.objective_id;
    INSERT INTO continuity_case_events (tenant_id, objective_id, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, c.motion, v_actor, 'Next step: ' || (r.composed->>'next_step'), r.composed);

  ELSIF r.op = 'advance_stage' THEN
    v_before := c.stage_key;
    SELECT is_terminal, category INTO v_terminal, v_category
      FROM continuity_stage_config WHERE tenant_id = r.tenant_id AND stage_key = r.composed->>'to_stage';
    UPDATE continuity_cases
       SET stage_key = r.composed->>'to_stage',
           outcome = CASE WHEN coalesce(v_terminal,false) THEN v_category ELSE outcome END,
           updated_at = now()
     WHERE objective_id = r.objective_id;
    INSERT INTO continuity_case_events (tenant_id, objective_id, from_stage, to_stage, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, v_before, r.composed->>'to_stage', c.motion, v_actor,
            'Stage ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_stage'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage', 'terminal', coalesce(v_terminal,false)));
  END IF;

  UPDATE continuity_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('op', r.op) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'op', r.op);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_entity_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_am workforce_entity_amendments; v_cfg jsonb; begin
  select * into v_am from workforce_entity_amendments where id = p_id;
  if not found then raise exception 'amendment not found'; end if;
  if v_am.status = 'applied' then return jsonb_build_object('ok', true, 'already', true); end if;
  v_cfg := v_am.proposed_config;

  if v_am.entity_kind = 'de' then
    update digital_employees set
      persona_name = coalesce(v_cfg->>'persona_name', persona_name),
      description = coalesce(v_cfg->>'description', description),
      purpose_statement = coalesce(v_cfg->>'purpose_statement', purpose_statement)
    where id = v_am.entity_id and tenant_id = v_am.tenant_id;
  else
    -- specialist entities are digital_employees now; charter is jsonb {mission}
    update digital_employees
      set charter = jsonb_set(coalesce(charter, '{}'::jsonb), '{mission}', to_jsonb(coalesce(v_cfg->>'charter', charter->>'mission')))
      where id = v_am.entity_id and tenant_id = v_am.tenant_id and is_specialist = true;
  end if;

  update workforce_entity_amendments set status = 'applied' where id = p_id;
  begin perform append_audit_event(v_am.tenant_id, 'Practice Engine', 'de',
      format('%s amendment applied — improved config landed', v_am.entity_kind),
      'config_change', jsonb_build_object('kind','entity_amendment_applied','amendment_id',p_id,'entity_kind',v_am.entity_kind,'entity_id',v_am.entity_id));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'entity_id', v_am.entity_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.apply_improvement(p_improvement_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp de_improvements; v_task_status text; v_doc uuid; v_arch text;
begin
  select * into imp from de_improvements where id = p_improvement_id for update;
  if imp.id is null then raise exception 'improvement not found'; end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = imp.tenant_id)) then
    raise exception 'not authorized';
  end if;
  if imp.status = 'applied' then return imp.applied_doc_id; end if;
  if imp.status = 'rejected' then raise exception 'improvement was rejected'; end if;

  if imp.human_task_id is null then
    raise exception 'improvement has no review task — call create_improvement_review first';
  end if;
  select status into v_task_status from human_tasks where id = imp.human_task_id;
  if v_task_status is distinct from 'approved' then
    raise exception 'improvement is not human-approved (review task status: %) — a proposed fix can only be published after explicit approval', coalesce(v_task_status, 'missing');
  end if;

  -- T2.2: publish at role scope when the human chose it AND the DE's archetype
  -- resolves; otherwise the unchanged de-scoped path (today's behavior).
  v_arch := case when imp.publish_scope = 'role' then resolve_de_archetype(imp.de_id) end;
  if imp.publish_scope = 'role' and v_arch is not null then
    insert into knowledge_docs (tenant_id, title, content, source, visibility, is_current, tags, share_archetype_key)
    values (imp.tenant_id, imp.proposed_title, imp.proposed_content, 'self_improvement', 'role', true,
            array['self-improvement','team-learning'], v_arch)
    returning id into v_doc;
  else
    insert into knowledge_docs (tenant_id, title, content, source, visibility, is_current, tags)
    values (imp.tenant_id, imp.proposed_title, imp.proposed_content, 'self_improvement', 'scoped', true,
            array['self-improvement'])
    returning id into v_doc;
    insert into knowledge_doc_scopes (tenant_id, doc_id, subject_kind, subject_id)
    values (imp.tenant_id, v_doc, 'de', imp.de_id);
  end if;

  update de_improvements set status = 'applied', applied_doc_id = v_doc, updated_at = now()
   where id = p_improvement_id;

  insert into activity_events (tenant_id, actor, actor_type, event_type, text, confidence)
  select imp.tenant_id, coalesce(d.persona_name, d.name, 'DE'), 'system', 'config_change',
    format('Approved self-improvement published: "%s" (%s). Proposed from a failed answer, verified by replay, human-approved.',
           imp.proposed_title, case when imp.publish_scope = 'role' and v_arch is not null then 'shared with all '||v_arch||' employees' else 'scoped to '||coalesce(d.persona_name, d.name, 'this employee') end),
    coalesce((imp.replay->'after'->>'score')::numeric, 0)
  from digital_employees d where d.id = imp.de_id;

  return v_doc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_invoice_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r invoice_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM invoice_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind')) RETURNING id INTO v_act;
  ELSIF r.op = 'set_next_step' THEN
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;
  ELSIF r.op = 'update_status' THEN
    SELECT status INTO v_before FROM invoices WHERE id = r.invoice_id AND tenant_id = r.tenant_id;
    UPDATE invoices SET status = r.composed->>'to_status' WHERE id = r.invoice_id AND tenant_id = r.tenant_id;
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'status_changed',
            'Status ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_status'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_status')) RETURNING id INTO v_act;
  END IF;

  UPDATE invoice_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_knowledge_revision(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_req           record;
  v_new_doc_id    uuid;
  v_actor_name    text;
  v_rep_inquiry   text;
  v_cluster       record;
begin
  select * into v_req from knowledge_revision_requests where id = p_request_id;
  if v_req.id is null then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;
  if v_req.status <> 'pending_approval' then
    return jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_req.status);
  end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_req.tenant_id then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select coalesce(full_name, 'A reviewer') into v_actor_name from profiles where user_id = v_user;
  v_actor_name := coalesce(v_actor_name, 'A reviewer');

  insert into knowledge_docs (
    tenant_id, title, content, source, tags, previous_version_id, is_current, visibility, lifecycle_status
  )
  select
    v_req.tenant_id, v_req.proposed_title, v_req.proposed_body_md, 'paste',
    coalesce((select tags from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), '{}'),
    v_req.source_doc_id, true,
    coalesce((select visibility from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), 'tenant'),
    -- 355: a revision of a draft stays a draft. Otherwise "propose an edit"
    -- becomes a way to publish without passing the publisher gate.
    coalesce((select lifecycle_status from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), 'published')
  returning id into v_new_doc_id;

  if v_req.source_doc_id is not null then
    update knowledge_docs set is_current = false where id = v_req.source_doc_id and tenant_id = v_req.tenant_id;
  end if;

  update knowledge_revision_requests
    set status = 'applied', decided_by = v_user, decided_at = now(), applied_doc_id = v_new_doc_id
    where id = p_request_id;

  perform append_audit_event(
    v_req.tenant_id, v_actor_name, case when v_user is null then 'system' else 'human' end,
    v_actor_name || ' approved and applied a knowledge revision — "' || v_req.proposed_title || '"',
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_applied', 'revision_request_id', p_request_id,
      'new_doc_id', v_new_doc_id, 'previous_doc_id', v_req.source_doc_id)
  );

  update knowledge_gap_clusters
  set status = 'resolved', fix_applied_at = now(), updated_at = now()
  where revision_request_id = p_request_id and status = 'revision_requested';

  -- Ledger-2B: seed the golden exam from the resolved gap — the cluster's
  -- representative question becomes an INACTIVE golden_qa row (founder
  -- reviews expected fragments and activates it). Dedup on exact question.
  select c.*, er.inquiry into v_cluster
  from knowledge_gap_clusters c
  left join evidence_runs er on er.id = c.representative_run_id
  where c.revision_request_id = p_request_id
  limit 1;
  v_rep_inquiry := v_cluster.inquiry;
  if v_rep_inquiry is not null and length(btrim(v_rep_inquiry)) >= 8 then
    insert into golden_qa (tenant_id, question, expected_fragments, min_confidence, category, active)
    select v_req.tenant_id, btrim(v_rep_inquiry), ARRAY[v_req.proposed_title], 60,
           coalesce(v_cluster.category, 'support'), false
    where not exists (
      select 1 from golden_qa g
      where g.tenant_id = v_req.tenant_id and g.question = btrim(v_rep_inquiry)
    );
  end if;

  return jsonb_build_object('ok', true, 'new_doc_id', v_new_doc_id, 'previous_doc_id', v_req.source_doc_id);
end $function$;

CREATE OR REPLACE FUNCTION public.apply_onboarding_verification(p_project_id uuid, p_key text, p_verified boolean, p_detail text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_old       text;
  v_task_id   uuid;
  v_acct_name text;
  v_completed boolean := false;
  v_signoff   boolean;
begin
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if v_proj.status <> 'active' then return jsonb_build_object('error', 'project_not_active'); end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = p_key limit 1;
  if v_def is null or v_def->'verify' is null then
    return jsonb_build_object('error', 'item_not_verifiable');
  end if;
  v_signoff := coalesce((v_def->>'requires_signoff')::boolean, false);

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'key' = p_key then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_state_missing'); end if;
  v_old := v_item->>'status';

  if v_old in ('done', 'signed_off') then
    -- Already complete (by whatever means) — record the check for the
    -- audit trail but don't re-run completion side effects.
    v_item := v_item || jsonb_build_object(
      'last_check_at', now(), 'last_check_result', case when p_verified then 'verified' else 'not_yet' end,
      'verify_detail', left(coalesce(p_detail, ''), 300));
    update onboarding_projects set items_state = jsonb_set(items_state, array[v_idx::text], v_item) where id = p_project_id;
    return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', false, 'already_complete', true);
  end if;

  if not p_verified then
    v_item := v_item || jsonb_build_object(
      'last_check_at', now(), 'last_check_result', 'not_yet',
      'verify_detail', left(coalesce(p_detail, ''), 300));
    update onboarding_projects set items_state = jsonb_set(items_state, array[v_idx::text], v_item) where id = p_project_id;
    return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', false, 'verified', false);
  end if;

  -- Verified true: same completion shape as update_onboarding_item's
  -- done path, attributed to System rather than a human.
  v_item := v_item || jsonb_build_object(
    'status', 'done', 'done_at', now(),
    'verified_by', 'system', 'verified_at', now(),
    'last_check_at', now(), 'last_check_result', 'verified',
    'verify_detail', left(coalesce(p_detail, ''), 300));

  if v_signoff then
    insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
    values (v_proj.tenant_id, 'review_gate',
            format('Onboarding sign-off — %s · %s', v_def->>'label', v_proj.name),
            format('Item "%s" was CONNECTOR-VERIFIED (%s) and needs a human sign-off before the project can complete.', v_def->>'label', left(coalesce(p_detail, ''), 200)),
            'system', 'onboarding_projects', p_project_id)
    returning id into v_task_id;
    v_item := v_item || jsonb_build_object('signoff_task_id', v_task_id);
  end if;

  select name into v_acct_name from customer_accounts where id = v_proj.account_id;
  insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
  values (v_proj.tenant_id, v_proj.account_id, 'System', 'system', 'resolved',
          format('Onboarding — %s: connector-verified done%s (%s) — %s', v_def->>'label',
                 case when v_task_id is not null then ' · awaiting sign-off' else '' end,
                 coalesce(v_acct_name, v_proj.name), left(coalesce(p_detail, ''), 160)));

  perform append_audit_event_internal(
    v_proj.tenant_id, 'System', 'system',
    format('Onboarding item connector-verified — %s (%s): %s', v_def->>'label', v_proj.name, left(coalesce(p_detail, ''), 200)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_verify', 'project_id', p_project_id, 'item_key', p_key,
                       'detail', p_detail, 'signoff_task_id', v_task_id));

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = p_project_id;

  if not v_signoff then
    v_completed := onboarding_check_complete(p_project_id);
  end if;

  return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', true,
                            'verified', true, 'signoff_task_id', v_task_id, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_opportunity_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r opportunity_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM opportunity_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind')) RETURNING id INTO v_act;
  ELSIF r.op = 'set_next_step' THEN
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;
  ELSIF r.op = 'update_stage' THEN
    SELECT stage INTO v_before FROM opportunities WHERE id = r.opportunity_id AND tenant_id = r.tenant_id;
    UPDATE opportunities SET stage = r.composed->>'to_stage', updated_at = now(),
           stage_history = coalesce(stage_history,'[]'::jsonb) || jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage', 'at', now())
     WHERE id = r.opportunity_id AND tenant_id = r.tenant_id;
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'stage_changed',
            'Stage ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_stage'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage')) RETURNING id INTO v_act;
  END IF;

  UPDATE opportunity_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_playbook_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_am playbook_amendments; begin
  select * into v_am from playbook_amendments where id = p_id;
  if not found then raise exception 'amendment not found'; end if;
  if v_am.status = 'applied' then return jsonb_build_object('ok', true, 'already', true); end if;
  update playbook_definitions set steps = v_am.proposed_steps, status = 'draft'
    where id = v_am.definition_id and tenant_id = v_am.tenant_id;
  update playbook_amendments set status = 'applied' where id = p_id;
  begin
    perform append_audit_event(v_am.tenant_id, 'Practice Engine', 'de',
      'Playbook amendment applied to draft — ready to review & publish', 'config_change',
      jsonb_build_object('kind','playbook_amendment_applied','amendment_id',p_id,'definition_id',v_am.definition_id));
  exception when others then null;
  end;
  return jsonb_build_object('ok', true, 'definition_id', v_am.definition_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.apply_trust_promotion(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy    trust_policies;
  v_evidence  jsonb;
  v_new       integer;
  v_label     text;
  v_is_active boolean;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected';
  end if;

  select * into v_policy from trust_policies where pending_task_id = p_task_id;
  if not found then
    return jsonb_build_object('applied', false, 'reason', 'no_pending_policy');
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() and tenant_id = v_policy.tenant_id;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;

  v_label := replace(v_policy.action_category, '_', ' ');

  if p_decision = 'rejected' then
    update trust_policies
    set pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
    where id = v_policy.id;
    perform append_audit_event(
      v_policy.tenant_id, 'You', 'human',
      format('Trust promotion rejected — %s stays at level %s', v_label, v_policy.current_level),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_rejected', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'level', v_policy.current_level,
        'task_id', p_task_id, 'decided_by', auth.uid())
    );
    return jsonb_build_object('applied', false, 'reason', 'rejected');
  end if;

  -- Self-approval block: the requester cannot approve their own promotion.
  if auth.uid() is not null and v_policy.requested_by is not null and auth.uid() = v_policy.requested_by then
    perform append_audit_event(
      v_policy.tenant_id, 'Trust engine', 'system',
      format('Trust promotion blocked — requester cannot approve their own request (%s)', v_label),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_blocked_self_approval', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'task_id', p_task_id, 'user_id', auth.uid())
    );
    raise exception 'the requester cannot approve their own promotion — a different teammate must approve';
  end if;

  -- Stale-check: evidence could have regressed since the request.
  v_evidence := trust_evidence_for(v_policy);
  if not coalesce((v_evidence->>'eligible')::boolean, false) then
    update trust_policies
    set pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
    where id = v_policy.id;
    perform append_audit_event(
      v_policy.tenant_id, 'Trust engine', 'system',
      format('Trust promotion rejected as stale — %s evidence regressed since the request', v_label),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_stale', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'task_id', p_task_id,
        'evidence_at_request', v_policy.pending_evidence, 'evidence_at_apply', v_evidence)
    );
    raise exception 'evidence regressed since the request — promotion rejected as stale';
  end if;

  v_new := least(v_policy.current_level + 1, 3);
  -- GI-3: scope the dial write to THIS employee (v_policy.de_id) — a NULL de_id
  -- keeps the historical tenant-wide behavior for tenant-scoped policies.
  perform trust_apply_level(v_policy.tenant_id, v_policy.action_category, v_new, auth.uid(), v_policy.source_category, v_policy.de_id);

  update trust_policies
  set current_level = v_new,
      pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
  where id = v_policy.id;

  perform append_audit_event(
    v_policy.tenant_id, 'You', 'human',
    format('Trust promoted — %s level %s → %s (evidence re-verified at apply time; still capped by guardrails)',
      v_label, v_policy.current_level, v_new),
    'config_change',
    jsonb_build_object('kind', 'trust_promoted', 'policy_id', v_policy.id,
      'action_category', v_policy.action_category, 'de_id', v_policy.de_id,
      'from_level', v_policy.current_level,
      'to_level', v_new, 'task_id', p_task_id, 'approved_by', auth.uid(),
      'requested_by', v_policy.requested_by, 'evidence', v_evidence,
      'dial_settings', trust_level_settings(v_policy.action_category, v_new),
      'composition', 'autonomy_narrows_within_guardrails')
  );

  return jsonb_build_object('applied', true, 'new_level', v_new);
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_draft(p_draft_id uuid, p_edited_content text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE draft_responses
  SET
    status = 'approved',
    draft_content = COALESCE(p_edited_content, draft_content),
    edited_content = p_edited_content,
    approved_at = now(),
    approved_by = v_user_id
  WHERE draft_id = p_draft_id
    AND tenant_id = current_setting('app.current_tenant_id')::uuid;

  RETURN json_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_draft_reply(p_message_id uuid, p_edited_content text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_conv uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select tenant_id, conversation_id into v_tenant, v_conv
  from de_messages where id = p_message_id and delivery = 'draft_pending';
  if v_tenant is null then raise exception 'not_a_pending_draft'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  update de_messages
    set delivery = 'sent', escalated = false,
        content = coalesce(nullif(trim(p_edited_content), ''), content)
  where id = p_message_id;
  update de_conversations set owner_user_id = coalesce(owner_user_id, auth.uid()), status = 'human_owned', last_message_at = now()
  where id = v_conv;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_learned_behavior(p_cluster_id uuid, p_final_pattern text DEFAULT NULL::text, p_final_threshold bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_cluster       record;
  v_rule_id       uuid;
  v_pattern       text;
begin
  select * into v_cluster from de_learned_behavior_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'proposed' then
    return jsonb_build_object('ok', false, 'error', 'not_proposed');
  end if;

  select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
  if v_caller_tenant is distinct from v_cluster.tenant_id then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;
  if not v_is_active then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  if v_cluster.verdict_type = 'correction' then
    v_pattern := coalesce(p_final_pattern, v_cluster.proposed_rule->>'suggested_pattern');
    if coalesce(btrim(v_pattern), '') = '' then
      return jsonb_build_object('ok', false, 'error', 'pattern_required');
    end if;
    insert into guardrail_rules (tenant_id, rule, rule_type, pattern, severity, active, created_by)
    values (
      v_cluster.tenant_id,
      format('Learned behavior — %s', left(v_pattern, 60)),
      coalesce(v_cluster.proposed_rule->>'rule_type', 'blocked_phrase'),
      v_pattern, 'warning', true, v_user
    )
    returning id into v_rule_id;
  else
    v_rule_id := v_cluster.guardrail_rule_id;
    if v_rule_id is null then
      return jsonb_build_object('ok', false, 'error', 'no_target_rule');
    end if;
    if p_final_threshold is not null then
      update guardrail_rules set threshold = p_final_threshold, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    elsif p_final_pattern is not null then
      update guardrail_rules set pattern = p_final_pattern, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    else
      -- No override given: the evidence says this rule is too strict for
      -- this whole pattern — the honest default is to deactivate it
      -- rather than silently leave it exactly as-is (which would make
      -- "approve" a no-op).
      update guardrail_rules set active = false, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    end if;
  end if;

  update de_learned_behavior_clusters
  set status = 'resolved', fix_applied_at = now(), resulting_guardrail_rule_id = v_rule_id, updated_at = now()
  where id = p_cluster_id;

  if v_cluster.human_task_id is not null then
    update human_tasks set status = 'approved', decided_by = v_user, decided_at = now() where id = v_cluster.human_task_id;
  end if;

  perform append_audit_event(
    v_cluster.tenant_id, coalesce((select full_name from profiles where user_id = v_user), 'A reviewer'), 'human',
    format('Approved a learned behavior (%s) — %s guardrail rule %s', v_cluster.verdict_type,
      case when v_cluster.verdict_type = 'correction' then 'created' else 'updated' end, v_rule_id),
    'config_change',
    jsonb_build_object('kind', 'learned_behavior_approved', 'cluster_id', p_cluster_id, 'guardrail_rule_id', v_rule_id)
  );

  return jsonb_build_object('ok', true, 'guardrail_rule_id', v_rule_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_subtenant_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req      tenant_provisioning_requests;
  v_slug     text;
  v_base_slug text;
  v_suffix   int := 0;
  v_tenant   tenants;
  v_requester_tenant uuid;
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may approve a tenant provisioning request';
  end if;

  select * into v_req from tenant_provisioning_requests where id = p_request_id for update;
  if not found then
    raise exception 'provisioning request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request has already been decided (status=%)', v_req.status;
  end if;

  v_base_slug := lower(regexp_replace(btrim(v_req.proposed_name), '[^a-zA-Z0-9]+', '-', 'g'));
  v_base_slug := trim(both '-' from v_base_slug);
  if coalesce(v_base_slug, '') = '' then
    v_base_slug := 'org';
  end if;
  v_slug := v_base_slug;
  while exists (select 1 from tenants where slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := v_base_slug || '-' || v_suffix::text;
  end loop;

  insert into tenants (name, slug, industry, plan, status, settings, parent_tenant_id)
  values (v_req.proposed_name, v_slug, nullif(btrim(coalesce(v_req.proposed_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, v_req.proposed_parent_tenant_id)
  returning * into v_tenant;

  update tenant_provisioning_requests
  set status = 'approved', reviewed_by = auth.uid(), decided_at = now(), created_tenant_id = v_tenant.id
  where id = p_request_id;

  select tenant_id into v_requester_tenant from profiles where user_id = v_req.requested_by_user_id;
  if v_requester_tenant is null then
    update profiles
    set tenant_id = v_tenant.id, role = 'tenant_owner', updated_at = now()
    where user_id = v_req.requested_by_user_id and tenant_id is null;
  end if;

  -- Console-approved tenants previously got NO provisioning at all —
  -- no starter DEs, no playbooks, nothing. Run the same baseline
  -- contract the self-serve signup path runs.
  perform provision_tenant_baseline_internal(v_tenant.id);

  if v_req.proposed_parent_tenant_id is not null and exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_req.proposed_parent_tenant_id
  ) then
    perform append_audit_event(
      v_req.proposed_parent_tenant_id, 'Platform admin', 'human',
      format('Sub-tenant "%s" approved and created (request %s, new tenant id %s)', v_tenant.name, p_request_id, v_tenant.id),
      'config_change',
      jsonb_build_object('kind', 'tenant_provisioning_approved', 'request_id', p_request_id,
        'tenant_id', v_tenant.id, 'parent_tenant_id', v_req.proposed_parent_tenant_id,
        'approved_by', auth.uid(), 'requested_by', v_req.requested_by_user_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'tenant_id', v_tenant.id, 'slug', v_tenant.slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.archive_knowledge_collection(p_id uuid, p_archived boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_docs int; v_children int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF knowledge_my_admin_level(p_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: archiving requires knowledge manager';
  END IF;

  SELECT count(DISTINCT doc_id) INTO v_docs FROM knowledge_doc_access_paths WHERE collection_id = p_id;
  SELECT count(*) INTO v_children FROM knowledge_collections WHERE parent_id = p_id AND archived_at IS NULL;

  UPDATE knowledge_collections
     SET archived_at = CASE WHEN p_archived THEN now() ELSE NULL END, updated_at = now()
   WHERE id = p_id;

  -- The documents are untouched — say so, because "archive" reads as "delete"
  -- to most people and this one genuinely is not.
  RETURN jsonb_build_object('ok', true, 'archived', p_archived,
                            'documents_kept', v_docs, 'child_collections', v_children);
END $function$;

CREATE OR REPLACE FUNCTION public.archive_workforce_team(p_team_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_team workforce_teams;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can manage workforce teams';
  end if;
  update workforce_teams set status = 'archived', updated_at = now()
  where id = p_team_id and tenant_id = v_tenant
  returning * into v_team;
  if v_team.id is null then raise exception 'team not found in this workspace'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('Workforce team "%s" archived — its fallback chain no longer applies', v_team.name),
    'config_change',
    jsonb_build_object('kind', 'workforce_team_archived', 'team_id', p_team_id)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.assert_kpi_metric_known()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM kpi_metric_catalog c
     WHERE c.metric_key = NEW.metric_key
       AND (c.tenant_id IS NULL OR c.tenant_id = NEW.tenant_id)
  ) THEN
    RAISE EXCEPTION 'unknown_metric_key: % — add it to your KPI catalog first', NEW.metric_key;
  END IF;
  RETURN NEW;
END$function$;

CREATE OR REPLACE FUNCTION public.assess_de_skills_internal(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de record;
  v_updated integer := 0;
  -- signal scratch
  v_dec_total integer; v_dec_escalated integer; v_dec_conf numeric;
  v_run_total integer; v_run_blocked integer; v_run_answered integer;
  v_csat_total integer; v_csat_pos integer;
  v_act_total integer; v_act_ok integer;
  -- per-skill result
  v_prof integer; v_prev integer; v_sample integer; v_value numeric; v_detail text;
  v_weak text[];
  v_weak_names text;
begin
  for v_de in
    select id, tenant_id, name from digital_employees
    where lifecycle_status not in ('retired', 'archived')
      and (p_tenant_id is null or tenant_id = p_tenant_id)
  loop
    v_weak := '{}';

    -- ── raw signals, all windowed to the last 30 days ──
    select count(*), count(*) filter (where d.decision = 'needs_review'),
           round(avg(d.confidence) filter (where d.confidence is not null), 1)
      into v_dec_total, v_dec_escalated, v_dec_conf
    from evidence_run_decisions d
    join evidence_runs er on er.id = d.evidence_run_id
    where er.tenant_id = v_de.tenant_id and er.de_id = v_de.id
      and d.created_at > now() - interval '30 days';

    -- Domain grounding measures GENUINE answer attempts only: a run
    -- that never reached the model (llm_not_configured — no key/budget,
    -- an infrastructure state, not a knowledge signal) or was withheld
    -- by a guardrail (blocked — a policy signal, not knowledge) does not
    -- count for or against the DE's domain knowledge. Denominator =
    -- answered + error (the DE tried); numerator = answered.
    select count(*) filter (where answer_status in ('answered', 'error')),
           count(*) filter (where answer_status = 'blocked'),
           count(*) filter (where answer_status = 'answered')
      into v_run_total, v_run_blocked, v_run_answered
    from evidence_runs
    where tenant_id = v_de.tenant_id and de_id = v_de.id
      and created_at > now() - interval '30 days';

    select count(*) filter (where csat_submitted_at is not null),
           count(*) filter (where csat_score = 1)
      into v_csat_total, v_csat_pos
    from de_conversations
    where tenant_id = v_de.tenant_id and de_id = v_de.id
      and csat_submitted_at > now() - interval '30 days';

    select count(*) filter (where decision in ('auto_executed', 'executed_after_approval', 'failed')),
           count(*) filter (where decision in ('auto_executed', 'executed_after_approval'))
      into v_act_total, v_act_ok
    from action_executions
    where tenant_id = v_de.tenant_id and subject_kind = 'de' and subject_id = v_de.id
      and mode = 'execute' and created_at > now() - interval '30 days';

    -- ── skill 1: Case Resolution (escalation rate, lower better) ──
    v_sample := coalesce(v_dec_total, 0);
    if v_sample >= 10 then
      v_value := round(100.0 * v_dec_escalated / v_sample, 1);
      v_prof := case when v_value <= 10 then 4 when v_value <= 25 then 3 when v_value <= 50 then 2 else 1 end;
      v_detail := format('Escalated %s%% of %s decisions (last 30 days). Lower is better; level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 real decisions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'case_resolution', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Case Resolution'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 2: Judgment Calibration (avg confidence, higher better) ──
    v_sample := coalesce(v_dec_total, 0);
    if v_sample >= 10 and v_dec_conf is not null then
      v_value := v_dec_conf;
      v_prof := case when v_value >= 80 then 4 when v_value >= 65 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('Average confidence %s%% across %s decisions (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 real decisions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'judgment_calibration', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Judgment Calibration'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 3: Domain Grounding (answered share of non-blocked) ──
    v_sample := coalesce(v_run_total, 0);
    if v_sample >= 10 then
      v_value := round(100.0 * v_run_answered / v_sample, 1);
      v_prof := case when v_value >= 90 then 4 when v_value >= 75 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('Produced a real answer on %s%% of %s genuine answer attempts (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 genuine answer attempts needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'domain_grounding', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Domain Knowledge Grounding'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 4: Communication Quality (positive CSAT) ──
    v_sample := coalesce(v_csat_total, 0);
    if v_sample >= 5 then
      v_value := round(100.0 * v_csat_pos / v_sample, 1);
      v_prof := case when v_value >= 90 then 4 when v_value >= 75 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('%s%% positive across %s ratings (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 5 customer ratings needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'communication_quality', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Communication Quality'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 5: System Integration (action success rate) ──
    v_sample := coalesce(v_act_total, 0);
    if v_sample >= 5 then
      v_value := round(100.0 * v_act_ok / v_sample, 1);
      v_prof := case when v_value >= 95 then 4 when v_value >= 85 then 3 when v_value >= 60 then 2 else 1 end;
      v_detail := format('%s%% of %s executed actions succeeded (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 5 executed actions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'system_integration', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'System Integration'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── §4.5: skill gaps drive Development. One consolidated item per
    --    DE, refreshed; removed when no skills are weak. ──
    if array_length(v_weak, 1) is not null then
      v_weak_names := array_to_string(v_weak, ', ');
      insert into de_development_items (tenant_id, de_id, item_type, source, priority, description, target_metric, target_value, baseline_value, status)
      values (v_de.tenant_id, v_de.id, 'skill_gap', 'detected', 'medium',
        format('%s is below Proficient (level 3) on: %s. These are assessed from real 30-day evidence — target level 3+.', v_de.name, v_weak_names),
        'skill_proficiency', 3, 2, 'proposed')
      on conflict (tenant_id, de_id, item_type) where source = 'detected' and status in ('proposed', 'in_progress')
      do update set description = excluded.description, updated_at = now();
    else
      -- No weak skills → retire any still-open detected skill_gap item.
      update de_development_items set status = 'completed', updated_at = now()
      where tenant_id = v_de.tenant_id and de_id = v_de.id and item_type = 'skill_gap'
        and source = 'detected' and status in ('proposed', 'in_progress');
    end if;
  end loop;

  return jsonb_build_object('skills_changed', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION public.assess_definition_of_done(p_tenant_id uuid, p_scope text, p_scope_id uuid, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pending int := 0;
  v_unresolved boolean := false;
  v_gated_task uuid;
begin
  -- (a) origin-scoped gated actions: pending = a gated row whose task is still
  --     'pending', OR 'approved' but with no non-failed row resolving it.
  select count(*) into v_pending
    from action_executions ae
    join human_tasks ht on ht.id = ae.task_id
   where ae.tenant_id = p_tenant_id and ae.origin_kind = p_scope and ae.origin_id = p_scope_id
     and ae.decision in ('human_gated_destructive','human_gated_trust')
     and ( ht.status = 'pending'
        or ( ht.status = 'approved'
             and not exists (select 1 from action_executions ex where ex.resolves_task_id = ae.task_id and ex.decision <> 'failed') ) );

  -- (b) account / opportunity write-backs on this objective.
  if p_objective_id is not null then
    v_pending := v_pending
      + (select count(*) from account_writeback_requests w where w.tenant_id = p_tenant_id and w.objective_id = p_objective_id and w.status = 'pending_approval')
      + (select count(*) from opportunity_writeback_requests w where w.tenant_id = p_tenant_id and w.objective_id = p_objective_id and w.status = 'pending_approval');
  end if;

  -- (c) outbound drafts scoped to this run/item.
  v_pending := v_pending
    + (select count(*) from outbound_drafts d where d.tenant_id = p_tenant_id and d.source_kind = p_scope and d.source_ref = p_scope_id and d.status = 'pending_approval');

  -- (d) fail-CLOSED anchor: an agentic run that flagged a gate whose task is not
  --     resolved by a non-failed execution is 'unresolved' even if origin wasn't
  --     threaded — so a missing correlation can never pass as "nothing pending".
  if p_scope = 'agentic_run' then
    select last_gated_human_task_id into v_gated_task from agentic_step_runs where id = p_scope_id and tenant_id = p_tenant_id;
    if v_gated_task is not null
       and not exists (select 1 from action_executions ex where ex.resolves_task_id = v_gated_task and ex.decision <> 'failed') then
      v_unresolved := true;
    end if;
  end if;

  return jsonb_build_object(
    'verified', (coalesce(v_pending, 0) = 0) and not v_unresolved,
    'pending_count', coalesce(v_pending, 0),
    'unresolved', v_unresolved,
    'detail', jsonb_build_object('scope', p_scope, 'scope_id', p_scope_id, 'objective_id', p_objective_id)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.assign_doc_collection(p_doc_id uuid, p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_collection_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'collection_not_found'); END IF;

  -- 359: filing a document you cannot edit, into a space you do not administer,
  -- is how a member moves a document somewhere they CAN read it.
  IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN
    IF public.knowledge_effective_level(p_doc_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need edit access to that document');
    END IF;
    IF public.knowledge_my_admin_level(p_collection_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need access to the space you are filing it into');
    END IF;
  END IF;

  INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
  VALUES (v_tenant, p_doc_id, p_collection_id)
  ON CONFLICT (doc_id, collection_id) DO NOTHING;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.assign_training_for_de(p_de_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_arch text; v_n int;
begin
  select tenant_id, catalog_id into v_tenant, v_arch from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  insert into de_training_progress (tenant_id, de_id, module_key, status)
  select v_tenant, p_de_id, m.module_key, 'assigned'
  from de_training_modules m
  where m.archetype_key = v_arch and m.required
    and (m.scope = 'platform' or m.tenant_id = v_tenant)
  on conflict (de_id, module_key) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.attach_compliance_pack(p_tenant_id uuid, p_pack_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count int := 0;
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or (p.tenant_id = p_tenant_id and p.role in ('tenant_owner','tenant_admin')))) then
    raise exception 'only an owner/admin (or platform) can attach a compliance pack';
  end if;
  insert into tenant_compliance_packs(tenant_id, pack_key, attached_by)
    values (p_tenant_id, p_pack_key, auth.uid()) on conflict do nothing;
  -- Materialize the pack's rules as real guardrail_rules (skip ones
  -- already materialized for this tenant+pack).
  insert into guardrail_rules (tenant_id, rule, rule_type, pattern, applies_to, severity, active, compliance_pack_key)
  select p_tenant_id, r.rule, r.rule_type, r.pattern, 'all', r.severity, true, r.pack_key
  from compliance_pack_rules r
  where r.pack_key = p_pack_key
    and not exists (select 1 from guardrail_rules g
                    where g.tenant_id = p_tenant_id and g.compliance_pack_key = r.pack_key and g.rule = r.rule);
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_chain_head(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_head    text;
  v_at      timestamptz;
  v_count   bigint;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'not a member of this tenant';
  END IF;

  SELECT hash, created_at INTO v_head, v_at
  FROM audit_events
  WHERE tenant_id = p_tenant_id
  ORDER BY created_at DESC, id DESC
  LIMIT 1;

  SELECT count(*) INTO v_count FROM audit_events WHERE tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'head_hash', coalesce(v_head, ''),
    'head_at',   v_at,
    'count',     coalesce(v_count, 0)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_events_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if TG_OP = 'DELETE' and coalesce(current_setting('app.allow_audit_purge', true), '') = 'on' then
    return OLD;
  end if;
  raise exception 'audit_events is immutable — records can only be appended';
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_tenant_provisioning()
 RETURNS TABLE(tenant_id uuid, tenant_name text, tenant_status text, des bigint, playbooks bigint, guardrails bigint, onboarding_templates bigint, specialists bigint, trust_policies bigint, autonomy_rows bigint, connectors bigint, baseline_complete boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then raise exception 'only a platform team member with tenant management access may audit tenant provisioning'; end if;
  return query
  select t.id, t.name, t.status,
    (select count(*) from digital_employees d where d.tenant_id = t.id and d.lifecycle_status <> 'retired' and not d.is_specialist),
    (select count(*) from playbook_definitions p where p.tenant_id = t.id),
    (select count(*) from guardrail_rules g where g.tenant_id = t.id and g.active),
    (select count(*) from onboarding_template_versions v where v.tenant_id = t.id),
    (select count(*) from digital_employees d where d.tenant_id = t.id and d.is_specialist = true and d.status = 'active'),
    (select count(*) from trust_policies tp where tp.tenant_id = t.id),
    (select count(*) from de_autonomy da where da.tenant_id = t.id),
    (select count(*) from connectors c where c.tenant_id = t.id),
    (select count(*) from digital_employees d where d.tenant_id = t.id and d.lifecycle_status <> 'retired' and not d.is_specialist) >= 2
      and (select count(*) from playbook_definitions p where p.tenant_id = t.id) >= 2
      and (select count(*) from guardrail_rules g where g.tenant_id = t.id and g.active) >= 7
      and (select count(*) from onboarding_template_versions v where v.tenant_id = t.id) >= 1
  from tenants t
  where t.id <> 'a0000000-0000-0000-0000-000000000001' and t.name not like '[TEST DEBRIS%'
  order by t.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.auth_has_tenant_role(required_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    exists (
      select 1 from public.profiles
      where user_id = auth.uid() and coalesce(is_active, true) = true
        and role = any(required_roles)
    )
    or
    public.resolve_remote_access_tenant(auth.uid(), public.auth_tenant_id()) is not null;
$function$;

CREATE OR REPLACE FUNCTION public.auth_tenant_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (
      select tenant_id from public.profiles
      where user_id = auth.uid() and coalesce(is_active, true) = true
      limit 1
    ),
    (
      select e.tenant_id
      from public.platform_access_events e
      where e.operator_user_id = auth.uid()
        and e.event = 'start'
        and e.created_at > now() - interval '12 hours'
        and exists (
          select 1 from public.profiles p
          where p.user_id = auth.uid() and coalesce(p.is_active, true) = true
        )
        and e.id = (
          select e2.id
          from public.platform_access_events e2
          where e2.operator_user_id = auth.uid()
          order by e2.created_at desc
          limit 1
        )
      limit 1
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.auto_provision_new_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_de_id UUID;
BEGIN
  -- Only provision if tenant is created with status='active'
  IF NEW.status = 'active' THEN
    RAISE NOTICE 'Auto-provisioning features for new tenant: %', NEW.name;

    -- Create Workforce Assistant DE
    INSERT INTO digital_employees (
      tenant_id,
      name,
      status,
      charter,
      is_workforce_assistant,
      is_product_expert,
      created_by,
      description
    ) VALUES (
      NEW.id,
      'Workforce Assistant',
      'active',
      jsonb_build_object(
        'name', 'Workforce Assistant',
        'persona', 'You are a trusted advisor helping this organization hire, improve, and manage their digital workforce. You are an expert on the DreamTeamAI platform.',
        'responsibilities', jsonb_build_array(
          'Help hire new DEs by understanding role requirements',
          'Suggest improvements to underperforming DEs based on metrics',
          'Monitor team performance and provide insights',
          'Help retire DEs and transition knowledge',
          'Train new tenants on DreamTeamAI features'
        ),
        'guardrails', jsonb_build_array(
          'Never auto-approve DE changes without explicit user consent',
          'Always show evidence for recommendations',
          'Prioritize user success over automation',
          'Escalate ambiguous decisions to the tenant admin'
        )
      ),
      true,
      true,
      auth.uid(),
      'Conversational workforce management assistant'
    ) RETURNING id INTO v_de_id;

    -- Create initial deployment stage
    INSERT INTO de_deployment_stages (de_id, stage)
    VALUES (v_de_id, 'live');

    RAISE NOTICE 'Auto-provisioned Workforce Assistant for tenant: %', NEW.name;
  END IF;

  -- 332: every workspace gets the platform-provided Workforce Assistant.

  -- Never let this block tenant creation: a missing Assistant is

  -- recoverable, a failed workspace creation is not.

  begin perform public.provision_workforce_assistant_internal(new.id);

  exception when others then

    raise warning 'workforce assistant provisioning failed for %: %', new.id, sqlerrm;

  end;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.b64url(p_in text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT translate(
           replace(replace(rtrim(encode(convert_to(coalesce(p_in,''),'UTF8'),'base64'), '='), chr(10), ''), chr(13), ''),
           '+/', '-_');
$function$;

CREATE OR REPLACE FUNCTION public.begin_objective_wake(p_objective_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update de_objectives
     set wake_count = wake_count + 1,
         next_wake_at = case when cadence_minutes is not null
                             then now() + make_interval(mins => cadence_minutes)
                             else now() + interval '60 minutes' end,
         updated_at = now()
   where id = p_objective_id and status in ('open', 'in_progress')
     and next_wake_at is not null and next_wake_at <= now()   -- the actual claim
   returning wake_count into v_count;
  if v_count is null then raise exception 'objective not wakeable (already claimed, disarmed, or closed)'; end if;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.build_base_predicates(p jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE e jsonb; out text := ''; BEGIN
  FOR e IN SELECT jsonb_array_elements(coalesce(p,'[]'::jsonb)) LOOP
    out := out || CASE e->>'op'
      WHEN 'is_null'         THEN format(' AND %I IS NULL', e->>'col')
      WHEN 'is_not_null'     THEN format(' AND %I IS NOT NULL', e->>'col')
      WHEN 'ge_current_date' THEN format(' AND %I >= current_date', e->>'col')
      ELSE '' END;
  END LOOP; RETURN out; END $function$;

CREATE OR REPLACE FUNCTION public.bulk_add_doc_tag(p_doc_ids uuid[], p_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int; v_tag text := btrim(coalesce(p_tag, ''));
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  IF v_tag = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'empty_tag'); END IF;
  UPDATE knowledge_docs
     SET tags = (SELECT array_agg(DISTINCT t) FROM unnest(coalesce(tags, '{}') || ARRAY[v_tag]) t),
         updated_at = now()
   WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant AND NOT (coalesce(tags, '{}') @> ARRAY[v_tag]);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'updated', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_assign_collection(p_doc_ids uuid[], p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_collection_id AND tenant_id = v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'collection_not_found');
  END IF;
  INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
  SELECT v_tenant, d.id, p_collection_id FROM knowledge_docs d
   WHERE d.id = ANY(p_doc_ids) AND d.tenant_id = v_tenant
  ON CONFLICT (doc_id, collection_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'added', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_delete_docs(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 500 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many', 'cap', 500); END IF;
  DELETE FROM knowledge_docs WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'deleted', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_mark_verified(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  UPDATE knowledge_docs SET last_verified_at = now()
   WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'verified', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_reembed_docs(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT public.is_feature_enabled_internal(v_tenant, 'knowledge_reembed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'reembed_disabled'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 500 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many', 'cap', 500); END IF;
  UPDATE knowledge_doc_chunks SET reembed_pending = true
   WHERE doc_id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'chunks_queued', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.calculate_tenant_monthly_cost(p_tenant_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_features_cost NUMERIC(10,2) := 0;
  v_usage_cost NUMERIC(10,2) := 0;
  v_total_cost NUMERIC(10,2) := 0;
  v_month_year VARCHAR(7) := to_char(now(), 'YYYY-MM');
  v_responses INT;
  v_amendments INT;
  v_de_count INT;
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get current month metrics
  SELECT
    COALESCE(total_responses_this_month, 0),
    COALESCE(total_amendments_created, 0)
  INTO v_responses, v_amendments
  FROM tenant_usage_metrics
  WHERE tenant_id = p_tenant_id AND month_year = v_month_year;

  -- Get DE count
  SELECT COUNT(*) INTO v_de_count
  FROM digital_employees
  WHERE tenant_id = p_tenant_id;

  -- Calculate feature costs (assuming all enabled)
  SELECT
    COALESCE(sophie_config_cost, 100) +
    COALESCE(amendment_journeys_cost, 50) +
    COALESCE(metrics_tracking_cost, 75) +
    COALESCE(reply_mode_cost, 150) +
    COALESCE(hosted_chat_cost, 200)
  INTO v_features_cost
  FROM tenant_billing_config
  WHERE tenant_id = p_tenant_id;

  -- Calculate usage costs
  SELECT
    (v_responses::numeric / 1000) * COALESCE(cost_per_1k_responses, 0.50) +
    (v_amendments::numeric) * COALESCE(cost_per_amendment, 5) +
    (v_de_count::numeric) * COALESCE(cost_per_de, 20)
  INTO v_usage_cost
  FROM tenant_billing_config
  WHERE tenant_id = p_tenant_id;

  v_total_cost := COALESCE(v_features_cost, 0) + COALESCE(v_usage_cost, 0);

  -- Insert or update cost tracking
  INSERT INTO tenant_cost_tracking (
    tenant_id, billing_month, status,
    sophie_config_charge, amendment_journeys_charge, metrics_tracking_charge,
    reply_mode_charge, hosted_chat_charge, response_usage_cost,
    amendment_usage_cost, de_count_cost, subtotal, total_cost
  ) VALUES (
    p_tenant_id, v_month_year, 'estimated',
    100, 50, 75, 150, 200,
    (v_responses::numeric / 1000) * 0.50,
    (v_amendments::numeric) * 5,
    (v_de_count::numeric) * 20,
    v_features_cost, v_total_cost
  )
  ON CONFLICT (tenant_id, billing_month)
  DO UPDATE SET
    total_cost = EXCLUDED.total_cost,
    response_usage_cost = EXCLUDED.response_usage_cost,
    amendment_usage_cost = EXCLUDED.amendment_usage_cost,
    de_count_cost = EXCLUDED.de_count_cost,
    updated_at = now();

  RETURN json_build_object(
    'tenant_id', p_tenant_id,
    'month', v_month_year,
    'features_cost', ROUND(v_features_cost, 2),
    'usage_cost', ROUND(v_usage_cost, 2),
    'responses', v_responses,
    'amendments', v_amendments,
    'de_count', v_de_count,
    'total_cost', ROUND(v_total_cost, 2)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.caller_has_tenant_relationship(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    is_platform_admin()
    or exists (
      select 1 from profiles pr where pr.user_id = auth.uid() and pr.tenant_id = p_tenant_id and coalesce(pr.is_active, true) = true
    )
    or exists (
      -- caller's own tenant is an ancestor of p_tenant_id => opt-in rollup
      -- visibility for a parent looking at a descendant.
      select 1
      from profiles pr
      join tenant_ancestry ta on ta.tenant_id = p_tenant_id and ta.ancestor_id = pr.tenant_id
      where pr.user_id = auth.uid() and coalesce(pr.is_active, true) = true
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_admin_tenant_internal(p_tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(auth.role(),'') = 'service_role'
      OR (p_tenant = public.auth_tenant_id()
          AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']));
$function$;

CREATE OR REPLACE FUNCTION public.can_consult_multihop(p_tenant_id uuid, p_requester_de uuid, p_target_de uuid, p_path uuid[] DEFAULT '{}'::uuid[], p_max_depth integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_target_de = any(p_path) or p_target_de = p_requester_de then
    return jsonb_build_object('allowed', false, 'reason', 'cycle');
  end if;
  if coalesce(array_length(p_path, 1), 0) >= p_max_depth then
    return jsonb_build_object('allowed', false, 'reason', 'max_depth');
  end if;
  if not exists (
      select 1 from de_consultation_grants g
      where g.tenant_id = p_tenant_id and g.requester_de_id = p_requester_de
        and g.target_de_id = p_target_de and g.active) then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant');
  end if;
  return jsonb_build_object('allowed', true, 'next_path', (p_path || p_requester_de));
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_case_continuation(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM de_case_events WHERE id = p_event_id AND status = 'pending';
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found_or_decided'); END IF;
  IF coalesce(auth.role(),'') <> 'service_role' AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  UPDATE de_case_events SET status = 'cancelled', decided_at = now() WHERE id = p_event_id;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.cancel_ingestion_job(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_ingestion_jobs WHERE id=p_job_id AND tenant_id=v_tenant) THEN
    RAISE EXCEPTION 'job_not_found';
  END IF;

  UPDATE knowledge_ingestion_jobs SET status='cancelled', finished_at=now() WHERE id=p_job_id;
  UPDATE knowledge_ingestion_items SET status='cancelled', updated_at=now()
   WHERE job_id=p_job_id AND status IN ('queued','running');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'cancelled_items', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.certify_de_from_eval(p_de_id uuid, p_archetype_key text, p_eval_run_id uuid, p_threshold_pct integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_total int; v_passed int; v_pct numeric; v_status text; v_threshold integer;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;
  select coalesce((select pass_threshold_pct from role_archetypes where key = p_archetype_key), 80)
    into v_threshold;
  select total, passed into v_total, v_passed from eval_runs where id = p_eval_run_id and tenant_id = v_tenant;
  if v_total is null or v_total = 0 then raise exception 'eval run has no results'; end if;
  v_pct := round(100.0 * v_passed / v_total, 1);
  v_status := case when v_pct >= v_threshold then 'passed' else 'failed' end;
  insert into role_certifications (tenant_id, de_id, archetype_key, eval_run_id, score_pct, threshold_pct, status, evaluated_at, config_fingerprint)
  values (v_tenant, p_de_id, p_archetype_key, p_eval_run_id, v_pct, v_threshold, v_status, now(), public.de_config_fingerprint(p_de_id));
  return jsonb_build_object('status', v_status, 'score_pct', v_pct, 'threshold_pct', v_threshold, 'passed', v_passed, 'total', v_total);
end;
$function$;

CREATE OR REPLACE FUNCTION public.certify_de_from_sim(p_de_id uuid, p_archetype_key text, p_sim_run_id uuid, p_threshold_pct integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_run sim_runs; v_pct numeric; v_status text; v_threshold integer; v_fp text;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;

  -- The archetype's bar governs; the caller's p_threshold_pct is IGNORED
  -- (kept only for signature compatibility) — a threshold of 0 could mint
  -- a passing cert from any finished run (C2).
  select coalesce((select pass_threshold_pct from role_archetypes where key = p_archetype_key), 80)
    into v_threshold;

  select * into v_run from sim_runs
    where id = p_sim_run_id and tenant_id = v_tenant and de_id = p_de_id
      and status in ('passed', 'failed') and candidate = false;
  if v_run.id is null or v_run.total = 0 then
    raise exception 'simulation has no results (or is a candidate dry-run, which cannot certify)';
  end if;
  v_pct := round(100.0 * v_run.passed / v_run.total, 1);
  v_status := case when v_pct >= v_threshold then 'passed' else 'failed' end;
  -- The cert vouches for the config the run actually TESTED (C3).
  v_fp := coalesce(v_run.config_fingerprint, public.de_config_fingerprint(p_de_id));

  insert into role_certifications (tenant_id, de_id, archetype_key, eval_run_id, score_pct, threshold_pct, status, evaluated_at, config_fingerprint)
  values (v_tenant, p_de_id, p_archetype_key, null, v_pct, v_threshold, v_status, now(), v_fp);

  return jsonb_build_object('status', v_status, 'score_pct', v_pct, 'threshold_pct', v_threshold,
                            'passed', v_run.passed, 'total', v_run.total, 'from', 'simulation');
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_action_idempotency(p_tenant_id uuid, p_action_definition_id uuid, p_dedupe_key text)
 RETURNS TABLE(execution_id uuid, receipt text, executed_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.id, e.receipt, e.created_at
  from action_executions e
  where e.tenant_id = p_tenant_id
    and e.action_definition_id = p_action_definition_id
    and e.dedupe_key = p_dedupe_key
    and e.dedupe_key is not null
    and e.mode = 'execute'
    and e.decision in ('auto_executed', 'executed_after_approval')
    and e.rolled_back_at is null
  order by e.created_at desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.check_approval_sod(p_tenant_id uuid, p_scope text, p_preparer_user uuid, p_approver_user uuid, p_amount_cents bigint DEFAULT NULL::bigint, p_prior_approver uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p sod_policies;
BEGIN
  SELECT * INTO p FROM sod_policies WHERE tenant_id = p_tenant_id AND scope = p_scope AND active;
  IF p.id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'no SoD policy configured for this scope');
  END IF;
  -- 1) Preparer ≠ approver.
  IF p.require_distinct_approver
     AND p_preparer_user IS NOT NULL AND p_approver_user IS NOT NULL
     AND p_preparer_user = p_approver_user THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'The approver cannot be the person who prepared this — separation of duties.');
  END IF;
  -- 2) Dual control above the threshold — needs a second, DIFFERENT approver.
  IF p.dual_approval_over_cents IS NOT NULL AND coalesce(p_amount_cents, 0) > p.dual_approval_over_cents THEN
    IF p_prior_approver IS NULL OR p_prior_approver = p_approver_user THEN
      RETURN jsonb_build_object('ok', false, 'reason',
        format('This is over $%s — it requires a second, different approver (dual control).', round(p.dual_approval_over_cents / 100.0)));
    END IF;
  END IF;
  RETURN jsonb_build_object('ok', true, 'reason', 'separation of duties satisfied');
END; $function$;

CREATE OR REPLACE FUNCTION public.check_de_budget(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ceiling bigint; v_used numeric;
begin
  select monthly_ceiling_cents into v_ceiling from de_budget_policies where de_id = p_de_id;
  if v_ceiling is null or v_ceiling = 0 then
    return jsonb_build_object('allowed', true, 'ceiling_cents', 0, 'used_cents', 0);
  end if;
  -- Cost this month = tokens x model price (ai_model_pricing is $/1M tok),
  -- converted to cents. Unknown model -> priced at 0 (no false block).
  select coalesce(sum(
           (u.input_tokens::numeric / 1000000) * coalesce(p.input_price_per_million, 0) * 100
         + (u.output_tokens::numeric / 1000000) * coalesce(p.output_price_per_million, 0) * 100
         ), 0)
    into v_used
  from de_token_usage u
  left join ai_model_pricing p on p.model_id = u.model_id
  where u.de_id = p_de_id and u.created_at >= date_trunc('month', now());
  return jsonb_build_object('allowed', v_used < v_ceiling, 'ceiling_cents', v_ceiling, 'used_cents', round(v_used));
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_de_retirement_readiness(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_open_tasks integer;
  v_pending_actions integer;
  v_playbook_assignments integer;
  v_active_charter_bindings integer;
  v_consulted_by integer;
  v_blockers jsonb := '[]'::jsonb;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can check retirement readiness'; end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;

  select count(*) into v_open_tasks
  from human_tasks
  where tenant_id = v_tenant and status = 'open' and related_table = 'de_conversations'
    and related_id in (select id from de_conversations where de_id = p_de_id);

  select count(*) into v_pending_actions
  from action_executions ae
  join human_tasks ht on ht.id = ae.task_id
  where ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
    and ae.decision in ('human_gated_destructive', 'human_gated_trust') and ht.status = 'open';

  select count(*) into v_playbook_assignments
  from de_playbook_assignments where tenant_id = v_tenant and digital_employee_id = p_de_id;

  select count(*) into v_active_charter_bindings
  from de_playbook_charter where tenant_id = v_tenant and de_id = p_de_id and active;

  select count(*) into v_consulted_by
  from de_consultation_grants where tenant_id = v_tenant and target_de_id = p_de_id and active;

  if v_open_tasks > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'open_conversations', 'count', v_open_tasks,
      'message', format('%s open escalation(s) from conversations this employee is party to — resolve them first.', v_open_tasks));
  end if;
  if v_pending_actions > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'pending_approvals', 'count', v_pending_actions,
      'message', format('%s action(s) awaiting human approval — decide them first.', v_pending_actions));
  end if;
  if v_playbook_assignments > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'playbook_assignments', 'count', v_playbook_assignments,
      'message', format('Assigned to %s playbook(s) — reassign or remove those assignments first.', v_playbook_assignments));
  end if;
  if v_active_charter_bindings > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'active_charter_bindings', 'count', v_active_charter_bindings,
      'message', format('%s active playbook charter binding(s) — deactivate them first.', v_active_charter_bindings));
  end if;
  if v_consulted_by > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'consulted_by_other_des', 'count', v_consulted_by,
      'message', format('%s other employee(s) are configured to consult this one — remove those consultation grants first.', v_consulted_by));
  end if;

  return jsonb_build_object(
    'de_id', p_de_id, 'ready', jsonb_array_length(v_blockers) = 0,
    'open_conversations', v_open_tasks, 'pending_approvals', v_pending_actions,
    'playbook_assignments', v_playbook_assignments, 'active_charter_bindings', v_active_charter_bindings,
    'consulted_by_other_des', v_consulted_by,
    'blockers', v_blockers
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_ip_against_tenant_allowlist(p_tenant_id uuid, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
  v_matched boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'check_ip_against_tenant_allowlist is service-role only';
  end if;

  select enabled into v_enabled from tenant_ip_allowlists where tenant_id = p_tenant_id;
  if v_enabled is not true then
    return jsonb_build_object('allowed', true, 'reason', 'not_enabled');
  end if;

  select exists(
    select 1 from tenant_ip_allowlist_entries e
    where e.tenant_id = p_tenant_id and p_ip::inet <<= e.ip_range
  ) into v_matched;

  return jsonb_build_object('allowed', v_matched, 'reason', case when v_matched then 'matched' else 'no_match' end);
exception when others then
  return jsonb_build_object('allowed', true, 'reason', 'error_fail_open');
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_staleness(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy   record;
  v_proj     record;
  v_task     record;
  v_inv      record;
  v_open     record;
  v_warned   integer := 0;
  v_breached integer := 0;
  v_resolved integer := 0;
  v_acct     text;
begin
  for v_policy in
    select * from staleness_policies sp
    where sp.enabled
      and (p_tenant_id is null or sp.tenant_id = p_tenant_id)
      and is_feature_enabled_internal(sp.tenant_id, 'staleness_watchdog')
  loop

    if v_policy.target_kind = 'onboarding_project' then
      for v_proj in
        select op.id, op.name, op.updated_at, op.account_id
        from onboarding_projects op
        where op.tenant_id = v_policy.tenant_id
          and op.status = 'active'
      loop
        select name into v_acct from customer_accounts
          where id = v_proj.account_id and tenant_id = v_policy.tenant_id;

        if now() - v_proj.updated_at >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'onboarding_project', v_proj.id, 'breach',
            format('Onboarding stalled — %s', v_proj.name),
            format('This onboarding project for %s hasn''t been touched in %s (breach threshold: %s).',
                   coalesce(v_acct, v_proj.name), stale_humanize_interval(now() - v_proj.updated_at),
                   stale_humanize_interval(v_policy.breach_after)),
            'onboarding_projects', v_proj.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif now() - v_proj.updated_at >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'onboarding_project', v_proj.id, 'warning',
            format('Onboarding going quiet — %s', v_proj.name),
            format('This onboarding project for %s hasn''t been touched in %s (warning threshold: %s).',
                   coalesce(v_acct, v_proj.name), stale_humanize_interval(now() - v_proj.updated_at),
                   stale_humanize_interval(v_policy.warning_after)),
            'onboarding_projects', v_proj.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'onboarding_project'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from onboarding_projects op
          where op.id = v_open.target_id and op.tenant_id = v_policy.tenant_id
            and op.status = 'active'
            and now() - op.updated_at >= v_policy.warning_after
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    elsif v_policy.target_kind = 'pending_review_task' then
      for v_task in
        select ht.id, ht.title, ht.created_at, ht.type
        from human_tasks ht
        where ht.tenant_id = v_policy.tenant_id
          and ht.status = 'pending'
          and ht.type in ('inquiry_review', 'action_approval', 'checklist', 'review_gate', 'approval_gate')
      loop
        if now() - v_task.created_at >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'pending_review_task', v_task.id, 'breach',
            format('Review overdue — %s', v_task.title),
            format('This %s has been waiting %s for a human decision (breach threshold: %s).',
                   replace(v_task.type, '_', ' '), stale_humanize_interval(now() - v_task.created_at),
                   stale_humanize_interval(v_policy.breach_after)),
            'human_tasks', v_task.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif now() - v_task.created_at >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'pending_review_task', v_task.id, 'warning',
            format('Review waiting — %s', v_task.title),
            format('This %s has been waiting %s for a human decision (warning threshold: %s).',
                   replace(v_task.type, '_', ' '), stale_humanize_interval(now() - v_task.created_at),
                   stale_humanize_interval(v_policy.warning_after)),
            'human_tasks', v_task.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'pending_review_task'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from human_tasks ht
          where ht.id = v_open.target_id and ht.tenant_id = v_policy.tenant_id
            and ht.status = 'pending'
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    elsif v_policy.target_kind = 'overdue_invoice_unattended' then
      for v_inv in
        select ri.id, ri.account_id, ri.amount_cents, ri.due_date, ca.name as account_name
        from renewal_invoices ri
        join customer_accounts ca on ca.id = ri.account_id and ca.tenant_id = v_policy.tenant_id
        where ri.tenant_id = v_policy.tenant_id
          and ri.status in ('sent', 'awaiting_approval')
          and ri.due_date is not null
      loop
        if (current_date - v_inv.due_date) * interval '1 day' >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'overdue_invoice_unattended', v_inv.id, 'breach',
            format('Invoice seriously overdue — %s', v_inv.account_name),
            format('Invoice for %s (%s cents) has been overdue since %s — %s past due (breach threshold: %s).',
                   v_inv.account_name, v_inv.amount_cents, v_inv.due_date,
                   stale_humanize_interval((current_date - v_inv.due_date) * interval '1 day'),
                   stale_humanize_interval(v_policy.breach_after)),
            'renewal_invoices', v_inv.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif (current_date - v_inv.due_date) * interval '1 day' >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'overdue_invoice_unattended', v_inv.id, 'warning',
            format('Invoice overdue — %s', v_inv.account_name),
            format('Invoice for %s (%s cents) has been overdue since %s — %s past due (warning threshold: %s).',
                   v_inv.account_name, v_inv.amount_cents, v_inv.due_date,
                   stale_humanize_interval((current_date - v_inv.due_date) * interval '1 day'),
                   stale_humanize_interval(v_policy.warning_after)),
            'renewal_invoices', v_inv.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'overdue_invoice_unattended'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from renewal_invoices ri
          where ri.id = v_open.target_id and ri.tenant_id = v_policy.tenant_id
            and ri.status in ('sent', 'awaiting_approval')
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    end if;
  end loop;

  return jsonb_build_object('warned', v_warned, 'breached', v_breached, 'resolved', v_resolved);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_tenant_ai_budget(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_budget  integer;
  v_used    bigint;
  v_allowed boolean;
  v_period  text := to_char(date_trunc('month', now()), 'YYYY-MM');
  v_kind    text;
  v_name    text;
begin
  select monthly_token_budget, name into v_budget, v_name
    from tenants where id = p_tenant_id;

  -- null / <= 0 means "no ceiling" — unchanged behaviour.
  if v_budget is null or v_budget <= 0 then
    return jsonb_build_object('allowed', true, 'used', 0, 'budget', v_budget);
  end if;

  v_used   := get_tenant_token_usage_this_month(p_tenant_id);
  v_allowed := v_used < v_budget;

  if v_used >= (v_budget::numeric * 0.8) then
    v_kind := case when v_allowed then 'ai_budget_approaching' else 'ai_budget_exhausted' end;

    insert into ops_alerts (kind, message, detail)
    select
      v_kind,
      case when v_allowed
        then format('%s has used %s%% of its monthly AI budget (%s of %s tokens).',
                    coalesce(v_name, 'A tenant'),
                    round((v_used::numeric / v_budget) * 100),
                    v_used, v_budget)
        else format('%s has EXHAUSTED its monthly AI budget (%s of %s tokens). Its digital employees have stopped answering.',
                    coalesce(v_name, 'A tenant'), v_used, v_budget)
      end,
      jsonb_build_object(
        'tenant_id', p_tenant_id,
        'tenant_name', v_name,
        'period', v_period,
        'used', v_used,
        'budget', v_budget
      )
    where not exists (
      select 1 from ops_alerts a
       where a.kind = v_kind
         and a.detail->>'tenant_id' = p_tenant_id::text
         and a.detail->>'period' = v_period
    );
  end if;

  return jsonb_build_object('allowed', v_allowed, 'used', v_used, 'budget', v_budget);
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_amendment_for_fitness(p_tenant_id uuid, p_amendment_id uuid, p_entity_kind text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO amendment_metrics (tenant_id, amendment_id, entity_kind, entity_id,
      before_metrics, replay_score_before, replay_score_after, adopted_at)
  VALUES (p_tenant_id, p_amendment_id, p_entity_kind, p_entity_id,
      '{}'::jsonb, null, null, now())
  ON CONFLICT (amendment_id) DO NOTHING
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('claimed', v_id IS NOT NULL);
END $function$;

CREATE OR REPLACE FUNCTION public.claim_computer_use_task(p_task_id uuid, p_runtime_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row computer_use_tasks;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'claim_computer_use_task is service-role only';
  end if;
  -- Atomic claim; the transition trigger re-verifies approval + runtime.
  update computer_use_tasks
     set status = 'claimed', runtime_id = p_runtime_id, updated_at = now()
   where id = p_task_id and status = 'approved'
   returning * into v_row;
  if v_row.id is null then raise exception 'task not claimable (not approved, already claimed, or missing)'; end if;
  return jsonb_build_object('task_id', v_row.id, 'goal', v_row.goal,
                            'allowed_domains', v_row.allowed_domains, 'max_steps', v_row.max_steps,
                            'constraints', v_row.constraints);
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_gated_action_execution(p_tenant_id uuid, p_task_id uuid, p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task_status text;
  v_new_id uuid;
  v_existing_id uuid;
  v_existing_receipt text;
begin
  -- Authoritative resolution signal — the human_task must be APPROVED (the
  -- action_executions.decision alone can't distinguish pending/approved/rejected).
  select status into v_task_status from human_tasks where id = p_task_id and tenant_id = p_tenant_id;
  if v_task_status is distinct from 'approved' then
    return jsonb_build_object('claimed', false, 'reason', 'task_not_approved');
  end if;

  -- Already executed for this task?
  select id, receipt into v_existing_id, v_existing_receipt
    from action_executions where resolves_task_id = p_task_id and decision <> 'failed' limit 1;
  if v_existing_id is not null then
    return jsonb_build_object('claimed', false, 'existing_id', v_existing_id, 'receipt', v_existing_receipt);
  end if;

  -- Claim: copy the gated row's fields into a new executed-placeholder row,
  -- guarded by the partial unique index. Concurrent/retry attempts collide.
  begin
    insert into action_executions (
      tenant_id, action_definition_id, connector_id, subject_kind, subject_id, mode, params,
      decision, destructive, idempotent, dedupe_key, request_summary,
      origin_kind, origin_id, resolves_task_id, receipt, result, task_id
    )
    select
      tenant_id, action_definition_id, connector_id, subject_kind, subject_id, mode, params,
      'executed_after_approval', destructive, idempotent, dedupe_key, request_summary,
      origin_kind, origin_id, p_task_id, null, null, null
    from action_executions
    where id = p_execution_id and tenant_id = p_tenant_id
    returning id into v_new_id;
  exception when unique_violation then
    select id, receipt into v_existing_id, v_existing_receipt
      from action_executions where resolves_task_id = p_task_id and decision <> 'failed' limit 1;
    return jsonb_build_object('claimed', false, 'existing_id', v_existing_id, 'receipt', v_existing_receipt);
  end;

  if v_new_id is null then
    return jsonb_build_object('claimed', false, 'reason', 'gated_row_not_found');
  end if;
  return jsonb_build_object('claimed', true, 'claim_row_id', v_new_id);
end $function$;

CREATE OR REPLACE FUNCTION public.claim_support_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  v_tenant := _assert_conv_member(p_conversation_id);
  update de_conversations set owner_user_id = auth.uid(), status = 'human_owned', last_message_at = now()
  where id = p_conversation_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.classify_sentiment_text(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := lower(coalesce(p_text, ''));
BEGIN
  IF v ~ 'cancel my|switch to|competitor|leaving you|close my account|no longer want|take my business' THEN RETURN 'churn_risk'; END IF;
  IF v ~ 'unacceptable|furious|ridiculous|worst|terrible|outrageous|disgusted|so angry|fed up' THEN RETURN 'angry'; END IF;
  IF v ~ 'still not|yet again|third time|keep failing|frustrat|annoyed|why is this|not working again' THEN RETURN 'frustrated'; END IF;
  IF v ~ 'urgent|asap|deadline|worried|concerned|losing money|at risk|time-sensitive' THEN RETURN 'anxious'; END IF;
  IF v ~ 'confus|do not understand|don''t understand|not sure how|unclear|how do i|where do i' THEN RETURN 'confused'; END IF;
  IF v ~ 'thank you|thanks|great|awesome|perfect|works now|resolved|appreciate|much better' THEN RETURN 'satisfied'; END IF;
  RETURN 'neutral';
END; $function$;

CREATE OR REPLACE FUNCTION public.classify_support_text(p_tenant_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r support_triage_rules;
  v_low text := lower(coalesce(p_text, ''));
  frag text;
BEGIN
  FOR r IN
    SELECT * FROM support_triage_rules
    WHERE tenant_id = p_tenant_id AND active
    ORDER BY rule_order, created_at
  LOOP
    -- Catch-all rule (no pattern) applies immediately.
    IF r.match_pattern IS NULL OR btrim(r.match_pattern) = '' THEN
      RETURN jsonb_build_object('category', r.set_category, 'priority', r.set_priority, 'severity', r.set_severity, 'rule', r.name);
    END IF;
    -- First rule whose ANY literal keyword is present wins.
    FOREACH frag IN ARRAY string_to_array(r.match_pattern, '|') LOOP
      frag := lower(btrim(frag));
      IF frag <> '' AND position(frag IN v_low) > 0 THEN
        RETURN jsonb_build_object('category', r.set_category, 'priority', r.set_priority, 'severity', r.set_severity, 'rule', r.name);
      END IF;
    END LOOP;
  END LOOP;
  -- No rule matched and no catch-all configured — safe neutral default.
  RETURN jsonb_build_object('category','general','priority','normal','severity','sev3','rule','default');
END; $function$;

CREATE OR REPLACE FUNCTION public.clear_de_operate_login(p_system_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret uuid;
BEGIN
  SELECT tenant_id, login_secret_id INTO v_tenant, v_secret
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  UPDATE de_connected_systems SET login_secret_id = NULL WHERE id = p_system_id;
  IF v_secret IS NOT NULL THEN DELETE FROM vault.secrets WHERE id = v_secret; END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.close_opportunity_lost(p_opp uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_opp    opportunities;
  v_tenant uuid;
  v_is_active boolean;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;
  if coalesce(trim(p_reason), '') = '' then
    return jsonb_build_object('error', 'lost_reason_required');
  end if;
  select * into v_opp from opportunities where id = p_opp and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'opportunity_not_found'); end if;
  if v_opp.stage in ('won', 'lost') then return jsonb_build_object('error', 'already_closed'); end if;

  perform set_config('dreamteam.opp_close', 'on', true);
  update opportunities set stage = 'lost', lost_reason = trim(p_reason) where id = v_opp.id;
  perform set_config('dreamteam.opp_close', '', true);

  return jsonb_build_object('closed', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.close_opportunity_won(p_opp uuid, p_account_id uuid DEFAULT NULL::uuid, p_create_onboarding boolean DEFAULT false, p_template_version uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_opp       opportunities;
  v_tenant    uuid;
  v_is_active boolean;
  v_acct_id   uuid;
  v_acct_name text;
  v_proj      jsonb;
  v_proj_id   uuid;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;

  select * into v_opp from opportunities where id = p_opp and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'opportunity_not_found'); end if;
  if v_opp.stage in ('won', 'lost') then return jsonb_build_object('error', 'already_closed'); end if;

  v_acct_id := coalesce(p_account_id, v_opp.account_id);
  if v_acct_id is not null then
    select name into v_acct_name from customer_accounts where id = v_acct_id and tenant_id = v_tenant;
    if v_acct_name is null then return jsonb_build_object('error', 'account_not_found'); end if;
  else
    v_acct_name := coalesce(nullif(trim(v_opp.company_name), ''), v_opp.name);
    insert into customer_accounts (tenant_id, name, arr_cents, health_score, status, notes)
    values (v_tenant, v_acct_name, coalesce(v_opp.amount_cents, 0), 70, 'active',
            format('Created from won opportunity "%s"', v_opp.name))
    returning id into v_acct_id;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (v_tenant, v_acct_id, 'You', 'human', 'config_change',
            format('Account created from won opportunity — %s', v_acct_name));
  end if;

  perform set_config('dreamteam.opp_close', 'on', true);
  update opportunities set stage = 'won', account_id = v_acct_id where id = v_opp.id;
  perform set_config('dreamteam.opp_close', '', true);

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Won → lifecycle handoff — %s: account "%s"%s', v_opp.name, v_acct_name,
           case when p_create_onboarding then ' + onboarding kickoff' else '' end),
    'config_change',
    jsonb_build_object('kind', 'opportunity_won_handoff', 'opportunity_id', v_opp.id,
                       'account_id', v_acct_id, 'created_account', v_opp.account_id is null and p_account_id is null,
                       'create_onboarding', p_create_onboarding));

  if p_create_onboarding and p_template_version is not null then
    v_proj := create_onboarding_project(v_acct_id, p_template_version, null, null);
    v_proj_id := (v_proj->>'project_id')::uuid;
    if v_proj->>'error' is not null then
      return jsonb_build_object('account_id', v_acct_id, 'onboarding_error', v_proj->>'error');
    end if;
  end if;

  return jsonb_build_object('account_id', v_acct_id, 'project_id', v_proj_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.cluster_gap_candidates(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy       record;
  v_candidate    record;
  v_nearest_id   uuid;
  v_nearest_status text;
  v_nearest_dist double precision;
  v_new_cluster_id uuid;
  v_frustration  integer;
  v_new_members  integer := 0;
  v_new_clusters integer := 0;
  v_reopened     integer := 0;
  v_promoted     integer := 0;
  v_cluster_id   uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'knowledge_gap_detection') then
    return jsonb_build_object('skipped', 'feature_disabled');
  end if;

  for v_policy in
    select * from knowledge_gap_policies where tenant_id = p_tenant_id and enabled = true
  loop
    for v_candidate in
      select erd.id as decision_id, erd.evidence_run_id, erd.confidence, erd.source_category,
             er.inquiry, er.inquiry_embedding, er.created_at
      from evidence_run_decisions erd
      join evidence_runs er on er.id = erd.evidence_run_id
      where erd.tenant_id = p_tenant_id
        and (v_policy.category is null or erd.source_category = v_policy.category)
        and erd.confidence < v_policy.min_confidence_floor
        and er.inquiry_embedding is not null
        and er.created_at >= now() - make_interval(days => v_policy.window_days)
        and not exists (select 1 from knowledge_gap_cluster_members m where m.evidence_run_id = er.id)
      order by er.created_at asc
    loop
      v_frustration := score_frustration_internal(p_tenant_id, v_candidate.inquiry);

      select c.id, c.status, rer.inquiry_embedding <=> v_candidate.inquiry_embedding
        into v_nearest_id, v_nearest_status, v_nearest_dist
      from knowledge_gap_clusters c
      join evidence_runs rer on rer.id = c.representative_run_id
      where c.tenant_id = p_tenant_id
        and (v_policy.category is null or c.category = v_candidate.source_category)
        and c.last_seen_at >= now() - make_interval(days => v_policy.window_days)
      order by rer.inquiry_embedding <=> v_candidate.inquiry_embedding asc
      limit 1;

      if v_nearest_id is not null and v_nearest_dist < v_policy.similarity_threshold then
        insert into knowledge_gap_cluster_members (cluster_id, evidence_run_id, similarity_to_representative, frustration_score)
        values (v_nearest_id, v_candidate.evidence_run_id, 1 - v_nearest_dist, v_frustration)
        on conflict (evidence_run_id) do nothing;

        if v_nearest_status = 'resolved' then
          update knowledge_gap_clusters
          set status = 'open', member_count = member_count + 1, last_seen_at = now(),
              recurred_after_fix = true, recurrence_count = recurrence_count + 1,
              severity_score = (select count(*) * (1 + coalesce(avg(frustration_score), 0) / 100.0)
                                from knowledge_gap_cluster_members where cluster_id = v_nearest_id) + 10,
              updated_at = now()
          where id = v_nearest_id;
          v_reopened := v_reopened + 1;
        else
          update knowledge_gap_clusters
          set member_count = member_count + 1, last_seen_at = now(),
              severity_score = (select count(*) * (1 + coalesce(avg(frustration_score), 0) / 100.0)
                                from knowledge_gap_cluster_members where cluster_id = v_nearest_id),
              updated_at = now()
          where id = v_nearest_id;
        end if;
        v_new_members := v_new_members + 1;
      else
        insert into knowledge_gap_clusters (tenant_id, category, representative_run_id, member_count, severity_score, status, first_seen_at, last_seen_at)
        values (p_tenant_id, v_candidate.source_category, v_candidate.evidence_run_id, 1, 1 + v_frustration / 100.0, 'open', now(), now())
        returning id into v_new_cluster_id;

        insert into knowledge_gap_cluster_members (cluster_id, evidence_run_id, similarity_to_representative, frustration_score)
        values (v_new_cluster_id, v_candidate.evidence_run_id, 1.0, v_frustration)
        on conflict (evidence_run_id) do nothing;

        v_new_clusters := v_new_clusters + 1;
      end if;
    end loop;

    -- promote any open cluster that just crossed this policy's bar
    -- (fixed: category-null policy now correctly matches every
    -- category's clusters, not just category-null ones)
    for v_cluster_id in
      select c.id from knowledge_gap_clusters c
      where c.tenant_id = p_tenant_id
        and c.status = 'open'
        and (v_policy.category is null or c.category = v_policy.category)
        and c.member_count >= v_policy.min_cluster_size
    loop
      perform promote_gap_cluster(v_cluster_id);
      v_promoted := v_promoted + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'new_members', v_new_members, 'new_clusters', v_new_clusters,
    'reopened_after_fix', v_reopened, 'promoted', v_promoted
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.cluster_learned_behavior_candidates(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy        record;
  v_candidate     record;
  v_verdict       text;
  v_nearest_id    uuid;
  v_nearest_status text;
  v_nearest_dist  double precision;
  v_new_cluster_id uuid;
  v_new_members   integer := 0;
  v_new_clusters  integer := 0;
  v_reopened      integer := 0;
  v_promoted      integer := 0;
  v_cluster_id    uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_learned_behavior_detection') then
    return jsonb_build_object('skipped', 'feature_disabled');
  end if;

  for v_policy in
    select * from de_learning_policies where tenant_id = p_tenant_id and enabled = true
  loop
    for v_candidate in
      select erd.id as decision_id, erd.evidence_run_id, erd.confidence, erd.source_category,
             erd.guardrail_rule_id, er.inquiry, er.inquiry_embedding, er.created_at, er.de_id,
             ht.status as task_status
      from evidence_run_decisions erd
      join evidence_runs er on er.id = erd.evidence_run_id
      join human_tasks ht on ht.id = erd.human_task_id
      where erd.tenant_id = p_tenant_id
        and erd.decision = 'needs_review'
        and ht.status in ('approved', 'rejected')
        and (v_policy.category is null or erd.source_category = v_policy.category)
        and er.inquiry_embedding is not null
        and er.de_id is not null
        and er.created_at >= now() - make_interval(days => v_policy.window_days)
        and not exists (select 1 from de_learned_behavior_cluster_members m where m.evidence_run_id = er.id)
      order by er.created_at asc
    loop
      -- reject -> the DE's proposed answer was wrong (correction evidence)
      -- approve -> the DE didn't need to be this cautious (overcaution evidence)
      v_verdict := case when v_candidate.task_status = 'rejected' then 'correction' else 'overcaution' end;

      select c.id, c.status, rer.inquiry_embedding <=> v_candidate.inquiry_embedding
        into v_nearest_id, v_nearest_status, v_nearest_dist
      from de_learned_behavior_clusters c
      join evidence_runs rer on rer.id = c.representative_run_id
      where c.tenant_id = p_tenant_id
        and c.de_id = v_candidate.de_id
        and c.verdict_type = v_verdict
        and (v_policy.category is null or c.category = v_candidate.source_category)
        and (v_verdict = 'correction' or c.guardrail_rule_id is not distinct from v_candidate.guardrail_rule_id)
        and c.last_seen_at >= now() - make_interval(days => v_policy.window_days)
      order by rer.inquiry_embedding <=> v_candidate.inquiry_embedding asc
      limit 1;

      if v_nearest_id is not null and v_nearest_dist < v_policy.similarity_threshold then
        insert into de_learned_behavior_cluster_members (cluster_id, evidence_run_id, human_task_id, similarity_to_representative)
        values (v_nearest_id, v_candidate.evidence_run_id, erd_human_task_id(v_candidate.decision_id), 1 - v_nearest_dist)
        on conflict (evidence_run_id) do nothing;

        if v_nearest_status = 'resolved' then
          update de_learned_behavior_clusters
          set status = 'open', member_count = member_count + 1, last_seen_at = now(),
              recurred_after_fix = true, recurrence_count = recurrence_count + 1,
              severity_score = (select count(*) from de_learned_behavior_cluster_members where cluster_id = v_nearest_id) + 10,
              updated_at = now()
          where id = v_nearest_id;
          v_reopened := v_reopened + 1;
        else
          update de_learned_behavior_clusters
          set member_count = member_count + 1, last_seen_at = now(),
              severity_score = (select count(*) from de_learned_behavior_cluster_members where cluster_id = v_nearest_id),
              updated_at = now()
          where id = v_nearest_id;
        end if;
        v_new_members := v_new_members + 1;
      else
        insert into de_learned_behavior_clusters (
          tenant_id, de_id, category, verdict_type, representative_run_id, guardrail_rule_id,
          member_count, severity_score, status, first_seen_at, last_seen_at
        )
        values (
          p_tenant_id, v_candidate.de_id, v_candidate.source_category, v_verdict, v_candidate.evidence_run_id,
          case when v_verdict = 'overcaution' then v_candidate.guardrail_rule_id else null end,
          1, 1, 'open', now(), now()
        )
        returning id into v_new_cluster_id;

        insert into de_learned_behavior_cluster_members (cluster_id, evidence_run_id, human_task_id, similarity_to_representative)
        values (v_new_cluster_id, v_candidate.evidence_run_id, erd_human_task_id(v_candidate.decision_id), 1.0)
        on conflict (evidence_run_id) do nothing;

        v_new_clusters := v_new_clusters + 1;
      end if;
    end loop;

    for v_cluster_id in
      select c.id from de_learned_behavior_clusters c
      where c.tenant_id = p_tenant_id
        and c.status = 'open'
        and c.category is not distinct from v_policy.category
        and c.member_count >= v_policy.min_cluster_size
    loop
      perform propose_learned_behavior(v_cluster_id);
      v_promoted := v_promoted + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'new_members', v_new_members, 'new_clusters', v_new_clusters,
    'reopened_after_fix', v_reopened, 'promoted', v_promoted
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_de_work_item(p_id uuid, p_status text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text, p_retry_delay_seconds integer DEFAULT 300)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row de_work_items;
begin
  select * into v_row from de_work_items where id = p_id for update;
  if v_row.id is null then raise exception 'work item not found'; end if;

  if p_status = 'failed' and v_row.attempts < v_row.max_attempts then
    update de_work_items
       set status = 'queued', last_error = p_error,
           scheduled_for = now() + make_interval(secs => greatest(1, p_retry_delay_seconds)),
           locked_at = null, locked_by = null, updated_at = now()
     where id = p_id;
    return 'requeued';
  end if;

  update de_work_items
     set status = p_status, result = coalesce(p_result, result), last_error = p_error,
         locked_at = null, locked_by = null, updated_at = now()
   where id = p_id;
  return p_status;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_ingestion_item(p_item_id uuid, p_doc_id uuid, p_duplicate boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item knowledge_ingestion_items; v_job knowledge_ingestion_jobs;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'not callable by tenant users';
  END IF;
  SELECT * INTO v_item FROM knowledge_ingestion_items WHERE id = p_item_id;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'ingestion item not found'; END IF;

  UPDATE knowledge_ingestion_items
     SET status = CASE WHEN p_duplicate THEN 'skipped_duplicate' ELSE 'succeeded' END,
         doc_id = p_doc_id, last_error = NULL, error_kind = NULL, updated_at = now()
   WHERE id = p_item_id;

  -- File the result into the job's target Space, if it had one. This is what
  -- turns an import into an organised library rather than a flat pile.
  SELECT * INTO v_job FROM knowledge_ingestion_jobs WHERE id = v_item.job_id;
  IF v_job.target_collection_id IS NOT NULL AND p_doc_id IS NOT NULL AND NOT p_duplicate THEN
    INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
    VALUES (v_job.tenant_id, p_doc_id, v_job.target_collection_id)
    ON CONFLICT DO NOTHING;
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.complete_signup(p_org_name text, p_industry text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user   uuid := auth.uid();
  v_profile profiles;
  v_slug   text;
  v_base_slug text;
  v_suffix int := 0;
  v_tenant tenants;
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated',
      'detail', 'You must be signed in to set up an organization.');
  end if;

  if coalesce(btrim(p_org_name), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'org_name_required');
  end if;

  select * into v_profile from profiles where user_id = v_user;
  if v_profile.id is null then
    return jsonb_build_object('ok', false, 'error', 'no_profile',
      'detail', 'No profile found for this user. Please contact support.');
  end if;

  if v_profile.tenant_id is not null then
    return jsonb_build_object('ok', false, 'error', 'already_has_tenant',
      'tenant_id', v_profile.tenant_id,
      'detail', 'This account is already linked to an organization.');
  end if;

  v_base_slug := lower(regexp_replace(btrim(p_org_name), '[^a-zA-Z0-9]+', '-', 'g'));
  v_base_slug := trim(both '-' from v_base_slug);
  if coalesce(v_base_slug, '') = '' then
    v_base_slug := 'org';
  end if;
  v_slug := v_base_slug;
  while exists (select 1 from tenants where slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := v_base_slug || '-' || v_suffix::text;
  end loop;

  insert into tenants (name, slug, industry, plan, status, settings, trial_ends_at)
  values (btrim(p_org_name), v_slug, nullif(btrim(coalesce(p_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, now() + interval '14 days')
  returning * into v_tenant;

  if v_tenant.id = v_demo_tenant_id then
    raise exception 'Refusing to provision the reserved demo tenant id';
  end if;

  -- role='tenant_owner' added here — this UPDATE only ever fires once
  -- per user (tenant_id is null guard), for the tenant this same user
  -- just created above, so granting real ownership at this exact
  -- point is safe and correct, not a broadened grant.
  update profiles
  set tenant_id = v_tenant.id,
      role = 'tenant_owner',
      updated_at = now()
  where user_id = v_user
    and tenant_id is null;

  if not found then
    delete from tenants where id = v_tenant.id;
    return jsonb_build_object('ok', false, 'error', 'already_has_tenant',
      'detail', 'This account is already linked to an organization.');
  end if;

  -- Full baseline contract: feature reconcile (starter DEs + playbooks)
  -- PLUS starter guardrails, onboarding template, and specialist desk —
  -- previously only the reconcile ran here, so new tenants were missing
  -- every feature whose seed data had only ever been installed on the
  -- dev tenant by hand.
  perform provision_tenant_baseline_internal(v_tenant.id);

  perform append_audit_event(
    v_tenant.id,
    coalesce(v_profile.full_name, 'owner'),
    'human',
    'Organization "' || v_tenant.name || '" created at signup by ' || coalesce(v_profile.full_name, 'the account owner'),
    'config_change',
    jsonb_build_object('kind', 'tenant_provisioned', 'tenant_id', v_tenant.id,
      'tenant_name', v_tenant.name, 'slug', v_tenant.slug, 'industry', v_tenant.industry,
      'user_id', v_user)
  );

  return jsonb_build_object('ok', true, 'tenant_id', v_tenant.id, 'slug', v_tenant.slug, 'name', v_tenant.name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_account_health(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
begin
  select tenant_id into v_tenant from customer_accounts where id = p_account;
  if v_tenant is null then
    return jsonb_build_object('error', 'account_not_found');
  end if;
  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() and tenant_id = v_tenant;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;
  return compute_account_health_core(p_account);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_account_health_core(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_acct       customer_accounts;
  v_weights    jsonb;
  v_thresholds jsonb;
  w_tickets    numeric; w_escal numeric; w_overdue numeric; w_activity numeric;
  n_open       integer; n_escal integer; n_overdue integer;
  v_last_act   timestamptz;
  v_days       integer;                  -- null = no activity ever
  p_tickets    numeric; p_escal numeric; p_overdue numeric; p_activity numeric;
  v_score      integer;
  v_components jsonb;
  v_at_risk    integer; v_healthy integer;
  v_new_status text;
begin
  select * into v_acct from customer_accounts where id = p_account;
  if not found then
    return jsonb_build_object('error', 'account_not_found');
  end if;

  select weights, thresholds into v_weights, v_thresholds
  from health_score_config where tenant_id = v_acct.tenant_id;
  v_weights    := coalesce(v_weights,    '{"open_tickets":25,"escalations":25,"overdue_invoices":30,"activity_recency":20}'::jsonb);
  v_thresholds := coalesce(v_thresholds, '{"at_risk_below":50,"healthy_above":75}'::jsonb);

  w_tickets  := coalesce((v_weights->>'open_tickets')::numeric, 25);
  w_escal    := coalesce((v_weights->>'escalations')::numeric, 25);
  w_overdue  := coalesce((v_weights->>'overdue_invoices')::numeric, 30);
  w_activity := coalesce((v_weights->>'activity_recency')::numeric, 20);
  v_at_risk  := coalesce((v_thresholds->>'at_risk_below')::int, 50);
  v_healthy  := coalesce((v_thresholds->>'healthy_above')::int, 75);

  -- ── real signals ──
  select count(*) filter (where status in ('open', 'pending')),
         count(*) filter (where status = 'escalated')
    into n_open, n_escal
  from support_tickets where account_id = p_account;

  select count(*) into n_overdue
  from renewal_invoices
  where account_id = p_account and status = 'sent'
    and due_date is not null and due_date < current_date;

  select max(created_at) into v_last_act
  from activity_events where account_id = p_account;
  v_days := case when v_last_act is null then null
                 else greatest(0, extract(day from now() - v_last_act)::int) end;

  -- ── bucketed penalties ──
  p_tickets  := case when n_open = 0 then 0 when n_open <= 2 then 0.4 * w_tickets
                     when n_open <= 5 then 0.7 * w_tickets else w_tickets end;
  p_escal    := case when n_escal = 0 then 0 when n_escal = 1 then 0.6 * w_escal else w_escal end;
  p_overdue  := case when n_overdue = 0 then 0 when n_overdue = 1 then 0.7 * w_overdue else w_overdue end;
  p_activity := case when v_days is null then w_activity
                     when v_days <= 7 then 0 when v_days <= 14 then 0.3 * w_activity
                     when v_days <= 30 then 0.6 * w_activity else w_activity end;

  v_score := greatest(0, least(100, round(100 - p_tickets - p_escal - p_overdue - p_activity)::int));

  v_components := jsonb_build_object(
    'score', v_score,
    'computed_at', now(),
    'open_tickets',     jsonb_build_object('count', n_open,    'penalty', round(p_tickets, 1),  'weight', w_tickets),
    'escalations',      jsonb_build_object('count', n_escal,   'penalty', round(p_escal, 1),    'weight', w_escal),
    'overdue_invoices', jsonb_build_object('count', n_overdue, 'penalty', round(p_overdue, 1),  'weight', w_overdue),
    'activity_recency', jsonb_build_object('days_since', v_days, 'penalty', round(p_activity, 1), 'weight', w_activity)
  );

  -- ── status flip per thresholds (never touches churned) ──
  v_new_status := v_acct.status;
  if v_acct.status = 'active' and v_score < v_at_risk then
    v_new_status := 'at_risk';
  elsif v_acct.status = 'at_risk' and v_score > v_healthy then
    v_new_status := 'active';
  end if;

  update customer_accounts
    set health_score = v_score, health_components = v_components, status = v_new_status
    where id = p_account;

  -- Audit ONLY on a status change — not on every recompute.
  if v_new_status <> v_acct.status then
    perform append_audit_event_internal(
      v_acct.tenant_id, 'Success DE', 'de',
      format('Account health flip — %s: %s → %s (score %s, at-risk < %s, healthy > %s)',
             v_acct.name, v_acct.status, v_new_status, v_score, v_at_risk, v_healthy),
      'config_change',
      jsonb_build_object('kind', 'health_recompute', 'account_id', p_account,
                         'old_status', v_acct.status, 'new_status', v_new_status,
                         'score', v_score, 'components', v_components));
  end if;

  return v_components || jsonb_build_object('status', v_new_status, 'status_changed', v_new_status <> v_acct.status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_confidence_dimensions(p_base_confidence integer, p_has_sources boolean DEFAULT NULL::boolean, p_identity_verified boolean DEFAULT NULL::boolean, p_action_ready boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'knowledge', greatest(0, least(100, coalesce(p_base_confidence, 0))),
    'grounding', case when p_has_sources is null then null when p_has_sources then 90 else 30 end,
    'identity',  case when p_identity_verified is null then null when p_identity_verified then 90 else 40 end,
    'action',    case when p_action_ready is null then null when p_action_ready then 80 else null end
  ));
$function$;

CREATE OR REPLACE FUNCTION public.compute_de_lifecycle_readiness(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_de digital_employees;
  v_tenant uuid;
  v_identity boolean;
  v_grants boolean;
  v_knowledge boolean;
  v_policies boolean;
  v_embedded boolean;
  v_qa_passed boolean;
  v_certified boolean;
  v_channel boolean;
  v_executed boolean;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return jsonb_build_object('error', 'not_found'); end if;
  v_tenant := v_de.tenant_id;

  -- Humans must belong to the workspace; trusted server contexts pass.
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth_tenant_id() is distinct from v_tenant then
      raise exception 'not a member of this workspace';
    end if;
  end if;

  v_identity := coalesce(v_de.name, '') <> '' and coalesce(v_de.description, '') <> ''
    and (coalesce(v_de.department, '') <> '' or coalesce(v_de.workspace, '') <> '')
    and coalesce(array_length(v_de.responsibilities, 1), 0) >= 1;

  v_grants := exists (select 1 from data_access_grants
    where tenant_id = v_tenant and subject_kind = 'de' and subject_id = p_de_id);

  v_knowledge := exists (select 1 from knowledge_docs d
    where d.tenant_id = v_tenant
      and (d.visibility = 'tenant'
           or exists (select 1 from knowledge_doc_scopes s
                      where s.doc_id = d.id and s.subject_kind = 'de' and s.subject_id = p_de_id)));

  v_policies := exists (select 1 from guardrail_rules where tenant_id = v_tenant and active);

  v_embedded := exists (select 1 from knowledge_doc_chunks c
    join knowledge_docs d on d.id = c.doc_id
    where d.tenant_id = v_tenant and c.embedding is not null
      and (d.visibility = 'tenant'
           or exists (select 1 from knowledge_doc_scopes s
                      where s.doc_id = d.id and s.subject_kind = 'de' and s.subject_id = p_de_id)));

  v_qa_passed := coalesce((select r.status = 'passed' from eval_runs r
    where r.tenant_id = v_tenant
    order by coalesce(r.finished_at, r.started_at) desc limit 1), false);

  v_certified := exists (select 1 from de_lifecycle_events
    where tenant_id = v_tenant and de_id = p_de_id and to_stage = 'certified' and actor_id is not null);

  v_channel := exists (select 1 from data_access_grants g
      where g.tenant_id = v_tenant and g.subject_kind = 'de' and g.subject_id = p_de_id
        and access_permission_level(g.permission) >= access_permission_level('search'))
    or exists (select 1 from widget_keys where tenant_id = v_tenant and active);

  v_executed := exists (select 1 from evidence_runs where tenant_id = v_tenant and de_id = p_de_id);

  return jsonb_build_object(
    'stage', v_de.lifecycle_status,
    'status', v_de.status,
    'criteria', jsonb_build_object(
      'configured', jsonb_build_object(
        'identity_complete', v_identity,
        'detail', 'Name, description, a department or workspace, and at least one responsibility.'),
      'trained', jsonb_build_object(
        'control_fabric_grant', v_grants,
        'knowledge_in_scope', v_knowledge,
        'active_guardrails', v_policies,
        'detail', 'At least one system-access grant, knowledge this employee can see, and active workspace guardrails.'),
      'tested', jsonb_build_object(
        'knowledge_embedded', v_embedded,
        'detail', 'The knowledge in scope is actually searchable (embedded), so answers can cite it.'),
      'certified', jsonb_build_object(
        'golden_qa_passed', v_qa_passed,
        'scope', 'workspace',
        'detail', 'The latest golden Q&A run passed. (Suite is workspace-level today — per-employee suites arrive with Skills, DE-C1.)'),
      'published', jsonb_build_object(
        'certified_by_human', v_certified,
        'detail', 'A named workspace owner/admin recorded certification.'),
      'assigned', jsonb_build_object(
        'has_work_channel', v_channel,
        'detail', 'A searchable system grant (inbox) or an active site widget key.'),
      'active', jsonb_build_object(
        'first_live_execution', v_executed,
        'detail', 'At least one real evidence run attributed to this employee.')
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_inquiry_confidence(p_inputs jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select greatest(0, least(97,
    40
    + least(24, 8 * coalesce((p_inputs->>'knowledge_hits')::int, 0))
    + least(24, 8 * coalesce((p_inputs->>'history_corroborations')::int, 0))
    + case when coalesce((p_inputs->>'account_context_found')::boolean, false) then 12 else 0 end
    - 15 * coalesce((p_inputs->>'systems_failed')::int, 0)
    - 15 * coalesce((p_inputs->>'systems_denied_no_access')::int, 0)
  ))::integer;
$function$;

CREATE OR REPLACE FUNCTION public.compute_tenant_health(p_force boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_last   timestamptz;
  v_n      integer := 0;
  v_flips  integer := 0;
  v_acct   record;
  v_res    jsonb;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;

  insert into health_score_config (tenant_id) values (v_tenant)
  on conflict (tenant_id) do nothing;

  select last_computed_at into v_last from health_score_config where tenant_id = v_tenant;
  if not p_force and v_last is not null and v_last > now() - interval '1 hour' then
    return jsonb_build_object('computed', 0, 'skipped', true, 'last_computed_at', v_last);
  end if;

  for v_acct in select id from customer_accounts where tenant_id = v_tenant and status <> 'churned' loop
    v_res := compute_account_health_core(v_acct.id);
    v_n := v_n + 1;
    if coalesce((v_res->>'status_changed')::boolean, false) then v_flips := v_flips + 1; end if;
  end loop;

  update health_score_config set last_computed_at = now() where tenant_id = v_tenant;
  return jsonb_build_object('computed', v_n, 'status_flips', v_flips, 'skipped', false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_tenant_health_service(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_n     integer := 0;
  v_flips integer := 0;
  v_acct  record;
  v_res   jsonb;
begin
  for v_acct in select id from customer_accounts where tenant_id = p_tenant_id and status <> 'churned' loop
    v_res := compute_account_health_core(v_acct.id);
    v_n := v_n + 1;
    if coalesce((v_res->>'status_changed')::boolean, false) then v_flips := v_flips + 1; end if;
  end loop;
  insert into health_score_config (tenant_id, last_computed_at) values (p_tenant_id, now())
  on conflict (tenant_id) do update set last_computed_at = now();
  return jsonb_build_object('computed', v_n, 'status_flips', v_flips);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_trust_evidence(p_de_id uuid, p_action_category text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_policy trust_policies;
begin
  select tenant_id, coalesce(is_active, true) into v_tenant, v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_tenant is null then
    raise exception 'not a member of any tenant';
  end if;
  if not v_is_active then
    raise exception 'account is deactivated';
  end if;

  select * into v_policy
  from trust_policies
  where tenant_id = v_tenant
    and action_category = p_action_category
    and (p_de_id is null or de_id is null or de_id = p_de_id)
  order by (de_id is not null and de_id = p_de_id) desc, (de_id is null) asc
  limit 1;
  if not found then
    raise exception 'no trust policy for category %', p_action_category;
  end if;

  return trust_evidence_for(v_policy);
end;
$function$;

CREATE OR REPLACE FUNCTION public.conclude_objective_verified(p_tenant_id uuid, p_objective_id uuid, p_assessment text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enforce boolean := false;
  v_master boolean; v_tenant_on boolean; v_mode text;
  v_assess jsonb; v_final text := p_assessment;
begin
  begin
    select (value = 'true') into v_master from platform_config where key = 'definition_of_done.enabled';
    if coalesce(v_master, false) then
      select is_feature_enabled_internal(p_tenant_id, 'definition_of_done') into v_tenant_on;
      if v_tenant_on is true then
        select value into v_mode from platform_config where key = 'definition_of_done.mode';
        v_enforce := coalesce(v_mode, 'shadow') = 'enforce';
      end if;
    end if;
  exception when others then v_enforce := false; end;   -- flag axis fails to current behavior

  if p_assessment = 'achieved' then
    v_assess := assess_definition_of_done(p_tenant_id, 'objective', p_objective_id, p_objective_id);
    begin
      insert into definition_of_done_log (tenant_id, writer, scope, scope_id, objective_id, verdict, would_withhold, enforced)
      values (p_tenant_id, 'objective', 'objective', p_objective_id, p_objective_id, v_assess, not (v_assess->>'verified')::boolean, v_enforce);
    exception when others then null; end;
    if v_enforce and not (v_assess->>'verified')::boolean then
      v_final := 'in_progress';   -- withhold; re-reviewed once the evidence lands
    end if;
  end if;

  update de_objectives set status = v_final, updated_at = now()
    where id = p_objective_id and tenant_id = p_tenant_id;
  return v_final;
end $function$;

CREATE OR REPLACE FUNCTION public.conclude_objective_wake(p_objective_id uuid, p_assessment text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_assessment = 'achieved' then
    update de_objectives set status = 'achieved', next_wake_at = null, updated_at = now()
     where id = p_objective_id and status in ('open', 'in_progress');
  elsif p_assessment = 'blocked' then
    update de_objectives set status = 'blocked', next_wake_at = null, updated_at = now()
     where id = p_objective_id and status in ('open', 'in_progress');
  elsif p_assessment = 'continue' then
    null;
  else
    raise exception 'assessment must be achieved | blocked | continue';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.count_pending_knowledge_gaps(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  perform public._assert_caller_tenant(p_tenant_id);

  select count(*) into v_count
  from knowledge_revision_requests
  where tenant_id = p_tenant_id
    and status = 'pending_approval';

  return coalesce(v_count, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_browser_operation(p_de_id uuid, p_system_key text, p_instruction text, p_max_steps integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s de_connected_systems; v_tenant uuid; v_domain text; v_cred text; v_task uuid; v_ht uuid;
  v_de_name text; v_goal text; v_title text;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  -- de-work (service) or a tenant admin acting for the DE.
  IF NOT v_is_service AND NOT (v_tenant = public.auth_tenant_id()
       AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin','tenant_manager'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF NOT public.is_feature_enabled_internal(v_tenant, 'computer_use') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'browser_operator_disabled');
  END IF;

  SELECT * INTO s FROM de_connected_systems
    WHERE de_id = p_de_id AND system_key = p_system_key AND active AND can_operate;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_not_operable'); END IF;

  v_domain := public.operate_domain_of(s);
  IF v_domain IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_operate_domain'); END IF;
  IF nullif(btrim(coalesce(p_instruction,'')),'') IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'instruction_required'); END IF;

  SELECT coalesce(persona_name, name, 'DE') INTO v_de_name FROM digital_employees WHERE id = p_de_id;
  v_title := format('Operate %s', coalesce(s.label, p_system_key));
  v_goal  := format(E'In %s (%s): %s\n\nWork within this app only. When finished, report the outcome as JSON: what you changed/found and any IDs. Do not perform irreversible actions (payments, deletions, sending) — hand those to a human.',
                    coalesce(s.label, p_system_key), v_domain, btrim(p_instruction));

  INSERT INTO computer_use_tasks (tenant_id, de_id, goal, allowed_domains, max_steps, engine, credential_policy, title)
  VALUES (v_tenant, p_de_id, v_goal, ARRAY[v_domain], greatest(1, least(50, coalesce(p_max_steps,20))),
          'browser_dom',
          CASE WHEN s.login_secret_id IS NOT NULL THEN 'vault_injected' ELSE 'human_login' END,
          v_title)
  RETURNING id INTO v_task;

  INSERT INTO human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  VALUES (v_tenant, 'approval_gate', 'de',
    format('%s wants to operate %s', v_de_name, coalesce(s.label, p_system_key)),
    format(E'%s wants to run this in %s (%s):\n\n%s\n\nIt stays on %s, is limited to %s steps, never performs payments/deletions without you, and records every step.',
           v_de_name, coalesce(s.label, p_system_key), v_domain, btrim(p_instruction), v_domain, greatest(1, least(50, coalesce(p_max_steps,20)))),
    'computer_use_tasks', v_task)
  RETURNING id INTO v_ht;
  UPDATE computer_use_tasks SET human_task_id = v_ht, updated_at = now() WHERE id = v_task;

  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
    format('%s requested a browser operation in %s', v_de_name, coalesce(s.label, p_system_key)), 'de_consultation',
    jsonb_build_object('kind','browser_operation_requested','task_id',v_task,'system_key',p_system_key,'domain',v_domain));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'task_id', v_task, 'domain', v_domain,
    'credential_policy', CASE WHEN s.login_secret_id IS NOT NULL THEN 'vault_injected' ELSE 'human_login' END,
    'status', 'pending_approval');
END; $function$;

CREATE OR REPLACE FUNCTION public.create_config_schema(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_fields jsonb DEFAULT '[]'::jsonb, p_tags text[] DEFAULT '{}'::text[])
 RETURNS TABLE(schema_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, name text, fields jsonb, tags text[], created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_schema_id UUID := gen_random_uuid();
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO de_config_schemas (schema_id, tenant_id, entity_kind, entity_id, name, fields, tags)
  VALUES (v_schema_id, p_tenant_id, p_entity_kind, p_entity_id, p_name, p_fields, p_tags);
  RETURN QUERY SELECT * FROM de_config_schemas s WHERE s.schema_id = v_schema_id;
END$function$;

CREATE OR REPLACE FUNCTION public.create_custom_metric(p_tenant_id uuid, p_name text, p_key text, p_type text, p_description text, p_unit text DEFAULT NULL::text, p_calculation_rule text DEFAULT NULL::text, p_query_template text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[], p_thresholds jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(metric_id uuid, tenant_id uuid, name text, key text, type text, description text, unit text, calculation_rule text, query_template text, tags text[], thresholds jsonb, created_at timestamp with time zone, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_metric_id UUID := gen_random_uuid();
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO customer_metrics (
    metric_id, tenant_id, name, key, type, description, unit,
    calculation_rule, query_template, tags, thresholds, created_by
  ) VALUES (
    v_metric_id, p_tenant_id, p_name, p_key, p_type, p_description, p_unit,
    p_calculation_rule, p_query_template, p_tags, p_thresholds, auth.uid()
  );
  RETURN QUERY SELECT * FROM customer_metrics cm WHERE cm.metric_id = v_metric_id;
END$function$;

CREATE OR REPLACE FUNCTION public.create_de_mission(p_de_id uuid, p_directive text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_id uuid;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF length(btrim(coalesce(p_directive,''))) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'directive_too_short');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees
                 WHERE id = p_de_id AND tenant_id = v_tenant AND status = 'active') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_inactive_de');
  END IF;
  INSERT INTO de_missions (tenant_id, de_id, directive_text, created_by)
  VALUES (v_tenant, p_de_id, btrim(p_directive), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'mission_id', v_id);
END $function$;

CREATE OR REPLACE FUNCTION public.create_de_team_mission(p_target_spec jsonb, p_directive text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_id uuid; v_kind text; v_routing text;
  v_de_ids uuid[]; v_sup uuid; v_arch text; v_bad int;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF length(btrim(coalesce(p_directive,''))) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'directive_too_short');
  END IF;

  v_kind    := p_target_spec->>'kind';
  v_routing := coalesce(p_target_spec->>'routing', 'auto');
  IF v_kind NOT IN ('archetype','explicit','supervisor') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_target_kind');
  END IF;
  IF v_routing NOT IN ('auto','owner_continuity','least_loaded','round_robin') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_routing');
  END IF;

  IF v_kind = 'archetype' THEN
    v_arch := p_target_spec->>'archetype_key';
    IF v_arch IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'archetype_required');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM digital_employees
                   WHERE tenant_id = v_tenant AND archetype_key = v_arch AND status = 'active') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'no_active_de_for_archetype');
    END IF;

  ELSIF v_kind = 'explicit' THEN
    BEGIN
      SELECT array_agg((x)::uuid) INTO v_de_ids
        FROM jsonb_array_elements_text(coalesce(p_target_spec->'de_ids', '[]'::jsonb)) x;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_de_ids');
    END;
    IF v_de_ids IS NULL OR array_length(v_de_ids, 1) IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'de_ids_required');
    END IF;
    SELECT count(*) INTO v_bad FROM unnest(v_de_ids) d
     WHERE NOT EXISTS (SELECT 1 FROM digital_employees
                       WHERE id = d AND tenant_id = v_tenant AND status = 'active');
    IF v_bad > 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_foreign_de');
    END IF;

  ELSE  -- supervisor
    BEGIN
      v_sup := (p_target_spec->>'supervisor_de_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_supervisor_id');
    END;
    IF v_sup IS NULL OR NOT EXISTS (SELECT 1 FROM digital_employees
          WHERE id = v_sup AND tenant_id = v_tenant AND status = 'active') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_foreign_supervisor');
    END IF;
  END IF;

  INSERT INTO de_missions (tenant_id, de_id, target_spec, directive_text, created_by)
  VALUES (v_tenant, NULL, p_target_spec, btrim(p_directive), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'mission_id', v_id);
END $function$;

CREATE OR REPLACE FUNCTION public.create_improvement_review(p_improvement_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp de_improvements; v_task uuid; v_name text;
begin
  select * into imp from de_improvements where id = p_improvement_id;
  if imp.id is null then raise exception 'improvement not found'; end if;
  if imp.status <> 'replayed' then
    raise exception 'improvement must have a PASSING replay before review (status is %)', imp.status;
  end if;

  select coalesce(persona_name, name, 'DE') into v_name from digital_employees where id = imp.de_id;
  insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  values (imp.tenant_id, 'knowledge_revision', 'system',
    format('Approve knowledge fix proposed by %s — "%s"', v_name, left(imp.proposed_title, 80)),
    format(E'%s answered a question wrongly and proposes this knowledge fix.\n\nFailing question: %s\n\nWhy it failed: %s\n\nProposed article "%s":\n%s\n\nReplay proof: re-answering WITH this fix scored %s/100 (was %s/100); golden set %s/%s passed. Approving publishes the article scoped to this employee; rejecting discards it.',
      v_name, left(imp.failure_question, 300), left(imp.failure_rationale, 400),
      imp.proposed_title, left(imp.proposed_content, 1500),
      coalesce(imp.replay->'after'->>'score','?'), coalesce(imp.replay->'before'->>'score','?'),
      coalesce(imp.replay->'golden'->>'passed','?'), coalesce(imp.replay->'golden'->>'total','?')),
    'de_improvements', imp.id)
  returning id into v_task;

  update de_improvements set human_task_id = v_task, status = 'review_pending', updated_at = now()
   where id = p_improvement_id;
  return v_task;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_ingestion_job(p_label text, p_source_kind text, p_items jsonb, p_target_collection_id uuid DEFAULT NULL::uuid, p_source_ref text DEFAULT NULL::text, p_connector_id uuid DEFAULT NULL::uuid, p_publish_mode text DEFAULT 'published'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_job uuid; v_n int; v_lvl int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_publish_mode NOT IN ('published','draft') THEN
    RAISE EXCEPTION 'publish mode must be published or draft';
  END IF;

  SELECT coalesce(max(knowledge_permission_rank(g.permission)), 0) INTO v_lvl
    FROM knowledge_access_grants g
   WHERE g.tenant_id = v_tenant AND g.resource_type = 'workspace'
     AND knowledge_grant_matches_caller(g);
  IF v_lvl < 2 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: adding knowledge requires contributor';
  END IF;
  -- Publishing straight through is a publisher act. A contributor may still
  -- import — their work lands as drafts, which is exactly the review flow.
  IF p_publish_mode = 'published' AND v_lvl < 4 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: publishing on import requires publisher — import as draft instead';
  END IF;

  IF p_target_collection_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM knowledge_collections c
                      WHERE c.id = p_target_collection_id AND c.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'target collection does not belong to this workspace';
  END IF;

  INSERT INTO knowledge_ingestion_jobs (tenant_id, label, source_kind, source_ref,
                                        target_collection_id, connector_id, created_by, publish_mode)
  VALUES (v_tenant, p_label, p_source_kind, p_source_ref,
          p_target_collection_id, p_connector_id, auth.uid(), p_publish_mode)
  RETURNING id INTO v_job;

  INSERT INTO knowledge_ingestion_items (job_id, tenant_id, source_ref, title, byte_size, mime_type, raw_content)
  SELECT v_job, v_tenant,
         coalesce(e->>'source_ref', e->>'url', e->>'filename', 'item'),
         e->>'title', (e->>'byte_size')::bigint, e->>'mime_type', e->>'content'
    FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) e;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE EXCEPTION 'an ingestion job needs at least one item'; END IF;
  RETURN v_job;
END $function$;

CREATE OR REPLACE FUNCTION public.create_knowledge_collection(p_parent_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_parent_id IS NULL THEN
    RAISE EXCEPTION 'a collection lives inside a space — use create_knowledge_space for a new top-level space';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_parent_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'that parent does not belong to this workspace';
  END IF;
  -- Administering the branch, not reading it (mig 359's distinction).
  IF knowledge_my_admin_level(p_parent_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: organising knowledge requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a collection needs a name'; END IF;

  -- The 341 trigger enforces depth <= 3, no cycles and no cross-workspace parent.
  INSERT INTO knowledge_collections (tenant_id, parent_id, name, description, is_space)
  VALUES (v_tenant, p_parent_id, btrim(p_name), nullif(btrim(coalesce(p_description,'')),''), false)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.create_knowledge_space(p_name text, p_description text DEFAULT NULL::text, p_icon text DEFAULT 'folder'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: creating a space requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a space needs a name'; END IF;

  INSERT INTO knowledge_collections (tenant_id, parent_id, name, description, is_space, icon)
  VALUES (v_tenant, NULL, btrim(p_name), nullif(btrim(coalesce(p_description,'')),''), true, p_icon)
  RETURNING id INTO v_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Created the space "%s"', btrim(p_name)), 'access_control',
    jsonb_build_object('space_id', v_id));
  RETURN v_id;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'a space called "%" already exists', btrim(p_name);
END $function$;

CREATE OR REPLACE FUNCTION public.create_onboarding_project(p_account_id uuid, p_version_id uuid, p_name text DEFAULT NULL::text, p_target date DEFAULT NULL::date, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant  uuid;
  v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
  v_is_active boolean;
  v_acct    customer_accounts;
  v_ver     onboarding_template_versions;
  v_state   jsonb;
  v_proj_id uuid;
  v_name    text;
  v_created_by uuid;
begin
  if v_is_service then
    if p_tenant_id is null then
      return jsonb_build_object('error', 'tenant_id_required_for_service_call');
    end if;
    v_tenant := p_tenant_id;
    v_created_by := null;
  else
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
    if v_is_active is false then raise exception 'account is deactivated'; end if;
    v_tenant := auth_tenant_id();
    if v_tenant is null then raise exception 'no tenant for caller'; end if;
    v_created_by := auth.uid();
  end if;

  select * into v_acct from customer_accounts where id = p_account_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'account_not_found'); end if;

  select * into v_ver from onboarding_template_versions where id = p_version_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'template_version_not_found'); end if;

  select jsonb_agg(jsonb_build_object(
    'key', i->>'key', 'status', 'pending', 'assignee', null, 'note', ''))
    into v_state
  from jsonb_array_elements(v_ver.items) i;

  v_name := coalesce(nullif(trim(p_name), ''), format('%s — %s', v_acct.name, v_ver.name));

  insert into onboarding_projects (tenant_id, account_id, template_version_id, name, target_golive, items_state, created_by)
  values (v_tenant, p_account_id, p_version_id, v_name, p_target, coalesce(v_state, '[]'::jsonb), v_created_by)
  returning id into v_proj_id;

  perform append_audit_event_internal(
    v_tenant, case when v_is_service then 'Playbook DE' else 'You' end, case when v_is_service then 'de' else 'human' end,
    format('Onboarding project created — %s (%s v%s, %s items)', v_name, v_ver.name, v_ver.version, jsonb_array_length(v_ver.items)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_project_create', 'project_id', v_proj_id,
                       'account_id', p_account_id, 'version_id', p_version_id));

  insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
  values (v_tenant, p_account_id, case when v_is_service then 'Playbook DE' else 'You' end, case when v_is_service then 'de' else 'human' end, 'config_change',
          format('Onboarding started — %s', v_acct.name));

  return jsonb_build_object('project_id', v_proj_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_outbound_draft(p_tenant_id uuid, p_de_id uuid, p_recipient text, p_channel text, p_subject text, p_body text, p_reason text DEFAULT ''::text, p_source_kind text DEFAULT 'manual'::text, p_source_ref uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_draft uuid; v_task uuid; v_name text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'create_outbound_draft is service-role only';
  end if;
  if p_body is null or length(trim(p_body)) < 10 then
    raise exception 'draft body required (min 10 chars)';
  end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = p_tenant_id) then
    raise exception 'de not in tenant';
  end if;

  insert into outbound_drafts (tenant_id, de_id, recipient_ref, channel, subject, body, reason, source_kind, source_ref)
  values (p_tenant_id, p_de_id, left(coalesce(p_recipient, ''), 200),
          case when p_channel in ('email','sms','chat','other') then p_channel else 'email' end,
          left(coalesce(p_subject, ''), 200), p_body, left(coalesce(p_reason, ''), 500),
          case when p_source_kind in ('work_item','objective','conversation','manual') then p_source_kind else 'manual' end,
          p_source_ref)
  returning id into v_draft;

  select coalesce(persona_name, name, 'DE') into v_name from digital_employees where id = p_de_id;
  insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  values (p_tenant_id, 'approval_gate', 'de',
    format('Outbound draft from %s — to %s', v_name, left(coalesce(p_recipient, 'recipient'), 60)),
    format(E'%s drafted an outbound %s message and needs your approval. NOTHING sends automatically — approving means you deliver it via your own channel.\n\nTo: %s\nSubject: %s\n\n%s\n\nWhy: %s',
           v_name, case when p_channel in ('email','sms','chat','other') then p_channel else 'email' end,
           coalesce(p_recipient, '—'), coalesce(nullif(p_subject, ''), '—'), p_body, coalesce(nullif(p_reason, ''), '—')),
    'outbound_drafts', v_draft)
  returning id into v_task;

  update outbound_drafts set human_task_id = v_task, updated_at = now() where id = v_draft;
  return v_draft;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_principal_group(p_name text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF public.knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a group needs a name'; END IF;

  INSERT INTO knowledge_principal_groups (tenant_id, name, description, created_by)
  VALUES (v_tenant, btrim(p_name), nullif(btrim(coalesce(p_description,'')), ''), auth.uid())
  RETURNING id INTO v_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Created the group "%s"', btrim(p_name)), 'access_control',
    jsonb_build_object('group_id', v_id));
  RETURN v_id;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'a group called "%" already exists', btrim(p_name);
END $function$;

CREATE OR REPLACE FUNCTION public.create_tenant_api_key(p_tenant_id uuid, p_name text, p_scopes text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_raw text;
  v_hash text;
  v_hint text;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can create an API key';
  end if;
  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'name is required';
  end if;

  v_raw := encode(gen_random_bytes(24), 'hex');
  v_hash := encode(digest(v_raw, 'sha256'), 'hex');
  v_hint := 'dt_live_' || repeat('•', 8) || right(v_raw, 4);

  insert into tenant_api_keys (tenant_id, name, display_hint, key_hash, scopes, created_by)
  values (p_tenant_id, trim(p_name), v_hint, v_hash, coalesce(p_scopes, '{}'), auth.uid())
  returning id into v_id;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('API key created: %s', trim(p_name)),
    'config_change',
    jsonb_build_object('kind', 'api_key_created', 'key_id', v_id, 'name', trim(p_name), 'scopes', p_scopes)
  );

  return jsonb_build_object('id', v_id, 'raw_key', 'dt_live_' || v_raw, 'display_hint', v_hint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_workforce_assistant_de(p_tenant_id uuid, p_charter_override jsonb DEFAULT NULL::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_de_id UUID;
  v_assistant_charter JSONB;
BEGIN
  IF NOT (p_tenant_id = auth_tenant_id() AND auth_has_tenant_role(array['tenant_owner', 'tenant_admin'])) THEN
    RAISE EXCEPTION 'Unauthorized: must be tenant admin';
  END IF;

  SELECT id INTO v_de_id FROM digital_employees WHERE tenant_id = p_tenant_id AND is_workforce_assistant = true;
  IF v_de_id IS NOT NULL THEN RETURN json_build_object('success', false, 'error', 'Workforce Assistant already exists'); END IF;

  v_assistant_charter := jsonb_build_object('name', 'Workforce Assistant', 'persona', 'You are a trusted advisor helping this organization hire, improve, and manage their digital workforce.', 'responsibilities', jsonb_build_array('Help hire new DEs', 'Suggest improvements to underperforming DEs', 'Monitor team performance', 'Help retire DEs', 'Train new tenants on DreamTeamAI features'), 'guardrails', jsonb_build_array('Never auto-approve DE changes without explicit user consent', 'Always show evidence for recommendations', 'Prioritize user success', 'Escalate ambiguous decisions'));
  v_assistant_charter := COALESCE(v_assistant_charter || p_charter_override, v_assistant_charter);

  INSERT INTO digital_employees (tenant_id, name, status, charter, is_workforce_assistant, is_product_expert, created_by) VALUES (p_tenant_id, 'Workforce Assistant', 'active', v_assistant_charter, true, true, auth.uid()) RETURNING id INTO v_de_id;
  INSERT INTO de_deployment_stages (de_id, stage) VALUES (v_de_id, 'live');

  RETURN json_build_object('success', true, 'de_id', v_de_id, 'message', 'Workforce Assistant provisioned successfully', 'charter', v_assistant_charter);
END;
$function$;

CREATE OR REPLACE FUNCTION public.de_certification_status(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_current text;
  v_fresh boolean;
  v_has_pass boolean;
  v_disp role_certifications;   -- the cert to DISPLAY (prefer a fresh one)
  v_any  role_certifications;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return jsonb_build_object('state', 'unknown'); end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;

  v_current := public.de_config_fingerprint(p_de_id);

  -- Freshness is decided the SAME way the go-live gate decides it: does ANY
  -- passing cert match the current config fingerprint? (Not "is the newest
  -- passing cert fresh" — two passing certs can share a timestamp.)
  v_fresh := exists (
    select 1 from role_certifications
     where de_id = p_de_id and status = 'passed'
       and config_fingerprint is not distinct from v_current);
  v_has_pass := exists (
    select 1 from role_certifications where de_id = p_de_id and status = 'passed');

  -- Display cert: the matching fresh one if present, else the newest passing.
  select * into v_disp from role_certifications
    where de_id = p_de_id and status = 'passed'
    order by (config_fingerprint is not distinct from v_current) desc,
             evaluated_at desc nulls last, created_at desc limit 1;
  select * into v_any from role_certifications
    where de_id = p_de_id
    order by evaluated_at desc nulls last, created_at desc limit 1;

  return jsonb_build_object(
    'state', case
      when not v_has_pass and v_any.id is null then 'uncertified'
      when not v_has_pass then 'failed'
      when v_fresh then 'certified'
      else 'stale'
    end,
    'fresh', v_fresh,
    'latest_passed', case when v_disp.id is null then null else jsonb_build_object(
      'id', v_disp.id, 'score_pct', v_disp.score_pct, 'threshold_pct', v_disp.threshold_pct,
      'evaluated_at', v_disp.evaluated_at, 'archetype_key', v_disp.archetype_key,
      'certified_fingerprint', v_disp.config_fingerprint) end,
    'current_fingerprint', v_current,
    'latest_status', v_any.status
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_config_fingerprint(p_de_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_de digital_employees;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return null; end if;
  return public.de_config_fingerprint_row(v_de);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_eval_quality(p_tenant_id uuid, p_de_id uuid, p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'n', count(*),
    'avg_score', coalesce(round(avg(score)), 0),
    'pass_rate', coalesce(round(100.0 * count(*) filter (where verdict = 'pass') / nullif(count(*), 0)), 0),
    'fail_rate', coalesce(round(100.0 * count(*) filter (where verdict = 'fail') / nullif(count(*), 0)), 0),
    'by_source', coalesce((select jsonb_object_agg(source, c) from
       (select source, count(*) c from eval_judgments
        where tenant_id = p_tenant_id and de_id = p_de_id
          and created_at >= now() - make_interval(days => greatest(1, p_days)) group by source) s), '{}'::jsonb)
  )
  from eval_judgments
  where tenant_id = p_tenant_id and de_id = p_de_id
    and created_at >= now() - make_interval(days => greatest(1, p_days));
$function$;

CREATE OR REPLACE FUNCTION public.de_governance_sweep_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_cert record;
  v_pip record;
  v_inc record;
  m record;
  v_warned integer := 0;
  v_expired integer := 0;
  v_pip_completed integer := 0;
  v_pip_failed integer := 0;
  v_sla integer := 0;
  v_de_name text;
  v_passing boolean;
begin
  -- (a) Expiring within 14 days → one warning audit event per cert.
  for v_cert in
    select c.*, de.name as de_name from de_certifications c
    join digital_employees de on de.id = c.de_id
    where c.status = 'active' and c.warned_at is null
      and c.expires_at <= now() + interval '14 days' and c.expires_at > now()
  loop
    update de_certifications set warned_at = now() where id = v_cert.id;
    perform append_audit_event_internal(
      v_cert.tenant_id, 'Governance sweep', 'system',
      format('%s''s %s certification expires %s — recertify to keep it current', v_cert.de_name, v_cert.cert_type, to_char(v_cert.expires_at, 'YYYY-MM-DD')),
      'config_change',
      jsonb_build_object('kind', 'certification_expiring', 'cert_id', v_cert.id, 'de_id', v_cert.de_id)
    );
    v_warned := v_warned + 1;
  end loop;

  -- (b) Expired → status flip + incident (dedup via unique source key).
  for v_cert in
    select c.*, de.name as de_name from de_certifications c
    join digital_employees de on de.id = c.de_id
    where c.status = 'active' and c.expires_at <= now()
  loop
    update de_certifications set status = 'expired' where id = v_cert.id;
    insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
    values (v_cert.tenant_id, v_cert.de_id, 'certification_expired', 'warning',
      format('%s certification expired — %s', initcap(v_cert.cert_type), v_cert.de_name),
      jsonb_build_object('cert_id', v_cert.id, 'cert_type', v_cert.cert_type, 'scope', v_cert.scope,
                         'issued_by', v_cert.issued_by_name, 'expired_at', v_cert.expires_at),
      'de_certifications', v_cert.id, v_cert.expires_at)
    on conflict (tenant_id, source_table, source_id) do nothing;
    v_expired := v_expired + 1;
  end loop;

  -- (c) Overdue open PIPs → RE-MEASURE on a fresh 4-week window: now
  --     passing → completed (closed loop); still failing → 'failed' +
  --     CRITICAL incident for human trust review.
  for v_pip in
    select i.* from de_development_items i
    where i.item_type = 'pip' and i.source = 'detected'
      and i.status in ('proposed', 'in_progress') and i.due_date < current_date
  loop
    select name into v_de_name from digital_employees where id = v_pip.de_id;
    v_passing := false;
    for m in select * from get_de_performance_metrics(v_pip.tenant_id, 4) where de_id = v_pip.de_id loop
      v_passing := m.total_decisions >= 10
        and m.escalation_rate <= 50 and m.avg_confidence >= 50 and m.error_rate <= 15;
    end loop;

    if v_passing then
      update de_development_items set status = 'completed', completed_at = now(), updated_at = now() where id = v_pip.id;
      perform append_audit_event_internal(
        v_pip.tenant_id, 'Governance sweep', 'system',
        format('%s met its Performance Improvement Plan targets — PIP closed', coalesce(v_de_name, 'Employee')),
        'config_change',
        jsonb_build_object('kind', 'pip_completed', 'item_id', v_pip.id, 'de_id', v_pip.de_id)
      );
      v_pip_completed := v_pip_completed + 1;
    else
      update de_development_items set status = 'failed', updated_at = now() where id = v_pip.id;
      insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
      values (v_pip.tenant_id, v_pip.de_id, 'pip_failed', 'critical',
        format('Performance Improvement Plan failed — %s', coalesce(v_de_name, 'employee')),
        jsonb_build_object('item_id', v_pip.id, 'due_date', v_pip.due_date,
          'consequence', v_pip.consequence,
          'next_step', 'A human decides here: trust reduction, added approval gates, or pause (Pause is on the employee profile).'),
        'de_development_items', v_pip.id, now())
      on conflict (tenant_id, source_table, source_id) do nothing;
      v_pip_failed := v_pip_failed + 1;
    end if;
  end loop;

  -- (d) §10.3: critical incidents should be reviewed within 48 hours —
  --     one nudge each (detail flag dedup).
  for v_inc in
    select * from de_incidents
    where status = 'open' and severity = 'critical'
      and created_at < now() - interval '48 hours'
      and coalesce(detail->>'sla_nudged', '') = ''
  loop
    update de_incidents set detail = detail || '{"sla_nudged": true}'::jsonb where id = v_inc.id;
    perform append_audit_event_internal(
      v_inc.tenant_id, 'Governance sweep', 'system',
      format('Critical incident open past the 48-hour review window: %s', left(v_inc.title, 160)),
      'config_change',
      jsonb_build_object('kind', 'incident_sla_nudge', 'incident_id', v_inc.id, 'de_id', v_inc.de_id)
    );
    v_sla := v_sla + 1;
  end loop;

  return jsonb_build_object('cert_warnings', v_warned, 'certs_expired', v_expired,
    'pips_completed', v_pip_completed, 'pips_failed', v_pip_failed, 'sla_nudges', v_sla);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_is_available(p_availability jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamp;
  v_dow integer;
  v_hour integer;
begin
  if coalesce(p_availability->>'mode', 'always_on') <> 'business_hours' then
    return true;
  end if;
  begin
    v_now := now() at time zone coalesce(p_availability->>'timezone', 'UTC');
  exception when others then
    return true;  -- fail-open: bad timezone never stops an inbox
  end;
  v_dow := extract(isodow from v_now);
  v_hour := extract(hour from v_now);
  return exists (
      select 1 from jsonb_array_elements_text(coalesce(p_availability->'days', '[1,2,3,4,5]'::jsonb)) d
      where d::integer = v_dow)
    and v_hour >= coalesce((p_availability->>'start_hour')::integer, 9)
    and v_hour < coalesce((p_availability->>'end_hour')::integer, 17);
exception when others then
  return true;  -- fail-open on any malformed shape
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_search(p_tenant_id uuid, p_de_id uuid, p_query_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT NULL::text, p_subject_ref text DEFAULT NULL::text, p_kinds text[] DEFAULT NULL::text[], p_match_count integer DEFAULT 8)
 RETURNS TABLE(id uuid, content text, kind text, subject_kind text, subject_ref text, salience numeric, distance double precision, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null
     and not exists (select 1 from profiles p where p.user_id = auth.uid()
                       and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to read memory for this tenant';
  end if;

  return query
  select m.id, m.content, m.kind, m.subject_kind, m.subject_ref, m.salience,
         case when p_query_embedding is not null and m.embedding is not null
              then (m.embedding <=> p_query_embedding)::float else null end as distance,
         m.created_at
  from de_memory m
  where m.tenant_id = p_tenant_id
    and m.de_id = p_de_id
    and (m.expires_at is null or m.expires_at > now())
    and (p_subject_kind is null or m.subject_kind = p_subject_kind)
    and (p_subject_ref  is null or m.subject_ref  = p_subject_ref)
    and (p_kinds is null or m.kind = any(p_kinds))
  order by
    -- lower is better: semantic distance when available, else a recency+
    -- salience proxy (newer & more salient sort first).
    coalesce(case when p_query_embedding is not null and m.embedding is not null
                  then (m.embedding <=> p_query_embedding)::float end,
             1.0 - m.salience
               + least(0.5, extract(epoch from (now() - m.created_at)) / (86400.0 * 60)))
    asc
  limit greatest(1, least(50, p_match_count));
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_write(p_tenant_id uuid, p_de_id uuid, p_content text, p_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT 'general'::text, p_subject_ref text DEFAULT NULL::text, p_kind text DEFAULT 'episodic'::text, p_salience numeric DEFAULT 0.5, p_source text DEFAULT 'de'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  -- Caller must be service_role (edge functions) or a member of the
  -- tenant. auth.uid() is null under service_role, so the membership
  -- check is skipped for it; a signed-in user must belong to p_tenant_id.
  if auth.uid() is not null
     and not exists (select 1 from profiles p where p.user_id = auth.uid()
                       and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to write memory for this tenant';
  end if;
  if p_content is null or btrim(p_content) = '' then
    raise exception 'memory content required';
  end if;

  insert into de_memory (tenant_id, de_id, subject_kind, subject_ref, kind,
                         content, embedding, salience, source, expires_at)
  values (p_tenant_id, p_de_id, p_subject_kind, p_subject_ref, p_kind,
          p_content, p_embedding, greatest(0, least(1, coalesce(p_salience, 0.5))),
          p_source, p_expires_at)
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_records_gate(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(gated boolean, reasons text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_reasons text[] := '{}';
  v_cert record;
  v_fp text;
  v_n bigint;       -- GI-4: this DE's 56d evidence-run volume
  v_failed bigint;  -- GI-4: this DE's 56d failed-run count
  v_req boolean;        -- GI-9: tenant opted into mandatory cert?
  v_req_since timestamptz;
  v_de_created timestamptz;
  v_arch text;
  v_has_exam boolean;
  v_has_pass boolean;
begin
  -- (a) Exam certifications (role_certifications): latest row decides.
  select rc.status, rc.config_fingerprint into v_cert
    from role_certifications rc
   where rc.tenant_id = p_tenant_id and rc.de_id = p_de_id
   order by rc.evaluated_at desc nulls last, rc.created_at desc limit 1;
  if found then
    if v_cert.status = 'failed' then
      v_reasons := array_append(v_reasons, 'failed_certification');
    elsif v_cert.status = 'passed' and v_cert.config_fingerprint is not null then
      v_fp := public.de_config_fingerprint(p_de_id);
      if v_fp is not null and v_fp <> v_cert.config_fingerprint then
        v_reasons := array_append(v_reasons, 'stale_certification');
      end if;
    end if;
  end if;

  -- (b) Governance certifications (de_certifications): an expired cert not
  --     superseded by a newer active one of the same type gates.
  if exists (
    select 1 from de_certifications c
     where c.tenant_id = p_tenant_id and c.de_id = p_de_id and c.status = 'expired'
       and not exists (
         select 1 from de_certifications c2
          where c2.tenant_id = p_tenant_id and c2.de_id = p_de_id
            and c2.cert_type = c.cert_type and c2.status = 'active'
            and c2.created_at > c.created_at)
  ) then
    v_reasons := array_append(v_reasons, 'expired_certification');
  end if;

  -- (c) GI-4: an OPEN CRITICAL incident on THIS employee gates. de_id is
  --     required so a tenant-level (null-de_id) incident never over-gates one
  --     employee. Self-clears the moment the incident moves off 'open'.
  if exists (
    select 1 from de_incidents i
     where i.tenant_id = p_tenant_id and i.de_id = p_de_id
       and i.status = 'open' and i.severity = 'critical'
  ) then
    v_reasons := array_append(v_reasons, 'open_critical_incident');
  end if;

  -- (d) GI-4: degraded performance gates on ERROR RATE ONLY (never escalation —
  --     escalation self-manufactures under gating; see header). Scoped to this
  --     employee, 56-day recoverable window, >=10-run sample floor so a DE with
  --     little/no run volume is never gated. Div-by-zero guarded. The inner
  --     block fails CLOSED with a distinct diagnosable reason so a throwing
  --     metric query can never bubble up and silently un-gate a fail-open path.
  begin
    select count(*)::bigint,
           count(*) filter (where er.status = 'failed')::bigint
      into v_n, v_failed
      from evidence_runs er
     where er.tenant_id = p_tenant_id and er.de_id = p_de_id
       and er.created_at > now() - interval '56 days';
    if coalesce(v_n, 0) >= 10
       and (100.0 * coalesce(v_failed, 0) / nullif(v_n, 0)) > 15 then
      v_reasons := array_append(v_reasons, 'degraded_metrics');
    end if;
  exception when others then
    v_reasons := array_append(v_reasons, 'metrics_check_unavailable');
  end;

  -- (e) GI-9: MANDATORY CERTIFICATION — opt-in per tenant (default off),
  --     grandfathered by hire date, honest per CURRENT role. A DE that has never
  --     passed its current role's exam is supervised, but ONLY when (i) the tenant
  --     explicitly opted in, (ii) the DE was hired AFTER opt-in, (iii) an exam
  --     actually exists for its role. Opt-in is an EXPLICIT-true DIRECT read (never
  --     is_feature_enabled_internal, which fails OPEN). The cert/exam lookups fail
  --     CLOSED inside their own block so a throw on an opted-in tenant goes supervised.
  if p_de_id is not null then
    select tfo.enabled, tfo.updated_at
      into v_req, v_req_since
      from tenant_feature_overrides tfo
     where tfo.tenant_id = p_tenant_id
       and tfo.feature_key = 'require_certification';
    if coalesce(v_req, false) then
      begin
        select d.created_at into v_de_created
          from digital_employees d
         where d.id = p_de_id and d.tenant_id = p_tenant_id;
        -- Grandfather: only DEs hired after opt-in must certify.
        if v_de_created is not null and v_de_created > v_req_since then
          v_arch := public.resolve_de_archetype(p_de_id);
          select exists (
            select 1 from golden_qa gq
             where gq.tenant_id = p_tenant_id and gq.active = true
               and (gq.archetype_key is null or gq.archetype_key = v_arch)
          ) into v_has_exam;
          select exists (
            select 1 from role_certifications rc
             where rc.tenant_id = p_tenant_id and rc.de_id = p_de_id
               and rc.status = 'passed'
               and rc.archetype_key is not distinct from v_arch
          ) into v_has_pass;
          if coalesce(v_has_exam, false) and not coalesce(v_has_pass, false) then
            v_reasons := array_append(v_reasons, 'never_certified');
          end if;
        end if;
      exception when others then
        v_reasons := array_append(v_reasons, 'certification_check_unavailable');
      end;
    end if;
  end if;

  return query select coalesce(array_length(v_reasons, 1), 0) > 0, v_reasons;
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_action_execution(p_tenant_id uuid, p_action_label text, p_category text, p_destructive boolean, p_de_id uuid DEFAULT NULL::uuid, p_amount_cents bigint DEFAULT NULL::bigint, p_action_type text DEFAULT 'action_execute'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule      record;
  v_text      text := lower(coalesce(p_action_label, '') || ' ' || coalesce(p_category, ''));
  v_autonomy  record;
  v_frag      text;
  v_hit       boolean;
  v_threshold bigint;
  v_period    text;
  v_spent     bigint;
begin
  -- 0) DESTRUCTIVE ALWAYS GATES.
  if coalesce(p_destructive, true) then
    return jsonb_build_object('decision', 'human_gated_destructive',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
      'reasoning', format('This action is marked destructive — it always requires human approval regardless of trust level. This is a platform safety floor, not a per-department setting: "%s" will never auto-execute.', p_action_label));
  end if;

  -- 1) Guardrail check (blocked_phrase / blocked_topic — always win).
  --    WAVE-1 FIX: scope-aware via guardrail_rules_for_de (workspace + this
  --    employee's employee/department rules) instead of every tenant rule.
  for v_rule in
    select id, rule, pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id,
                                array['blocked_phrase', 'blocked_topic'])
    where severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    -- mig 328: match the WHOLE pattern as ONE case-insensitive regex. The old
    -- code split on '|' FIRST and then matched each fragment as its own regex,
    -- which shredded any grouping the rule author wrote -- turning
    --   what is your (pin|cvv|password|ssn|social security)|tell me your (...)
    -- into the bare fragments 'cvv', 'password', 'ssn', so the rule fired on ANY
    -- mention of them. POSIX ~* understands | and () as the author intended.
    begin
      v_hit := v_text ~* v_rule.pattern;
    exception when others then
      -- Not a valid regex -> the author meant literal phrases split by '|'.
      -- Literal only, never regex: a fragment that failed to compile as part of
      -- a whole is not meaningful as a regex on its own.
      v_hit := false;
      foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
        v_frag := trim(both from lower(v_frag));
        if v_frag <> '' and position(v_frag in v_text) > 0 then v_hit := true; exit; end if;
      end loop;
    end;
    if v_hit then
      return jsonb_build_object('decision', 'guardrail_blocked',
        'guardrail_rule_id', v_rule.id, 'guardrail_rule', v_rule.rule, 'trust_level', null,
        'reasoning', format('Blocked: guardrail rule "%s" matched this action — routed to a human regardless of trust. Guardrails always win over the trust dial.', v_rule.rule));
    end if;
  end loop;

  -- 1.5) Amount guardrail (require_approval_over_cents).
  if p_amount_cents is not null then
    select threshold into v_threshold
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['require_approval_over_cents'])
    where active
    order by (case scope when 'employee' then 0 when 'playbook' then 1 when 'department' then 2 when 'workspace' then 3 else 4 end), updated_at desc
    limit 1;
    v_threshold := coalesce(v_threshold, 1000000);
    if p_amount_cents > v_threshold then
      return jsonb_build_object('decision', 'human_gated_trust',
        'guardrail_rule_id', null, 'guardrail_rule', 'require_approval_over_cents', 'trust_level', null,
        'reasoning', format('Needs approval: "%s" is for $%s, above this workspace''s $%s approval threshold. Amounts over the threshold always get a human, regardless of the trust dial.', p_action_label, round(p_amount_cents / 100.0), round(v_threshold / 100.0)));
    end if;
  end if;

  -- 1.6) SPEND CAPS (additive, GUARDED) — only DEs with a configured spend_cap
  --      rule are affected. Sums this period's ledger + this action's amount and
  --      gates to a human if it would breach the cap. A DE with no cap: no-op.
  if p_de_id is not null and p_amount_cents is not null then
    for v_rule in
      select rule_type, threshold from guardrail_rules
      where tenant_id = p_tenant_id and active
        and rule_type in ('spend_cap_daily_cents', 'spend_cap_monthly_cents')
        and (scope = 'workspace' or (scope = 'employee' and scope_ref = p_de_id::text))
        and threshold is not null
      order by threshold asc
    loop
      if v_rule.rule_type = 'spend_cap_daily_cents' then
        v_period := to_char(current_date, 'YYYY-MM-DD');
        select coalesce(sum(cents), 0) into v_spent from de_spend_ledger
          where tenant_id = p_tenant_id and de_id = p_de_id and period_kind = 'day' and period_key = v_period;
      else
        v_period := to_char(current_date, 'YYYY-MM');
        select coalesce(sum(cents), 0) into v_spent from de_spend_ledger
          where tenant_id = p_tenant_id and de_id = p_de_id and period_kind = 'month' and period_key = v_period;
      end if;
      if v_spent + p_amount_cents > v_rule.threshold then
        return jsonb_build_object('decision', 'human_gated_trust',
          'guardrail_rule_id', null, 'guardrail_rule', v_rule.rule_type, 'trust_level', null,
          'reasoning', format('Needs approval: this $%s spend would take %s spend to $%s, over the $%s cap. Spend over the cap always gets a human.',
            round(p_amount_cents / 100.0),
            case when v_rule.rule_type = 'spend_cap_daily_cents' then 'today''s' else 'this month''s' end,
            round((v_spent + p_amount_cents) / 100.0), round(v_rule.threshold / 100.0)));
      end if;
    end loop;
  end if;

  -- 2) Trust dial (per-employee cascade).
  select * into v_autonomy from resolve_de_autonomy(p_tenant_id, p_action_type, p_de_id, p_category);
  if coalesce(v_autonomy.enabled, false)
     and (p_amount_cents is null
          or (v_autonomy.max_amount_cents is not null and p_amount_cents <= v_autonomy.max_amount_cents)) then
    return jsonb_build_object('decision', 'auto_executed',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', 1,
      'reasoning', case
        when p_amount_cents is not null then
          format('Auto-executed: "%s" ($%s) is within both the workspace approval threshold and the earned trust-dial limit of $%s%s, and no guardrail blocked it.',
            p_action_label, round(p_amount_cents / 100.0), round(v_autonomy.max_amount_cents / 100.0),
            case when p_de_id is not null then ' resolved for this employee' else '' end)
        else
          format('Auto-executed: "%s" is not destructive, no guardrail blocked it, and the trust dial%s allows auto-executing non-destructive actions for %s.',
            p_action_label, case when p_de_id is not null then ' (resolved for this employee)' else '' end, p_category)
      end);
  end if;

  return jsonb_build_object('decision', 'human_gated_trust',
    'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
    'reasoning', case
      when not coalesce(v_autonomy.enabled, false) then
        format('Needs approval: "%s" is not destructive, but the trust dial has not enabled auto-execution for %s %s actions yet (Governance -> Trust & Architecture).',
          p_action_label, case when p_de_id is not null then 'this employee''s' else 'this workspace''s' end, p_category)
      else
        format('Needs approval: "%s" ($%s) exceeds the trust-dial limit of %s earned so far.',
          p_action_label, round(coalesce(p_amount_cents, 0) / 100.0),
          coalesce('$' || round(v_autonomy.max_amount_cents / 100.0)::text, 'no amount'))
    end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_de_exception(p_exception_id uuid, p_decision text, p_outcome text DEFAULT NULL::text, p_learned boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_row de_exceptions;
  v_de_name text;
  v_status text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  IF p_decision NOT IN ('approved','rejected','denied') THEN
    RAISE EXCEPTION 'decision must be approved or rejected';
  END IF;

  -- The UI's word is 'rejected'; the table's word is 'denied'. Translate at the
  -- boundary rather than teaching the table a second spelling.
  v_status := CASE WHEN p_decision = 'rejected' THEN 'denied' ELSE p_decision END;

  SELECT * INTO v_row FROM de_exceptions WHERE id = p_exception_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'exception_not_found'; END IF;
  -- 'proposed' is the state a new exception is actually in.
  IF v_row.status <> 'proposed' THEN RAISE EXCEPTION 'already_decided: %', v_row.status; END IF;

  SELECT name INTO v_de_name FROM digital_employees WHERE id = v_row.de_id;

  UPDATE de_exceptions SET
    status     = v_status,
    outcome    = p_outcome,
    learned    = coalesce(p_learned, false),
    decided_by = auth.uid(),
    decided_at = now()
  WHERE id = p_exception_id;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('%s exception %s — %s', coalesce(v_de_name, 'An employee'), v_status,
           left(v_row.situation, 120)),
    'approval',                                  -- 'decision' is not a valid category
    jsonb_build_object('exception_id', p_exception_id, 'de_id', v_row.de_id,
                       'decision', v_status, 'learned', coalesce(p_learned, false))
  );
  RETURN jsonb_build_object('ok', true, 'status', v_status);
END$function$;

CREATE OR REPLACE FUNCTION public.decide_ingest_candidates(p_connector_id uuid, p_refs text[], p_decision text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_count int;
begin
  if p_decision not in ('approved','rejected','pending') then
    raise exception 'decision must be approved, rejected, or pending';
  end if;
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null or v_tenant <> auth_tenant_id()
     or not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'only workspace owners/admins can review connector documents';
  end if;
  update connector_ingest_candidates
     set status = p_decision, decided_by = auth.uid(), decided_at = now()
   where connector_id = p_connector_id
     and status <> 'ingested'
     and (p_refs is null or external_ref = any (p_refs));
  get diagnostics v_count = row_count;
  return v_count;
end $function$;

CREATE OR REPLACE FUNCTION public.decide_inquiry_triage(p_tenant_id uuid, p_inquiry text, p_confidence integer, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule       record;
  v_text       text := lower(coalesce(p_inquiry, ''));
  v_autonomy   record;
  v_min_conf   integer;
  v_enabled    boolean;
  v_frag       text;
  v_hit        boolean;
  v_frustration integer;
  v_esc        record;
begin
  -- 1) Guardrail check — blocking blocked_topic/blocked_phrase rules,
  --    now scoped to this employee (workspace ∪ department ∪ employee).
  for v_rule in
    select g.id, g.rule, g.pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['blocked_phrase','blocked_topic']) g
    where g.severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'blocked_guardrail',
          'confidence', p_confidence,
          'guardrail_rule_id', v_rule.id,
          'guardrail_rule', v_rule.rule,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Blocked: guardrail rule "%s" matched this inquiry — routed to a human regardless of confidence (%s%%). Guardrails always win over the trust dial.', v_rule.rule, p_confidence)
        );
      end if;
    end loop;
  end loop;

  select * into v_esc from resolve_de_escalation(p_tenant_id, p_de_id);

  -- 1.25) Always-escalate topics (DE-B2): per-employee (or workspace-
  --       default) topic patterns that always get a human, regardless
  --       of confidence — below guardrails, above everything else.
  if array_length(v_esc.always_escalate_topics, 1) is not null then
    foreach v_frag in array v_esc.always_escalate_topics loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'needs_review',
          'confidence', p_confidence,
          'guardrail_rule_id', null,
          'guardrail_rule', null,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Needs review: this inquiry matches the always-escalate topic "%s" configured for this employee — routed to a human regardless of confidence (%s%%).', v_frag, p_confidence)
        );
      end if;
    end loop;
  end if;

  -- 1.5) Frustration check — threshold resolved per-employee with
  --      workspace fallback (was hardcoded 50).
  v_frustration := score_frustration_internal(p_tenant_id, p_inquiry);
  if v_frustration >= v_esc.frustration_threshold then
    return jsonb_build_object(
      'decision', 'needs_review',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', null,
      'frustration_score', v_frustration,
      'reasoning', format('Needs review: this inquiry scored %s%% on frustration signals (threshold %s%%) — routed to a human regardless of confidence (%s%%). A frustrated customer always gets a human.', v_frustration, v_esc.frustration_threshold, p_confidence)
    );
  end if;

  -- 2) Trust dial — resolved per-employee first now (no category
  --    dimension for this sibling, matching its existing scope).
  select * into v_autonomy from resolve_de_autonomy(p_tenant_id, 'answer_widget', p_de_id, null);
  v_enabled := coalesce(v_autonomy.enabled, false);
  v_min_conf := v_autonomy.min_confidence;

  if v_enabled and v_min_conf is not null and p_confidence >= v_min_conf then
    return jsonb_build_object(
      'decision', 'would_auto_send',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', v_min_conf,
      'frustration_score', v_frustration,
      'reasoning', format('Would auto-send: confidence %s%% clears the trust-dial floor of %s%% for auto-answering customers, and no guardrail blocked it. Recorded as intent only — no outbound reply channel exists yet, so nothing was actually sent.', p_confidence, v_min_conf)
    );
  end if;

  return jsonb_build_object(
    'decision', 'needs_review',
    'confidence', p_confidence,
    'guardrail_rule_id', null,
    'guardrail_rule', null,
    'trust_level', v_min_conf,
    'frustration_score', v_frustration,
    'reasoning', case
      when not v_enabled then format('Needs review: confidence %s%%, but auto-answering customers is not yet enabled on the trust dial (Governance -> Trust & Architecture).', p_confidence)
      else format('Needs review: confidence %s%% is below the trust-dial floor of %s%% required to auto-answer customers.', p_confidence, coalesce(v_min_conf, 0))
    end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_work_item_triage(p_tenant_id uuid, p_category text, p_inquiry text, p_confidence integer, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule       record;
  v_text       text := lower(coalesce(p_inquiry, ''));
  v_autonomy   record;
  v_min_conf   integer;
  v_enabled    boolean;
  v_frag       text;
  v_hit        boolean;
  v_frustration integer;
  v_esc        record;
begin
  -- 1) Guardrail check — now scoped to this employee (workspace ∪
  --    department ∪ employee), identical matching to the sibling.
  for v_rule in
    select g.id, g.rule, g.pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['blocked_phrase','blocked_topic']) g
    where g.severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'blocked_guardrail',
          'confidence', p_confidence,
          'guardrail_rule_id', v_rule.id,
          'guardrail_rule', v_rule.rule,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Blocked: guardrail rule "%s" matched this %s item — routed to a human regardless of confidence (%s%%). Guardrails always win over the trust dial.', v_rule.rule, p_category, p_confidence)
        );
      end if;
    end loop;
  end loop;

  select * into v_esc from resolve_de_escalation(p_tenant_id, p_de_id);

  -- 1.25) Always-escalate topics (DE-B2) — same tier as the sibling.
  if array_length(v_esc.always_escalate_topics, 1) is not null then
    foreach v_frag in array v_esc.always_escalate_topics loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'needs_review',
          'confidence', p_confidence,
          'guardrail_rule_id', null,
          'guardrail_rule', null,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Needs review: this %s item matches the always-escalate topic "%s" configured for this employee — routed to a human regardless of confidence (%s%%).', p_category, v_frag, p_confidence)
        );
      end if;
    end loop;
  end if;

  -- 1.5) Frustration check — threshold resolved per-employee with
  --      workspace fallback (was hardcoded 50).
  v_frustration := score_frustration_internal(p_tenant_id, p_inquiry);
  if v_frustration >= v_esc.frustration_threshold then
    return jsonb_build_object(
      'decision', 'needs_review',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', null,
      'frustration_score', v_frustration,
      'reasoning', format('Needs review: this %s item scored %s%% on frustration signals (threshold %s%%) — routed to a human regardless of confidence (%s%%). A frustrated customer always gets a human.', p_category, v_frustration, v_esc.frustration_threshold, p_confidence)
    );
  end if;

  -- 2) Trust dial — resolved per-employee first now, via the shared
  --    cascade (exact de+category -> de-wide -> category-wide -> tenant-wide).
  select * into v_autonomy from resolve_de_autonomy(p_tenant_id, 'answer_widget', p_de_id, p_category);
  v_enabled := coalesce(v_autonomy.enabled, false);
  v_min_conf := v_autonomy.min_confidence;

  if v_enabled and v_min_conf is not null and p_confidence >= v_min_conf then
    return jsonb_build_object(
      'decision', 'would_auto_send',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', v_min_conf,
      'frustration_score', v_frustration,
      'reasoning', format('Would auto-send: confidence %s%% clears the trust-dial floor of %s%% for auto-answering on %s, and no guardrail blocked it. Recorded as intent only unless a registered action can act on this item.', p_confidence, v_min_conf, p_category)
    );
  end if;

  return jsonb_build_object(
    'decision', 'needs_review',
    'confidence', p_confidence,
    'guardrail_rule_id', null,
    'guardrail_rule', null,
    'trust_level', v_min_conf,
    'frustration_score', v_frustration,
    'reasoning', case
      when not v_enabled then format('Needs review: confidence %s%%, but auto-answering on %s is not yet enabled on the trust dial (Governance -> Trust & Architecture).', p_confidence, p_category)
      else format('Needs review: confidence %s%% is below the trust-dial floor of %s%% required to auto-answer on %s.', p_confidence, coalesce(v_min_conf, 0), p_category)
    end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_custom_metric(p_metric_id uuid)
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT cm.tenant_id INTO v_owner FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'metric_not_found'; END IF;
  PERFORM public._assert_caller_tenant(v_owner);

  DELETE FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  RETURN QUERY SELECT TRUE::BOOLEAN, 'Metric deleted'::TEXT;
END$function$;

CREATE OR REPLACE FUNCTION public.delete_de_operate_binding(p_system_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret uuid; v_operate_only boolean;
BEGIN
  SELECT tenant_id, login_secret_id, (binding_kind = 'connector' AND source_table IS NULL)
    INTO v_tenant, v_secret, v_operate_only
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF NOT v_operate_only THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_operate_only');
  END IF;
  DELETE FROM de_connected_systems WHERE id = p_system_id;
  IF v_secret IS NOT NULL THEN DELETE FROM vault.secrets WHERE id = v_secret; END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.delete_principal_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_name text; v_grants int; v_members int; v_my int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  -- Symmetric with 356's revoke guard: deleting a group revokes its grants, so
  -- you may not delete one holding more access than you could have removed.
  IF public.knowledge_group_max_level(p_group_id) > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: that group holds access above your level';
  END IF;

  SELECT count(*) INTO v_grants FROM knowledge_access_grants
   WHERE principal_type = 'group' AND principal_group_id = p_group_id;
  SELECT count(*) INTO v_members FROM knowledge_principal_group_members WHERE group_id = p_group_id;

  DELETE FROM knowledge_principal_groups WHERE id = p_group_id;   -- cascades the grants

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Deleted the group "%s" — %s grant(s) removed, %s member(s) affected', v_name, v_grants, v_members),
    'access_control',
    jsonb_build_object('group_id', p_group_id, 'grants_removed', v_grants, 'members', v_members));

  RETURN jsonb_build_object('ok', true, 'grants_removed', v_grants, 'members_affected', v_members);
END $function$;

CREATE OR REPLACE FUNCTION public.delete_tenant(p_tenant_id uuid, p_confirm_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_t tenants; v_self uuid; v_children int;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant-management access may delete a tenant';
  end if;
  select * into v_t from tenants where id = p_tenant_id;
  if not found then raise exception 'tenant not found'; end if;
  if p_tenant_id = v_demo_tenant_id then raise exception 'the demo tenant cannot be deleted'; end if;
  select tenant_id into v_self from profiles where user_id = auth.uid();
  if v_self is not distinct from p_tenant_id then raise exception 'you cannot delete the tenant you belong to'; end if;
  if v_t.status <> 'suspended' then
    raise exception 'suspend the tenant before deleting it — deletion is permanent and irreversible';
  end if;
  if coalesce(p_confirm_slug, '') <> v_t.slug then
    raise exception 'confirmation text must exactly match the tenant slug (%)', v_t.slug;
  end if;
  select count(*) into v_children from tenants where parent_tenant_id = p_tenant_id;
  if v_children > 0 then
    raise exception 'this tenant still has % sub-tenant(s) — delete or reassign them first', v_children;
  end if;
  delete from tenant_provisioning_requests
    where proposed_parent_tenant_id = p_tenant_id or created_tenant_id = p_tenant_id;
  delete from platform_access_events where tenant_id = p_tenant_id;
  perform set_config('app.allow_audit_purge', 'on', true);
  delete from tenants where id = p_tenant_id;
  return jsonb_build_object('ok', true, 'deleted_tenant', p_tenant_id, 'name', v_t.name, 'slug', v_t.slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.deprovision_starter_de_internal(p_tenant_id uuid, p_feature_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_catalog_id text;
  v_source_cat text;
  v_de_id      uuid;
begin
  v_catalog_id := case p_feature_key when 'account_de' then 'starter_account_de' when 'finance_de' then 'starter_finance_de' else null end;
  v_source_cat := case p_feature_key when 'account_de' then 'crm' when 'finance_de' then 'erp_financials' else null end;
  if v_catalog_id is null then
    return; -- not a DE-provisioning feature — nothing to do
  end if;

  select id into v_de_id from digital_employees where tenant_id = p_tenant_id and catalog_id = v_catalog_id;
  if v_de_id is null then
    return; -- never provisioned — honest no-op
  end if;

  update digital_employees set status = 'disabled', lifecycle_status = 'paused' where id = v_de_id;

  update de_playbook_charter set active = false
  where tenant_id = p_tenant_id and de_id = v_de_id;

  update playbook_event_rules set active = false
  where tenant_id = p_tenant_id
    and definition_id in (select playbook_id from de_playbook_charter where de_id = v_de_id);

  update de_autonomy set enabled = false
  where tenant_id = p_tenant_id and action_type = 'action_execute' and source_category = v_source_cat;

  perform append_audit_event_internal(
    p_tenant_id, 'DreamTeam', 'system',
    format('Starter Digital Employee paused (feature "%s" turned off) — its playbook and autonomy were disabled; access grants and history were kept, not deleted.', p_feature_key),
    'config_change',
    jsonb_build_object('kind', 'feature_de_deprovisioned', 'feature_key', p_feature_key, 'de_id', v_de_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.detach_compliance_pack(p_tenant_id uuid, p_pack_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or (p.tenant_id = p_tenant_id and p.role in ('tenant_owner','tenant_admin')))) then
    raise exception 'only an owner/admin (or platform) can detach a compliance pack';
  end if;
  perform set_config('app.allow_compliance_change', 'on', true);  -- txn-local; lets the trigger permit these deletes
  delete from guardrail_rules where tenant_id = p_tenant_id and compliance_pack_key = p_pack_key;
  delete from tenant_compliance_packs where tenant_id = p_tenant_id and pack_key = p_pack_key;
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_de_incidents_internal(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inserted integer := 0;
  v_count integer;
begin
  -- 1. Guardrail blocks from the triage pipeline (best attribution:
  --    evidence_runs.de_id).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select d.tenant_id, er.de_id, 'guardrail_block', 'warning',
    'Guardrail blocked an automatic action',
    jsonb_build_object('reasoning', left(d.reasoning, 400), 'guardrail_rule_id', d.guardrail_rule_id,
                       'external_ref', d.external_ref, 'source_category', d.source_category,
                       'evidence_run_id', d.evidence_run_id),
    'evidence_run_decisions', d.id, d.created_at
  from evidence_run_decisions d
  join evidence_runs er on er.id = d.evidence_run_id
  where d.decision = 'blocked_guardrail'
    and d.created_at > now() - interval '30 days'
    and (p_tenant_id is null or d.tenant_id = p_tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 2. Guardrail blocks recorded straight to the audit trail (widget/
  --    chat answers withheld). Attribution by actor name — the same
  --    semantics the old profile tab used, now persisted once.
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select a.tenant_id,
    (select de.id from digital_employees de
     where de.tenant_id = a.tenant_id and (de.name = a.actor or de.persona_name = a.actor)
     limit 1),
    'guardrail_block', 'warning',
    'Guardrail withheld an answer',
    jsonb_build_object('action', left(a.action, 400), 'rule', a.detail->>'rule', 'channel', a.detail->>'channel'),
    'audit_events', a.id, a.created_at
  from audit_events a
  where a.category = 'guardrail_block'
    and a.created_at > now() - interval '30 days'
    and (p_tenant_id is null or a.tenant_id = p_tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 3. Automatic trust demotions (migration 025's "demote fast" path).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select a.tenant_id,
    nullif(a.detail->>'de_id', '')::uuid,
    'trust_demotion', 'critical',
    'Trust level automatically demoted',
    jsonb_build_object('action', left(a.action, 400), 'action_category', a.detail->>'action_category',
                       'policy_id', a.detail->>'policy_id'),
    'audit_events', a.id, a.created_at
  from audit_events a
  where a.detail->>'kind' = 'trust_demoted'
    and a.created_at > now() - interval '30 days'
    and (p_tenant_id is null or a.tenant_id = p_tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 4. Failed eval runs (tenant-level: no single attributable DE).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select r.tenant_id, null,
    'eval_regression', 'warning',
    format('Golden QA run failed — %s of %s passed', r.passed, r.total),
    jsonb_build_object('run_id', r.id, 'passed', r.passed, 'failed', r.failed, 'trigger', r.trigger),
    'eval_runs', r.id, coalesce(r.finished_at, r.started_at)
  from eval_runs r
  where r.status = 'failed'
    and coalesce(r.finished_at, r.started_at) > now() - interval '30 days'
    and (p_tenant_id is null or r.tenant_id = p_tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 5. Humans rejecting a proposed action (a draft the DE got wrong).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select t.tenant_id,
    case when ae.subject_kind = 'de' then ae.subject_id else null end,
    'action_rejected', 'info',
    format('Proposed action rejected by a human — %s', left(t.title, 120)),
    jsonb_build_object('task_id', t.id, 'request_summary', left(ae.request_summary, 300), 'decided_at', t.decided_at),
    'human_tasks', t.id, coalesce(t.decided_at, t.created_at)
  from human_tasks t
  join action_executions ae on ae.task_id = t.id
  where t.type = 'action_approval' and t.status = 'rejected'
    and coalesce(t.decided_at, t.created_at) > now() - interval '30 days'
    and (p_tenant_id is null or t.tenant_id = p_tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  return jsonb_build_object('inserted', v_inserted);
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_exceptions(p_tenant_id uuid, p_workspace_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid;
  v_period_end date;
  v_count int := 0;
begin
  v_caller := auth_tenant_id();
  if v_caller is distinct from p_tenant_id and not is_platform_admin() then
    raise exception 'tenant mismatch';
  end if;

  select period_end into v_period_end from public.close_workspaces where id = p_workspace_id and tenant_id = p_tenant_id;

  delete from public.exceptions where tenant_id = p_tenant_id and workspace_id = p_workspace_id and status = 'open';

  -- 1) UNMATCHED BANK TRANSACTIONS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'unmatched_bank_txn',
    case when abs(bt.amount) >= 10000 then 'high' when abs(bt.amount) >= 1000 then 'medium' else 'low' end,
    'Unmatched bank transaction: '||left(bt.description,40),
    'Bank line of '||bt.amount||' on '||bt.txn_date||' has no matching payment record.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'No payment row links to this bank line; it is uncleared in the ledger.',
    0.82, 'Investigate and match to a payment, or create an adjusting entry.', false, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id and bt.is_matched = false and bt.matched_payment_id is null;

  -- 2) DUPLICATE BILLS (same vendor + amount; flag the later one only)
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'duplicate_invoice', 'high',
    'Possible duplicate bill: '||b.bill_number,
    'Another bill with the same vendor and amount ('||b.amount||') exists in this period.',
    b.amount, b.account_id, 'bills', b.id,
    'Two bills share vendor_id and amount within the same close window, a strong duplicate signal.',
    0.88, 'Confirm whether this is a true duplicate before payment; void if confirmed.', true, 'open'
  from public.bills b
  where b.tenant_id = p_tenant_id and b.workspace_id = p_workspace_id
    and exists (
      select 1 from public.bills b2 where b2.tenant_id = b.tenant_id and b2.workspace_id = b.workspace_id
        and b2.id <> b.id and b2.vendor_id = b.vendor_id and b2.amount = b.amount
        and b2.id::text < b.id::text
    );

  -- 3) MISSING RECEIPTS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'missing_receipt',
    case when b.amount >= 5000 then 'high' else 'medium' end,
    'Missing receipt: '||b.bill_number,
    'Bill of '||b.amount||' has no supporting receipt attached.',
    b.amount, b.account_id, 'bills', b.id,
    'has_receipt is false; audit evidence is incomplete for this expense.',
    0.79, 'Request and attach the receipt before close.', false, 'open'
  from public.bills b
  where b.tenant_id = p_tenant_id and b.workspace_id = p_workspace_id and b.has_receipt = false;

  -- 4) UNUSUAL SPEND
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'unusual_spend', 'high',
    'Unusual spend: '||left(bt.description,40),
    'Large outbound transfer of '||bt.amount||' on '||bt.txn_date||
      case when extract(dow from bt.txn_date) in (0,6) then ' (weekend)' else '' end||
      case when (abs(bt.amount)::numeric % 1000) = 0 then ' (round-number)' else '' end||'.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'Outbound amount far exceeds typical spend'||
      case when extract(dow from bt.txn_date) in (0,6) then '; posted on a weekend' else '' end||
      case when (abs(bt.amount)::numeric % 1000) = 0 then '; exact round number' else '' end||
      ', elevating fraud/error risk.',
    case when extract(dow from bt.txn_date) in (0,6) or (abs(bt.amount)::numeric % 1000)=0 then 0.86 else 0.74 end,
    'Verify authorization and supporting documentation; do not auto-clear.', true, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id
    and bt.amount <= -10000;

  -- 5) LATE CUSTOMER PAYMENTS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'late_customer_payment',
    case when (coalesce(v_period_end, current_date) - i.due_date) >= 60 then 'high'
         when (coalesce(v_period_end, current_date) - i.due_date) >= 30 then 'medium' else 'low' end,
    'Overdue receivable: '||i.invoice_number,
    'Invoice '||i.invoice_number||' of '||(i.amount - i.amount_paid)||' is '||
      (coalesce(v_period_end, current_date) - i.due_date)||' days past due.',
    (i.amount - i.amount_paid), null, 'invoices', i.id,
    'Due date passed with outstanding balance; aging increases collection risk.',
    0.9, 'Send dunning reminder / escalate to collections.', false, 'open'
  from public.invoices i
  where i.tenant_id = p_tenant_id and i.workspace_id = p_workspace_id
    and i.status in ('open','partial','overdue')
    and i.amount_paid < i.amount
    and i.due_date < coalesce(v_period_end, current_date);

  -- 6) UNCATEGORIZED
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'uncategorized_txn', 'low',
    'Uncategorized transaction: '||left(bt.description,40),
    'Bank line of '||bt.amount||' on '||bt.txn_date||' has no category assigned.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'category is null; cannot be posted to the correct GL account without coding.',
    0.7, 'Assign a GL category for proper classification.', false, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id and bt.category is null;

  -- 7) REVENUE / PAYMENT MISMATCH
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'revenue_payment_mismatch', 'medium',
    'Revenue/payment mismatch: '||i.invoice_number,
    'Invoice '||i.invoice_number||' status is '''||i.status||''' but amount_paid ('||i.amount_paid||') does not reconcile to amount ('||i.amount||').',
    (i.amount - i.amount_paid), null, 'invoices', i.id,
    'Status/paid amount inconsistency indicates a posting drift between AR and cash.',
    0.81, 'Reconcile the applied payments against the invoice balance.', false, 'open'
  from public.invoices i
  where i.tenant_id = p_tenant_id and i.workspace_id = p_workspace_id
    and ((i.status = 'paid' and i.amount_paid <> i.amount) or (i.amount_paid > i.amount));

  select count(*) into v_count from public.exceptions
    where tenant_id = p_tenant_id and workspace_id = p_workspace_id and status = 'open';
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.dismiss_platform_kb_change(p_change_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'only platform administrators can manage the shelf review queue';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'say why this change needs no documentation update';
  END IF;
  UPDATE platform_kb_changes
     SET status = 'dismissed', dismiss_reason = btrim(p_reason),
         reviewed_at = now(), reviewed_by = auth.uid()
   WHERE id = p_change_id;
END $function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_fitness_measure_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
begin
  -- Gate: no work + no wasted post while the feature is off.
  if coalesce((select value from platform_config where key = 'amendment_fitness.enabled'), 'false') <> 'true' then
    return 'amendment_fitness disabled';
  end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  -- One amendment per tick (the fn picks the oldest unmeasured applied 'de').
  perform net.http_post(
    url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/de-fitness-measure',
    body    := '{}'::jsonb,
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'Authorization', 'Bearer ' || v_anon,
                 'x-dispatch-secret', v_secret
               )
  );
  return 'de-fitness-measure dispatched (async)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_improve_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
  v_row    record;
  v_count  int := 0;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  -- Retryability: an infra-caused mid-replay failure (fail_closed) must not
  -- permanently burn a judgment. Clear such proposals older than 3 days so the
  -- candidate query re-picks their judgment for another pass. A genuine
  -- "answer could not be improved" that did NOT fail closed stays deduped.
  delete from de_improvements
   where status = 'failed_replay'
     and (replay->'golden'->>'failed_closed') = 'true'
     and updated_at < now() - interval '3 days';

  -- One oldest-unhandled below-standard judgment per tenant (FIFO fairness +
  -- sidesteps the edge fn's recency-window picker), skipping tenants that
  -- already have >= 3 open reviews (backpressure on the human queue), and only
  -- for active employees. Passing judgment_id makes each tick idempotent.
  for v_row in
    with pending as (
      select tenant_id, count(*) n from de_improvements
       where status = 'review_pending' group by tenant_id
    )
    select distinct on (j.tenant_id) j.tenant_id, j.id as judgment_id
      from eval_judgments j
      join digital_employees de on de.id = j.de_id
       and de.status = 'active'
       and de.lifecycle_status not in ('retired','archived')
      left join pending p on p.tenant_id = j.tenant_id
     where j.verdict in ('fail','partial')
       and j.score < 70
       and j.de_id is not null
       and coalesce(p.n, 0) < 3
       and not exists (select 1 from de_improvements di
                        where di.tenant_id = j.tenant_id and di.judgment_id = j.id)
     order by j.tenant_id, j.created_at asc
     limit 25
  loop
    -- per-iteration isolation: a bad row can never abort the global tick.
    begin
      perform net.http_post(
        url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/de-improve',
        body    := jsonb_build_object('tenant_id', v_row.tenant_id, 'judgment_id', v_row.judgment_id),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret
                   )
      );
      v_count := v_count + 1;
    exception when others then
      raise warning 'de-improve dispatch failed for tenant % judgment %: %', v_row.tenant_id, v_row.judgment_id, sqlerrm;
    end;
  end loop;

  -- Honest: the posts are async; this counts dispatches, not improvements.
  return 'de-improve dispatched ' || v_count || ' http_post(s) (async)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_work_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  v_req_id bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM de_work_items WHERE status = 'queued' AND scheduled_for <= now())
     AND NOT EXISTS (SELECT 1 FROM de_objectives WHERE status IN ('open','in_progress')
                       AND ( (next_wake_at IS NOT NULL AND next_wake_at <= now())
                             OR NOT EXISTS (SELECT 1 FROM de_work_items w WHERE w.objective_id = de_objectives.id) ))
  THEN
    RETURN 'idle — nothing due';
  END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — de-work items are queued but the work engine cron cannot run them.',
      jsonb_build_object('cron', 'dispatch_de_work_internal'));
    RETURN 'no dispatch secret';
  END IF;
  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/de-work'),
    body := '{"action":"run","max_items":3}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'x-dispatch-secret',v_secret)
  ) INTO v_req_id;
  RETURN 'de-work dispatched, req ' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_due_triggers(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_sched      record;
  v_rule       record;
  v_acct       record;
  v_inv        record;
  v_ticket     record;
  v_opp        record;
  v_pending    integer := 0;
  v_skipped    integer := 0;
  v_days       integer;
  v_priority   text;
  v_within     integer;
  v_recent     record;
  v_min_arr    bigint;
  v_min_amount bigint;
begin
  -- ── (a) due schedules — lowest DE-assigned priority first ──
  for v_sched in
    select s.*, d.status as def_status,
      coalesce((select min(a.priority) from de_playbook_charter a
                where a.playbook_id = s.definition_id and a.active), 1000) as charter_priority
    from playbook_schedules s
    join playbook_definitions d on d.id = s.definition_id
    where s.active
      and s.next_fire_at is not null
      and s.next_fire_at <= now()
      and (p_tenant_id is null or s.tenant_id = p_tenant_id)
    order by charter_priority asc, s.next_fire_at asc
    for update of s skip locked
  loop
    if v_sched.def_status <> 'published' then
      insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, status, detail)
      values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id, 'error',
              'definition is not published — schedule fired into the void');
      v_skipped := v_skipped + 1;
    elsif v_sched.account_selector->>'mode' = 'single' then
      insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, target_account_id, status, detail)
      values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id,
              (v_sched.account_selector->>'account_id')::uuid, 'pending_start',
              format('schedule due at %s (single account, charter priority %s)', v_sched.next_fire_at, v_sched.charter_priority));
      v_pending := v_pending + 1;
    else
      v_within := coalesce((v_sched.account_selector->>'renewal_within_days')::int, 60);
      for v_acct in
        select id from customer_accounts
        where tenant_id = v_sched.tenant_id
          and renewal_date is not null
          and renewal_date <= (current_date + v_within)
      loop
        insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, target_account_id, status, detail)
        values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id, v_acct.id, 'pending_start',
                format('schedule due at %s (renewal within %s days, charter priority %s)', v_sched.next_fire_at, v_within, v_sched.charter_priority));
        v_pending := v_pending + 1;
      end loop;
    end if;

    update playbook_schedules set last_fired_at = now() where id = v_sched.id;
  end loop;

  -- ── (b) event rules — lowest DE-assigned priority first ────
  for v_rule in
    select r.*, d.status as def_status,
      coalesce((select min(a.priority) from de_playbook_charter a
                where a.playbook_id = r.definition_id and a.active), 1000) as charter_priority
    from playbook_event_rules r
    join playbook_definitions d on d.id = r.definition_id
    where r.active
      and d.status = 'published'
      and (p_tenant_id is null or r.tenant_id = p_tenant_id)
    order by charter_priority asc
  loop
    if v_rule.event_key = 'invoice_overdue' then
      v_days := coalesce((v_rule.params->>'overdue_days')::int, 7);
      for v_inv in
        select id, account_id from renewal_invoices
        where tenant_id = v_rule.tenant_id
          and status = 'sent'
          and due_date is not null
          and due_date < (current_date - v_days)
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_inv.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_inv.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_inv.account_id, v_inv.id::text, 'skipped_dedup',
                    format('invoice already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_inv.account_id, v_inv.id::text, 'pending_start',
                  format('invoice overdue > %s days (charter priority %s)', v_days, v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'ticket_synced_high_priority' then
      v_priority := coalesce(v_rule.params->>'priority', 'p1');
      for v_ticket in
        select id, account_id from support_tickets
        where tenant_id = v_rule.tenant_id
          and source = 'zendesk'
          and priority = v_priority
          and created_at > now() - interval '7 days'
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_ticket.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_ticket.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_ticket.account_id, v_ticket.id::text, 'skipped_dedup',
                    format('ticket already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_ticket.account_id, v_ticket.id::text, 'pending_start',
                  format('%s ticket synced from Zendesk (charter priority %s)', v_priority, v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'account_at_risk' then
      v_min_arr := coalesce((v_rule.params->>'min_arr_cents')::bigint, 0);
      for v_acct in
        select id, arr_cents from customer_accounts
        where tenant_id = v_rule.tenant_id
          and status = 'at_risk'
          and arr_cents >= v_min_arr
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_acct.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_acct.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_acct.id, v_acct.id::text, 'skipped_dedup',
                    format('account already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_acct.id, v_acct.id::text, 'pending_start',
                  format('account at risk (computed health below threshold, charter priority %s)', v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'opportunity_won' then
      -- RESTORED (originally 023, never actually applied live because
      -- 023's own version predated charter_priority — see this
      -- migration's header). Byte-faithful to 023's query/dedup/
      -- cooldown logic, with charter_priority ordering applied on top
      -- exactly like the other three branches already get.
      v_min_amount := coalesce((v_rule.params->>'min_amount_cents')::bigint, 0);
      for v_opp in
        select id, account_id, amount_cents from opportunities
        where tenant_id = v_rule.tenant_id
          and stage = 'won'
          and account_id is not null
          and closed_at > now() - interval '7 days'
          and coalesce(amount_cents, 0) >= v_min_amount
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_opp.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_opp.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_opp.account_id, v_opp.id::text, 'skipped_dedup',
                    format('opportunity already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_opp.account_id, v_opp.id::text, 'pending_start',
                  format('opportunity won — welcome/kickoff play (charter priority %s)', v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;
    end if;
  end loop;

  return jsonb_build_object('pending', v_pending, 'skipped_dedup', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_eval_driver_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
  v_run    record;
  v_count  int := 0;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  for v_run in
    select id, tenant_id, de_id, archetype_key
      from eval_runs
     where status = 'running'
       and de_id is not null
       and finished_at is null
       and coalesce(jsonb_array_length(results), 0) < total
  loop
    perform net.http_post(
      url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/eval-run',
      body    := jsonb_build_object(
                   'run_id',        v_run.id,
                   'tenant_id',     v_run.tenant_id,
                   'de_id',         v_run.de_id,
                   'archetype_key', v_run.archetype_key
                 ),
      headers := jsonb_build_object(
                   'Content-Type', 'application/json',
                   'Authorization', 'Bearer ' || v_anon,
                   'x-dispatch-secret', v_secret
                 )
    );
    v_count := v_count + 1;
  end loop;

  return 'eval-driver dispatched ' || v_count || ' run(s)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_gap_improve_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
  v_row    record;
  v_count  int := 0;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN RETURN 'no dispatch secret'; END IF;

  FOR v_row IN
    WITH pending AS (
      SELECT tenant_id, count(*) n FROM de_improvements
       WHERE status = 'review_pending' GROUP BY tenant_id
    )
    SELECT DISTINCT ON (g.tenant_id) g.tenant_id, g.id AS cluster_id
      FROM knowledge_gap_clusters g
      LEFT JOIN pending p ON p.tenant_id = g.tenant_id
     WHERE g.status = 'open'
       AND g.de_improvement_id IS NULL
       AND g.representative_run_id IS NOT NULL
       AND coalesce(p.n, 0) < 3
       AND NOT EXISTS (SELECT 1 FROM de_improvements di WHERE di.gap_cluster_id = g.id)
       -- draftable only: de-improve needs a DE + question from the rep run;
       -- a rep run with no de_id would 422 forever, so never dispatch it.
       AND EXISTS (SELECT 1 FROM evidence_runs r
                    WHERE r.id = g.representative_run_id
                      AND r.de_id IS NOT NULL AND r.inquiry IS NOT NULL)
     ORDER BY g.tenant_id, g.severity_score DESC NULLS LAST, g.member_count DESC
     LIMIT 25
  LOOP
    BEGIN
      PERFORM net.http_post(
        url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/de-improve',
        body    := jsonb_build_object('tenant_id', v_row.tenant_id, 'gap_cluster_id', v_row.cluster_id),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret)
      );
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'gap-improve dispatch failed for tenant % cluster %: %', v_row.tenant_id, v_row.cluster_id, sqlerrm;
    END;
  END LOOP;

  RETURN 'gap-improve dispatched ' || v_count || ' http_post(s) (async)';
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_knowledge_sync_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
  v_row    record;
  v_count  int := 0;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN RETURN 'no dispatch secret'; END IF;

  FOR v_row IN
    SELECT c.id AS connector_id, c.tenant_id
      FROM connectors c
     WHERE c.scheduled_sync_enabled = true
       AND coalesce(c.access_mode, '') <> 'fetch_only'
       -- default-OFF flag => no tenant is touched until it explicitly opts in
       AND public.is_feature_enabled_internal(c.tenant_id, 'knowledge_scheduled_sync') = true
       AND (c.last_scheduled_sync_at IS NULL
            OR c.last_scheduled_sync_at < now() - make_interval(mins => greatest(60, c.sync_interval_mins)))
     ORDER BY c.last_scheduled_sync_at ASC NULLS FIRST
     LIMIT 25
  LOOP
    BEGIN
      -- Claim first (advance the clock) so a slow/duplicate tick can't double-fire.
      UPDATE connectors SET last_scheduled_sync_at = now() WHERE id = v_row.connector_id;
      PERFORM net.http_post(
        url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/connector-hub',
        body    := jsonb_build_object('action', 'sync', 'connector_id', v_row.connector_id,
                                      'tenant_id', v_row.tenant_id, 'scheduled', true),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret)
      );
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'knowledge-sync dispatch failed for connector %: %', v_row.connector_id, sqlerrm;
    END;
  END LOOP;

  RETURN 'knowledge-sync dispatched ' || v_count || ' connector(s) (async)';
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_online_eval_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  v_req_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — online eval cron is doing nothing.',
      jsonb_build_object('cron', 'dispatch_online_eval_internal'));
    RETURN 'no dispatch secret';
  END IF;
  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/de-eval-online'),
    body := '{"limit":8,"window_minutes":90}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'x-dispatch-secret',v_secret)
  ) INTO v_req_id;
  RETURN 'online-eval dispatched, req ' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.edit_outbound_draft(p_draft_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if coalesce(btrim(p_body), '') = '' or length(btrim(p_body)) < 10 then raise exception 'draft body required (min 10 chars)'; end if;
  select tenant_id into v_tenant from outbound_drafts where id = p_draft_id and status = 'pending_approval';
  if v_tenant is null then raise exception 'not_a_pending_draft'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  update outbound_drafts set body = btrim(p_body), updated_at = now() where id = p_draft_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.emit_tenant_event(p_tenant_id uuid, p_event_key text, p_target_ref text DEFAULT NULL::text, p_target_account_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_is_active boolean;
  v_tenant_check uuid;
  v_evt event_definitions;
  v_rule record;
  v_recent record;
  v_ref text;
  v_pending integer := 0;
  v_skipped integer := 0;
begin
  -- Trusted-server gate (same as upsert_event_definition above).
  if auth.role() is not null and auth.role() <> 'service_role' then
    select tenant_id, role, coalesce(is_active, true) into v_tenant_check, v_role, v_is_active
      from profiles where user_id = v_user;
    if v_tenant_check is distinct from p_tenant_id then
      raise exception 'not a member of this tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can fire events';
    end if;
  end if;

  -- The event must exist for this tenant (own event preferred, else platform)
  -- and be active.
  select * into v_evt from event_definitions
   where event_key = p_event_key and active
     and (scope = 'platform' or tenant_id = p_tenant_id)
   order by (scope = 'tenant') desc
   limit 1;
  if v_evt.id is null then
    return jsonb_build_object('ok', false, 'error', 'event_not_found', 'event_key', p_event_key);
  end if;

  v_ref := coalesce(nullif(p_target_ref, ''), p_target_account_id::text, '');

  for v_rule in
    select r.*, d.status as def_status
    from playbook_event_rules r
    join playbook_definitions d on d.id = r.definition_id
    where r.active and r.tenant_id = p_tenant_id and r.event_key = p_event_key
  loop
    if v_rule.def_status <> 'published' then
      continue;  -- unpublished definition: nothing runnable
    end if;

    -- Cooldown / dedup — identical shape to dispatch_due_triggers.
    select * into v_recent from playbook_trigger_fires
      where event_rule_id = v_rule.id and target_ref = v_ref
        and status in ('pending_start', 'started')
        and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
      order by fired_at desc limit 1;
    if found then
      if not exists (
        select 1 from playbook_trigger_fires
        where event_rule_id = v_rule.id and target_ref = v_ref
          and status = 'skipped_dedup' and fired_at > v_recent.fired_at
      ) then
        insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
        values (p_tenant_id, 'event', v_rule.id, v_rule.definition_id, p_target_account_id, v_ref, 'skipped_dedup',
                format('event "%s" already fired within the %sh cooldown', p_event_key, v_rule.cooldown_hours));
        v_skipped := v_skipped + 1;
      end if;
    else
      insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
      values (p_tenant_id, 'event', v_rule.id, v_rule.definition_id, p_target_account_id, v_ref, 'pending_start',
              format('emitted event "%s"%s', p_event_key,
                     case when p_payload ? 'source' then ' from '||(p_payload->>'source') else '' end));
      update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
      v_pending := v_pending + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'event_key', p_event_key, 'fires_created', v_pending, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.end_platform_remote_access(p_session_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_start platform_access_events;
begin
  if not resolve_platform_capability(auth.uid(), 'remote_access.use') then
    raise exception 'only a platform team member with remote access may end a remote access session';
  end if;

  select * into v_start from platform_access_events
  where session_key = p_session_key and event = 'start' and operator_user_id = auth.uid()
  order by created_at desc limit 1;

  if not found then
    raise exception 'no matching remote access session found to end';
  end if;

  if exists (select 1 from platform_access_events where session_key = p_session_key and event = 'end') then
    raise exception 'this remote access session has already been ended';
  end if;

  insert into platform_access_events (tenant_id, operator_user_id, operator_name, event, session_key, detail)
  values (v_start.tenant_id, auth.uid(), v_start.operator_name, 'end', p_session_key,
    jsonb_build_object('duration_seconds', extract(epoch from (now() - v_start.created_at))));

  return jsonb_build_object('ok', true, 'session_key', p_session_key);
end;
$function$;

CREATE OR REPLACE FUNCTION public.enqueue_conflict_backlog(p_tenant_id uuid, p_limit integer DEFAULT 500, p_after_chunk_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int; v_last uuid;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT (p_tenant_id = auth_tenant_id()
              AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF NOT is_feature_enabled_internal(p_tenant_id, 'knowledge_conflict_detection') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'detection_disabled');
  END IF;
  WITH batch AS (
    SELECT c.id, c.doc_id, c.tenant_id, c.content_hash
    FROM knowledge_doc_chunks c
    WHERE c.tenant_id = p_tenant_id AND c.embedding IS NOT NULL
      AND (p_after_chunk_id IS NULL OR c.id > p_after_chunk_id)
    ORDER BY c.id
    LIMIT least(greatest(coalesce(p_limit, 500), 1), 2000)
  ), ins AS (
    INSERT INTO knowledge_conflict_probe_queue (tenant_id, chunk_id, doc_id, content_hash)
    SELECT b.tenant_id, b.id, b.doc_id, b.content_hash FROM batch b
    ON CONFLICT (tenant_id, chunk_id) DO NOTHING
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM ins),
         (SELECT b.id FROM batch b ORDER BY b.id DESC LIMIT 1)   -- keyset watermark (no max(uuid))
    INTO v_n, v_last;
  RETURN jsonb_build_object('ok', true, 'seeded', coalesce(v_n, 0), 'last_chunk_id', v_last);
END $function$;

CREATE OR REPLACE FUNCTION public.enqueue_conflict_probe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Fire only for an embedded chunk whose content/embedding meaningfully changed,
  -- and only for tenants that opted in (default-OFF flag → inert for everyone else).
  IF NEW.embedding IS NOT NULL
     AND (TG_OP = 'INSERT' OR OLD.embedding IS NULL OR NEW.content_hash IS DISTINCT FROM OLD.content_hash)
     AND is_feature_enabled_internal(NEW.tenant_id, 'knowledge_conflict_detection') THEN
    INSERT INTO knowledge_conflict_probe_queue (tenant_id, chunk_id, doc_id, content_hash)
    VALUES (NEW.tenant_id, NEW.id, NEW.doc_id, NEW.content_hash)
    ON CONFLICT (tenant_id, chunk_id) DO UPDATE
      SET content_hash = EXCLUDED.content_hash, enqueued_at = now(), probed_at = NULL, attempts = 0;
    -- A changed chunk invalidates its prior open findings.
    UPDATE knowledge_conflicts SET status = 'superseded'
     WHERE tenant_id = NEW.tenant_id AND status = 'open' AND NEW.id IN (chunk_a_id, chunk_b_id);
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.enqueue_de_work_item(p_tenant_id uuid, p_de_id uuid, p_title text, p_kind text DEFAULT 'act'::text, p_scheduled_for timestamp with time zone DEFAULT now(), p_objective_id uuid DEFAULT NULL::uuid, p_seq integer DEFAULT 0, p_depends_on uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_max_attempts integer DEFAULT 3)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if auth.uid() is not null
     and not exists (select 1 from profiles p where p.user_id = auth.uid()
                       and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to enqueue work for this tenant';
  end if;

  insert into de_work_items (tenant_id, de_id, objective_id, title, kind,
                             scheduled_for, seq, depends_on, payload,
                             idempotency_key, max_attempts)
  values (p_tenant_id, p_de_id, p_objective_id, p_title, p_kind,
          coalesce(p_scheduled_for, now()), p_seq, p_depends_on, coalesce(p_payload, '{}'::jsonb),
          p_idempotency_key, greatest(1, p_max_attempts))
  on conflict (tenant_id, idempotency_key) where idempotency_key is not null
    do nothing
  returning id into v_id;

  -- ON CONFLICT DO NOTHING returns no row; fetch the existing one so the
  -- caller always gets a stable id for the same idempotency key.
  if v_id is null and p_idempotency_key is not null then
    select id into v_id from de_work_items
     where tenant_id = p_tenant_id and idempotency_key = p_idempotency_key;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.erd_human_task_id(p_decision_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select human_task_id from evidence_run_decisions where id = p_decision_id;
$function$;

CREATE OR REPLACE FUNCTION public.expire_trials()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_count int;
begin
  with expired as (
    update tenants
    set status = 'suspended', updated_at = now()
    where status = 'trial'
      and trial_ends_at is not null
      and trial_ends_at < now()
      and id <> v_demo_tenant_id
    returning id, name
  )
  select count(*) into v_count from expired;

  return coalesce(v_count, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_config(p_tenant_id uuid)
 RETURNS TABLE(metrics jsonb, schemas jsonb, configs jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT
    (SELECT jsonb_agg(row_to_json(t)) FROM customer_metrics t WHERE t.tenant_id = p_tenant_id),
    (SELECT jsonb_agg(row_to_json(t)) FROM de_config_schemas t WHERE t.tenant_id = p_tenant_id),
    (SELECT jsonb_agg(row_to_json(t)) FROM de_config t WHERE t.tenant_id = p_tenant_id);
END$function$;

CREATE OR REPLACE FUNCTION public.fail_ingestion_item(p_item_id uuid, p_error text, p_kind text DEFAULT 'retryable'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item knowledge_ingestion_items; v_final boolean; v_backoff interval;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'not callable by tenant users';
  END IF;
  IF p_kind NOT IN ('retryable','terminal') THEN
    RAISE EXCEPTION 'error kind must be retryable or terminal, got %', p_kind;
  END IF;

  SELECT * INTO v_item FROM knowledge_ingestion_items WHERE id = p_item_id;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'ingestion item not found'; END IF;

  -- Terminal failures do not get their remaining attempts. Retrying an
  -- unreadable file three times just delays telling the human it is unreadable.
  v_final := (p_kind = 'terminal') OR (v_item.attempts >= v_item.max_attempts);

  IF v_final THEN
    UPDATE knowledge_ingestion_items
       SET status='failed', last_error=left(p_error, 2000), error_kind=p_kind, updated_at=now()
     WHERE id = p_item_id;
    RETURN 'failed';
  END IF;

  -- Exponential backoff, capped: 1m, 4m, 9m... never more than an hour.
  v_backoff := make_interval(secs => least(3600, 60 * power(greatest(v_item.attempts,1), 2)::int));
  UPDATE knowledge_ingestion_items
     SET status='queued', last_error=left(p_error, 2000), error_kind=p_kind,
         next_attempt_at = now() + v_backoff, updated_at=now()
   WHERE id = p_item_id;
  RETURN 'retry_scheduled';
END $function$;

CREATE OR REPLACE FUNCTION public.find_duplicate_knowledge_doc(p_tenant_id uuid, p_title text, p_content text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT d.id FROM knowledge_docs d
   WHERE d.tenant_id = p_tenant_id
     AND d.is_current
     AND d.content_hash = public.knowledge_content_hash(p_title, p_content)
   LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.finish_browser_task(p_task_id uuid, p_status text, p_result text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  IF p_status NOT IN ('done','failed') THEN RAISE EXCEPTION 'status must be done or failed'; END IF;
  UPDATE computer_use_tasks
     SET status = p_status, result = left(coalesce(p_result, ''), 8000), updated_at = now()
   WHERE id = p_task_id AND status IN ('claimed','running');
END; $function$;

CREATE OR REPLACE FUNCTION public.forget_de_memory(p_memory_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_row de_memory;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  SELECT * INTO v_row FROM de_memory WHERE id = p_memory_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'memory_not_found'; END IF;

  DELETE FROM de_memory WHERE id = p_memory_id;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('Memory removed — %s', left(v_row.content, 120)), 'config_change',
    jsonb_build_object('de_id', v_row.de_id, 'kind', v_row.kind, 'subject_ref', v_row.subject_ref)
  );
  RETURN jsonb_build_object('ok', true);
END$function$;

CREATE OR REPLACE FUNCTION public.gate_de_certification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_gated text[] := array['certified','published','assigned','active']; v_fp text;
begin
  if NEW.lifecycle_status = any(v_gated) and OLD.lifecycle_status is distinct from NEW.lifecycle_status
     and OLD.lifecycle_status <> all(v_gated) then
    -- Fingerprint NEW, not a re-SELECT of the pre-update row: a single
    -- statement changing config AND lifecycle is judged on the config
    -- that will actually go live (C1).
    v_fp := public.de_config_fingerprint_row(NEW);
    if not exists (
      select 1 from role_certifications c
       where c.de_id = NEW.id and c.status = 'passed'
         and c.config_fingerprint is not distinct from v_fp
    ) then
      if exists (select 1 from role_certifications c where c.de_id = NEW.id and c.status = 'passed') then
        raise exception 'DE % cannot advance to "%": its passing certification is STALE — the configuration (including changes in this statement) was not certified. Re-run its eval/simulation and re-certify first.', NEW.id, NEW.lifecycle_status;
      else
        raise exception 'DE % cannot advance to "%": it has not passed role certification. Run its eval/simulation and certify it first.', NEW.id, NEW.lifecycle_status;
      end if;
    end if;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.gate_knowledge_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_gate record;
BEGIN
  -- Humans only: service-role pipelines and unauthenticated internals pass.
  IF coalesce(auth.role(), '') <> 'authenticated' THEN RETURN NEW; END IF;
  -- Revisions are the FIX path — never gate them.
  IF NEW.previous_version_id IS NOT NULL THEN RETURN NEW; END IF;
  -- The audited override tag from the client dialog passes.
  IF NEW.tags IS NOT NULL AND 'eval-gate-override' = ANY(NEW.tags) THEN RETURN NEW; END IF;

  SELECT status, passed, failed INTO v_gate
  FROM eval_gate WHERE tenant_id = NEW.tenant_id;
  IF v_gate.status = 'failed' THEN
    RAISE EXCEPTION 'eval_gate_failed: your latest evaluation run failed (% passed, % failed). Fix the failing answers in the Proving Ground, or use the override in the Library editor — overrides are recorded on the audit trail.',
      coalesce(v_gate.passed, 0), coalesce(v_gate.failed, 0)
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.generate_embed_token(p_tenant_id uuid, p_de_id uuid, p_expires_in_hours integer DEFAULT 24)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token TEXT;
  v_token_hash TEXT;
  v_expires_at TIMESTAMP;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  IF auth.uid() IS NOT NULL
     AND NOT public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'admin_role_required';
  END IF;
  PERFORM 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'de_not_in_tenant'; END IF;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_token_hash := encode(digest(v_token, 'sha256'), 'hex');
  v_expires_at := now() + make_interval(hours => LEAST(GREATEST(p_expires_in_hours, 1), 24 * 90));

  INSERT INTO embed_tokens (tenant_id, de_id, token_hash, expires_at)
  VALUES (p_tenant_id, p_de_id, v_token_hash, v_expires_at);

  RETURN json_build_object('token', v_token, 'expires_at', v_expires_at::text);
END$function$;

CREATE OR REPLACE FUNCTION public.get_agentic_run_messages(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  -- The run must belong to the caller's tenant, or no turns are returned.
  if not exists (select 1 from agentic_step_runs r where r.id = p_run_id and r.tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'run_not_found');
  end if;
  select coalesce(jsonb_agg(row_to_json(x) order by x.turn_index), '[]'::jsonb) into v_out from (
    select m.id, m.turn_index, m.role, m.content, m.created_at
      from agentic_step_messages m
     where m.agentic_step_run_id = p_run_id
     order by m.turn_index
  ) x;
  return jsonb_build_object('ok', true, 'messages', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_agentic_tools_for_de(p_tenant_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tools jsonb := '[]'::jsonb;
  v_conn record;
  v_def record;
  v_verdict jsonb;
  v_properties jsonb;
  v_required jsonb;
  v_param record;
  v_type text;
  v_name text;     -- sanitized, connector-unique tool name
  v_suffix text;   -- per-connector discriminator
begin
  for v_conn in
    select id, category, display_name, provider
    from connectors
    where tenant_id = p_tenant_id and status = 'connected'
  loop
    for v_def in
      select *
      from action_definitions
      where status = 'active'
        and provider <> 'internal'
        and category = v_conn.category
        and (scope = 'platform' or (scope = 'tenant' and tenant_id = p_tenant_id))
    loop
      select resolve_access(p_tenant_id, 'de', p_de_id, v_conn.id, 'write_back') into v_verdict;
      if coalesce((v_verdict->>'allowed')::boolean, false) then
        v_properties := '{}'::jsonb;
        v_required := '[]'::jsonb;

        for v_param in
          select * from jsonb_to_recordset(v_def.param_schema)
            as x(name text, type text, required boolean, help text)
        loop
          v_type := case v_param.type when 'number' then 'number' when 'boolean' then 'boolean' else 'string' end;
          v_properties := v_properties || jsonb_build_object(
            v_param.name, jsonb_build_object('type', v_type, 'description', coalesce(v_param.help, ''))
          );
          if coalesce(v_param.required, false) then
            v_required := v_required || to_jsonb(v_param.name);
          end if;
        end loop;

        -- Connector-unique + charset-safe + length-bounded (Anthropic: ^[a-zA-Z0-9_-]{1,64}$).
        v_suffix := '__' || left(replace(v_conn.id::text, '-', ''), 6);
        v_name := regexp_replace(v_conn.category || '__' || v_def.action_key, '[^a-zA-Z0-9_-]', '_', 'g');
        v_name := left(v_name, 64 - length(v_suffix)) || v_suffix;

        v_tools := v_tools || jsonb_build_array(jsonb_build_object(
          'name', v_name,
          'description', v_def.label || '. ' || v_def.description
                         || ' (system: ' || coalesce(nullif(v_conn.display_name, ''), v_conn.provider) || ')',
          'input_schema', jsonb_build_object(
            'type', 'object', 'properties', v_properties, 'required', v_required
          ),
          'connector_id', v_conn.id,
          'action_key', v_def.action_key,
          'destructive', coalesce((v_def.risk->>'destructive')::boolean, true)
        ));
      end if;
    end loop;
  end loop;

  return v_tools;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_all_tenants_with_summary()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN json_agg(
    json_build_object(
      'tenant_id', t.id,
      'name', t.name,
      'slug', t.slug,
      'status', t.status,
      'plan', t.plan,
      'industry', t.industry,
      'admin_email', t.admin_email,
      'adoption_score', COALESCE(t.adoption_score, 0),
      'de_count', de_cnt.count,
      'active_features', active_features.count,
      'monthly_cost', COALESCE(ROUND(tct.total_cost, 2), 0),
      'cost_vs_budget', CASE
        WHEN tft.monthly_cost_limit IS NOT NULL
        THEN ROUND(100 * tct.total_cost / tft.monthly_cost_limit, 1)
        ELSE NULL
      END,
      'created_at', t.created_at::text
    )
  )
  FROM tenants t
  LEFT JOIN tenant_feature_toggles tft ON tft.tenant_id = t.id
  LEFT JOIN tenant_cost_tracking tct ON tct.tenant_id = t.id
    AND tct.billing_month = to_char(now(), 'YYYY-MM')
  LEFT JOIN LATERAL (
    SELECT COUNT(*) as count FROM digital_employees
    WHERE tenant_id = t.id
  ) de_cnt ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*) as count FROM tenant_feature_toggles
    WHERE tenant_id = t.id
    AND (sophie_config_enabled OR amendment_journeys_enabled OR metrics_tracking_enabled
      OR reply_mode_enabled OR hosted_chat_enabled)
  ) active_features ON true
  ORDER BY t.created_at DESC;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_amendment_effectiveness(p_entity_kind text, p_entity_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_total INT; v_adopted INT;
  v_conf NUMERIC; v_esc NUMERIC; v_replay NUMERIC;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE adopted_at IS NOT NULL)
  INTO v_total, v_adopted
  FROM amendment_metrics
  WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id AND tenant_id = v_tenant_id;

  SELECT AVG(confidence_delta), AVG(escalation_rate_delta),
         AVG(COALESCE(replay_score_after - replay_score_before, 0))
  INTO v_conf, v_esc, v_replay
  FROM amendment_metrics
  WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id
    AND tenant_id = v_tenant_id AND adopted_at IS NOT NULL;

  RETURN json_build_object(
    'entity_kind', p_entity_kind,
    'entity_id', p_entity_id,
    'total_amendments', v_total,
    'adopted_count', v_adopted,
    'adoption_rate_pct', CASE WHEN v_total > 0 THEN ROUND((v_adopted::NUMERIC / v_total) * 100, 1) ELSE 0 END,
    'avg_confidence_delta', ROUND(COALESCE(v_conf, 0)::NUMERIC, 2),
    'avg_escalation_rate_delta', ROUND(COALESCE(v_esc, 0)::NUMERIC, 2),
    'avg_replay_score_gain', ROUND(COALESCE(v_replay, 0)::NUMERIC, 2)
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_amendment_impact_history(p_entity_kind text, p_entity_id uuid, p_limit integer DEFAULT 10)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  RETURN (
    SELECT json_agg(row_to_json(t))
    FROM (
      SELECT metric_id, amendment_id, confidence_delta, escalation_rate_delta,
             COALESCE(replay_score_after - replay_score_before, 0) AS replay_score_delta,
             adopted_at::text AS adopted_at,
             CASE WHEN adopted_at IS NOT NULL THEN 'adopted' ELSE 'pending' END AS status
      FROM amendment_metrics
      WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id AND tenant_id = v_tenant_id
      ORDER BY created_at DESC
      LIMIT p_limit
    ) t
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_benchmark_report(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_from timestamptz := now() - make_interval(days => greatest(1, least(365, p_days)));
  v_outcomes jsonb; v_quality jsonb; v_csat jsonb; v_cost jsonb; v_sim jsonb;
  v_res bigint; v_esc bigint; v_cost_cents numeric;
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized';
  end if;

  -- Billable resolutions only (a human-handled conversation is not an AI
  -- resolution); escalations and blocks all stay in the denominator.
  select count(*) filter (where kind = 'resolution' and billable),
         count(*) filter (where kind = 'escalation')
    into v_res, v_esc
    from billable_outcomes
   where tenant_id = p_tenant_id and occurred_at >= v_from
     and (p_de_id is null or de_id = p_de_id);
  v_outcomes := jsonb_build_object(
    'resolutions', v_res, 'escalations', v_esc,
    'resolution_rate_pct', case when v_res + v_esc > 0 then round(100.0 * v_res / (v_res + v_esc), 1) end);

  select jsonb_build_object(
      'graded', count(*),
      'pass_rate_pct', case when count(*) > 0 then round(100.0 * count(*) filter (where verdict = 'pass') / count(*), 1) end,
      'avg_score', case when count(*) > 0 then round(avg(score), 1) end)
    into v_quality
    from eval_judgments
   where tenant_id = p_tenant_id and created_at >= v_from
     and (p_de_id is null or de_id = p_de_id);

  -- CSAT is a ±1 thumbs field: % positive is the honest statistic (an
  -- "average of 0.33" is meaningless to a reader).
  select jsonb_build_object(
      'ratings', count(*),
      'positive_pct', case when count(*) > 0 then round(100.0 * count(*) filter (where csat_score = 1) / count(*), 1) end)
    into v_csat
    from de_conversations
   where tenant_id = p_tenant_id and csat_submitted_at is not null and csat_submitted_at >= v_from
     and (p_de_id is null or de_id = p_de_id);

  select coalesce(sum(
      u.input_tokens  / 1000000.0 * coalesce(pr.input_price_per_million, 0) * 100
    + u.output_tokens / 1000000.0 * coalesce(pr.output_price_per_million, 0) * 100), 0)
    into v_cost_cents
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
   where u.tenant_id = p_tenant_id and u.created_at >= v_from
     and (p_de_id is null or u.de_id = p_de_id);
  v_cost := jsonb_build_object(
    'ai_spend_cents', round(v_cost_cents),
    'cost_per_resolution_cents', case when v_res > 0 then round(v_cost_cents / v_res) end);

  select jsonb_build_object('mode', mode, 'passed', passed, 'total', total,
                            'avg_score', avg_score, 'status', status, 'ran_at', started_at)
    into v_sim
    from sim_runs
   where tenant_id = p_tenant_id and candidate = false and status in ('passed', 'failed')
     and (p_de_id is null or de_id = p_de_id)
   order by started_at desc limit 1;

  return jsonb_build_object(
    'window_days', greatest(1, least(365, p_days)),
    'de_id', p_de_id,
    'generated_at', now(),
    'outcomes', v_outcomes,
    'judged_quality', v_quality,
    'csat', v_csat,
    'cost', v_cost,
    'capability', coalesce(v_sim, jsonb_build_object('status', 'no_simulation_yet')),
    'definitions', jsonb_build_object(
      'resolution_rate_pct', 'Auto-sent, guardrail-clean answers that were NOT later handed to a human, as a share of ALL metered outcomes in the window — every escalation, hand-off, and guardrail block counts in the denominator. Nothing is excluded.',
      'judged_quality', 'Share of graded answers an independent LLM judge scored as passing on grounding, correctness, guardrail adherence, and tone.',
      'csat', 'Percent of customer-submitted thumbs ratings that were positive. Never inferred or imputed.',
      'cost_per_resolution_cents', 'Real model spend in the window divided by billable resolutions delivered.',
      'capability', 'Latest certification-grade simulation result. Dry-run (candidate) simulations are excluded, exactly as they are excluded from certification.'));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_browser_login(p_tenant_id uuid, p_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s de_connected_systems; v_secret text; v_dom text;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  v_dom := lower(regexp_replace(regexp_replace(coalesce(p_domain,''), '^https?://', ''), '/.*$', ''));
  FOR s IN SELECT * FROM de_connected_systems WHERE tenant_id = p_tenant_id AND can_operate AND login_secret_id IS NOT NULL LOOP
    IF public.operate_domain_of(s) = v_dom THEN
      SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE id = s.login_secret_id LIMIT 1;
      IF v_secret IS NOT NULL THEN
        -- Secret convention: JSON {"username":"…","password":"…"} or a bare password.
        RETURN jsonb_build_object('ok', true, 'secret', v_secret);
      END IF;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', false, 'error', 'no_login_secret');
END; $function$;

CREATE OR REPLACE FUNCTION public.get_browser_task(p_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  SELECT to_jsonb(c) - 'constraints' INTO v FROM computer_use_tasks c WHERE c.id = p_task_id
    AND (c.tenant_id = public.auth_tenant_id() OR EXISTS (SELECT 1 FROM profiles WHERE user_id = auth.uid() AND layer = 'platform'));
  IF v IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'task', v);
END; $function$;

CREATE OR REPLACE FUNCTION public.get_config_audit_log(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(audit_id uuid, "timestamp" timestamp with time zone, changed_by uuid, action text, field_name text, old_value jsonb, new_value jsonb, details text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT dal.audit_id, dal.changed_at, dal.changed_by, dal.action,
         dal.field_name, dal.old_value, dal.new_value, dal.details
  FROM de_config_audit_log dal
  WHERE dal.tenant_id = p_tenant_id AND dal.entity_kind = p_entity_kind AND dal.entity_id = p_entity_id
  ORDER BY dal.changed_at DESC
  LIMIT p_limit;
END$function$;

CREATE OR REPLACE FUNCTION public.get_config_schema(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(schema_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, name text, fields jsonb, tags text[], created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT * FROM de_config_schemas s
  WHERE s.tenant_id = p_tenant_id AND s.entity_kind = p_entity_kind
    AND (s.entity_id = p_entity_id OR s.entity_id IS NULL)
  ORDER BY s.entity_id DESC NULLS LAST
  LIMIT 1;
END$function$;

CREATE OR REPLACE FUNCTION public.get_config_template_with_overrides(p_de_id uuid, p_template_key text DEFAULT 'support-de-template'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_template JSONB;
  v_field JSONB;
  v_overrides JSONB;
  v_merged JSONB := '{}'::jsonb;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT fields INTO v_template FROM config_schema_templates WHERE template_key = p_template_key;
  IF v_template IS NULL THEN RAISE EXCEPTION 'Template not found: %', p_template_key; END IF;

  SELECT values INTO v_overrides
  FROM config_schema_instances
  WHERE de_id = p_de_id AND tenant_id = v_tenant_id AND template_key = p_template_key;
  v_overrides := COALESCE(v_overrides, '{}'::jsonb);

  FOR v_field IN SELECT * FROM jsonb_array_elements(v_template)
  LOOP
    v_merged := v_merged || jsonb_build_object(
      v_field->>'key',
      COALESCE(v_overrides->(v_field->>'key'), v_field->'defaultValue')
    );
  END LOOP;

  RETURN v_merged;
END$function$;

CREATE OR REPLACE FUNCTION public.get_conversation_facts(p_tenant_id uuid, p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select coalesce(jsonb_object_agg(fact_key, fact_value), '{}'::jsonb)
  from conversation_facts
  where tenant_id = p_tenant_id and conversation_id = p_conversation_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_action_metrics(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_events bigint, executed bigint, auto_executed bigint, approved_after_gate bigint, sent_to_human bigint, blocked bigint, rejected bigint, failed bigint, autonomy_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s performance data';
  end if;
  return query
    with ax as (
      select ae.subject_id as d_de_id, ae.decision as dec
      from action_executions ae
      where ae.tenant_id = p_tenant_id
        and ae.subject_kind = 'de'
        and ae.subject_id is not null
        and ae.decision <> 'previewed'
        and (p_days is null or ae.created_at >= now() - make_interval(days => p_days))
    )
    select
      ax.d_de_id as de_id,
      count(*)::bigint,
      count(*) filter (where dec in ('auto_executed', 'executed_after_approval'))::bigint,
      count(*) filter (where dec = 'auto_executed')::bigint,
      count(*) filter (where dec = 'executed_after_approval')::bigint,
      count(*) filter (where dec in ('human_gated_destructive', 'human_gated_trust'))::bigint,
      count(*) filter (where dec in ('guardrail_blocked', 'access_denied'))::bigint,
      count(*) filter (where dec = 'rejected')::bigint,
      count(*) filter (where dec = 'failed')::bigint,
      round(100.0 * count(*) filter (where dec = 'auto_executed')
        / nullif(count(*) filter (where dec in ('auto_executed', 'executed_after_approval')), 0), 1)
    from ax
    group by ax.d_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_agentic_runs(p_de_id uuid, p_limit integer DEFAULT 15)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(50, coalesce(p_limit, 15)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select r.id, r.goal, r.status, r.iteration_count,
           coalesce(r.cost_used_cents, 0) as cost_used_cents,
           r.tokens_used, r.created_at, r.completed_at
      from agentic_step_runs r
     where r.tenant_id = v_tenant and r.de_id = p_de_id
     order by r.created_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'runs', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_briefing(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_sop text;
  v_guard text;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return jsonb_build_object('sop','','guardrails',''); end if;

  -- ALL attached, published SOPs (titled; newest first; capped at 4).
  select string_agg(sop_text, E'\n\n' order by upd desc)
  into v_sop
  from (
    select pd.updated_at as upd,
           '## ' || pd.name || E'\n' || (
             select string_agg(
               s.ord || '. ' || coalesce(s.elem->>'label','step') ||
               case
                 when s.elem->>'key' = 'instruction' and s.elem->'params'->>'body_md' is not null
                   then ' — ' || (s.elem->'params'->>'body_md')
                 when s.elem->>'key' = 'checklist'
                   then ' — ' || coalesce((select string_agg(i.value #>> '{}', '; ')
                                            from jsonb_array_elements(s.elem->'params'->'items') i), '')
                 else ''
               end, E'\n' order by s.ord)
             from jsonb_array_elements(pd.steps) with ordinality as s(elem, ord)
           ) as sop_text
    from playbook_definitions pd
    where pd.de_id = p_de_id and pd.status = 'published'
    order by pd.updated_at desc
    limit 4
  ) sops;

  -- The DE's active guardrails, rendered as rules it must honour.
  select string_agg('- ' ||
    case r.rule_type
      when 'blocked_phrase' then 'Never commit to / say: ' || coalesce(r.pattern,'')
      when 'blocked_topic'  then 'Do not act on topic: ' || coalesce(r.pattern,'')
      when 'max_discount_pct' then 'Any discount above ' || coalesce(r.threshold::text,'0') || '% must be proposed for human approval'
      when 'require_approval_over_cents' then 'Any amount over $' || to_char(coalesce(r.threshold,0)/100.0,'FM999,999,990.00') || ' must be proposed for human approval'
      when 'frustration_signal' then 'Escalate to a human on: ' || coalesce(r.pattern,'')
      else coalesce(r.rule,'')
    end, E'\n')
  into v_guard
  from guardrail_rules_for_de(v_tenant, p_de_id,
       ARRAY['blocked_phrase','blocked_topic','max_discount_pct','require_approval_over_cents','frustration_signal'],
       null) r
  where r.active;

  return jsonb_build_object('sop', coalesce(v_sop,''), 'guardrails', coalesce(v_guard,''));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_briefing_for_objective(p_de_id uuid, p_objective text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid; v_sop text; v_guard text; v_pid uuid; v_name text; v_by_rel boolean := false;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then
    return jsonb_build_object('sop','','guardrails','','matched_playbook_id',null,'matched_by_relevance',false);
  end if;

  -- Best-matching published SOP by full-text rank vs the objective; fallback to
  -- most-recent (empty/nonsense objective → all ranks 0 → most-recent wins).
  select pd.id, pd.name, render_playbook_structure(pd.steps),
         (ts_rank(to_tsvector('english', coalesce(pd.name,'') || ' ' || coalesce(pd.description,'')),
                  plainto_tsquery('english', coalesce(p_objective,''))) > 0)
    into v_pid, v_name, v_sop, v_by_rel
  from playbook_definitions pd
  where pd.de_id = p_de_id and pd.status = 'published'
  order by ts_rank(to_tsvector('english', coalesce(pd.name,'') || ' ' || coalesce(pd.description,'')),
                   plainto_tsquery('english', coalesce(p_objective,''))) desc nulls last,
           pd.updated_at desc
  limit 1;

  -- Guardrail block — byte-identical to get_de_briefing (mig 250:48-62).
  select string_agg('- ' ||
    case r.rule_type
      when 'blocked_phrase' then 'Never commit to / say: ' || coalesce(r.pattern,'')
      when 'blocked_topic'  then 'Do not act on topic: ' || coalesce(r.pattern,'')
      when 'max_discount_pct' then 'Any discount above ' || coalesce(r.threshold::text,'0') || '% must be proposed for human approval'
      when 'require_approval_over_cents' then 'Any amount over $' || to_char(coalesce(r.threshold,0)/100.0,'FM999,999,990.00') || ' must be proposed for human approval'
      when 'frustration_signal' then 'Escalate to a human on: ' || coalesce(r.pattern,'')
      else coalesce(r.rule,'')
    end, E'\n')
  into v_guard
  from guardrail_rules_for_de(v_tenant, p_de_id,
       ARRAY['blocked_phrase','blocked_topic','max_discount_pct','require_approval_over_cents','frustration_signal'],
       null) r
  where r.active;

  return jsonb_build_object(
    'sop', case when v_sop is not null and v_name is not null then '## ' || v_name || E'\n' || v_sop else '' end,
    'guardrails', coalesce(v_guard,''),
    'matched_playbook_id', v_pid,
    'matched_by_relevance', coalesce(v_by_rel,false)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_config(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid)
 RETURNS TABLE(config_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, schema_id uuid, data jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT * FROM de_config dc
  WHERE dc.tenant_id = p_tenant_id AND dc.entity_kind = p_entity_kind AND dc.entity_id = p_entity_id;
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_config(p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  RETURN (
    SELECT json_build_object(
      'instance_id', instance_id,
      'de_id', de_id,
      'template_key', template_key,
      'values', values,
      'updated_at', updated_at::text
    )
    FROM config_schema_instances
    WHERE de_id = p_de_id AND tenant_id = v_tenant_id
    LIMIT 1
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_cost_metrics(p_tenant_id uuid)
 RETURNS TABLE(de_id uuid, total_calls bigint, total_input_tokens bigint, total_output_tokens bigint, total_cost_usd numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s cost data';
  end if;

  return query
    select
      u.de_id,
      count(*) as total_calls,
      sum(u.input_tokens) as total_input_tokens,
      sum(u.output_tokens) as total_output_tokens,
      round(sum(
        (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
        + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
      ), 4) as total_cost_usd
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
    where u.tenant_id = p_tenant_id and u.de_id is not null
    group by u.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_cost_metrics_ranged(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_calls bigint, total_input_tokens bigint, total_output_tokens bigint, total_cost_usd numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s cost data';
  end if;
  return query
    select
      u.de_id,
      count(*)::bigint as total_calls,
      sum(u.input_tokens)::bigint as total_input_tokens,
      sum(u.output_tokens)::bigint as total_output_tokens,
      round(sum(
        (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
        + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
      ), 4) as total_cost_usd
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
    where u.tenant_id = p_tenant_id and u.de_id is not null
      and (p_days is null or u.created_at >= now() - make_interval(days => p_days))
    group by u.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_csat_metrics(p_tenant_id uuid)
 RETURNS TABLE(de_id uuid, total_ratings bigint, positive_ratings bigint, csat_pct numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s CSAT data';
  end if;

  return query
    select
      c.de_id,
      count(*) as total_ratings,
      count(*) filter (where c.csat_score = 1) as positive_ratings,
      round(100.0 * count(*) filter (where c.csat_score = 1) / nullif(count(*), 0), 1) as csat_pct
    from de_conversations c
    where c.tenant_id = p_tenant_id and c.csat_submitted_at is not null and c.de_id is not null
    group by c.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_economics(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  b workforce_baselines;
  v_inquiries bigint;
  v_actions bigint;
  v_conversations bigint;
  v_de_cost numeric;
  v_human_minutes numeric := 0;
  v_counted boolean := false;
  v_missing text[] := '{}';
  v_fte numeric;
  v_human_cost numeric;
  v_roi numeric;
  v_savings numeric;
  v_std_minutes numeric;
begin
  if p_days < 1 or p_days > 365 then raise exception 'window must be 1-365 days'; end if;
  -- Same trusted-server/human gate as get_de_performance_metrics.
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then raise exception 'not authenticated'; end if;
    if not (is_platform_admin()
            or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
      raise exception 'not authorized to view this workspace''s economics';
    end if;
  end if;

  select * into b from workforce_baselines where tenant_id = p_tenant_id;

  -- Real work counts, windowed.
  select count(*) into v_inquiries
  from evidence_run_decisions d join evidence_runs er on er.id = d.evidence_run_id
  where er.tenant_id = p_tenant_id and er.de_id is not null
    and (p_de_id is null or er.de_id = p_de_id)
    and d.created_at > now() - make_interval(days => p_days);

  select count(*) into v_actions
  from action_executions
  where tenant_id = p_tenant_id and subject_kind = 'de' and mode = 'execute'
    and decision in ('auto_executed', 'executed_after_approval')
    and (p_de_id is null or subject_id = p_de_id)
    and created_at > now() - make_interval(days => p_days);

  select count(*) into v_conversations
  from de_conversations
  where tenant_id = p_tenant_id and de_id is not null
    and (p_de_id is null or de_id = p_de_id)
    and created_at > now() - make_interval(days => p_days);

  -- Real AI cost, windowed (same pricing join as get_de_cost_metrics).
  select coalesce(round(sum(
      (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
      + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
    ), 4), 0) into v_de_cost
  from de_token_usage u
  left join ai_model_pricing pr on pr.model_id = u.model_id
  where u.tenant_id = p_tenant_id
    and (p_de_id is null or u.de_id = p_de_id)
    and u.created_at > now() - make_interval(days => p_days);

  -- Human-minutes over CONFIGURED task types only.
  if b.inquiry_minutes is not null then
    v_human_minutes := v_human_minutes + v_inquiries * b.inquiry_minutes; v_counted := true;
  elsif v_inquiries > 0 then v_missing := array_append(v_missing, 'inquiry_minutes'); end if;

  if b.action_minutes is not null then
    v_human_minutes := v_human_minutes + v_actions * b.action_minutes; v_counted := true;
  elsif v_actions > 0 then v_missing := array_append(v_missing, 'action_minutes'); end if;

  if b.conversation_minutes is not null then
    v_human_minutes := v_human_minutes + v_conversations * b.conversation_minutes; v_counted := true;
  elsif v_conversations > 0 then v_missing := array_append(v_missing, 'conversation_minutes'); end if;

  -- §12.3: 9,600 standard working minutes per month, prorated.
  v_std_minutes := 9600.0 * p_days / 30.0;
  if v_counted then
    v_fte := round(v_human_minutes / v_std_minutes, 3);
    if b.avg_fte_cost_monthly_usd is not null then
      v_human_cost := round(v_fte * b.avg_fte_cost_monthly_usd * p_days / 30.0, 2);
      v_savings := round(v_human_cost - v_de_cost, 2);
      if v_de_cost > 0 then
        v_roi := round((v_human_cost - v_de_cost) / v_de_cost, 1);
      end if;
    else
      v_missing := array_append(v_missing, 'avg_fte_cost_monthly_usd');
    end if;
  end if;

  return jsonb_build_object(
    'window_days', p_days,
    'counts', jsonb_build_object(
      'inquiries_handled', v_inquiries, 'actions_executed', v_actions, 'conversations_answered', v_conversations),
    'baselines', jsonb_build_object(
      'inquiry_minutes', b.inquiry_minutes, 'action_minutes', b.action_minutes,
      'conversation_minutes', b.conversation_minutes, 'avg_fte_cost_monthly_usd', b.avg_fte_cost_monthly_usd),
    'hours_saved', case when v_counted then round(v_human_minutes / 60.0, 1) end,
    'fte_equivalent', v_fte,
    'de_cost_usd', v_de_cost,
    'human_cost_equivalent_usd', v_human_cost,
    'monthly_saving_usd', case when v_savings is not null then round(v_savings * 30.0 / p_days, 2) end,
    'roi_ratio', v_roi,
    'unconfigured', to_jsonb(v_missing),
    'configured', v_counted and b.avg_fte_cost_monthly_usd is not null and array_length(v_missing, 1) is null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_escalation_rules(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de_rules jsonb; v_tenant_rules jsonb; v_frust int; v_topics text[];
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;

  select coalesce(custom_rules, '[]'::jsonb) into v_de_rules
    from de_escalation_rules where tenant_id = v_tenant and de_id = p_de_id;
  select coalesce(custom_rules, '[]'::jsonb) into v_tenant_rules
    from de_escalation_rules where tenant_id = v_tenant and de_id is null;

  select frustration_threshold, always_escalate_topics into v_frust, v_topics
    from resolve_de_escalation(v_tenant, p_de_id);

  return jsonb_build_object(
    'ok', true,
    'frustration_threshold', v_frust,
    'always_escalate_topics', to_jsonb(coalesce(v_topics, '{}')),
    'de_rules', coalesce(v_de_rules, '[]'::jsonb),
    'tenant_rules', coalesce(v_tenant_rules, '[]'::jsonb)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_execution_log(p_de_id uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(100, coalesce(p_limit, 25)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select s.name,
           round(extract(epoch from (s.ended_at - s.started_at)) * 1000)::int as duration_ms,
           s.started_at,
           s.attributes->>'gen_ai.request.model' as model,
           s.attributes->>'gen_ai.system' as provider,
           (s.attributes->>'gen_ai.usage.input_tokens')::int as input_tokens,
           (s.attributes->>'gen_ai.usage.output_tokens')::int as output_tokens,
           (s.attributes->>'dreamteam.confidence')::int as confidence,
           (s.attributes->>'dreamteam.escalated')::boolean as escalated,
           s.attributes->>'dreamteam.status' as work_status,
           (s.attributes->>'dreamteam.turns')::int as turns
      from otel_spans s
     where s.tenant_id = v_tenant
       and s.attributes->>'dreamteam.de_id' = p_de_id::text
       and s.parent_span_id is null   -- root span = one row per run
     order by s.started_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'runs', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_experience(p_de_id uuid, p_limit integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(200, coalesce(p_limit, 40)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select e.id, e.category, e.fact_summary, e.external_ref, e.created_at,
           (e.source_action_execution_id is not null) as from_action,
           (e.source_evidence_run_id is not null) as from_evidence
      from de_experience e
     where e.tenant_id = v_tenant
       and e.subject_kind in ('de', 'specialist')
       and e.subject_id = p_de_id
     order by e.created_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'experience', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_gate_status(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_g record;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  select * into v_g from public.de_records_gate(v_tenant, p_de_id);
  return jsonb_build_object('ok', true, 'gated', v_g.gated, 'reasons', to_jsonb(v_g.reasons));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_guardrail_activity(p_tenant_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(de_id uuid, de_name text, gated_count bigint, blocked_count bigint, tenant_total_events bigint, tenant_attributed_events bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant_total bigint;
  v_tenant_attributed bigint;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s guardrail activity';
  end if;

  -- Raw tenant-wide total, independent of name-attribution success --
  -- audit_events.actor is a free-text DE name (no de_id FK exists), so a
  -- historical DE rename can leave real events un-attributable to any
  -- CURRENT digital_employees row. Surfacing the raw total alongside the
  -- attributed rows keeps this honest instead of silently reading as
  -- "no guardrail activity" when there genuinely was some.
  select count(*) into v_tenant_total
    from audit_events a
    where a.tenant_id = p_tenant_id
      and (a.category = 'guardrail_block' or (a.category = 'guardrail_check' and a.detail->>'result' = 'gated'))
      and a.created_at > now() - (p_days || ' days')::interval;

  select count(*) into v_tenant_attributed
    from audit_events a
    join digital_employees de on de.tenant_id = p_tenant_id and de.name = a.actor
    where a.tenant_id = p_tenant_id
      and (a.category = 'guardrail_block' or (a.category = 'guardrail_check' and a.detail->>'result' = 'gated'))
      and a.created_at > now() - (p_days || ' days')::interval;

  return query
    select
      de.id, de.name,
      count(*) filter (where a.category = 'guardrail_check' and a.detail->>'result' = 'gated') as gated_count,
      count(*) filter (where a.category = 'guardrail_block') as blocked_count,
      v_tenant_total, v_tenant_attributed
    from digital_employees de
    join audit_events a on a.tenant_id = p_tenant_id and a.actor = de.name
      and a.category in ('guardrail_check', 'guardrail_block')
      and a.created_at > now() - (p_days || ' days')::interval
    where de.tenant_id = p_tenant_id
    group by de.id, de.name
    having count(*) filter (where a.category = 'guardrail_block' or a.detail->>'result' = 'gated') > 0;

  -- If real events exist tenant-wide but none could be attributed to a
  -- current DE name, still surface the totals via one summary-only row
  -- rather than silently returning nothing.
  if v_tenant_total > 0 and v_tenant_attributed = 0 and not found then
    return query select null::uuid, null::text, 0::bigint, 0::bigint, v_tenant_total, v_tenant_attributed;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_inquiry_metrics(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_decisions bigint, resolution_rate numeric, avg_confidence numeric, escalation_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s performance data';
  end if;
  return query
    with dec as (
      select er.de_id as d_de_id, d.confidence as conf, d.decision as decision
      from evidence_run_decisions d
      join evidence_runs er on er.id = d.evidence_run_id
      where er.tenant_id = p_tenant_id and er.de_id is not null
        and (p_days is null or d.created_at >= now() - make_interval(days => p_days))
    )
    select
      dec.d_de_id as de_id,
      count(*)::bigint,
      round(100.0 * count(*) filter (where dec.decision <> 'needs_review') / nullif(count(*), 0), 1),
      round(avg(dec.conf) filter (where dec.conf is not null), 1),
      round(100.0 * count(*) filter (where dec.decision = 'needs_review') / nullif(count(*), 0), 1)
    from dec
    group by dec.d_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_kpi_status(p_de_id uuid)
 RETURNS TABLE(kpi_id uuid, name text, metric_key text, target numeric, direction text, current numeric, met boolean, sample bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid; m record; v_csat numeric; v_csat_n bigint; v_vals jsonb; v_samples jsonb;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return; end if;
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth_tenant_id() is distinct from v_tenant then raise exception 'not a member of this workspace'; end if;
  end if;

  select * into m from get_de_performance_metrics(v_tenant, 13) where de_id = p_de_id;
  select round(100.0 * count(*) filter (where csat_score = 1) / nullif(count(*) filter (where csat_submitted_at is not null), 0), 1),
         count(*) filter (where csat_submitted_at is not null)
    into v_csat, v_csat_n
  from de_conversations where tenant_id = v_tenant and de_id = p_de_id;

  v_vals := jsonb_strip_nulls(jsonb_build_object(
    'resolution_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.resolution_rate end,
    'avg_confidence',         case when coalesce(m.total_decisions, 0) >= 1 then m.avg_confidence end,
    'escalation_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.escalation_rate end,
    'error_rate',             case when coalesce(m.total_runs, 0) >= 1 then m.error_rate end,
    'csat_pct',               v_csat,
    'high_frustration_count', case when coalesce(m.total_decisions, 0) >= 1 then m.high_frustration_count::numeric end,
    'total_decisions',        coalesce(m.total_decisions, 0)::numeric
  ));
  v_samples := jsonb_build_object('csat_pct', v_csat_n);

  return query
  select k.id, k.name, k.metric_key, k.target, k.direction, cur.v,
         case when cur.v is null then null
              when k.direction = 'higher' then cur.v >= k.target
              else cur.v <= k.target end,
         cur.n
  from de_kpis k
  left join kpi_metric_catalog c
    on c.metric_key = k.metric_key and (c.tenant_id is null or c.tenant_id = v_tenant)
  left join lateral (
    select
      case when coalesce(c.source, '') = 'action' then
        case when coalesce(c.source_config->>'agg', 'count') = 'auto_rate' then
          round(100.0 * count(*) filter (where ae.decision = 'auto_executed') / nullif(count(*), 0), 1)
        else count(*)::numeric end
      end as v,
      count(*) as n
      from action_executions ae
      left join action_definitions ad on ad.id = ae.action_definition_id
     where c.source = 'action'
       and ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
       and ae.rollback_of is null and ae.created_at >= now() - interval '91 days'
       and (coalesce(c.source_config->>'category', '') = '' or ad.category = c.source_config->>'category')
       and (coalesce(c.source_config->>'action_label', '') = '' or ad.label = c.source_config->>'action_label')
  ) act on true
  -- Latest manual reading, for metrics the platform doesn't compute.
  left join lateral (
    select d.value, count(*) over () as rn from de_kpi_readings d
     where d.de_id = k.de_id and d.metric_key = k.metric_key
       and d.source = 'manual'                    -- GI-5: fallback = human readings only
     order by d.as_of desc, d.created_at desc limit 1
  ) r on true
  cross join lateral (
    select coalesce((v_vals->>k.metric_key)::numeric, act.v, r.value) as v,
           coalesce((v_samples->>k.metric_key)::bigint, nullif(act.n, 0), r.rn, coalesce(m.total_decisions, 0)) as n
  ) cur;
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_metrics_batch(p_tenant_id uuid, p_de_id uuid, p_metric_keys text[] DEFAULT NULL::text[], p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(metric_key text, metric_name text, value numeric, unit text, trend text, comparison jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY SELECT NULL::TEXT, NULL::TEXT, NULL::NUMERIC, NULL::TEXT, NULL::TEXT, NULL::JSONB WHERE FALSE;
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_operating_model(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de record; v_out jsonb; v_board jsonb;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  SELECT * INTO v_de FROM digital_employees
   WHERE id = p_de_id AND tenant_id = v_tenant;
  IF v_de.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- The board row for this DE — next_up/listens_live come from the exact
  -- same read the whole-workforce board renders.
  v_board := (public.get_workforce_board(p_de_id)->'board')->0;

  v_out := jsonb_build_object(
    'ok', true,
    'identity', jsonb_build_object(
      'de_id', v_de.id, 'name', v_de.name, 'persona_name', v_de.persona_name,
      'department', v_de.department, 'category', v_de.category,
      'trust_level', v_de.trust_level, 'status', v_de.status),
    'work_sources', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'label', w.label, 'description', w.description, 'kind', w.kind,
               'active', w.active, 'next_fire_at', w.next_fire_at,
               'last_run_at', w.last_run_at, 'last_match_count', w.last_match_count)
             ORDER BY w.active DESC, w.label)
        FROM work_watchers w
       WHERE w.tenant_id = v_tenant AND w.de_id = p_de_id), '[]'::jsonb),
    'playbooks', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'key', p.key, 'name', p.name, 'status', p.status,
               'version', p.version, 'steps', jsonb_array_length(p.steps),
               'trigger_type', p.trigger_type)
             ORDER BY p.name)
        FROM playbook_definitions p
       WHERE p.tenant_id = v_tenant AND p.de_id = p_de_id
         AND p.status = 'published'), '[]'::jsonb),
    'open_objectives', COALESCE((
      SELECT count(*) FROM de_objectives o
       WHERE o.tenant_id = v_tenant AND o.de_id = p_de_id
         AND o.status IN ('open','in_progress','blocked')), 0),
    'waiting_on_human', COALESCE((
      SELECT count(*) FROM human_tasks h
       WHERE h.tenant_id = v_tenant AND h.de_id = p_de_id
         AND h.status = 'pending'), 0),

    -- v2 additions ---------------------------------------------------------
    'current_focus', (
      SELECT jsonb_build_object(
               'title', o.title, 'status', o.status,
               'next_wake_at', o.next_wake_at, 'wake_count', o.wake_count,
               'mission_id', o.mission_id, 'due_at', o.due_at)
        FROM de_objectives o
       WHERE o.tenant_id = v_tenant AND o.de_id = p_de_id
         AND o.status = 'in_progress'
       ORDER BY o.updated_at DESC LIMIT 1),
    'next_up', COALESCE(v_board->'next_up', '[]'::jsonb),
    'listens_live', COALESCE(v_board->'listens_live', 'false'::jsonb),
    'rhythm', jsonb_build_object(
      'done_7d', COALESCE((
        SELECT count(*) FROM de_work_items t
         WHERE t.tenant_id = v_tenant AND t.de_id = p_de_id
           AND t.status = 'done'
           AND t.updated_at >= now() - interval '7 days'), 0),
      'deliverables_7d', COALESCE((
        SELECT count(*) FROM de_deliverables d
         WHERE d.tenant_id = v_tenant AND d.de_id = p_de_id
           AND d.created_at >= now() - interval '7 days'), 0),
      'last_deliverable', (
        SELECT jsonb_build_object('title', d.title, 'at', d.created_at)
          FROM de_deliverables d
         WHERE d.tenant_id = v_tenant AND d.de_id = p_de_id
         ORDER BY d.created_at DESC LIMIT 1))
  );
  RETURN v_out;
END $function$;

CREATE OR REPLACE FUNCTION public.get_de_performance_metrics(p_tenant_id uuid, p_weeks integer DEFAULT 26)
 RETURNS TABLE(de_id uuid, de_name text, total_decisions bigint, resolution_rate numeric, avg_confidence numeric, escalation_rate numeric, blocked_guardrail_count bigint, total_runs bigint, error_rate numeric, avg_frustration_score numeric, high_frustration_count bigint, trend jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then
      raise exception 'not authenticated';
    end if;
    if not (
      is_platform_admin()
      or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
    ) then
      raise exception 'not authorized to view this workspace''s performance data';
    end if;
  end if;

  return query
    with decisions as (
      select er.de_id as d_de_id, d.confidence as d_confidence, d.decision as d_decision,
        d.human_task_id as d_human_task_id, d.created_at as d_created_at,
        d.frustration_score as d_frustration_score
      from evidence_run_decisions d
      join evidence_runs er on er.id = d.evidence_run_id
      where er.tenant_id = p_tenant_id and er.de_id is not null
    ),
    runs as (
      select er.de_id as r_de_id, er.status as r_status
      from evidence_runs er
      where er.tenant_id = p_tenant_id and er.de_id is not null
    ),
    summary as (
      select
        dec.d_de_id as s_de_id,
        count(*) as total_decisions,
        round(100.0 * count(*) filter (where dec.d_decision <> 'needs_review') / nullif(count(*), 0), 1) as resolution_rate,
        round(avg(dec.d_confidence) filter (where dec.d_confidence is not null), 1) as avg_confidence,
        round(100.0 * count(*) filter (where dec.d_decision = 'needs_review') / nullif(count(*), 0), 1) as escalation_rate,
        count(*) filter (where dec.d_decision = 'blocked_guardrail') as blocked_guardrail_count,
        round(avg(dec.d_frustration_score) filter (where dec.d_frustration_score is not null), 1) as avg_frustration_score,
        count(*) filter (where dec.d_frustration_score >= 50) as high_frustration_count
      from decisions dec
      group by dec.d_de_id
    ),
    run_summary as (
      select r.r_de_id as rs_de_id, count(*) as total_runs,
        round(100.0 * count(*) filter (where r.r_status = 'failed') / nullif(count(*), 0), 1) as error_rate
      from runs r
      group by r.r_de_id
    ),
    weekly as (
      select
        dec.d_de_id as w_de_id,
        date_trunc('week', dec.d_created_at) as week_start,
        count(*) as decisions_count,
        round(100.0 * count(*) filter (where dec.d_decision <> 'needs_review') / nullif(count(*), 0), 1) as week_resolution_rate,
        round(avg(dec.d_confidence) filter (where dec.d_confidence is not null), 1) as week_avg_confidence
      from decisions dec
      where dec.d_created_at > now() - (p_weeks || ' weeks')::interval
      group by dec.d_de_id, date_trunc('week', dec.d_created_at)
    ),
    trend_agg as (
      select w.w_de_id as t_de_id, jsonb_agg(
        jsonb_build_object(
          'week', to_char(w.week_start, 'YYYY-MM-DD'),
          'decisions', w.decisions_count,
          'resolution_rate', w.week_resolution_rate,
          'avg_confidence', w.week_avg_confidence
        ) order by w.week_start
      ) as trend
      from weekly w
      group by w.w_de_id
    )
    select
      de.id, de.name,
      coalesce(s.total_decisions, 0),
      coalesce(s.resolution_rate, 0),
      coalesce(s.avg_confidence, 0),
      coalesce(s.escalation_rate, 0),
      coalesce(s.blocked_guardrail_count, 0),
      coalesce(rs.total_runs, 0),
      coalesce(rs.error_rate, 0),
      coalesce(s.avg_frustration_score, 0),
      coalesce(s.high_frustration_count, 0),
      coalesce(t.trend, '[]'::jsonb)
    from digital_employees de
    left join summary s on s.s_de_id = de.id
    left join run_summary rs on rs.rs_de_id = de.id
    left join trend_agg t on t.t_de_id = de.id
    where de.tenant_id = p_tenant_id
    order by de.name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_performance_summary(p_de_id uuid, p_time_window_days integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tenant_id UUID;
  v_de_name TEXT;
  v_de_status TEXT;
  v_current_stage TEXT;
  v_cost_this_month NUMERIC;
  v_responses_this_month INT;
  v_avg_csat NUMERIC;
  v_escalation_rate NUMERIC;
  v_resolution_rate NUMERIC;
  v_amendments_count INT;
  v_training_sessions INT;
BEGIN
  SELECT tenant_id, name, status INTO v_tenant_id, v_de_name, v_de_status
  FROM digital_employees WHERE id = p_de_id;

  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'DE not found'; END IF;
  IF NOT (v_tenant_id = auth_tenant_id() AND auth_has_tenant_role(array['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT stage INTO v_current_stage FROM de_deployment_stages WHERE de_id = p_de_id;
  IF v_current_stage IS NULL THEN v_current_stage := 'unknown'; END IF;

  SELECT COALESCE(SUM(total_cost), 0) INTO v_cost_this_month FROM tenant_cost_tracking
  WHERE entity_id = p_de_id AND billing_month = to_char(now(), 'YYYY-MM');

  SELECT COALESCE(COUNT(*), 0) INTO v_responses_this_month FROM action_executions
  WHERE de_id = p_de_id AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(AVG(score), 0) INTO v_avg_csat FROM csat_surveys
  WHERE de_id = p_de_id AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*)::NUMERIC / NULLIF(v_responses_this_month, 0) * 100, 0) INTO v_escalation_rate
  FROM action_executions WHERE de_id = p_de_id AND status = 'escalated' AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*)::NUMERIC / NULLIF(v_responses_this_month, 0) * 100, 0) INTO v_resolution_rate
  FROM action_executions WHERE de_id = p_de_id AND status = 'completed' AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*), 0) INTO v_amendments_count FROM workforce_actions
  WHERE entity_id = p_de_id AND action_type IN ('de_amend', 'de_train') AND applied_at IS NOT NULL AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*), 0) INTO v_training_sessions FROM de_training_feedback
  WHERE de_id = p_de_id AND created_at > now() - (p_time_window_days || ' days')::interval;

  RETURN json_build_object('de_id', p_de_id, 'de_name', v_de_name, 'de_status', v_de_status, 'current_stage', v_current_stage, 'time_window_days', p_time_window_days, 'cost_this_month', v_cost_this_month, 'responses_this_month', v_responses_this_month, 'avg_csat', v_avg_csat, 'escalation_rate', v_escalation_rate, 'resolution_rate', v_resolution_rate, 'amendments_applied', v_amendments_count, 'training_sessions', v_training_sessions, 'fte_equivalent_cost', ROUND((v_cost_this_month / 30)::numeric, 2), 'roi_hours_saved', (v_responses_this_month * 0.5)::INT, 'timestamp', now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_role_context(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de record; v_arch record; v_domains jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  select id, category, department, is_specialist, specialist_key
    into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('ok', false, 'error', 'de_not_found'); end if;

  -- Domains it operates = the system categories it's actually granted.
  select coalesce(jsonb_agg(distinct g.resource_category), '[]'::jsonb) into v_domains
    from data_access_grants g
   where g.tenant_id = v_tenant and g.subject_kind = 'de' and g.subject_id = p_de_id
     and g.resource_category is not null;

  -- Certified archetype (if any) supplies the canonical role name + domain.
  select ra.key, ra.name, ra.domain, ra.required_connector_categories
    into v_arch
    from role_certifications rc
    join role_archetypes ra on ra.key = rc.archetype_key
   where rc.tenant_id = v_tenant and rc.de_id = p_de_id and rc.archetype_key is not null
   order by rc.evaluated_at desc nulls last limit 1;

  return jsonb_build_object(
    'ok', true,
    'department', v_de.department,
    'category', v_de.category,
    'is_specialist', v_de.is_specialist,
    'domains', v_domains,
    'archetype_key', v_arch.key,
    'archetype_name', v_arch.name,
    'archetype_domain', v_arch.domain,
    'archetype_categories', coalesce(to_jsonb(v_arch.required_connector_categories), '[]'::jsonb)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_systems(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'system_key', t.system_key, 'label', t.label, 'source_table', t.source_table,
    'read_fields', t.read_fields, 'can_read', t.can_read, 'can_write', t.can_write,
    'can_verify', t.can_verify, 'can_operate', t.can_operate,
    'operate_domain', public.operate_domain_of(t),
    'write_registry', t.write_registry) ORDER BY t.system_key), '[]'::jsonb)
  FROM de_connected_systems t WHERE t.de_id = p_de_id AND t.active;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_work_product(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_conv jsonb; v_actions jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;

  -- Conversational work-product (support/CRM/product domains).
  select jsonb_build_object(
      'total', count(*),
      'resolved', count(*) filter (where status = 'resolved'),
      'open', count(*) filter (where status in ('needs_human', 'human_owned', 'ai_handling')),
      'by_channel', coalesce((select jsonb_object_agg(ch, n) from (
          select channel ch, count(*) n from de_conversations
           where tenant_id = v_tenant and de_id = p_de_id group by channel) c), '{}'::jsonb)
    ) into v_conv
    from de_conversations where tenant_id = v_tenant and de_id = p_de_id;

  -- System-action work-product, grouped by category + human label. Each row
  -- already carries its domain category — this is the generic bit.
  select coalesce(jsonb_agg(row_to_json(x) order by x.n desc), '[]'::jsonb) into v_actions from (
    select ad.category, ad.label,
           count(*) as n,
           count(*) filter (where ae.decision = 'auto_executed') as auto_n,
           count(*) filter (where ae.decision like 'human_gated%') as gated_n,
           max(ae.created_at) as last_at
      from action_executions ae
      join action_definitions ad on ad.id = ae.action_definition_id
     where ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
       and ae.rollback_of is null
     group by ad.category, ad.label
  ) x;

  return jsonb_build_object('ok', true, 'conversations', v_conv, 'actions', v_actions);
end $function$;

CREATE OR REPLACE FUNCTION public.get_embedding_coverage(p_tenant_id uuid)
 RETURNS TABLE(total_chunks bigint, embedded_chunks bigint, coverage_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(c.*) as total_chunks,
         count(c.*) filter (where c.embedding is not null) as embedded_chunks,
         case when count(c.*) = 0 then 100
              else round(100.0 * count(c.*) filter (where c.embedding is not null) / count(c.*), 1)
         end as coverage_pct
  from knowledge_doc_chunks c
  join knowledge_docs kd on kd.id = c.doc_id
  where kd.tenant_id = p_tenant_id
    and (auth.uid() is null or exists (
      select 1 from profiles p where p.user_id = auth.uid()
        and (p.layer = 'platform' or p.tenant_id = p_tenant_id)));
$function$;

CREATE OR REPLACE FUNCTION public.get_identity_inventory(p_tenant_id uuid)
 RETURNS TABLE(subject_kind text, subject_id uuid, subject_name text, subject_label text, subject_role text, subject_status text, connector_id uuid, connector_name text, connector_provider text, connector_category text, connector_status text, connector_last_ok_at timestamp with time zone, connector_last_error_at timestamp with time zone, connector_consecutive_failures integer, has_stored_credential boolean, permission text, permission_via text, trust_current_level integer, trust_target_level integer, autonomy_enabled boolean, possible_actions jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_caller_tenant uuid; v_is_service boolean := coalesce(auth.role(), '') = 'service_role'; v_is_active boolean;
begin
  if not v_is_service then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid();
    if v_is_active is false then raise exception 'account is deactivated'; end if;
    v_caller_tenant := auth_tenant_id();
    if v_caller_tenant is null then raise exception 'not authenticated or no tenant membership'; end if;
    if v_caller_tenant is distinct from p_tenant_id then raise exception 'not a member of this tenant'; end if;
  end if;
  if not is_feature_enabled_internal(p_tenant_id, 'identity_credential_inventory') then return; end if;

  return query
  with subjects as (
    select case when d.is_specialist then 'specialist' else 'de' end as subject_kind, d.id as subject_id, d.name as subject_name,
           coalesce(d.persona_name, d.name) as subject_label,
           case when d.is_specialist then coalesce(d.specialist_key, 'specialist') else coalesce(nullif(d.department, ''), d.category) end as subject_role,
           d.status as subject_status
    from digital_employees d where d.tenant_id = p_tenant_id
  ),
  grants_resolved as (
    select g.subject_kind, g.subject_id, c.id as connector_id, g.permission, 'category'::text as via, g.resource_category as eff_category
    from data_access_grants g join connectors c on c.tenant_id = g.tenant_id and c.category = g.resource_category
    where g.tenant_id = p_tenant_id and g.resource_kind = 'category'
    union all
    select g.subject_kind, g.subject_id, g.resource_id as connector_id, g.permission, 'connector'::text as via, c.category as eff_category
    from data_access_grants g join connectors c on c.id = g.resource_id and c.tenant_id = p_tenant_id
    where g.tenant_id = p_tenant_id and g.resource_kind = 'connector'
  ),
  grants_final as (
    select distinct on (gr.subject_kind, gr.subject_id, gr.connector_id) gr.subject_kind, gr.subject_id, gr.connector_id, gr.permission, gr.via, gr.eff_category
    from grants_resolved gr order by gr.subject_kind, gr.subject_id, gr.connector_id, (gr.via = 'connector') desc
  ),
  secrets as (select cs.connector_id as secret_connector_id, true as has_secret from connector_secrets cs),
  trust as (select tp.de_id, tp.source_category, tp.current_level, tp.target_level from trust_policies tp where tp.tenant_id = p_tenant_id and tp.action_category = 'action_execute'),
  autonomy as (select da.source_category, da.enabled from de_autonomy da where da.tenant_id = p_tenant_id and da.action_type = 'action_execute'),
  actions_by_category as (
    select ad.category, jsonb_agg(jsonb_build_object('action_key', ad.action_key, 'label', ad.label, 'destructive', coalesce((ad.risk->>'destructive')::boolean, true)) order by ad.label) as actions
    from action_definitions ad where ad.status = 'active' and (ad.scope = 'platform' or ad.tenant_id = p_tenant_id) group by ad.category
  )
  select s.subject_kind, s.subject_id, s.subject_name, s.subject_label, s.subject_role, s.subject_status,
    c.id, c.display_name, c.provider, c.category, c.status, c.last_ok_at, c.last_error_at, c.consecutive_failures,
    coalesce(sec.has_secret, false), gf.permission, gf.via,
    coalesce((select tr.current_level from trust tr where tr.de_id = s.subject_id and tr.source_category = c.category),
             (select tr.current_level from trust tr where tr.de_id = s.subject_id and tr.source_category is null)),
    coalesce((select tr.target_level from trust tr where tr.de_id = s.subject_id and tr.source_category = c.category),
             (select tr.target_level from trust tr where tr.de_id = s.subject_id and tr.source_category is null)),
    coalesce((select au.enabled from autonomy au where au.source_category = c.category), (select au.enabled from autonomy au where au.source_category is null)),
    coalesce(abc.actions, '[]'::jsonb)
  from subjects s
  left join grants_final gf on gf.subject_kind = s.subject_kind and gf.subject_id = s.subject_id
  left join connectors c on c.id = gf.connector_id
  left join secrets sec on sec.secret_connector_id = c.id
  left join actions_by_category abc on abc.category = c.category
  order by s.subject_kind, s.subject_name, c.category, c.display_name;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_conflict_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'ok', true,
    'enabled', is_feature_enabled_internal(auth_tenant_id(), 'knowledge_conflict_detection'),
    'open_count', (SELECT count(*) FROM knowledge_conflicts
                    WHERE tenant_id = auth_tenant_id() AND status = 'open'));
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_conflicts(p_status text DEFAULT 'open'::text, p_relation text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, relation text, status text, cosine_distance real, confidence real, signal jsonb, doc_a_id uuid, doc_a_title text, doc_b_id uuid, doc_b_title text, authoritative_doc_id uuid, detected_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT kc.id, kc.relation, kc.status, kc.cosine_distance, kc.confidence, kc.signal,
         kc.doc_a_id, da.title, kc.doc_b_id, db.title,
         kc.authoritative_doc_id, kc.detected_at
  FROM knowledge_conflicts kc
  JOIN knowledge_docs da ON da.id = kc.doc_a_id
  JOIN knowledge_docs db ON db.id = kc.doc_b_id
  WHERE kc.tenant_id IN (SELECT tenant_id FROM profiles WHERE user_id = auth.uid())
    AND kc.status = p_status
    AND (p_relation IS NULL OR kc.relation = p_relation)
  ORDER BY kc.detected_at DESC
  LIMIT least(greatest(coalesce(p_limit, 50), 1), 100) OFFSET greatest(coalesce(p_offset, 0), 0);
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_coverage_demand(p_days integer DEFAULT 30, p_gap_limit integer DEFAULT 20, p_list_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_probe_on boolean := false;
  v_cfg text;
  v_gap_limit int := least(greatest(coalesce(p_gap_limit, 20), 1), 50);
  v_list_limit int := least(greatest(coalesce(p_list_limit, 10), 1), 50);
  v_days int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_top_gaps jsonb; v_never jsonb; v_most jsonb; v_trend jsonb;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;

  -- Probe gate: feature flag ON and not paused.
  IF is_feature_enabled_internal(v_tenant, 'knowledge_coverage_probe') THEN
    SELECT (value #>> '{}') INTO v_cfg FROM platform_config WHERE key = 'knowledge.coverage_probe_paused';
    v_probe_on := coalesce(v_cfg, '') NOT IN ('true', '1', 't');
  END IF;

  -- (a) TOP-DEMAND GAPS. When the probe is on, reuse hybrid_match_knowledge per
  -- gap (its inquiry + embedding) and derive coverage_state from whether a CITED
  -- doc chunk sits near. When off, coverage_state='unknown' (no probe cost).
  IF v_probe_on THEN
    SELECT jsonb_agg(row_to_json(x)) INTO v_top_gaps FROM (
      SELECT g.id, g.category, g.severity_score, g.member_count, g.reviewer_summary, g.status,
             cov.nearest_cited_dist,
             CASE
               WHEN NOT coalesce(cov.has_cited, false) THEN 'none'
               WHEN cov.nearest_cited_dist IS NULL THEN 'weak'            -- cited doc matched lexically only
               WHEN cov.nearest_cited_dist <= 0.25 THEN 'covered'
               WHEN cov.nearest_cited_dist <= 0.35 THEN 'weak'
               ELSE 'none'
             END AS coverage_state
      FROM knowledge_gap_clusters g
      JOIN evidence_runs er ON er.id = g.representative_run_id AND er.tenant_id = v_tenant
      LEFT JOIN LATERAL (
        SELECT bool_or(coalesce(d.citation_count, 0) > 0) AS has_cited,
               min(h.distance) FILTER (WHERE coalesce(d.citation_count, 0) > 0) AS nearest_cited_dist
        FROM hybrid_match_knowledge(v_tenant, er.inquiry, NULL, er.inquiry_embedding, 20, NULL, NULL, 0.35) h
        JOIN knowledge_docs d ON d.id = h.doc_id
      ) cov ON true
      WHERE g.tenant_id = v_tenant AND g.status = 'open' AND er.inquiry_embedding IS NOT NULL
      ORDER BY g.severity_score DESC NULLS LAST, g.member_count DESC
      LIMIT v_gap_limit
    ) x;
  ELSE
    SELECT jsonb_agg(row_to_json(x)) INTO v_top_gaps FROM (
      SELECT g.id, g.category, g.severity_score, g.member_count, g.reviewer_summary, g.status,
             NULL::float AS nearest_cited_dist, 'unknown'::text AS coverage_state
      FROM knowledge_gap_clusters g
      WHERE g.tenant_id = v_tenant AND g.status = 'open'
      ORDER BY g.severity_score DESC NULLS LAST, g.member_count DESC
      LIMIT v_gap_limit
    ) x;
  END IF;

  -- (b) NEVER-CITED LIST (oldest-uncited first; 14-day grace so a fresh import
  -- isn't labeled dead weight). Total count comes from get_knowledge_overview
  -- client-side (never_cited is the common case → don't O(corpus)-count here).
  SELECT jsonb_agg(row_to_json(x)) INTO v_never FROM (
    SELECT d.id, d.title, d.updated_at, d.last_verified_at
    FROM knowledge_docs d
    WHERE d.tenant_id = v_tenant AND d.is_current AND coalesce(d.citation_count, 0) = 0
      AND d.created_at < now() - interval '14 days'
    ORDER BY d.updated_at ASC
    LIMIT v_list_limit
  ) x;

  -- (c) COVERAGE LEADERS (most-cited).
  SELECT jsonb_agg(row_to_json(x)) INTO v_most FROM (
    SELECT d.id, d.title, d.citation_count, d.last_cited_at
    FROM knowledge_docs d
    WHERE d.tenant_id = v_tenant AND d.is_current AND coalesce(d.citation_count, 0) > 0
    ORDER BY d.citation_count DESC
    LIMIT v_list_limit
  ) x;

  -- (d) CITATION TREND from the usage rollup.
  SELECT jsonb_agg(row_to_json(x)) INTO v_trend FROM (
    SELECT u.usage_date, sum(u.cited_count)::int AS citations, count(DISTINCT u.doc_id)::int AS docs_cited
    FROM knowledge_doc_usage_daily u
    WHERE u.tenant_id = v_tenant AND u.usage_date >= (now()::date - v_days)
    GROUP BY u.usage_date ORDER BY u.usage_date
  ) x;

  RETURN jsonb_build_object('ok', true, 'probe_enabled', v_probe_on,
    'top_gaps', coalesce(v_top_gaps, '[]'::jsonb),
    'never_cited', coalesce(v_never, '[]'::jsonb),
    'most_cited', coalesce(v_most, '[]'::jsonb),
    'trend', coalesce(v_trend, '[]'::jsonb));
END $function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_doc_citation_stats(p_tenant_id uuid)
 RETURNS TABLE(doc_id uuid, citation_count bigint, avg_confidence numeric, accurate_count bigint, needs_improvement_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_is_platform   boolean := is_platform_admin();
begin
  if not v_is_platform then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active
    from profiles where user_id = auth.uid();
    if v_caller_tenant is distinct from p_tenant_id or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;

  return query
  with cited as (
    select
      (cit->>'ref')::uuid as c_doc_id,
      er.id as c_run_id
    from evidence_runs er,
      jsonb_array_elements(coalesce(er.steps, '[]'::jsonb)) as step,
      jsonb_array_elements(coalesce(step->'citations', '[]'::jsonb)) as cit
    where er.tenant_id = p_tenant_id
      and cit->>'system' = 'DreamTeam knowledge'
      and (cit->>'ref') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ),
  conf as (
    select c.c_doc_id, avg(erd.confidence) as a_avg_confidence
    from cited c
    join evidence_run_decisions erd on erd.evidence_run_id = c.c_run_id and erd.tenant_id = p_tenant_id
    group by c.c_doc_id
  ),
  fb as (
    select c.c_doc_id,
      count(*) filter (where ef.verdict = 'accurate') as f_accurate_count,
      count(*) filter (where ef.verdict in ('needs_improvement', 'inaccurate')) as f_needs_improvement_count
    from cited c
    join evidence_feedback ef on ef.evidence_run_id = c.c_run_id and ef.tenant_id = p_tenant_id
    group by c.c_doc_id
  )
  select
    d.id,
    coalesce(ca.cnt, 0),
    conf.a_avg_confidence,
    coalesce(fb.f_accurate_count, 0),
    coalesce(fb.f_needs_improvement_count, 0)
  from knowledge_docs d
  left join (select c_doc_id, count(*) as cnt from cited group by c_doc_id) ca on ca.c_doc_id = d.id
  left join conf on conf.c_doc_id = d.id
  left join fb on fb.c_doc_id = d.id
  where d.tenant_id = p_tenant_id and d.is_current = true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_out jsonb;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;

  WITH d AS (
    SELECT * FROM knowledge_docs WHERE tenant_id = v_tenant AND is_current
  )
  SELECT jsonb_build_object(
    'ok', true,
    'total_docs',       (SELECT count(*) FROM d),
    'indexed_docs',     (SELECT count(*) FROM d WHERE embedded_count > 0),
    'keyword_only',     (SELECT count(*) FROM d WHERE embedded_count = 0),
    'stale_docs',       (SELECT count(*) FROM d WHERE last_verified_at IS NULL OR last_verified_at < now() - interval '90 days'),
    'role_shared',      (SELECT count(*) FROM d WHERE visibility = 'role'),
    'scoped',           (SELECT count(*) FROM d WHERE visibility = 'scoped'),
    'total_citations',  (SELECT coalesce(sum(citation_count), 0) FROM d),
    'cited_docs',       (SELECT count(*) FROM d WHERE citation_count > 0),
    'never_cited',      (SELECT count(*) FROM d WHERE citation_count = 0),
    'last_updated_at',  (SELECT max(updated_at) FROM d),
    'open_gaps',        (SELECT count(*) FROM knowledge_gap_clusters WHERE tenant_id = v_tenant AND status = 'open'),
    'pending_reviews',  (SELECT count(*) FROM de_improvements WHERE tenant_id = v_tenant AND status = 'review_pending')
                        + (SELECT count(*) FROM knowledge_revision_requests WHERE tenant_id = v_tenant AND status = 'pending_approval'),
    'top_cited', COALESCE((SELECT jsonb_agg(x) FROM (
        SELECT id, title, citation_count FROM d WHERE citation_count > 0
         ORDER BY citation_count DESC, updated_at DESC LIMIT 5) x), '[]'::jsonb),
    'recent', COALESCE((SELECT jsonb_agg(x) FROM (
        SELECT id, title, updated_at, embedded_count > 0 AS indexed FROM d
         ORDER BY updated_at DESC LIMIT 5) x), '[]'::jsonb)
  ) INTO v_out;
  RETURN v_out;
END $function$;

CREATE OR REPLACE FUNCTION public.get_kpi_metrics_for_de(p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_cats text[];
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return '[]'::json; end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then return '[]'::json; end if;
  select coalesce(array_agg(distinct resource_category), '{}') into v_cats
    from data_access_grants where tenant_id = v_tenant and subject_kind = 'de' and subject_id = p_de_id and resource_category is not null;
  return (
    select coalesce(json_agg(row_to_json(x) order by x.applicable desc, x.sort_order, x.label), '[]'::json) from (
      select metric_key, label, description, direction, unit, source, source_config, domains, sort_order,
             (tenant_id is not null) as is_custom,
             (domains is null or domains && v_cats) as applicable
        from kpi_metric_catalog
       where tenant_id is null or tenant_id = v_tenant
    ) x
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_metric_trend(p_tenant_id uuid, p_de_id uuid, p_metric_key text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_interval text DEFAULT 'daily'::text)
 RETURNS TABLE(metric_key text, value numeric, "timestamp" timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
