END$function$;

CREATE OR REPLACE FUNCTION public.get_metric_value(p_tenant_id uuid, p_de_id uuid, p_metric_key text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(metric_key text, value numeric, "timestamp" timestamp with time zone, period jsonb, context jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
