  -- (honest "no data") rather than a fabricated zero row.
  RETURN QUERY SELECT NULL::TEXT, NULL::NUMERIC, NULL::TIMESTAMPTZ, NULL::JSONB, NULL::JSONB WHERE FALSE;
END$function$;

