CREATE OR REPLACE FUNCTION public.get_outcome_metering(p_tenant_id uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_totals jsonb; v_by_de jsonb; v_by_day jsonb; v_price integer;
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized';
  end if;

  select coalesce((select price_per_resolution_cents from tenant_outcome_pricing where tenant_id = p_tenant_id), 99)
    into v_price;

  select jsonb_build_object(
    'resolutions', count(*) filter (where kind = 'resolution' and billable),
    'escalations', count(*) filter (where kind = 'escalation'),
    'billable_amount_cents', coalesce(sum(unit_price_cents) filter (where billable), 0))
    into v_totals
    from billable_outcomes
   where tenant_id = p_tenant_id and occurred_at between p_from and p_to;

  select coalesce(jsonb_agg(row_de order by (row_de->>'amount_cents')::bigint desc), '[]'::jsonb) into v_by_de
  from (
    select jsonb_build_object(
      'de_id', b.de_id,
      'name', coalesce(max(d.persona_name), max(d.name), 'Unknown'),
      'resolutions', count(*) filter (where b.kind = 'resolution' and b.billable),
      'escalations', count(*) filter (where b.kind = 'escalation'),
      'amount_cents', coalesce(sum(b.unit_price_cents) filter (where b.billable), 0)) as row_de
    from billable_outcomes b
    left join digital_employees d on d.id = b.de_id
    where b.tenant_id = p_tenant_id and b.occurred_at between p_from and p_to
    group by b.de_id
  ) s;

  select coalesce(jsonb_agg(row_day order by row_day->>'day'), '[]'::jsonb) into v_by_day
  from (
    select jsonb_build_object(
      'day', day_key,
      'resolutions', count(*) filter (where kind = 'resolution' and billable),
      'escalations', count(*) filter (where kind = 'escalation')) as row_day
    from (
      select to_char(occurred_at at time zone 'utc', 'YYYY-MM-DD') as day_key, kind, billable
      from billable_outcomes
      where tenant_id = p_tenant_id and occurred_at between p_from and p_to
    ) raw
    group by day_key
  ) s;

  return jsonb_build_object('totals', v_totals, 'by_de', v_by_de, 'by_day', v_by_day,
                            'price_per_resolution_cents', v_price);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_pending_draft(p_draft_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN (
    SELECT json_build_object(
      'draft_id', draft_id,
      'de_id', de_id,
      'conversation_id', conversation_id,
      'user_question', user_question,
      'draft_content', draft_content,
      'confidence', confidence,
      'sources', sources,
      'created_at', created_at::text,
      'expires_at', expires_at::text
    )
    FROM draft_responses
    WHERE draft_id = p_draft_id
      AND status = 'pending'
      AND expires_at > now()
      AND tenant_id = current_setting('app.current_tenant_id')::uuid
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_pending_drafts_for_de(p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN json_agg(
    json_build_object(
      'draft_id', draft_id,
      'de_id', de_id,
      'conversation_id', conversation_id,
      'user_question', user_question,
      'draft_content', draft_content,
      'confidence', confidence,
      'sources', sources,
      'created_at', created_at::text,
      'expires_at', expires_at::text
    )
  ) FILTER (WHERE draft_id IS NOT NULL)
  FROM draft_responses
  WHERE de_id = p_de_id
    AND status = 'pending'
    AND expires_at > now()
    AND tenant_id = current_setting('app.current_tenant_id')::uuid;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_platform_kb_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'changes_awaiting_review', (SELECT count(*) FROM platform_kb_changes WHERE status = 'new'),
    'articles_flagged',        (SELECT count(DISTINCT i.doc_id) FROM platform_kb_change_impacts i
                                  JOIN platform_kb_changes c ON c.id = i.change_id WHERE c.status = 'new'),
    'articles_total',          (SELECT count(*) FROM platform_knowledge_docs WHERE is_current AND published_at IS NOT NULL),
    'stalest_verified_at',     (SELECT min(last_verified_at) FROM platform_knowledge_docs WHERE is_current),
    'chunks_awaiting_reembed', (SELECT count(*) FROM platform_knowledge_chunks WHERE reembed_pending));
$function$;

CREATE OR REPLACE FUNCTION public.get_platform_shelf_doc(p_doc_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT to_jsonb(x) FROM (
    SELECT d.id, d.title, d.content, d.topic, d.tags,
           d.source_doc_path, d.source_migration, d.source_commit,
           d.last_verified_at, d.updated_at, d.version
      FROM platform_knowledge_docs d
     WHERE d.id = p_doc_id
       AND d.is_current
       AND d.published_at IS NOT NULL
       AND NOT coalesce((SELECT paused FROM platform_knowledge_shelf_state WHERE singleton), true)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.get_platform_shelf_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'paused',           (SELECT paused FROM platform_knowledge_shelf_state WHERE singleton),
    'docs_total',       (SELECT count(*) FROM platform_knowledge_docs),
    'docs_published',   (SELECT count(*) FROM platform_knowledge_docs WHERE is_current AND published_at IS NOT NULL),
    'chunks_total',     (SELECT count(*) FROM platform_knowledge_chunks),
    'chunks_embedded',  (SELECT count(*) FROM platform_knowledge_chunks WHERE embedding IS NOT NULL),
    'reembed_pending',  (SELECT count(*) FROM platform_knowledge_chunks WHERE reembed_pending),
    'citations_30d',    (SELECT coalesce(sum(cited_count), 0) FROM platform_knowledge_usage_daily
                          WHERE usage_date > current_date - 30));
$function$;

CREATE OR REPLACE FUNCTION public.get_platform_tenant_overview()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN (
    SELECT coalesce(json_agg(row_to_json(x)), '[]'::json)
    FROM (
      SELECT
        t.id::text AS tenant_id,
        adm.full_name AS admin_name,
        adm.email AS admin_email,
        coalesce(de_cnt.n, 0) AS de_count,
        coalesce(usr_cnt.n, 0) AS user_count,
        act.last_activity::text AS last_activity
      FROM tenants t
      LEFT JOIN LATERAL (
        -- Most senior member: owner > admin > manager > anyone. Tenants
        -- operated purely via platform Remote Access have no members at
        -- all — those honestly show "no admin user".
        SELECT p.full_name, u.email::text AS email
        FROM profiles p
        JOIN auth.users u ON u.id = p.user_id
        WHERE p.tenant_id = t.id
        ORDER BY CASE p.role
          WHEN 'tenant_owner' THEN 0
          WHEN 'tenant_admin' THEN 1
          WHEN 'tenant_manager' THEN 2
          ELSE 3 END
        LIMIT 1
      ) adm ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n FROM digital_employees d WHERE d.tenant_id = t.id
      ) de_cnt ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n FROM profiles p WHERE p.tenant_id = t.id
      ) usr_cnt ON true
      LEFT JOIN LATERAL (
        SELECT max(m.created_at) AS last_activity FROM de_messages m WHERE m.tenant_id = t.id
      ) act ON true
    ) x
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_playbook_economics(p_definition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid; v_runs int; v_completed int; v_failed int;
  v_cost numeric; v_minutes numeric; v_value numeric;
  v_bl workforce_baselines;
begin
  select tenant_id into v_tenant from playbook_definitions where id = p_definition_id;
  if v_tenant is null then return jsonb_build_object('error', 'not_found'); end if;
  if auth.uid() is not null and not exists (
    select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;

  select count(*), count(*) filter (where status = 'completed'), count(*) filter (where status = 'failed')
    into v_runs, v_completed, v_failed
  from playbook_runs where definition_id = p_definition_id;

  select coalesce(sum(a.cost_used_cents), 0) into v_cost
  from agentic_step_runs a
  join playbook_runs r on r.id = a.playbook_run_id
  where r.definition_id = p_definition_id;

  select * into v_bl from workforce_baselines where tenant_id = v_tenant;
  v_minutes := v_completed * coalesce(v_bl.action_minutes, 15);
  -- hourly rate implied by the tenant's own monthly FTE cost (160 h/month)
  v_value := case when v_bl.avg_fte_cost_monthly_usd is not null and v_bl.avg_fte_cost_monthly_usd > 0
    then round((v_minutes / 60.0) * (v_bl.avg_fte_cost_monthly_usd / 160.0), 2) else null end;

  return jsonb_build_object(
    'runs', v_runs, 'completed', v_completed, 'failed', v_failed,
    'completion_pct', case when v_runs > 0 then round(100.0 * v_completed / v_runs, 1) else null end,
    'ai_cost_cents', round(v_cost, 1),
    'human_minutes_saved', round(v_minutes, 0),
    'est_value_usd', v_value,
    'baseline_configured', v_bl.tenant_id is not null
  );
end; $function$;

