CREATE OR REPLACE FUNCTION public.get_workforce_board(p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_out jsonb;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  SELECT COALESCE(jsonb_agg(row_json ORDER BY dept, pname), '[]'::jsonb)
    INTO v_out
  FROM (
    SELECT
      COALESCE(d.department, 'zz') AS dept,
      COALESCE(d.persona_name, d.name) AS pname,
      jsonb_build_object(
        'de_id', d.id,
        'name', d.name,
        'persona_name', d.persona_name,
        'department', d.department,
        'trust_level', d.trust_level,
        'lifecycle_status', COALESCE(d.lifecycle_status, 'active'),

        -- NOW: the item being executed this moment (claimed by the tick).
        'now', (
          SELECT jsonb_build_object('title', w.title, 'since', w.locked_at)
            FROM de_work_items w
           WHERE w.tenant_id = v_tenant AND w.de_id = d.id
             AND w.status = 'running'
           ORDER BY w.locked_at DESC NULLS LAST LIMIT 1),

        -- NEXT UP: top 3 across every arrival channel, unified + ordered by
        -- WHEN. Undated queue items sort last within the horizon.
        'next_up', COALESCE((
          SELECT jsonb_agg(n ORDER BY (n->>'when') ASC NULLS LAST)
            FROM (
              SELECT n FROM (
                (SELECT jsonb_build_object(
                         'kind', 'work_item', 'title', q.title,
                         'when', COALESCE(q.scheduled_for, q.created_at)) AS n
                   FROM de_work_items q
                  WHERE q.tenant_id = v_tenant AND q.de_id = d.id AND q.status = 'queued'
                  ORDER BY COALESCE(q.scheduled_for, q.created_at) ASC LIMIT 3)
                UNION ALL
                (SELECT jsonb_build_object(
                         'kind', 'case_wait', 'title', COALESCE(NULLIF(c.instruction, ''), 'follow up on a waiting case'),
                         'when', c.fire_at)
                   FROM de_case_events c
                  WHERE c.tenant_id = v_tenant AND c.de_id = d.id AND c.status = 'pending'
                  ORDER BY c.fire_at ASC LIMIT 3)
                UNION ALL
                (SELECT jsonb_build_object(
                         'kind', 'watcher', 'title', v.label,
                         'when', v.next_fire_at)
                   FROM work_watchers v
                  WHERE v.tenant_id = v_tenant AND v.de_id = d.id
                    AND v.active AND v.kind <> 'inbox' AND v.next_fire_at IS NOT NULL
                  ORDER BY v.next_fire_at ASC LIMIT 2)
                UNION ALL
                (SELECT jsonb_build_object(
                         'kind', 'objective_wake', 'title', 'check on: ' || o.title,
                         'when', o.next_wake_at)
                   FROM de_objectives o
                  WHERE o.tenant_id = v_tenant AND o.de_id = d.id
                    AND o.status = 'in_progress' AND o.next_wake_at IS NOT NULL
                  ORDER BY o.next_wake_at ASC LIMIT 2)
              ) uni
              ORDER BY (n->>'when') ASC NULLS LAST LIMIT 3
            ) nx), '[]'::jsonb),

        -- Continuous listening (no timestamp, always on): the live inbox.
        'listens_live', EXISTS (
          SELECT 1 FROM work_watchers lv
           WHERE lv.tenant_id = v_tenant AND lv.de_id = d.id
             AND lv.active AND lv.kind = 'inbox'),

        -- BLOCKED: where the founder is the bottleneck.
        'waiting_on_you', (
          SELECT count(*) FROM human_tasks h
           WHERE h.tenant_id = v_tenant AND h.de_id = d.id AND h.status = 'pending'),
        'blocked_objectives', (
          SELECT count(*) FROM de_objectives b
           WHERE b.tenant_id = v_tenant AND b.de_id = d.id AND b.status = 'blocked'),

        'open_objectives', (
          SELECT count(*) FROM de_objectives o2
           WHERE o2.tenant_id = v_tenant AND o2.de_id = d.id
             AND o2.status IN ('open', 'in_progress')),
        'done_today', (
          SELECT count(*) FROM de_work_items t
           WHERE t.tenant_id = v_tenant AND t.de_id = d.id
             AND t.status = 'done' AND t.updated_at >= date_trunc('day', now()))
      ) AS row_json
    FROM digital_employees d
    WHERE d.tenant_id = v_tenant
      AND COALESCE(d.lifecycle_status, 'active') NOT IN ('retired')
      AND (p_de_id IS NULL OR d.id = p_de_id)
  ) rows;

  RETURN jsonb_build_object('ok', true, 'board', v_out);
END $function$;

CREATE OR REPLACE FUNCTION public.get_workforce_economics(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_de_count int; v_pb_runs int; v_pb_done int; v_minutes numeric; v_ai numeric; v_value numeric; v_bl workforce_baselines;
begin
  if auth.uid() is not null and not exists (select 1 from profiles p where p.user_id=auth.uid() and (p.layer='platform' or p.tenant_id=p_tenant_id)) then raise exception 'not authorized'; end if;
  select count(*) into v_de_count from digital_employees where tenant_id=p_tenant_id and lifecycle_status not in ('retired','archived');
  select count(*), count(*) filter (where r.status='completed') into v_pb_runs, v_pb_done from playbook_runs r join playbook_definitions d on d.id=r.definition_id where d.tenant_id=p_tenant_id;
  select coalesce(sum(a.cost_used_cents),0) into v_ai from agentic_step_runs a where a.tenant_id=p_tenant_id;
  select * into v_bl from workforce_baselines where tenant_id=p_tenant_id;
  v_minutes := v_pb_done * coalesce(v_bl.action_minutes,15);
  v_value := case when v_bl.avg_fte_cost_monthly_usd is not null and v_bl.avg_fte_cost_monthly_usd>0 then round((v_minutes/60.0)*(v_bl.avg_fte_cost_monthly_usd/160.0),2) else null end;
  return jsonb_build_object('digital_employees',v_de_count,'playbook_runs',v_pb_runs,'playbook_completed',v_pb_done,'ai_cost_usd',round(v_ai/100.0,2),'human_minutes_saved',round(v_minutes,0),'est_value_usd',v_value,'baseline_configured',v_bl.tenant_id is not null);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_workforce_learning_digest(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_since timestamptz;
  v_prior timestamptz;
  v_avg numeric; v_prev_avg numeric; v_n bigint; v_prev_n bigint;
  v_out jsonb;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  p_days  := GREATEST(1, LEAST(90, COALESCE(p_days, 7)));
  v_since := now() - make_interval(days => p_days);
  v_prior := now() - make_interval(days => p_days * 2);

  SELECT avg(score), count(*) INTO v_avg, v_n
    FROM eval_judgments WHERE tenant_id = v_tenant AND created_at >= v_since
     AND source IS DISTINCT FROM 'simulation';
  SELECT avg(score), count(*) INTO v_prev_avg, v_prev_n
    FROM eval_judgments WHERE tenant_id = v_tenant
     AND created_at >= v_prior AND created_at < v_since
     AND source IS DISTINCT FROM 'simulation';

  v_out := jsonb_build_object(
    'ok', true,
    'period', jsonb_build_object('days', p_days, 'since', v_since),

    'volume', jsonb_build_object(
      'work_done', (SELECT count(*) FROM de_work_items
        WHERE tenant_id = v_tenant AND status = 'done' AND updated_at >= v_since),
      'conversations', (SELECT count(*) FROM de_conversations
        WHERE tenant_id = v_tenant AND last_message_at >= v_since),
      'escalations', (SELECT count(*) FROM human_tasks
        WHERE tenant_id = v_tenant AND created_at >= v_since)),

    'knowledge', jsonb_build_object(
      'docs_added', (SELECT count(*) FROM knowledge_docs
        WHERE tenant_id = v_tenant AND is_current AND created_at >= v_since),
      'docs_by_source', COALESCE((SELECT jsonb_object_agg(src, n) FROM (
          SELECT COALESCE(source, 'manual') AS src, count(*) AS n
            FROM knowledge_docs
           WHERE tenant_id = v_tenant AND is_current AND created_at >= v_since
           GROUP BY 1) s), '{}'::jsonb),
      'gaps_detected', (SELECT count(*) FROM knowledge_gap_clusters
        WHERE tenant_id = v_tenant AND first_seen_at >= v_since),
      'gaps_resolved', (SELECT count(*) FROM knowledge_gap_clusters
        WHERE tenant_id = v_tenant AND fix_applied_at >= v_since)),

    -- GI-6a: the CLOSED LOOP on recurring problems — the honest, already-real
    -- "it gets measurably better" evidence (persona-amendment fitness is GI-6b).
    'learning', jsonb_build_object(
      -- Issues that RECURRED (came back at least once) and then got a fix
      -- applied in this window — genuine repeat problems the workforce closed.
      'recurring_issues_fixed', (SELECT count(*) FROM knowledge_gap_clusters
        WHERE tenant_id = v_tenant AND fix_applied_at >= v_since
          AND COALESCE(recurrence_count, 0) >= 1),
      -- Fix durability, ALL-TIME (a fix's durability isn't a window property):
      -- of every gap ever fixed, how many held vs came back. Denominator is
      -- exposed so the reader never over-reads a tiny sample.
      'fixes_held', (SELECT count(*) FROM knowledge_gap_clusters
        WHERE tenant_id = v_tenant AND fix_applied_at IS NOT NULL
          AND NOT COALESCE(recurred_after_fix, false)),
      'fixes_reopened', (SELECT count(*) FROM knowledge_gap_clusters
        WHERE tenant_id = v_tenant AND fix_applied_at IS NOT NULL
          AND COALESCE(recurred_after_fix, false))),

    'quality', jsonb_build_object(
      'evals', COALESCE(v_n, 0),
      'avg_score', round(COALESCE(v_avg, 0)::numeric, 1),
      'prev_evals', COALESCE(v_prev_n, 0),
      'prev_avg_score', round(COALESCE(v_prev_avg, 0)::numeric, 1),
      'delta', CASE WHEN v_n >= 5 AND v_prev_n >= 5
                    THEN round((v_avg - v_prev_avg)::numeric, 1) END,
      'drift', (v_n >= 10 AND v_prev_n >= 10 AND (v_avg - v_prev_avg) <= -8)),

    'amendments', jsonb_build_object(
      'proposed', (SELECT count(*) FROM workforce_entity_amendments
        WHERE tenant_id = v_tenant AND created_at >= v_since),
      'adopted', (SELECT count(*) FROM workforce_entity_amendments
        WHERE tenant_id = v_tenant AND status IN ('applied', 'adopted')
          AND updated_at >= v_since),
      'fitness_avg_delta', (SELECT round(avg(replay_score_after - replay_score_before)::numeric, 1)
        FROM amendment_metrics
        WHERE tenant_id = v_tenant AND adopted_at >= v_since
          AND replay_score_after IS NOT NULL AND replay_score_before IS NOT NULL),
      'fitness_samples', (SELECT count(*) FROM amendment_metrics
        WHERE tenant_id = v_tenant AND adopted_at >= v_since
          AND replay_score_after IS NOT NULL AND replay_score_before IS NOT NULL)),

    'certifications', jsonb_build_object(
      'runs', (SELECT count(*) FROM role_certifications
        WHERE tenant_id = v_tenant AND evaluated_at >= v_since),
      'passed', (SELECT count(*) FROM role_certifications
        WHERE tenant_id = v_tenant AND evaluated_at >= v_since AND status = 'passed')),

    'ramp', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'who', who, 'hired_at', hired_at, 'trust_level', trust_level,
        'days_to_first_cert', days_to_first_cert) ORDER BY hired_at DESC)
      FROM (
        SELECT COALESCE(d.persona_name, d.name) AS who, d.created_at AS hired_at,
               d.trust_level,
               (SELECT round(extract(epoch FROM (min(rc.evaluated_at) - d.created_at)) / 86400.0, 1)
                  FROM role_certifications rc
                 WHERE rc.tenant_id = v_tenant AND rc.de_id = d.id AND rc.status = 'passed') AS days_to_first_cert
          FROM digital_employees d
         WHERE d.tenant_id = v_tenant
           AND COALESCE(d.lifecycle_status, 'active') <> 'retired'
         LIMIT 30) r), '[]'::jsonb)
  );
  RETURN v_out;
END $function$;

CREATE OR REPLACE FUNCTION public.governance_decide_proposal(p_proposal_id uuid, p_decision text, p_applied_rule_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_status text;
BEGIN
  IF p_decision NOT IN ('approved', 'dismissed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_decision');
  END IF;

  SELECT tenant_id, status INTO v_tenant, v_status
  FROM governance_proposals WHERE id = p_proposal_id;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF NOT public.governance_user_can_decide(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;
  IF v_status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_decided', 'status', v_status);
  END IF;

  UPDATE governance_proposals
     SET status = p_decision,
         decided_by = auth.uid(),
         decided_at = now(),
         applied_rule_id = CASE WHEN p_decision = 'approved' THEN p_applied_rule_id ELSE NULL END
   WHERE id = p_proposal_id;

  RETURN jsonb_build_object('ok', true, 'status', p_decision);
END;
$function$;

CREATE OR REPLACE FUNCTION public.governance_user_can_decide(p_tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND tenant_id = p_tenant
      AND role = ANY (ARRAY['tenant_owner', 'tenant_admin'])
  );
$function$;

CREATE OR REPLACE FUNCTION public.grant_knowledge_access(p_resource_type text, p_resource_id uuid, p_principal_type text, p_principal_id uuid, p_principal_role text, p_permission text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_my int; v_want int; v_id uuid; v_space uuid; v_who text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_resource_type NOT IN ('workspace','collection','document') THEN
    RAISE EXCEPTION 'unknown resource type: %', p_resource_type;
  END IF;
  IF p_principal_type NOT IN ('everyone','role','group','user','guest') THEN
    RAISE EXCEPTION 'unknown principal type: %', p_principal_type;
  END IF;
  v_want := knowledge_permission_rank(p_permission);
  IF v_want = 0 THEN RAISE EXCEPTION 'unknown permission: %', p_permission; END IF;

  -- The resource must belong to this workspace.
  IF p_resource_type = 'collection' THEN
    IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_resource_id AND tenant_id = v_tenant) THEN
      RAISE EXCEPTION 'that space does not belong to this workspace';
    END IF;
    v_space := p_resource_id;
  ELSIF p_resource_type = 'document' THEN
    IF NOT EXISTS (SELECT 1 FROM knowledge_docs WHERE id = p_resource_id AND tenant_id = v_tenant) THEN
      RAISE EXCEPTION 'that document does not belong to this workspace';
    END IF;
  ELSIF p_resource_id IS NOT NULL THEN
    RAISE EXCEPTION 'a workspace-wide grant does not take a resource';
  END IF;

  -- Managing permissions is a knowledge_manager act (rank 5).
  v_my := public.knowledge_my_admin_level(v_space);
  IF v_my < 5 THEN
    RAISE EXCEPTION 'insufficient_permission: changing who can see knowledge requires knowledge manager';
  END IF;
  -- ...and you cannot hand out more than you hold. Without this the ladder is
  -- decorative: a knowledge manager grants somebody workspace_admin, and is
  -- granted it back the same afternoon.
  IF v_want > v_my THEN
    RAISE EXCEPTION 'insufficient_permission: you cannot grant % because you only hold level %', p_permission, v_my;
  END IF;

  -- The principal must be real, and in THIS workspace.
  IF p_principal_type IN ('user','guest') THEN
    IF NOT EXISTS (SELECT 1 FROM profiles WHERE user_id = p_principal_id AND tenant_id = v_tenant
                     AND coalesce(is_active, true)) THEN
      RAISE EXCEPTION 'that person is not a member of this workspace';
    END IF;
    SELECT coalesce(full_name, 'a teammate') INTO v_who FROM profiles WHERE user_id = p_principal_id;
  ELSIF p_principal_type = 'group' THEN
    IF NOT EXISTS (SELECT 1 FROM knowledge_principal_groups WHERE id = p_principal_id AND tenant_id = v_tenant) THEN
      RAISE EXCEPTION 'that group does not belong to this workspace';
    END IF;
    SELECT name INTO v_who FROM knowledge_principal_groups WHERE id = p_principal_id;
  ELSIF p_principal_type = 'role' THEN
    IF p_principal_role IS NULL OR btrim(p_principal_role) = '' THEN
      RAISE EXCEPTION 'a role grant needs a role name';
    END IF;
    v_who := 'everyone with the role ' || p_principal_role;
  ELSE
    v_who := 'everyone in the workspace';
  END IF;

  INSERT INTO knowledge_access_grants (
    tenant_id, resource_type, resource_id, principal_type,
    principal_user_id, principal_group_id, principal_role, permission, granted_by, note)
  VALUES (
    v_tenant, p_resource_type, p_resource_id, p_principal_type,
    CASE WHEN p_principal_type IN ('user','guest') THEN p_principal_id END,
    CASE WHEN p_principal_type = 'group' THEN p_principal_id END,
    CASE WHEN p_principal_type = 'role' THEN p_principal_role END,
    p_permission, auth.uid(), p_note)
  ON CONFLICT (tenant_id, resource_type, coalesce(resource_id, '00000000-0000-0000-0000-000000000000'::uuid),
               principal_type,
               coalesce(principal_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(principal_group_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(principal_role, ''))
  DO UPDATE SET permission = excluded.permission, granted_by = excluded.granted_by,
                note = excluded.note, updated_at = now()
  RETURNING id INTO v_id;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('Gave %s %s access', v_who, p_permission),
    'access_control',
    jsonb_build_object('grant_id', v_id, 'resource_type', p_resource_type,
                       'resource_id', p_resource_id, 'permission', p_permission,
                       'principal_type', p_principal_type));
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_against_demo_tenant_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.tenant_id = 'a0000000-0000-0000-0000-000000000001'::uuid THEN
    RAISE EXCEPTION 'Cannot assign new signups to the demo tenant (a0000000-0000-0000-0000-000000000001). This tenant is reserved for the seeded product demo only.';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_against_demo_tenant_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.parent_tenant_id = 'a0000000-0000-0000-0000-000000000001'::uuid then
    raise exception 'Cannot set the demo tenant (a0000000-0000-0000-0000-000000000001) as a parent_tenant_id. This tenant is reserved for the seeded product demo only and must remain a flat, isolated island.';
  end if;
  if NEW.id = 'a0000000-0000-0000-0000-000000000001'::uuid and NEW.parent_tenant_id is not null then
    raise exception 'The demo tenant (a0000000-0000-0000-0000-000000000001) can never be given a parent_tenant_id.';
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_compliance_guardrails()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (TG_OP = 'DELETE' and OLD.compliance_pack_key is not null)
     or (TG_OP = 'UPDATE' and OLD.compliance_pack_key is not null and NEW.active = false) then
    if coalesce(current_setting('app.allow_compliance_change', true), '') <> 'on' then
      raise exception 'compliance guardrail (%): cannot be disabled or deleted — detach the pack instead', OLD.compliance_pack_key;
    end if;
  end if;
  return case when TG_OP = 'DELETE' then OLD else NEW end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_computer_use_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_approval text;
begin
  if NEW.status in ('claimed', 'running') then
    -- valid predecessor only
    if not ((NEW.status = 'claimed' and OLD.status = 'approved')
         or (NEW.status = 'running' and OLD.status = 'claimed')) then
      raise exception 'computer-use task % cannot move % -> % (invalid transition)', NEW.id, OLD.status, NEW.status;
    end if;
    -- the human approval must exist and be APPROVED
    if NEW.human_task_id is null then
      raise exception 'computer-use task % has no approval task — it can never execute', NEW.id;
    end if;
    select status into v_approval from human_tasks where id = NEW.human_task_id;
    if v_approval is distinct from 'approved' then
      raise exception 'computer-use task % is not human-approved (approval status: %)', NEW.id, coalesce(v_approval, 'missing');
    end if;
    -- an ACTIVE registered runtime must hold the claim
    if NEW.runtime_id is null or not exists (
        select 1 from computer_use_runtimes r where r.id = NEW.runtime_id and r.active) then
      raise exception 'computer-use task % has no active registered runtime — no runtime ships with the platform yet', NEW.id;
    end if;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guardrail_adjudications_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'guardrail_adjudications is append-only: a machine overturning a compliance block is a permanent record';
  END IF;
  IF coalesce(current_setting('app.allow_adjudication_redact', true), '') <> 'on' THEN
    RAISE EXCEPTION 'guardrail_adjudications rows cannot be edited';
  END IF;
  -- Redaction may only null the four free-text columns; every decision field
  -- must be byte-identical.
  IF (NEW.id, NEW.tenant_id, NEW.de_id, NEW.conversation_id, NEW.surface, NEW.rule_id,
      NEW.assessment, NEW.confidence, NEW.model, NEW.provider, NEW.prompt_version,
      NEW.mode, NEW.would_clear, NEW.applied, NEW.reason, NEW.content_sha256,
      NEW.audit_event_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.tenant_id, OLD.de_id, OLD.conversation_id, OLD.surface, OLD.rule_id,
      OLD.assessment, OLD.confidence, OLD.model, OLD.provider, OLD.prompt_version,
      OLD.mode, OLD.would_clear, OLD.applied, OLD.reason, OLD.content_sha256,
      OLD.audit_event_id, OLD.created_at)
  THEN RAISE EXCEPTION 'guardrail_adjudications: only the text previews may be redacted'; END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (user_id, full_name, avatar, role, layer, tenant_id)
  values (
    new.id,
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'avatar',
    'agent',
    'tenant',
    null
  ) on conflict (user_id) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handoff_back_to_de(p_conversation_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de uuid; v_status text; v_de_name text;
begin
  v_tenant := _assert_conv_member(p_conversation_id);
  select de_id, status into v_de, v_status from de_conversations where id = p_conversation_id;
  if v_status = 'resolved' then raise exception 'conversation_resolved'; end if;
  if v_de is null then raise exception 'no_de_on_conversation'; end if;

  update de_conversations
     set status = 'ai_handling', owner_user_id = null, handoff_summary = null, last_message_at = now()
   where id = p_conversation_id;

  -- The lesson: written into the DE's conversation-scoped memory, which
  -- de-answer recalls on the next customer message in this thread.
  if coalesce(btrim(p_note), '') <> '' then
    perform de_memory_write(
      v_tenant, v_de,
      'A human teammate handled part of this conversation and handed it back with this guidance: ' || btrim(p_note),
      null, 'conversation', p_conversation_id::text, 'episodic', 0.9, 'human', null);
  end if;

  -- The thread is visibly handled — its pending escalation tasks are done.
  update human_tasks
     set status = 'approved', decided_by = auth.uid(), decided_at = now(), updated_at = now()
   where tenant_id = v_tenant and related_table = 'de_conversations'
     and related_id = p_conversation_id and type = 'escalation' and status = 'pending';

  select coalesce(persona_name, name, 'the DE') into v_de_name from digital_employees where id = v_de;
  insert into activity_events (tenant_id, actor, actor_type, event_type, text)
  values (v_tenant, v_de_name, 'de', 'handoff_returned',
          'A human handed the conversation back to ' || v_de_name
          || case when coalesce(btrim(p_note), '') <> '' then ' with guidance: ' || left(btrim(p_note), 200) else '' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.heartbeat_computer_use_runtime(p_runtime_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'heartbeat is service-role only'; END IF;
  UPDATE computer_use_runtimes SET last_seen = now(), active = true WHERE id = p_runtime_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.hook_before_user_created(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_recent_signups int;
  v_burst_threshold constant int := 8;
  v_window_minutes constant int := 10;
begin
  select count(*) into v_recent_signups
  from auth.users
  where created_at > now() - make_interval(mins => v_window_minutes);

  if v_recent_signups >= v_burst_threshold then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many accounts are being created right now. Please try again shortly.'
    );
  end if;

  return jsonb_build_object('decision', 'continue');

exception when others then
  return jsonb_build_object('decision', 'continue');
end;
$function$;

CREATE OR REPLACE FUNCTION public.hook_password_verification_attempt(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_valid boolean;
  v_row public.auth_login_lockouts;
  v_new_count int;
  v_max_attempts constant int := 5;
  v_lockout_minutes constant int := 15;
  v_window_minutes constant int := 15;
begin
  v_user_id := (event->>'user_id')::uuid;
  v_valid := coalesce((event->>'valid')::boolean, true);

  if v_user_id is null then
    return jsonb_build_object('decision', 'continue');
  end if;

  select * into v_row from public.auth_login_lockouts where user_id = v_user_id for update;

  if v_row.user_id is not null and v_row.locked_until is not null and v_row.locked_until > now() then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Please try again in a few minutes.'
    );
  end if;

  if v_valid then
    if v_row.user_id is not null then
      update public.auth_login_lockouts
        set failed_count = 0, locked_until = null, last_attempt_at = now()
        where user_id = v_user_id;
    end if;
    return jsonb_build_object('decision', 'continue');
  end if;

  if v_row.user_id is null then
    insert into public.auth_login_lockouts (user_id, failed_count, last_attempt_at)
    values (v_user_id, 1, now());
    return jsonb_build_object('decision', 'continue');
  end if;

  if v_row.last_attempt_at < now() - make_interval(mins => v_window_minutes) then
    update public.auth_login_lockouts
      set failed_count = 1, last_attempt_at = now(), locked_until = null
      where user_id = v_user_id;
    return jsonb_build_object('decision', 'continue');
  end if;

  v_new_count := v_row.failed_count + 1;

  if v_new_count >= v_max_attempts then
    update public.auth_login_lockouts
      set failed_count = v_new_count, last_attempt_at = now(),
          locked_until = now() + make_interval(mins => v_lockout_minutes)
      where user_id = v_user_id;
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Please try again in 15 minutes.'
    );
  end if;

  update public.auth_login_lockouts
    set failed_count = v_new_count, last_attempt_at = now()
    where user_id = v_user_id;
  return jsonb_build_object('decision', 'continue');

exception when others then
  return jsonb_build_object('decision', 'continue');
end;
$function$;

CREATE OR REPLACE FUNCTION public.hybrid_match_knowledge(p_tenant_id uuid, p_query_text text, p_account_id uuid DEFAULT NULL::uuid, p_query_embedding vector DEFAULT NULL::vector, p_match_count integer DEFAULT 5, p_subject_kind text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_max_distance double precision DEFAULT 0.25, p_acting_user uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, doc_id uuid, doc_title text, content text, account_id uuid, visibility text, lexical_rank integer, semantic_rank integer, distance double precision, score double precision, withheld_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_archetype text;
  v_fresh_on boolean := false;
  v_fresh_weight double precision := 0.0;
  v_fresh_halflife double precision := 180.0;
  v_expired_penalty double precision := 0.0;
  v_cfg text;
  v_ann_on boolean := false;
  v_ann_pool bigint := 2000000000;
  -- 345: whose permissions apply, and whether they apply at all.
  v_actor uuid;
  v_acl_on boolean := false;
begin
  perform public._assert_caller_tenant(p_tenant_id);
  v_archetype := case when p_subject_kind = 'de' and p_subject_id is not null then resolve_de_archetype(p_subject_id) end;

  -- A logged-in caller may only ever act as themselves. Only a null-auth caller
  -- (edge function on service role, pg_cron) may name the human being served.
  v_actor := case when auth.uid() is not null then auth.uid() else p_acting_user end;
  if v_actor is not null and is_feature_enabled_internal(p_tenant_id, 'knowledge_acl_retrieval') then
    v_acl_on := true;
  end if;

  if is_feature_enabled_internal(p_tenant_id, 'knowledge_freshness_weighting') then
    select value into v_cfg from platform_config where key = 'knowledge.freshness_weighting_paused';
    if coalesce(v_cfg, '') not in ('true', '1', 't') then
      v_fresh_on := true;
      select coalesce((select case when value ~ '^[0-9]+(\.[0-9]+)?$' then value::double precision end
                         from platform_config where key = 'knowledge.freshness_weight'), 0.0007) into v_fresh_weight;
      select coalesce((select case when value ~ '^[0-9]+(\.[0-9]+)?$' then value::double precision end
                         from platform_config where key = 'knowledge.freshness_halflife_days'), 180.0) into v_fresh_halflife;
      select coalesce((select case when value ~ '^[0-9]+(\.[0-9]+)?$' then value::double precision end
                         from platform_config where key = 'knowledge.freshness_expired_penalty'), 0.006) into v_expired_penalty;
    end if;
  end if;

  if is_feature_enabled_internal(p_tenant_id, 'knowledge_ann_retrieval') then
    v_ann_on := true;
    v_ann_pool := 200;
    set local hnsw.iterative_scan = 'relaxed_order';
  end if;

  return query
  with visible_docs as (
    select d.id, d.title, d.visibility, d.search_tsv, coalesce(d.authority, 0) as authority,
           d.last_verified_at, d.updated_at, d.expires_at,
           -- 345: needed by the permission predicate below. Denormalised in 344
           -- precisely so this stays a column read.
           d.restricted_space_id, d.inherits_access
    from knowledge_docs d
    where d.tenant_id = p_tenant_id
      and d.is_current
      -- 346: drafts and archived versions never reach an answer.
      and d.lifecycle_status = 'published'
      and (
        d.visibility = 'tenant'
        or (p_subject_kind is not null and p_subject_id is not null and exists (
              select 1 from knowledge_doc_scopes s
              where s.doc_id = d.id
                and (
                  (s.subject_kind = p_subject_kind and s.subject_id = p_subject_id)
                  -- 363: an employee also sees what its TEAMS were given.
                  -- Membership is the grant; nothing is copied per employee,
                  -- so adding someone to a team updates their knowledge too.
                  or (p_subject_kind = 'de' and s.subject_kind = 'de_team'
                      and exists (select 1 from workforce_team_members m
                                   where m.team_id = s.subject_id
                                     and m.de_id = p_subject_id))
                )))
        or (d.visibility = 'role' and v_archetype is not null and d.share_archetype_key = v_archetype)
      )
  ),
  -- 345: the human ACL. When v_acl_on is false this is visible_docs verbatim,
  -- which is what makes flag-off byte-identical.
  permitted_docs as (
    select vd.* from visible_docs vd
    where
      -- 357: a restricted Space never leaves the room. With nobody named
      -- (autonomous work, public widget) its documents are excluded
      -- outright, so "restricted" does not quietly mean "restricted from
      -- logged-in humans only".
      (v_actor is not null or vd.restricted_space_id is null)
      and ((not v_acl_on)
       or exists (
         select 1 from knowledge_access_grants g
          where g.tenant_id = p_tenant_id
            and knowledge_permission_rank(g.permission) >= 1
            and knowledge_grant_matches_user(g, v_actor)
            and ((g.resource_type = 'workspace' and vd.restricted_space_id is null and vd.inherits_access)
              or (g.resource_type = 'document' and g.resource_id = vd.id)
              or (g.resource_type = 'collection' and vd.inherits_access
                  and exists (select 1 from knowledge_doc_access_paths p
                               where p.doc_id = vd.id and p.collection_id = g.resource_id)))))
  ),
  lexical as (
    select
      vd.id as doc_id,
      (row_number() over (order by ts_rank(vd.search_tsv, websearch_to_tsquery('english', p_query_text)) desc))::int as lexical_rank
    from permitted_docs vd
    where p_query_text is not null
      and length(trim(p_query_text)) > 0
      and vd.search_tsv @@ websearch_to_tsquery('english', p_query_text)
  ),
  ann as (
    select c.id as chunk_id, c.doc_id, c.content, c.account_id,
           (c.embedding <=> p_query_embedding) as distance
    from knowledge_doc_chunks c
    where c.tenant_id = p_tenant_id
      and c.embedding is not null
      and p_query_embedding is not null
      and (c.account_id is null or (p_account_id is not null and c.account_id = p_account_id))
    order by c.embedding <=> p_query_embedding
    limit v_ann_pool
  ),
  semantic as (
    select
      a.chunk_id,
      a.doc_id,
      a.content,
      a.account_id,
      a.distance::float as distance,
      (row_number() over (order by a.distance asc))::int as semantic_rank
    from ann a
    join permitted_docs vd on vd.id = a.doc_id
    where a.distance <= p_max_distance
  ),
  -- 345: what did permission cost this answer? Only documents that WOULD have
  -- been retrieved — matched lexically, or close enough semantically — count.
  -- Anything else would inflate the number into noise the employee learns to
  -- ignore. Empty by construction when the ACL is off.
  withheld as (
    select count(*)::int as n
      from visible_docs vd
     where v_acl_on
       and not exists (select 1 from permitted_docs pd where pd.id = vd.id)
       and (
         (p_query_text is not null and length(trim(p_query_text)) > 0
            and vd.search_tsv @@ websearch_to_tsquery('english', p_query_text))
         or exists (select 1 from ann a where a.doc_id = vd.id and a.distance <= p_max_distance)
       )
  ),
  candidates as (
    select
      s.chunk_id as id, s.doc_id, s.content, s.account_id, s.distance, s.semantic_rank
    from semantic s
    union
    select
      gen_random_uuid() as id, vd.id as doc_id,
      (select d2.content from knowledge_docs d2 where d2.id = vd.id) as content,
      null::uuid as account_id, null::float as distance, null::int as semantic_rank
    from permitted_docs vd
    join lexical l on l.doc_id = vd.id
    where not exists (select 1 from semantic s2 where s2.doc_id = vd.id)
  )
  select
    c.id, c.doc_id, vd.title as doc_title, c.content, c.account_id, vd.visibility,
    l.lexical_rank, c.semantic_rank, c.distance,
    (coalesce(1.0 / (60 + l.lexical_rank), 0.0)
      + coalesce(1.0 / (60 + c.semantic_rank), 0.0)
      + (coalesce(vd.authority, 0) * 0.002)
      + case when v_fresh_on then
          coalesce(
            v_fresh_weight * exp(- ln(2.0)
              * greatest(0.0, extract(epoch from (now() - coalesce(vd.last_verified_at, vd.updated_at))) / 86400.0)
              / greatest(1.0, v_fresh_halflife)),
            0.0)
          - (case when vd.expires_at is not null and vd.expires_at < now() then v_expired_penalty else 0.0 end)
        else 0.0 end
    )::double precision as score,
    w.n as withheld_count
  from candidates c
  join permitted_docs vd on vd.id = c.doc_id
  left join lexical l on l.doc_id = c.doc_id
  cross join withheld w
  where l.lexical_rank is not null or c.semantic_rank is not null
  order by
    (c.account_id is not null and c.account_id = p_account_id) desc,
    score desc
  limit p_match_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.increment_metric(p_metric text, p_delta bigint DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;
  insert into usage_metrics (tenant_id, day, metric, value)
    values (v_tenant, current_date, p_metric, p_delta)
    on conflict (tenant_id, day, metric)
    do update set value = usage_metrics.value + excluded.value;
end;
$function$;

CREATE OR REPLACE FUNCTION public.increment_metric_tenant(p_tenant_id uuid, p_metric text, p_delta bigint DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role only';
  end if;
  insert into usage_metrics (tenant_id, day, metric, value)
    values (p_tenant_id, current_date, p_metric, p_delta)
    on conflict (tenant_id, day, metric)
    do update set value = usage_metrics.value + excluded.value;
end;
$function$;

CREATE OR REPLACE FUNCTION public.increment_tenant_token_usage(p_tenant_id uuid, p_year_month text, p_tokens integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$BEGIN INSERT INTO tenant_ai_usage (tenant_id, year_month, tokens_used, updated_at) VALUES (p_tenant_id, p_year_month, p_tokens, now()) ON CONFLICT (tenant_id, year_month) DO UPDATE SET tokens_used = tenant_ai_usage.tokens_used + EXCLUDED.tokens_used, updated_at = now(); END;$function$;

CREATE OR REPLACE FUNCTION public.ingest_document(p_tenant_id uuid, p_workspace_id uuid, p_doc_type text, p_filename text, p_rows jsonb, p_uploaded_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_doc_id uuid;
  v_row jsonb;
  v_ingested int := 0;
  v_total int := 0;
  v_status text := 'ingested';
  v_acct uuid;
begin
  v_caller_tenant := auth_tenant_id();
  if v_caller_tenant is distinct from p_tenant_id and not is_platform_admin() then
    raise exception 'tenant mismatch: caller % cannot ingest for %', v_caller_tenant, p_tenant_id;
  end if;

  v_total := coalesce(jsonb_array_length(p_rows), 0);

  if p_doc_type in ('invoice_pdf','receipt_pdf') then
    v_status := 'needs_review';
  end if;

  insert into public.fin_documents(tenant_id, workspace_id, doc_type, filename, status, row_count, uploaded_by)
  values (p_tenant_id, p_workspace_id, p_doc_type, p_filename, v_status, v_total, p_uploaded_by)
  returning id into v_doc_id;

  if v_status = 'needs_review' then
    update public.fin_documents set parse_summary = 'PDF stored for manual review (no automated extraction)' where id = v_doc_id;
    return jsonb_build_object('document_id', v_doc_id, 'status', v_status, 'ingested', 0, 'total', v_total);
  end if;

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    begin
      if p_doc_type = 'bank_statement' then
        select id into v_acct from public.fin_accounts
          where tenant_id = p_tenant_id and is_bank = true order by code limit 1;
        insert into public.bank_transactions(tenant_id, workspace_id, account_id, txn_date, description, amount, category, is_matched, external_ref)
        values (p_tenant_id, p_workspace_id, v_acct,
          (v_row->>'date')::date, coalesce(v_row->>'description',''),
          (v_row->>'amount')::numeric, nullif(v_row->>'category',''), false, nullif(v_row->>'ref',''));
        v_ingested := v_ingested + 1;
      elsif p_doc_type = 'ar_aging' then
        insert into public.invoices(tenant_id, workspace_id, invoice_number, issue_date, due_date, amount, amount_paid, status, has_pdf)
        values (p_tenant_id, p_workspace_id,
          coalesce(v_row->>'invoice_number', 'IMP-'||substr(md5(random()::text),1,6)),
          (v_row->>'issue_date')::date, (v_row->>'due_date')::date,
          (v_row->>'amount')::numeric, coalesce((v_row->>'amount_paid')::numeric, 0),
          coalesce(nullif(v_row->>'status',''),'open'), false);
        v_ingested := v_ingested + 1;
      elsif p_doc_type = 'ap_aging' then
        insert into public.bills(tenant_id, workspace_id, bill_number, issue_date, due_date, amount, amount_paid, status, has_receipt)
        values (p_tenant_id, p_workspace_id,
          coalesce(v_row->>'bill_number', 'BIMP-'||substr(md5(random()::text),1,6)),
          (v_row->>'issue_date')::date, (v_row->>'due_date')::date,
          (v_row->>'amount')::numeric, coalesce((v_row->>'amount_paid')::numeric, 0),
          coalesce(nullif(v_row->>'status',''),'open'), coalesce((v_row->>'has_receipt')::boolean, false));
        v_ingested := v_ingested + 1;
      elsif p_doc_type = 'stripe_export' then
        insert into public.payments(tenant_id, workspace_id, direction, source, amount, paid_date, external_ref)
        values (p_tenant_id, p_workspace_id, 'inbound', 'stripe',
          (v_row->>'amount')::numeric, (v_row->>'date')::date, nullif(v_row->>'ref',''));
        v_ingested := v_ingested + 1;
      elsif p_doc_type = 'general_ledger' then
        select id into v_acct from public.fin_accounts
          where tenant_id = p_tenant_id and code = (v_row->>'account_code') limit 1;
        insert into public.journal_entries(tenant_id, workspace_id, account_id, entry_date, memo, debit, credit, source)
        values (p_tenant_id, p_workspace_id, v_acct,
          (v_row->>'date')::date, coalesce(v_row->>'memo',''),
          coalesce((v_row->>'debit')::numeric, 0), coalesce((v_row->>'credit')::numeric, 0), 'import');
        v_ingested := v_ingested + 1;
      elsif p_doc_type = 'payroll_summary' then
        select id into v_acct from public.fin_accounts
          where tenant_id = p_tenant_id and type = 'expense' order by code limit 1;
        insert into public.journal_entries(tenant_id, workspace_id, account_id, entry_date, memo, debit, credit, source)
        values (p_tenant_id, p_workspace_id, v_acct,
          (v_row->>'date')::date, 'Payroll: '||coalesce(v_row->>'memo','run'),
          coalesce((v_row->>'amount')::numeric, 0), 0, 'payroll');
        v_ingested := v_ingested + 1;
      end if;
    exception when others then
      null;
    end;
  end loop;

  update public.fin_documents
    set status = 'ingested', ingested_count = v_ingested,
        parse_summary = v_ingested||' of '||v_total||' rows normalized into finance objects'
    where id = v_doc_id;

  return jsonb_build_object('document_id', v_doc_id, 'status', 'ingested', 'ingested', v_ingested, 'total', v_total);
end;
$function$;

CREATE OR REPLACE FUNCTION public.install_role_kit(p_de_id uuid, p_archetype_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a role_archetypes;
  v_tenant uuid;
  v_watchers int := 0;
  v_guardrails int := 0;
  v_pb_key text;
  v_pb_id uuid;
  v_pb_version int;
  w jsonb;
  g jsonb;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'unknown DE %', p_de_id; end if;

  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or (p.tenant_id = v_tenant
           and p.role in ('tenant_owner','tenant_admin','tenant_manager')))) then
    raise exception 'not authorized to configure this DE';
  end if;

  select * into a from role_archetypes where key = p_archetype_key and status = 'active';
  if a.key is null then raise exception 'unknown archetype %', p_archetype_key; end if;

  -- Watchers: derive-your-own-work. The validate_work_watcher trigger enforces
  -- each kind's config shape, so a bad template fails loudly here.
  if a.watcher_templates is not null then
    for w in select * from jsonb_array_elements(a.watcher_templates) loop
      if not exists (
        select 1 from work_watchers
        where de_id = p_de_id and kind = w->>'kind' and label = w->>'label') then
        insert into work_watchers (tenant_id, de_id, kind, label, description, config, active)
        values (v_tenant, p_de_id, w->>'kind', w->>'label', w->>'description', w->'config', true);
        v_watchers := v_watchers + 1;
      end if;
    end loop;
  end if;

  -- SOP playbook: attach to THIS DE + publish (snapshot into playbook_versions).
  if a.sop_playbook is not null then
    v_pb_key := p_archetype_key || '_sop';
    insert into playbook_definitions
      (tenant_id, key, name, description, version, status, steps, trigger_type, de_id)
    values
      (v_tenant, v_pb_key, a.sop_playbook->>'name', a.sop_playbook->>'description',
       1, 'published', a.sop_playbook->'steps', 'manual', p_de_id)
    on conflict (tenant_id, key) do update
      set name = excluded.name, description = excluded.description,
          steps = excluded.steps, status = 'published',
          version = playbook_definitions.version + 1, de_id = p_de_id,
          updated_at = now()
    returning id, version into v_pb_id, v_pb_version;

    insert into playbook_versions (definition_id, version, steps, published_by)
    values (v_pb_id, v_pb_version, a.sop_playbook->'steps', null)
    on conflict do nothing;
  end if;

  -- Role guardrails: employee-scoped. The permanent propose-only guarantee for
  -- money/terms is the destructive-action FLOOR in decide_action_execution;
  -- these state the rules to the DE and add amount/discount/phrase gates.
  if a.guardrail_templates is not null then
    for g in select * from jsonb_array_elements(a.guardrail_templates) loop
      if not exists (
        select 1 from guardrail_rules
        where tenant_id = v_tenant and scope = 'employee' and scope_ref = p_de_id::text
          and rule_type = g->>'rule_type' and rule = g->>'rule') then
        insert into guardrail_rules
          (tenant_id, rule, rule_type, pattern, threshold, severity, active, scope, scope_ref)
        values
          (v_tenant, g->>'rule', g->>'rule_type', g->>'pattern',
           nullif(g->>'threshold','')::bigint,
           coalesce(g->>'severity','blocking'), true, 'employee', p_de_id::text);
        v_guardrails := v_guardrails + 1;
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'de_id', p_de_id, 'archetype', p_archetype_key,
    'watchers_created', v_watchers, 'guardrails_created', v_guardrails,
    'sop_playbook_id', v_pb_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.install_role_systems(p_de_id uuid, p_archetype_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a role_archetypes; v_tenant uuid; s jsonb; v_n int := 0;
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unknown DE %', p_de_id; END IF;
  SELECT * INTO a FROM role_archetypes WHERE key = p_archetype_key;
  IF a.system_templates IS NULL THEN RETURN 0; END IF;
  FOR s IN SELECT * FROM jsonb_array_elements(a.system_templates) LOOP
    INSERT INTO de_connected_systems (tenant_id, de_id, system_key, label, binding_kind, source_table, id_column,
      read_fields, write_registry, can_read, can_write, can_verify)
    VALUES (v_tenant, p_de_id, s->>'system_key', s->>'label', coalesce(s->>'binding_kind','internal_table'),
      s->>'source_table', coalesce(s->>'id_column','id'), coalesce(s->'read_fields','[]'::jsonb), s->>'write_registry',
      coalesce((s->>'can_read')::boolean, true), coalesce((s->>'can_write')::boolean, false), coalesce((s->>'can_verify')::boolean, true))
    ON CONFLICT (de_id, system_key) DO UPDATE SET
      label = excluded.label, source_table = excluded.source_table, read_fields = excluded.read_fields,
      write_registry = excluded.write_registry, can_read = excluded.can_read, can_write = excluded.can_write,
      can_verify = excluded.can_verify, active = true;
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END; $function$;

CREATE OR REPLACE FUNCTION public.install_standing_watchers(p_mission_id uuid, p_specs jsonb, p_approved_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_de uuid; v_status text;
  spec jsonb; v_installed int := 0; v_err text;
  v_label text; v_kind text; v_cfg jsonb;
BEGIN
  SELECT tenant_id, de_id, status INTO v_tenant, v_de, v_status
    FROM de_missions WHERE id = p_mission_id FOR UPDATE;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF v_status <> 'awaiting_approval' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_awaiting_approval', 'status', v_status);
  END IF;
  IF jsonb_typeof(p_specs) <> 'array' OR jsonb_array_length(p_specs) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_specs');
  END IF;

  FOR spec IN SELECT * FROM jsonb_array_elements(p_specs) LOOP
    v_kind  := spec->>'kind';
    v_label := left(coalesce(spec->>'label', ''), 200);
    v_cfg   := coalesce(spec->'config', '{}'::jsonb);
    IF v_label = '' THEN RAISE EXCEPTION 'A standing watcher is missing its label.'; END IF;
    v_err := public.validate_watcher_config(v_kind, v_cfg, v_tenant, v_de);
    IF v_err IS NOT NULL THEN RAISE EXCEPTION '%', v_err; END IF;
    IF EXISTS (SELECT 1 FROM work_watchers
                WHERE mission_id = p_mission_id AND label = v_label) THEN
      CONTINUE;  -- idempotent: already installed on a prior approve attempt
    END IF;
    INSERT INTO work_watchers
      (tenant_id, de_id, kind, label, description, config, active, mission_id)
    VALUES
      (v_tenant, v_de, v_kind, v_label,
       left(coalesce(spec->>'description', ''), 500), v_cfg, true, p_mission_id);
    v_installed := v_installed + 1;
  END LOOP;

  UPDATE de_missions
     SET status = 'running', approved_by = p_approved_by,
         approved_at = now(), updated_at = now()
   WHERE id = p_mission_id;
  RETURN jsonb_build_object('ok', true, 'installed', v_installed);
END $function$;

CREATE OR REPLACE FUNCTION public.install_starter_onboarding_template()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_tpl_id uuid;
  v_pub    jsonb;
  v_items  jsonb := '[
    {"key":"kickoff_call","label":"Kickoff call held","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"Intro call: goals, timeline, points of contact."},
    {"key":"data_export_received","label":"Data export received from customer","phase":"data","owner_type":"either","requires_signoff":false,"description":"Customer sends their employee/location export (CSV or spreadsheet)."},
    {"key":"employees_imported","label":"Employees imported","phase":"data","owner_type":"de","requires_signoff":false,"description":"Employee records loaded and normalized in the platform."},
    {"key":"locations_configured","label":"Locations configured","phase":"config","owner_type":"de","requires_signoff":false,"description":"Sites, time zones, and operating hours set up."},
    {"key":"settings_review","label":"Account settings reviewed","phase":"config","owner_type":"human","requires_signoff":true,"description":"Human sign-off on core account configuration."},
    {"key":"leave_rules_configured","label":"Leave rules configured","phase":"config","owner_type":"either","requires_signoff":true,"description":"Accrual, carryover, and approval chains — needs human sign-off."},
    {"key":"test_scenario_run","label":"Test scenario run","phase":"validation","owner_type":"de","requires_signoff":false,"description":"End-to-end test with sample data."},
    {"key":"uat_approved","label":"UAT approved by customer","phase":"validation","owner_type":"human","requires_signoff":true,"description":"Customer confirms acceptance testing passed."},
    {"key":"training_session","label":"Training session delivered","phase":"golive","owner_type":"human","requires_signoff":false,"description":"Admin + end-user training completed."},
    {"key":"go_live","label":"Go-live","phase":"golive","owner_type":"human","requires_signoff":true,"description":"Production cutover — final human sign-off."}
  ]'::jsonb;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then
    raise exception 'account is deactivated';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then
    raise exception 'no tenant for caller';
  end if;

  select id into v_tpl_id from onboarding_templates
    where tenant_id = v_tenant and name = 'SaaS onboarding — starter' limit 1;
  if v_tpl_id is not null then
    return jsonb_build_object('template_id', v_tpl_id, 'already_installed', true);
  end if;

  insert into onboarding_templates (tenant_id, name, description, items)
  values (v_tenant, 'SaaS onboarding — starter',
          '10-step implementation checklist: kickoff → data → config → validation → go-live. Sign-off gates on settings, leave rules, UAT, and go-live.',
          v_items)
  returning id into v_tpl_id;

  v_pub := publish_onboarding_template(v_tpl_id);
  return jsonb_build_object('template_id', v_tpl_id, 'already_installed', false) || v_pub;
end;
$function$;

CREATE OR REPLACE FUNCTION public.install_technical_specialist()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_is_active boolean; v_id uuid;
begin
  select tenant_id, coalesce(is_active, true) into v_tenant, v_is_active from profiles where user_id = auth.uid();
  if v_tenant is null then
    if coalesce(auth.role(), '') = 'service_role' then raise exception 'service role must use direct inserts with an explicit tenant'; end if;
    return jsonb_build_object('error', 'no_tenant');
  end if;
  if not v_is_active then raise exception 'account is deactivated'; end if;

  select id into v_id from digital_employees
    where tenant_id = v_tenant and is_specialist = true and specialist_key = 'technical' limit 1;
  if v_id is not null then return jsonb_build_object('profile_id', v_id, 'already_installed', true); end if;

  insert into digital_employees (tenant_id, name, persona_name, category, is_specialist, specialist_key, description, charter, lifecycle_status, status)
  values (v_tenant, 'Technical Specialist', 'Technical Specialist', 'Internal', true, 'technical',
    'Consulted for API, integration, architecture, and debugging questions that exceed a primary Digital Employee''s depth.',
    jsonb_build_object('mission', 'You are the Technical Specialist — consulted for deep technical questions. Answer ONLY from configured sources; cite every source; escalate when the sources do not support an answer.'),
    'active', 'active')
  returning id into v_id;

  perform append_audit_event(v_tenant, 'You', 'human',
    'Technical Specialist installed (as a Digital Employee) — charter seeded, sources not yet configured',
    'config_change', jsonb_build_object('kind', 'specialist_de', 'de_id', v_id, 'specialist_key', 'technical'));
  return jsonb_build_object('profile_id', v_id, 'already_installed', false);
end; $function$;

CREATE OR REPLACE FUNCTION public.instantiate_role_archetype(p_tenant_id uuid, p_archetype_key text, p_de_name text, p_persona_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a role_archetypes; v_de uuid; v_pack text;
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or (p.tenant_id = p_tenant_id and p.role in ('tenant_owner','tenant_admin','tenant_manager')))) then
    raise exception 'not authorized to hire a DE for this tenant';
  end if;
  select * into a from role_archetypes where key = p_archetype_key and status = 'active';
  if a.key is null then raise exception 'unknown archetype %', p_archetype_key; end if;

  insert into digital_employees (tenant_id, name, persona_name, description, category, department,
    lifecycle_status, trust_level, status, capabilities, responsibilities, model_provider, model_id,
    catalog_id, archetype_key)
  values (p_tenant_id, p_de_name, p_persona_name, a.description, 'Customer', a.domain,
    'designed', 'supervised', 'idle', a.required_capabilities, a.responsibilities, 'anthropic', a.recommended_model,
    a.key, a.key)
  returning id into v_de;

  -- Auto-attach the archetype's mandatory compliance packs (now populated).
  foreach v_pack in array a.compliance_pack_keys loop
    perform public.attach_compliance_pack(p_tenant_id, v_pack);
  end loop;

  return v_de;
end;
$function$;

CREATE OR REPLACE FUNCTION public.invalidate_answer_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update answer_cache
    set invalidated = true
    where tenant_id = coalesce(new.tenant_id, old.tenant_id)
      and invalidated = false;
  return coalesce(new, old);
end;
$function$;

CREATE OR REPLACE FUNCTION public.invite_platform_team_member(p_email text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_invite platform_invites;
begin
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may invite a platform team member';
  end if;

  if v_email = '' or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'a valid email address is required';
  end if;

  if p_role not in ('platform_support', 'platform_billing', 'platform_super_admin') then
    raise exception 'unrecognized platform role: %', p_role;
  end if;

  update platform_invites
  set status = 'revoked'
  where lower(email) = v_email and status = 'pending';

  insert into platform_invites (email, role, invited_by)
  values (v_email, p_role, auth.uid())
  returning * into v_invite;

  return jsonb_build_object(
    'ok', true,
    'invite_id', v_invite.id,
    'invite_code', v_invite.invite_code,
    'email', v_invite.email,
    'role', v_invite.role
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.invoke_conflict_probe_drain(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_req_id bigint;
  v_body   jsonb;
  -- Project anon JWT satisfies the edge gateway (verify_jwt); x-dispatch-secret is
  -- the real auth checked inside the fn (same pattern as mig 288/278).
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
   WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN RETURN 'no_secret'; END IF;

  v_body := jsonb_build_object('limit', 10);
  IF p_tenant_id IS NOT NULL THEN v_body := v_body || jsonb_build_object('tenant_id', p_tenant_id); END IF;

  SELECT net.http_post(
    url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/conflict-probe-drain',
    body    := v_body,
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_anon,
                                  'x-dispatch-secret', v_secret),
    timeout_milliseconds := 120000
  ) INTO v_req_id;

  RETURN 'dispatched:' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.invoke_embed_backfill()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_req_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — embedding backfill cron is doing nothing.',
      jsonb_build_object('cron', 'invoke_embed_backfill'));
    RETURN 'no_secret';
  END IF;

  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/embed-backfill'),
    body := jsonb_build_object('limit', 8),
    headers := jsonb_build_object('Content-Type','application/json','x-dispatch-secret',v_secret),
    timeout_milliseconds := 120000
  ) INTO v_req_id;

  RETURN 'dispatched:' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.invoke_eval_batch_poll()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_secret text; v_open int; v_req bigint;
BEGIN
  -- Nothing in flight → don't wake the function at all.
  SELECT count(*) INTO v_open FROM eval_batch_jobs WHERE status IN ('in_progress','collecting');
  IF v_open = 0 THEN RETURN 'idle'; END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN RETURN 'no_secret'; END IF;

  SELECT net.http_post(
    url := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/eval-batch',
    body := jsonb_build_object('action', 'poll'),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', v_secret),
    timeout_milliseconds := 150000
  ) INTO v_req;
  RETURN 'polled_open:' || v_open;
END; $function$;

CREATE OR REPLACE FUNCTION public.invoke_knowledge_ingest_drain(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_req_id bigint;
  v_body   jsonb;
  v_due    int;
  v_anon   text := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg';
BEGIN
  -- Reap first. An item abandoned by a worker that died mid-flight would
  -- otherwise hold its slot forever and never appear in the due count.
  PERFORM public.reap_stale_ingestion_items();

  -- Don't wake the edge function for an empty queue. This runs every 2 minutes
  -- across 16 workspaces that will usually have nothing to do; a cheap indexed
  -- count is the difference between a free tick and 720 pointless invocations
  -- a day.
  SELECT count(*) INTO v_due FROM knowledge_ingestion_items
   WHERE status = 'queued' AND next_attempt_at <= now();
  IF v_due = 0 THEN RETURN 'idle'; END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
   WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN RETURN 'no_secret'; END IF;

  v_body := jsonb_build_object('limit', 10);
  IF p_tenant_id IS NOT NULL THEN v_body := v_body || jsonb_build_object('tenant_id', p_tenant_id); END IF;

  SELECT net.http_post(
    url     := 'https://rfsvmhcqeiyrxivbmpel.supabase.co/functions/v1/knowledge-ingest-drain',
    body    := v_body,
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_anon,
                                  'x-dispatch-secret', v_secret),
    timeout_milliseconds := 120000
  ) INTO v_req_id;

  RETURN 'dispatched:' || v_req_id || ' due:' || v_due;
END $function$;

CREATE OR REPLACE FUNCTION public.invoke_playbook_dispatch()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret  text;
  v_anon    text := platform_anon_key();
  v_req_id  bigint; v_req_id2 bigint; v_req_id3 bigint; v_req_id4 bigint;
  v_t       record;
  v_health  integer := 0;
  v_stale   jsonb;
BEGIN
  FOR v_t IN
    SELECT DISTINCT ca.tenant_id
    FROM customer_accounts ca
    LEFT JOIN health_score_config c ON c.tenant_id = ca.tenant_id
    WHERE c.last_computed_at IS NULL OR c.last_computed_at < now() - interval '24 hours'
  LOOP
    PERFORM compute_tenant_health_service(v_t.tenant_id);
    v_health := v_health + 1;
  END LOOP;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — the 5-minute dispatch cron (playbooks, polling, gap/learn detection) is doing NOTHING.',
      jsonb_build_object('cron', 'invoke_playbook_dispatch'));
    RETURN format('health:%s no_secret', v_health);
  END IF;

  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/playbook-execute'),
    body := '{"action":"dispatch"}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'apikey',v_anon,'x-dispatch-secret',v_secret),
    timeout_milliseconds := 30000
  ) INTO v_req_id;

  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/specialist-consult'),
    body := '{"action":"poll_de_work_sources"}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'apikey',v_anon,'x-dispatch-secret',v_secret),
    timeout_milliseconds := 30000
  ) INTO v_req_id2;

  BEGIN
    v_stale := check_staleness();
  EXCEPTION WHEN OTHERS THEN
    v_stale := jsonb_build_object('error', sqlerrm);
  END;

  BEGIN
    SELECT net.http_post(
      url := platform_fn_url('/functions/v1/knowledge-gap-detect'),
      body := '{}'::jsonb,
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'apikey',v_anon,'x-dispatch-secret',v_secret),
      timeout_milliseconds := 30000
    ) INTO v_req_id3;
  EXCEPTION WHEN OTHERS THEN v_req_id3 := NULL; END;

  BEGIN
    SELECT net.http_post(
      url := platform_fn_url('/functions/v1/learned-behavior-detect'),
      body := '{}'::jsonb,
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'apikey',v_anon,'x-dispatch-secret',v_secret),
      timeout_milliseconds := 30000
    ) INTO v_req_id4;
  EXCEPTION WHEN OTHERS THEN v_req_id4 := NULL; END;

  RETURN format('health:%s dispatch:%s poll:%s gap:%s learn:%s stale:%s',
    v_health, v_req_id, v_req_id2, coalesce(v_req_id3::text, 'err'), coalesce(v_req_id4::text, 'err'),
    coalesce(v_stale->>'checked', '0'));
END;
$function$;

