CREATE OR REPLACE FUNCTION public.list_team_members_full(p_tenant_id uuid)
 RETURNS TABLE(user_id uuid, full_name text, email text, role text, department text, is_active boolean, last_seen_at timestamp with time zone, created_at timestamp with time zone, invited_by text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s team';
  end if;

  return query
    select p.user_id, p.full_name, u.email::text, p.role, p.department,
      coalesce(p.is_active, true), p.last_seen_at, p.created_at, p.invited_by
    from profiles p
    join auth.users u on u.id = p.user_id
    where p.tenant_id = p_tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_team_mfa_status(p_tenant_id uuid)
 RETURNS TABLE(user_id uuid, mfa_verified boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can view team MFA status';
  end if;

  return query
    select p.user_id,
      exists(
        select 1 from auth.mfa_factors f
        where f.user_id = p.user_id and f.status = 'verified'
      ) as mfa_verified
    from profiles p
    where p.tenant_id = p_tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_tenant_api_keys(p_tenant_id uuid)
 RETURNS TABLE(id uuid, name text, display_hint text, scopes text[], created_at timestamp with time zone, last_used_at timestamp with time zone, revoked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can view API keys';
  end if;

  return query
    select k.id, k.name, k.display_hint, k.scopes, k.created_at, k.last_used_at, k.revoked_at
    from tenant_api_keys k
    where k.tenant_id = p_tenant_id
    order by k.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_workspace_people()
 RETURNS TABLE(user_id uuid, full_name text, role text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT pr.user_id, coalesce(pr.full_name, 'Unnamed teammate'), pr.role
    FROM profiles pr
   WHERE pr.tenant_id = auth_tenant_id() AND coalesce(pr.is_active, true)
     AND pr.layer IS DISTINCT FROM 'platform'
   ORDER BY 2;
