CREATE OR REPLACE FUNCTION public.log_remote_access_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_is_remote boolean;
  v_full_name text;
  v_session_key uuid;
  v_tenant_id uuid;
  v_row_pk text;
begin
  begin
    select
      (not exists (select 1 from profiles where user_id = auth.uid() and tenant_id is not null))
      and exists (select 1 from profiles where user_id = auth.uid() and layer = 'platform')
    into v_is_remote;

    if not coalesce(v_is_remote, false) then
      return coalesce(NEW, OLD);
    end if;

    v_tenant_id := coalesce(
      nullif(to_jsonb(NEW)->>'tenant_id', '')::uuid,
      nullif(to_jsonb(OLD)->>'tenant_id', '')::uuid
    );
    if v_tenant_id is null then
      return coalesce(NEW, OLD);
    end if;

    select full_name into v_full_name from profiles where user_id = auth.uid();

    select e.session_key into v_session_key
    from platform_access_events e
    where e.operator_user_id = auth.uid()
      and e.event = 'start'
      and e.created_at > now() - interval '12 hours'
      and e.id = (
        select e2.id from platform_access_events e2
        where e2.operator_user_id = auth.uid()
        order by e2.created_at desc limit 1
      )
    limit 1;

    v_row_pk := coalesce(to_jsonb(NEW)->>'id', to_jsonb(OLD)->>'id');

    insert into remote_access_write_log (
      session_key, operator_user_id, operator_name, tenant_id,
      table_name, operation, row_pk, old_data, new_data
    ) values (
      v_session_key, auth.uid(), coalesce(v_full_name, 'Platform admin'), v_tenant_id,
      TG_TABLE_NAME, TG_OP, v_row_pk,
      case when TG_OP in ('UPDATE', 'DELETE') then to_jsonb(OLD) else null end,
      case when TG_OP in ('INSERT', 'UPDATE') then to_jsonb(NEW) else null end
    );
  exception when others then
    null;
  end;
  return coalesce(NEW, OLD);
end;
$function$;

CREATE OR REPLACE FUNCTION public.log_tenant_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_tenant uuid;
  v_actor_name text;
  v_actor_role text;
  v_row_tenant_id uuid;
  v_row_pk text;
begin
  begin
    if auth.uid() is null then
      return coalesce(NEW, OLD);
    end if;

    select tenant_id, full_name, role into v_actor_tenant, v_actor_name, v_actor_role
    from profiles where user_id = auth.uid();

    if v_actor_tenant is null then
      return coalesce(NEW, OLD);
    end if;

    v_row_tenant_id := coalesce(
      nullif(to_jsonb(NEW)->>'tenant_id', '')::uuid,
      nullif(to_jsonb(OLD)->>'tenant_id', '')::uuid
    );

    if v_row_tenant_id is null or v_row_tenant_id is distinct from v_actor_tenant then
      return coalesce(NEW, OLD);
    end if;

    v_row_pk := coalesce(to_jsonb(NEW)->>'id', to_jsonb(OLD)->>'id');

    insert into tenant_activity_log (
      tenant_id, actor_user_id, actor_name, actor_role,
      table_name, operation, row_pk, old_data, new_data
    ) values (
      v_row_tenant_id, auth.uid(), coalesce(v_actor_name, 'Team member'), v_actor_role,
      TG_TABLE_NAME, TG_OP, v_row_pk,
      case when TG_OP in ('UPDATE', 'DELETE') then to_jsonb(OLD) else null end,
      case when TG_OP in ('INSERT', 'UPDATE') then to_jsonb(NEW) else null end
    );
  exception when others then
    null;
  end;
  return coalesce(NEW, OLD);
end;
$function$;

CREATE OR REPLACE FUNCTION public.maintain_doc_chunk_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE knowledge_docs SET
      chunk_count    = coalesce(chunk_count, 0) + 1,
      embedded_count = coalesce(embedded_count, 0) + (CASE WHEN NEW.embedding IS NOT NULL THEN 1 ELSE 0 END)
     WHERE id = NEW.doc_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE knowledge_docs SET
      chunk_count    = greatest(coalesce(chunk_count, 0) - 1, 0),
      embedded_count = greatest(coalesce(embedded_count, 0) - (CASE WHEN OLD.embedding IS NOT NULL THEN 1 ELSE 0 END), 0)
     WHERE id = OLD.doc_id;
  ELSIF TG_OP = 'UPDATE' THEN
    IF (OLD.embedding IS NULL) IS DISTINCT FROM (NEW.embedding IS NULL) THEN
      UPDATE knowledge_docs SET
        embedded_count = greatest(coalesce(embedded_count, 0) + (CASE WHEN NEW.embedding IS NOT NULL THEN 1 ELSE -1 END), 0)
       WHERE id = NEW.doc_id;
    END IF;
    IF NEW.doc_id IS DISTINCT FROM OLD.doc_id THEN
      UPDATE knowledge_docs SET chunk_count = greatest(coalesce(chunk_count, 0) - 1, 0) WHERE id = OLD.doc_id;
      UPDATE knowledge_docs SET chunk_count = coalesce(chunk_count, 0) + 1 WHERE id = NEW.doc_id;
    END IF;
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.mark_doc_verified(p_doc_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  UPDATE knowledge_docs SET last_verified_at = now(), updated_at = updated_at
   WHERE id = p_doc_id AND tenant_id = v_tenant;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'verified_at', now());
END $function$;

CREATE OR REPLACE FUNCTION public.mark_outbound_delivery(p_draft_id uuid, p_status text, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de uuid;
BEGIN
  IF p_status NOT IN ('sent','failed','blocked_no_provider','sending') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  SELECT tenant_id, de_id INTO v_tenant, v_de FROM outbound_drafts WHERE id = p_draft_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  UPDATE outbound_drafts
     SET delivery_status = p_status,
         sent_at = CASE WHEN p_status = 'sent' THEN now() ELSE sent_at END,
         provider_message_id = coalesce(p_provider_message_id, provider_message_id),
         delivery_error = p_error,
         status = CASE WHEN p_status = 'sent' THEN 'sent' ELSE status END,
         updated_at = now()
   WHERE id = p_draft_id;
  BEGIN PERFORM append_audit_event_internal(v_tenant,
    (SELECT coalesce(persona_name, name) FROM digital_employees WHERE id = v_de), 'de',
    CASE p_status
      WHEN 'sent' THEN 'Outbound email SENT (human-approved) — draft ' || p_draft_id
      WHEN 'blocked_no_provider' THEN 'Outbound email approved but NOT sent — email provider not configured (add RESEND_API_KEY + a verified from-address)'
      ELSE 'Outbound email delivery ' || p_status || ' — ' || coalesce(p_error,'') END,
    'connector_action',
    jsonb_build_object('kind','outbound_email_delivery','draft_id',p_draft_id,'status',p_status,'provider_message_id',p_provider_message_id));
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('ok', true, 'status', p_status);
END; $function$;

CREATE OR REPLACE FUNCTION public.mark_training_progress(p_de_id uuid, p_module_key text, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into de_training_progress (tenant_id, de_id, module_key, status, completed_at, updated_at)
  select tenant_id, p_de_id, p_module_key, p_status,
         case when p_status = 'completed' then now() end, now()
  from digital_employees where id = p_de_id
  on conflict (de_id, module_key) do update
    set status = excluded.status, completed_at = excluded.completed_at, updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.match_cached_answer(p_tenant_id uuid, p_account_id uuid, p_query_embedding vector, p_max_distance double precision DEFAULT 0.15, p_language text DEFAULT NULL::text, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, answer text, confidence integer, sources jsonb, distance double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') = 'anon' then
    raise exception 'tenant access denied';
  end if;
  perform public._assert_caller_tenant(p_tenant_id);
  return query
  select a.id, a.answer, a.confidence, a.sources,
         (a.question_embedding <=> p_query_embedding)::float as distance
  from answer_cache a
  where a.tenant_id = p_tenant_id
    and a.invalidated = false
    and a.question_embedding is not null
    and a.de_id is not distinct from p_de_id   -- DE-scoped: a DE's cache serves only that DE
    and (a.account_id is null or (p_account_id is not null and a.account_id = p_account_id))
    and (a.question_embedding <=> p_query_embedding) < p_max_distance
    and (
      (p_language is null and (a.language is null or a.language ilike 'english'))
      or (p_language is not null and a.language ilike p_language)
    )
  order by
    (a.account_id is not null and a.account_id = p_account_id) desc,
    a.question_embedding <=> p_query_embedding
  limit 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.match_doc_chunks(p_tenant_id uuid, p_account_id uuid, p_query_embedding vector, p_match_count integer DEFAULT 5, p_subject_kind text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, doc_id uuid, content text, account_id uuid, distance double precision, visibility text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_archetype text;
begin
  perform public._assert_caller_tenant(p_tenant_id);
  v_archetype := case when p_subject_kind = 'de' and p_subject_id is not null then resolve_de_archetype(p_subject_id) end;
  return query
  select c.id, c.doc_id, c.content, c.account_id,
         (c.embedding <=> p_query_embedding)::float as distance,
         d.visibility
  from knowledge_doc_chunks c
  join knowledge_docs d on d.id = c.doc_id
  where c.tenant_id = p_tenant_id
    and c.embedding is not null
    and d.is_current
    and (c.account_id is null or (p_account_id is not null and c.account_id = p_account_id))
    and (
      d.visibility = 'tenant'
      or (p_subject_kind is not null and p_subject_id is not null and exists (
            select 1 from knowledge_doc_scopes s
            where s.doc_id = d.id
              and s.subject_kind = p_subject_kind
              and s.subject_id = p_subject_id))
      or (d.visibility = 'role' and v_archetype is not null and d.share_archetype_key = v_archetype)
    )
  order by
    (c.account_id is not null and c.account_id = p_account_id) desc,
    c.embedding <=> p_query_embedding
  limit p_match_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.match_knowledge_chunks(query_embedding vector, match_tenant_id uuid, match_threshold double precision DEFAULT 0.4, match_count integer DEFAULT 6)
 RETURNS TABLE(id uuid, content text, title text, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT kc.id, kc.content, kc.title,
    (1 - (kc.embedding <=> query_embedding))::float AS similarity
  FROM knowledge_chunks kc
  WHERE kc.tenant_id = match_tenant_id
    AND kc.embedding IS NOT NULL
    AND (1 - (kc.embedding <=> query_embedding)) > match_threshold
  ORDER BY kc.embedding <=> query_embedding
  LIMIT match_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.mcp_host_allowed(p_tenant_id uuid, p_host text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized';
  end if;
  return case
    when not exists (select 1 from mcp_server_allowlist where tenant_id = p_tenant_id) then true
    else exists (select 1 from mcp_server_allowlist
                  where tenant_id = p_tenant_id and lower(host) = lower(p_host))
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_knowledge_collection(p_id uuid, p_new_parent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_is_space boolean;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT is_space INTO v_is_space FROM knowledge_collections WHERE id = p_id AND tenant_id = v_tenant;
  IF v_is_space IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF v_is_space THEN RAISE EXCEPTION 'a space is already top level — it cannot be moved inside another'; END IF;
  IF p_new_parent_id IS NULL THEN
    RAISE EXCEPTION 'choose a space or collection to move this into';
  END IF;
  -- Authority over BOTH ends, or moving is a way to relocate content into a
  -- branch you control.
  IF (knowledge_my_admin_level(p_id) < 5 OR knowledge_my_admin_level(p_new_parent_id) < 5)
     AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: you need knowledge manager on both the item and its destination';
  END IF;

  -- 341's trigger rejects cycles, depth > 3 and cross-workspace parents; the
  -- reparent trigger rebuilds the ancestry closure for everything beneath.
  UPDATE knowledge_collections SET parent_id = p_new_parent_id, updated_at = now() WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.my_account_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile profiles;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  select * into v_profile from profiles where user_id = auth.uid();
  if not found then
    return jsonb_build_object('found', false);
  end if;
  return jsonb_build_object(
    'found', true,
    'is_active', coalesce(v_profile.is_active, true),
    'role', v_profile.role,
    'layer', v_profile.layer,
    'tenant_id', v_profile.tenant_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.next_approved_browser_task()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE t computer_use_tasks;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  SELECT * INTO t FROM computer_use_tasks
    WHERE status = 'approved' AND engine IN ('browser_dom','browser_vision')
    ORDER BY updated_at ASC LIMIT 1;
  IF t.id IS NULL THEN RETURN jsonb_build_object('ok', true, 'task', NULL); END IF;
  RETURN jsonb_build_object('ok', true, 'task', jsonb_build_object(
    'id', t.id, 'tenant_id', t.tenant_id, 'de_id', t.de_id, 'goal', t.goal,
    'allowed_domains', t.allowed_domains, 'max_steps', t.max_steps,
    'engine', t.engine, 'credential_policy', t.credential_policy));
END; $function$;

CREATE OR REPLACE FUNCTION public.normalize_operate_domain(p_domain text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT nullif(lower(regexp_replace(regexp_replace(coalesce(p_domain,''), '^https?://', ''), '/.*$', '')), '');
$function$;

CREATE OR REPLACE FUNCTION public.oauth_app_status()
 RETURNS TABLE(provider text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select split_part(key, ':', 2)
  from platform_config
  where key like 'oauth:%:client_id' and secret_id is not null;
$function$;

CREATE OR REPLACE FUNCTION public.onboarding_check_complete(p_project_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj onboarding_projects;
  v_ver  onboarding_template_versions;
  v_acct_name text;
  v_incomplete integer;
begin
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found or v_proj.status <> 'active' then return false; end if;
  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;

  select count(*) into v_incomplete
  from jsonb_array_elements(v_ver.items) def
  join lateral (
    select s from jsonb_array_elements(v_proj.items_state) s
    where s->>'key' = def->>'key' limit 1
  ) st on true
  where case when coalesce((def->>'requires_signoff')::boolean, false)
             then st.s->>'status' <> 'signed_off'
             else st.s->>'status' not in ('done', 'signed_off') end;

  if v_incomplete > 0 then return false; end if;

  update onboarding_projects
    set status = 'completed', completed_at = now()
    where id = p_project_id;

  select name into v_acct_name from customer_accounts where id = v_proj.account_id;

  perform append_audit_event_internal(
    v_proj.tenant_id, 'System', 'system',
    format('Onboarding project completed — %s', v_proj.name),
    'config_change',
    jsonb_build_object('kind', 'onboarding_project_complete', 'project_id', p_project_id,
                       'account_id', v_proj.account_id));

  insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
  values (v_proj.tenant_id, v_proj.account_id, 'System', 'system', 'resolved',
          format('Onboarding completed — %s', coalesce(v_acct_name, v_proj.name)));

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.onboarding_progress_recalc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_total integer;
  v_done  integer;
begin
  select count(*),
         count(*) filter (where i->>'status' in ('done', 'signed_off'))
    into v_total, v_done
  from jsonb_array_elements(coalesce(new.items_state, '[]'::jsonb)) i;
  new.progress_pct := case when v_total = 0 then 0 else round(100.0 * v_done / v_total)::int end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.opportunities_stage_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_via_rpc boolean := coalesce(current_setting('dreamteam.opp_close', true), '') = 'on';
  v_stage_ok boolean;
begin
  -- Wave 4: data-driven stage validation (replaces the dropped CHECK).
  if new.stage not in ('won', 'lost') then
    select case
      when exists (select 1 from tenant_pipeline_stages t where t.tenant_id = new.tenant_id)
        then exists (select 1 from tenant_pipeline_stages t
                     where t.tenant_id = new.tenant_id and t.stage_key = new.stage)
      else new.stage in ('prospect', 'qualified', 'proposal', 'negotiation')
    end into v_stage_ok;
    if not v_stage_ok then
      raise exception 'unknown pipeline stage "%" — configure stages under Sales settings', new.stage;
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.stage in ('won', 'lost') then
      raise exception 'opportunities cannot be created already closed';
    end if;
    new.stage_history := jsonb_build_array(jsonb_build_object(
      'stage', new.stage, 'at', now(), 'by', coalesce(auth.uid()::text, 'system')));
    return new;
  end if;

  if new.stage <> old.stage then
    if old.stage in ('won', 'lost') then
      raise exception 'closed opportunities cannot change stage';
    end if;
    if new.stage in ('won', 'lost') and not v_via_rpc then
      raise exception 'won/lost only via close_opportunity_won / close_opportunity_lost';
    end if;
    if new.stage = 'lost' and coalesce(trim(new.lost_reason), '') = '' then
      raise exception 'lost requires a reason';
    end if;
    new.stage_history := coalesce(old.stage_history, '[]'::jsonb)
      || jsonb_build_object('stage', new.stage, 'at', now(), 'by', coalesce(auth.uid()::text, 'system'));
    if new.stage in ('won', 'lost') then
      new.closed_at := now();
      perform append_audit_event_internal(
        new.tenant_id, 'You', 'human',
        format('Opportunity %s — %s%s', case new.stage when 'won' then 'WON' else 'lost' end,
               new.name,
               case when new.stage = 'lost' then format(' (reason: %s)', new.lost_reason)
                    when new.amount_cents is not null then format(' ($%s)', round(new.amount_cents / 100.0)) else '' end),
        'config_change',
        jsonb_build_object('kind', 'opportunity_closed', 'opportunity_id', new.id,
                           'stage', new.stage, 'amount_cents', new.amount_cents,
                           'lost_reason', new.lost_reason, 'account_id', new.account_id));
    end if;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (new.tenant_id, new.account_id, 'You', 'human',
            case when new.stage = 'lost' then 'escalated' else 'config_change' end,
            format('Opportunity %s → %s', new.name, new.stage));
  end if;
  return new;
end;
$function$;

