CREATE OR REPLACE FUNCTION public.platform_config_get(p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_value text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'not authorized';
  end if;
  select vs.decrypted_secret into v_value
  from platform_config pc
  join vault.decrypted_secrets vs on vs.id = pc.secret_id
  where pc.key = p_key;
  return v_value;
end;
$function$;

CREATE OR REPLACE FUNCTION public.platform_config_has_key(p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'billing.manage') then
    raise exception 'not authorized';
  end if;
  return exists (select 1 from platform_config where key = p_key and secret_id is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.platform_config_set(p_entries jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k text;
  v text;
  v_existing uuid;
begin
  if not resolve_platform_capability(auth.uid(), 'billing.manage') then
    raise exception 'not authorized';
  end if;

  for k, v in select * from jsonb_each_text(p_entries)
  loop
    select secret_id into v_existing from platform_config where key = k;

    if v_existing is not null then
      perform vault.update_secret(v_existing, v);
      update platform_config set updated_at = now() where key = k;
    else
      insert into platform_config (key, secret_id, updated_at)
      values (k, vault.create_secret(v, 'platform_config:' || k, 'Set via platform_config_set'), now());
    end if;
  end loop;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.platform_connector_health_summary()
 RETURNS TABLE(tenant_id uuid, tenant_name text, connector_id uuid, display_name text, provider text, status text, last_ok_at timestamp with time zone, last_error_at timestamp with time zone, last_error text, consecutive_failures integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
