CREATE OR REPLACE FUNCTION public.platform_knowledge_audit_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO platform_knowledge_audit (actor, op, table_name, row_id, before, after)
  VALUES (
    coalesce(auth.uid()::text, nullif(current_setting('request.jwt.claims', true), ''), 'server'),
    TG_OP, TG_TABLE_NAME,
    coalesce((CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END), NULL),
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) - 'search_tsv' - 'embedding' END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) - 'search_tsv' - 'embedding' END);
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$;

CREATE OR REPLACE FUNCTION public.platform_match_knowledge(p_query_text text, p_query_embedding vector DEFAULT NULL::vector, p_match_count integer DEFAULT 3, p_max_distance double precision DEFAULT 0.25)
 RETURNS TABLE(chunk_id uuid, doc_id uuid, doc_title text, content text, lexical_rank integer, semantic_rank integer, distance double precision, score double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_paused boolean;
BEGIN
  -- Defence in depth; the mig 330 idiom. The grant below is the real control.
  IF coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '') = 'anon' THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  SELECT paused INTO v_paused FROM platform_knowledge_shelf_state WHERE singleton;
  IF coalesce(v_paused, true) THEN RETURN; END IF;   -- fail CLOSED: missing row = paused

  RETURN QUERY
  WITH visible_shelf_docs AS (      -- the single choke point; BOTH branches join it
    SELECT d.id, d.title, coalesce(d.authority, 0) AS authority, d.search_tsv
      FROM platform_knowledge_docs d
     WHERE d.is_current AND d.published_at IS NOT NULL
  ),
  lexical AS (
    SELECT vd.id AS doc_id,
           (row_number() OVER (ORDER BY ts_rank(vd.search_tsv,
              websearch_to_tsquery('english', p_query_text)) DESC))::int AS lexical_rank
      FROM visible_shelf_docs vd
     WHERE p_query_text IS NOT NULL AND length(trim(p_query_text)) > 0
       AND vd.search_tsv @@ websearch_to_tsquery('english', p_query_text)
  ),
  ann AS (
    SELECT c.id AS chunk_id, c.doc_id, c.content, (c.embedding <=> p_query_embedding) AS distance
      FROM platform_knowledge_chunks c
     WHERE c.embedding IS NOT NULL AND p_query_embedding IS NOT NULL
     ORDER BY c.embedding <=> p_query_embedding
     LIMIT 200
  ),
  semantic AS (
    SELECT a.chunk_id, a.doc_id, a.content, a.distance::float AS distance,
           (row_number() OVER (ORDER BY a.distance ASC))::int AS semantic_rank
      FROM ann a JOIN visible_shelf_docs vd ON vd.id = a.doc_id
     WHERE a.distance <= p_max_distance
  ),
  candidates AS (
    SELECT s.chunk_id, s.doc_id, s.content, s.distance, s.semantic_rank FROM semantic s
    UNION
    SELECT gen_random_uuid(), vd.id,
           (SELECT d2.content FROM platform_knowledge_docs d2 WHERE d2.id = vd.id),
           NULL::float, NULL::int
      FROM visible_shelf_docs vd JOIN lexical l ON l.doc_id = vd.id
     WHERE NOT EXISTS (SELECT 1 FROM semantic s2 WHERE s2.doc_id = vd.id)
  )
  SELECT c.chunk_id, c.doc_id, vd.title, c.content, l.lexical_rank, c.semantic_rank, c.distance,
         (coalesce(1.0 / (60 + l.lexical_rank), 0.0)
          + coalesce(1.0 / (60 + c.semantic_rank), 0.0)
          + (coalesce(vd.authority, 0) * 0.002))::double precision AS score
    FROM candidates c
    JOIN visible_shelf_docs vd ON vd.id = c.doc_id
    LEFT JOIN lexical l ON l.doc_id = c.doc_id
   WHERE l.lexical_rank IS NOT NULL OR c.semantic_rank IS NOT NULL
   ORDER BY score DESC
   LIMIT p_match_count;
END $function$;

CREATE OR REPLACE FUNCTION public.playbook_next_fire_at(p_cadence text, p_run_at_hour integer, p_weekly_day integer, p_monthly_day integer, p_from timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_candidate timestamptz;
begin
  if p_cadence = 'daily' then
    v_candidate := date_trunc('day', p_from at time zone 'utc') at time zone 'utc'
                   + make_interval(hours => p_run_at_hour);
    if v_candidate <= p_from then v_candidate := v_candidate + interval '1 day'; end if;
  elsif p_cadence = 'weekly' then
    v_candidate := date_trunc('day', p_from at time zone 'utc') at time zone 'utc'
                   + make_interval(hours => p_run_at_hour);
    while extract(dow from v_candidate at time zone 'utc')::int <> coalesce(p_weekly_day, 1)
          or v_candidate <= p_from loop
      v_candidate := v_candidate + interval '1 day';
    end loop;
  elsif p_cadence = 'monthly' then
    v_candidate := date_trunc('month', p_from at time zone 'utc') at time zone 'utc'
                   + make_interval(days => coalesce(p_monthly_day, 1) - 1, hours => p_run_at_hour);
    if v_candidate <= p_from then
      v_candidate := date_trunc('month', (p_from at time zone 'utc') + interval '1 month') at time zone 'utc'
                     + make_interval(days => coalesce(p_monthly_day, 1) - 1, hours => p_run_at_hour);
    end if;
  else
    raise exception 'unknown cadence %', p_cadence;
  end if;
  return v_candidate;
end;
$function$;

CREATE OR REPLACE FUNCTION public.playbook_schedules_compute_next()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.next_fire_at := playbook_next_fire_at(new.cadence, new.run_at_hour, new.weekly_day, new.monthly_day,
                        coalesce(new.last_fired_at, now()));
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.poll_de_work_sources_targets(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tenant_id uuid, connector_id uuid, connector_provider text, connector_display_name text, category text, subject_kind text, subject_id uuid, subject_name text, last_seen_external_ref text, last_seen_timestamp timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.tenant_id, c.id, c.provider, c.display_name, c.category, g.subject_kind, g.subject_id,
    coalesce(sub.name, 'DE'), w.last_seen_external_ref, w.last_seen_timestamp
  from connectors c
  join data_access_grants g on g.tenant_id = c.tenant_id
   and ((g.resource_kind = 'connector' and g.resource_id = c.id) or (g.resource_kind = 'category' and g.resource_category = c.category))
   and access_permission_level(g.permission) >= access_permission_level('search')
  left join digital_employees sub on sub.id = g.subject_id
  left join digital_employees de on de.id = g.subject_id and g.subject_kind = 'de'
  left join inbox_watch_state w on w.tenant_id = c.tenant_id and w.connector_id = c.id
  where c.status <> 'disconnected'
    and (p_tenant_id is null or c.tenant_id = p_tenant_id)
    and (g.subject_kind <> 'de'
         or (de.lifecycle_status in ('assigned', 'active', 'improving') and de.status = 'active' and de_is_available(de.availability)))
    and not (
      g.subject_kind = 'de'
      and exists (
        select 1 from workforce_team_members me
        join workforce_teams t on t.id = me.team_id and t.status = 'active'
        join workforce_team_members peer on peer.team_id = me.team_id and peer.fallback_rank < me.fallback_rank
        join digital_employees pde on pde.id = peer.de_id
        where me.de_id = g.subject_id and t.tenant_id = c.tenant_id
          and pde.lifecycle_status in ('assigned', 'active', 'improving') and pde.status = 'active' and de_is_available(pde.availability)
          and exists (select 1 from data_access_grants pg where pg.tenant_id = c.tenant_id and pg.subject_kind = 'de' and pg.subject_id = pde.id
              and ((pg.resource_kind = 'connector' and pg.resource_id = c.id) or (pg.resource_kind = 'category' and pg.resource_category = c.category))
              and access_permission_level(pg.permission) >= access_permission_level('search'))
      )
    )
    and not (
      g.subject_kind = 'specialist'
      and exists (
        select 1 from data_access_grants g2 join digital_employees de2 on de2.id = g2.subject_id
        where g2.tenant_id = c.tenant_id and g2.subject_kind = 'de'
          and de2.lifecycle_status in ('assigned', 'active', 'improving') and de2.status = 'active' and de_is_available(de2.availability)
          and ((g2.resource_kind = 'connector' and g2.resource_id = c.id) or (g2.resource_kind = 'category' and g2.resource_category = c.category))
          and access_permission_level(g2.permission) >= access_permission_level('search')
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.poll_support_inbox_targets(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tenant_id uuid, connector_id uuid, connector_provider text, connector_display_name text, subject_kind text, subject_id uuid, subject_name text, last_seen_external_ref text, last_seen_timestamp timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select c.tenant_id, c.id, c.provider, c.display_name, g.subject_kind, g.subject_id,
    coalesce(de.name, 'DE'), w.last_seen_external_ref, w.last_seen_timestamp
  from connectors c
  join data_access_grants g on g.tenant_id = c.tenant_id
   and ((g.resource_kind = 'connector' and g.resource_id = c.id) or (g.resource_kind = 'category' and g.resource_category = c.category))
   and access_permission_level(g.permission) >= access_permission_level('search')
  left join digital_employees de on de.id = g.subject_id
  left join inbox_watch_state w on w.tenant_id = c.tenant_id and w.connector_id = c.id
  where c.category = 'helpdesk' and c.status <> 'disconnected'
    and (p_tenant_id is null or c.tenant_id = p_tenant_id)
    and is_feature_enabled_internal(c.tenant_id, 'proactive_triage');
$function$;

CREATE OR REPLACE FUNCTION public.preview_space_access(p_space_id uuid)
 RETURNS TABLE(user_id uuid, full_name text, role text, level integer, level_name text, reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT pr.user_id,
         coalesce(pr.full_name, 'Unnamed teammate'),
         pr.role,
         coalesce(l.level, 0),
         CASE coalesce(l.level, 0)
           WHEN 6 THEN 'Full access' WHEN 5 THEN 'Knowledge manager' WHEN 4 THEN 'Publisher'
           WHEN 3 THEN 'Editor'      WHEN 2 THEN 'Contributor'       WHEN 1 THEN 'Viewer'
           ELSE 'No access' END,
         coalesce(l.reason, 'nothing grants them access')
    FROM profiles pr
    LEFT JOIN LATERAL public.knowledge_space_level_for(pr.user_id, p_space_id) l ON true
   WHERE pr.tenant_id = auth_tenant_id()
     AND coalesce(pr.is_active, true)
     AND pr.layer IS DISTINCT FROM 'platform'
   ORDER BY coalesce(l.level, 0) DESC, pr.full_name;
$function$;

CREATE OR REPLACE FUNCTION public.preview_watcher_spec(p_kind text, p_config jsonb, p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c   jsonb := coalesce(p_config, '{}'::jsonb);
  src text  := coalesce(p_config->>'source', 'customer_accounts');
  s   watch_source_catalog;
  v_field text; v_op text; v_vt text; v_cast text; v_datef text;
  v_where text; v_sql text; v_cnt int; v_maxh int;
BEGIN
  SELECT * INTO s FROM watch_source_catalog
   WHERE source_key = src AND active AND NOT legacy_bespoke;
  IF s.source_key IS NULL THEN RETURN -1; END IF;

  IF p_kind = 'state_condition' THEN
    v_field := c->>'field'; v_op := c->>'op';
    SELECT value_type INTO v_vt FROM watch_source_fields
      WHERE source_key = src AND role = 'state' AND column_name = v_field
        AND v_op = ANY (allowed_ops);
    IF v_vt IS NULL THEN RETURN -1; END IF;
    v_cast := CASE WHEN v_vt = 'numeric' THEN '::numeric' ELSE '' END;
    v_where := format('%I = $1', s.tenant_column) || build_base_predicates(s.base_predicates)
               || format(' AND %I %s $2%s', v_field, sql_op(v_op), v_cast);
    v_sql := format('SELECT count(*) FROM %I t WHERE %s', s.table_name, v_where);
    EXECUTE v_sql INTO v_cnt USING p_tenant_id, (c->>'value');
    RETURN v_cnt;

  ELSIF p_kind = 'date_horizon' THEN
    v_datef := coalesce(c->>'date_field',
                 (SELECT column_name FROM watch_source_fields
                   WHERE source_key = src AND role = 'date' ORDER BY column_name LIMIT 1));
    IF v_datef IS NULL OR NOT EXISTS (
         SELECT 1 FROM watch_source_fields
          WHERE source_key = src AND role = 'date' AND column_name = v_datef) THEN
      RETURN -1;
    END IF;
    SELECT max(h) INTO v_maxh FROM (
      SELECT (jsonb_array_elements_text(coalesce(c->'horizons_days', s.default_horizons)))::int AS h) hs;
    IF v_maxh IS NULL THEN v_maxh := 90; END IF;
    v_where := format('%I = $1', s.tenant_column) || build_base_predicates(s.base_predicates)
               || format(' AND %I IS NOT NULL AND %I >= current_date AND %I <= current_date + $2::int',
                         v_datef, v_datef, v_datef);
    v_sql := format('SELECT count(*) FROM %I t WHERE %s', s.table_name, v_where);
    EXECUTE v_sql INTO v_cnt USING p_tenant_id, v_maxh;
    RETURN v_cnt;

  ELSE
    RETURN -1;  -- metric_threshold / schedule: not a per-entity fan-out
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.probe_chunk_neighbors(p_tenant_id uuid, p_chunk_id uuid, p_doc_id uuid, p_k integer DEFAULT 5)
 RETURNS TABLE(neighbor_chunk_id uuid, neighbor_doc_id uuid, neighbor_content text, distance real)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_emb vector;
BEGIN
  -- Only the drain worker (service role / dispatch) may probe — it trusts p_tenant_id.
  IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'probe_chunk_neighbors: service role only'; END IF;
  SELECT embedding INTO v_emb FROM knowledge_doc_chunks WHERE id = p_chunk_id AND tenant_id = p_tenant_id;
  IF v_emb IS NULL THEN RETURN; END IF;
  -- Keep walking the HNSW index until k tenant/doc-matched rows are found (pgvector
  -- >= 0.8) so a small tenant's neighbours aren't dropped by the post-filter.
  SET LOCAL hnsw.iterative_scan = 'relaxed_order';
  RETURN QUERY
  SELECT c.id, c.doc_id, c.content, (c.embedding <=> v_emb)::real AS distance
  FROM knowledge_doc_chunks c
  JOIN knowledge_docs d ON d.id = c.doc_id AND d.is_current
  WHERE c.tenant_id = p_tenant_id
    AND c.id <> p_chunk_id
    AND c.doc_id <> p_doc_id            -- ignore intra-doc chunk overlap
    AND c.embedding IS NOT NULL
  ORDER BY c.embedding <=> v_emb
  LIMIT greatest(1, least(p_k, 20));
END $function$;

CREATE OR REPLACE FUNCTION public.promote_gap_cluster(p_cluster_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cluster        record;
  v_rep_inquiry    text;
  v_excerpts       text := '';
  v_member         record;
  v_avg_confidence numeric;
  v_feedback_id    uuid;
  v_revision_id    uuid;
  v_task_id        uuid;
  v_proposed_title text;
  v_proposed_body  text;
  v_excerpt_count  integer := 0;
begin
  select * into v_cluster from knowledge_gap_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'open' then
    return jsonb_build_object('ok', false, 'error', 'not_open');
  end if;

  select inquiry into v_rep_inquiry from evidence_runs where id = v_cluster.representative_run_id;

  for v_member in
    select er.inquiry
    from knowledge_gap_cluster_members m
    join evidence_runs er on er.id = m.evidence_run_id
    where m.cluster_id = p_cluster_id and er.id <> v_cluster.representative_run_id
    order by m.added_at asc
    limit 3
  loop
    v_excerpt_count := v_excerpt_count + 1;
    v_excerpts := v_excerpts || format('%s. "%s"%s', v_excerpt_count, left(v_member.inquiry, 200), E'\n');
  end loop;

  select round(avg(erd.confidence)) into v_avg_confidence
  from knowledge_gap_cluster_members m
  join evidence_run_decisions erd on erd.evidence_run_id = m.evidence_run_id
  where m.cluster_id = p_cluster_id;

  insert into evidence_feedback (tenant_id, evidence_run_id, reviewer_user_id, verdict, notes)
  values (
    v_cluster.tenant_id, v_cluster.representative_run_id, null, 'needs_improvement',
    format('Auto-detected: %s similar questions went unanswered in the current window.', v_cluster.member_count)
  )
  returning id into v_feedback_id;

  v_proposed_title := 'Recurring gap: ' || left(v_rep_inquiry, 80);
  v_proposed_body :=
    '## Detected pattern' || E'\n'
    || format('%s customers asked something like this within the same window, and none of them got a good answer (average confidence: %s%%).', v_cluster.member_count, coalesce(v_avg_confidence, 0)) || E'\n\n'
    || '## Representative question' || E'\n' || coalesce(v_rep_inquiry, '') || E'\n\n'
    || case when v_excerpts <> '' then '## Other questions in this pattern' || E'\n' || v_excerpts || E'\n' else '' end
    || '## No existing knowledge adequately covered this' || E'\n'
    || 'This is a detected pattern, not a drafted answer — write or link the content that actually resolves it.';

  insert into knowledge_revision_requests (
    tenant_id, source_doc_id, evidence_run_id, feedback_id,
    proposed_title, proposed_body_md, status, created_by
  ) values (
    v_cluster.tenant_id, null, v_cluster.representative_run_id, v_feedback_id,
    v_proposed_title, v_proposed_body, 'pending_approval', null
  ) returning id into v_revision_id;

  insert into human_tasks (
    tenant_id, type, title, detail, source, related_table, related_id, status
  ) values (
    v_cluster.tenant_id, 'knowledge_revision',
    'Review detected knowledge gap: ' || v_proposed_title,
    format('%s similar low-confidence questions were automatically detected as a recurring pattern.', v_cluster.member_count),
    'system', 'knowledge_revision_requests', v_revision_id, 'pending'
  ) returning id into v_task_id;

  update knowledge_gap_clusters
  set status = 'revision_requested', revision_request_id = v_revision_id,
      pre_fix_avg_confidence = v_avg_confidence, updated_at = now()
  where id = p_cluster_id;

  perform append_audit_event_internal(
    v_cluster.tenant_id, 'DreamTeam', 'system',
    format('Automatic knowledge-gap detection flagged a recurring pattern (%s similar questions) — "%s"', v_cluster.member_count, v_proposed_title),
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_gap_detected', 'cluster_id', p_cluster_id,
      'revision_request_id', v_revision_id, 'task_id', v_task_id, 'member_count', v_cluster.member_count)
  );

  return jsonb_build_object('ok', true, 'revision_request_id', v_revision_id, 'task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.propose_account_writeback(p_de_id uuid, p_objective_id uuid, p_account_id uuid, p_op text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_de_tenant uuid; v_acct_name text; v_de_name text;
  v_destructive boolean; v_label text; v_composed jsonb; v_summary text;
  v_status text; v_req uuid; v_task uuid; v_decision jsonb;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_op NOT IN ('log_activity','set_next_step','update_status') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_op');
  END IF;

  SELECT tenant_id, coalesce(persona_name, name) INTO v_de_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_de_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  v_tenant := v_de_tenant;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  SELECT name INTO v_acct_name FROM customer_accounts WHERE id = p_account_id AND tenant_id = v_tenant;
  IF v_acct_name IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'account_not_in_tenant'); END IF;

  -- ── SERVER-COMPOSE the frozen write + destructive flag (the whitelist). ──
  IF p_op = 'log_activity' THEN
    IF coalesce(p_params->>'summary','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'summary_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('summary', left(p_params->>'summary', 2000), 'activity_kind', coalesce(nullif(left(p_params->>'activity_kind',40),''),'note'));
    v_label := 'Log an activity'; v_summary := 'Log activity on ' || v_acct_name || ': ' || left(p_params->>'summary', 120);

  ELSIF p_op = 'set_next_step' THEN
    IF coalesce(p_params->>'next_step','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'next_step_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('next_step', left(p_params->>'next_step', 500), 'next_step_date', nullif(p_params->>'next_step_date',''));
    v_label := 'Set the next step'; v_summary := 'Set next step on ' || v_acct_name || ': ' || left(p_params->>'next_step', 120);

  ELSIF p_op = 'update_status' THEN
    -- CLOSED ENUM — the anti-hallucination guarantee. A DE can only move the
    -- account to a real status, never invent one.
    IF NOT (p_params->>'to_status' IN ('active','at_risk','churned')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_status', 'detail', 'to_status must be one of: active, at_risk, churned');
    END IF;
    v_destructive := true;
    v_composed := jsonb_build_object('to_status', p_params->>'to_status');
    v_label := 'Change account status'; v_summary := 'Change ' || v_acct_name || ' status to "' || (p_params->>'to_status') || '"';
  END IF;

  -- ── THE GATE — destructive-always-gates → guardrail → trust (proven). ──
  SELECT public.decide_action_execution(v_tenant, v_label, 'crm', v_destructive, p_de_id) INTO v_decision;

  INSERT INTO account_writeback_requests (tenant_id, de_id, account_id, objective_id, op, composed, request_summary, status, created_by)
  VALUES (v_tenant, p_de_id, p_account_id, p_objective_id, p_op, v_composed, v_summary, 'pending_approval', auth.uid())
  RETURNING id INTO v_req;

  IF (v_decision->>'decision') = 'auto_executed' THEN
    PERFORM public.apply_account_writeback_internal(v_req);
    UPDATE account_writeback_requests SET status = 'auto_applied', decided_at = now() WHERE id = v_req AND status = 'applied';
    BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
      'Write-back APPLIED — ' || v_summary, 'connector_action',
      jsonb_build_object('kind','account_writeback','op',p_op,'request_id',v_req,'account_id',p_account_id,'objective_id',p_objective_id,'auto',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'gated', false, 'applied', true, 'request_id', v_req);
  END IF;

  -- Gated — freeze it and route for human approval (decideHumanTask resolves).
  INSERT INTO human_tasks (tenant_id, type, title, detail, source, related_table, related_id, account_id, status)
  VALUES (v_tenant, 'action_approval', 'Approve write-back — ' || v_label || ' (' || v_acct_name || ')',
          (v_decision->>'reasoning') || ' Preview: ' || v_summary, 'de',
          'account_writeback_requests', v_req, p_account_id, 'pending')
  RETURNING id INTO v_task;
  UPDATE account_writeback_requests SET task_id = v_task WHERE id = v_req;

  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
    'Write-back GATED — ' || v_summary || ': ' || (v_decision->>'reasoning'), 'approval',
    jsonb_build_object('kind','account_writeback_gated','op',p_op,'request_id',v_req,'task_id',v_task,'decision',v_decision->>'decision'));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'gated', true, 'task_id', v_task, 'request_id', v_req, 'reasoning', v_decision->>'reasoning');
END; $function$;

CREATE OR REPLACE FUNCTION public.propose_browser_task(p_tenant_id uuid, p_de_id uuid, p_goal text, p_allowed_domains text[], p_max_steps integer DEFAULT 15, p_engine text DEFAULT 'browser_dom'::text, p_credential_policy text DEFAULT 'none'::text, p_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_task uuid; v_ht uuid; v_name text;
BEGIN
  IF NOT (public.auth_tenant_id() = p_tenant_id
          AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin','tenant_manager'])) THEN
    RAISE EXCEPTION 'not permitted — tenant admin required';
  END IF;
  IF NOT public.is_feature_enabled_internal(p_tenant_id, 'computer_use') THEN
    RAISE EXCEPTION 'Browser Operator is not enabled for this workspace (default OFF)';
  END IF;
  IF coalesce(array_length(p_allowed_domains,1),0) < 1 THEN RAISE EXCEPTION 'at least one allowed site is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = p_tenant_id) THEN
    RAISE EXCEPTION 'de not in tenant';
  END IF;

  INSERT INTO computer_use_tasks (tenant_id, de_id, goal, allowed_domains, max_steps, engine, credential_policy, title)
  VALUES (p_tenant_id, p_de_id, p_goal, p_allowed_domains, greatest(1, least(50, coalesce(p_max_steps,15))),
          CASE WHEN p_engine IN ('browser_dom','browser_vision','desktop') THEN p_engine ELSE 'browser_dom' END,
          CASE WHEN p_credential_policy IN ('none','vault_injected','human_login') THEN p_credential_policy ELSE 'none' END,
          nullif(btrim(coalesce(p_title,'')),''))
  RETURNING id INTO v_task;

  SELECT coalesce(persona_name, name, 'DE') INTO v_name FROM digital_employees WHERE id = p_de_id;
  INSERT INTO human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  VALUES (p_tenant_id, 'approval_gate', 'human',
    format('Browser task for %s', v_name),
    format(E'Approve %s to operate a browser for this task. Nothing runs without approval + a connected browser runtime, and every step is audited.\n\nGoal: %s\nAllowed sites: %s\nStep budget: %s\nCredentials: %s',
           v_name, p_goal, array_to_string(p_allowed_domains, ', '), greatest(1, least(50, coalesce(p_max_steps,15))), coalesce(p_credential_policy,'none')),
    'computer_use_tasks', v_task)
  RETURNING id INTO v_ht;
  UPDATE computer_use_tasks SET human_task_id = v_ht, updated_at = now() WHERE id = v_task;
  RETURN v_task;
END; $function$;

CREATE OR REPLACE FUNCTION public.propose_computer_use_task(p_tenant_id uuid, p_de_id uuid, p_goal text, p_allowed_domains text[], p_max_steps integer DEFAULT 15, p_constraints jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_task uuid; v_ht uuid; v_name text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'propose_computer_use_task is service-role only';
  end if;
  if not public.is_feature_enabled_internal(p_tenant_id, 'computer_use') then
    raise exception 'computer_use is not enabled for this workspace (default OFF)';
  end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = p_tenant_id) then
    raise exception 'de not in tenant';
  end if;

  insert into computer_use_tasks (tenant_id, de_id, goal, allowed_domains, max_steps, constraints)
  values (p_tenant_id, p_de_id, p_goal, p_allowed_domains,
          greatest(1, least(50, coalesce(p_max_steps, 15))), coalesce(p_constraints, '{}'::jsonb))
  returning id into v_task;

  select coalesce(persona_name, name, 'DE') into v_name from digital_employees where id = p_de_id;
  insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  values (p_tenant_id, 'approval_gate', 'de',
    format('Computer-use request from %s', v_name),
    format(E'%s requests permission to operate a browser for this task. NOTHING runs without your approval, and no execution runtime is installed yet — approving only queues it for when one is.\n\nGoal: %s\n\nAllowed sites: %s\nStep budget: %s\n\nThe worker contract forbids credential entry and navigation outside the allowed sites, and records a screenshot audit of every step.',
           v_name, p_goal, array_to_string(p_allowed_domains, ', '), greatest(1, least(50, coalesce(p_max_steps, 15)))),
    'computer_use_tasks', v_task)
  returning id into v_ht;

  update computer_use_tasks set human_task_id = v_ht, updated_at = now() where id = v_task;
  return v_task;
end;
$function$;

CREATE OR REPLACE FUNCTION public.propose_continuity_writeback(p_de_id uuid, p_objective_id uuid, p_op text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_de_name text; c continuity_cases; v_case_name text;
  v_destructive boolean; v_label text; v_composed jsonb; v_summary text;
  v_req uuid; v_task uuid; v_decision jsonb;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_op NOT IN ('log_activity','set_next_step','advance_stage') THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_op'); END IF;

  SELECT tenant_id, coalesce(persona_name, name) INTO v_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member'); END IF;

  SELECT * INTO c FROM continuity_cases WHERE objective_id = p_objective_id AND tenant_id = v_tenant;
  IF c.objective_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_a_continuity_case'); END IF;
  SELECT coalesce(o.title, 'case') INTO v_case_name FROM de_objectives o WHERE o.id = p_objective_id;

  IF p_op = 'log_activity' THEN
    IF coalesce(p_params->>'summary','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'summary_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('summary', left(p_params->>'summary', 2000), 'activity_kind', coalesce(nullif(left(p_params->>'activity_kind',40),''),'note'));
    v_label := 'Log a continuity activity'; v_summary := 'Log activity on ' || v_case_name || ': ' || left(p_params->>'summary', 120);

  ELSIF p_op = 'set_next_step' THEN
    IF coalesce(p_params->>'next_step','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'next_step_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('next_step', left(p_params->>'next_step', 500), 'next_step_date', nullif(p_params->>'next_step_date',''));
    v_label := 'Set the next step'; v_summary := 'Set next step on ' || v_case_name || ': ' || left(p_params->>'next_step', 120);

  ELSIF p_op = 'advance_stage' THEN
    -- Anti-hallucination: the target must be a REAL configured stage for this tenant.
    IF NOT EXISTS (SELECT 1 FROM continuity_stage_config s WHERE s.tenant_id = v_tenant AND s.stage_key = p_params->>'to_stage' AND s.active) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_stage', 'detail', 'to_stage must be an active configured continuity stage_key');
    END IF;
    v_destructive := true;
    v_composed := jsonb_build_object('to_stage', p_params->>'to_stage');
    v_label := 'Advance the case stage'; v_summary := 'Advance ' || v_case_name || ' to stage "' || (p_params->>'to_stage') || '"';
  END IF;

  -- ── THE GATE — same proven composition as every other desk. ──
  SELECT public.decide_action_execution(v_tenant, v_label, 'crm', v_destructive, p_de_id) INTO v_decision;

  INSERT INTO continuity_writeback_requests (tenant_id, de_id, objective_id, op, composed, request_summary, status, created_by)
  VALUES (v_tenant, p_de_id, p_objective_id, p_op, v_composed, v_summary, 'pending_approval', auth.uid())
  RETURNING id INTO v_req;

  IF (v_decision->>'decision') = 'auto_executed' THEN
    PERFORM public.apply_continuity_writeback_internal(v_req);
    UPDATE continuity_writeback_requests SET status = 'auto_applied', decided_at = now() WHERE id = v_req AND status = 'applied';
    BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de', 'Continuity write-back APPLIED — ' || v_summary, 'connector_action',
      jsonb_build_object('kind','continuity_writeback','op',p_op,'request_id',v_req,'objective_id',p_objective_id,'auto',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'gated', false, 'applied', true, 'request_id', v_req);
  END IF;

  INSERT INTO human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
  VALUES (v_tenant, 'action_approval', 'Approve continuity write-back — ' || v_label || ' (' || v_case_name || ')',
          (v_decision->>'reasoning') || ' Preview: ' || v_summary, 'de', 'continuity_writeback_requests', v_req, 'pending')
  RETURNING id INTO v_task;
  UPDATE continuity_writeback_requests SET task_id = v_task WHERE id = v_req;

  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de', 'Continuity write-back GATED — ' || v_summary || ': ' || (v_decision->>'reasoning'), 'approval',
    jsonb_build_object('kind','continuity_writeback_gated','op',p_op,'request_id',v_req,'task_id',v_task,'decision',v_decision->>'decision'));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'gated', true, 'task_id', v_task, 'request_id', v_req, 'reasoning', v_decision->>'reasoning');
END; $function$;

CREATE OR REPLACE FUNCTION public.propose_invoice_writeback(p_de_id uuid, p_objective_id uuid, p_invoice_id uuid, p_op text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_de_name text; v_inv text; v_destructive boolean; v_label text; v_composed jsonb; v_summary text;
  v_req uuid; v_task uuid; v_decision jsonb; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_op NOT IN ('log_activity','set_next_step','update_status') THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_op'); END IF;
  SELECT tenant_id, coalesce(persona_name, name) INTO v_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member'); END IF;
  SELECT invoice_number INTO v_inv FROM invoices WHERE id = p_invoice_id AND tenant_id = v_tenant;
  IF v_inv IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invoice_not_in_tenant'); END IF;

  IF p_op = 'log_activity' THEN
    IF coalesce(p_params->>'summary','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'summary_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('summary', left(p_params->>'summary', 2000), 'activity_kind', coalesce(nullif(left(p_params->>'activity_kind',40),''),'collection_note'));
    v_label := 'Log a collection activity'; v_summary := 'Log activity on invoice ' || v_inv || ': ' || left(p_params->>'summary', 120);
  ELSIF p_op = 'set_next_step' THEN
    IF coalesce(p_params->>'next_step','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'next_step_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('next_step', left(p_params->>'next_step', 500), 'next_step_date', nullif(p_params->>'next_step_date',''));
    v_label := 'Set the next step'; v_summary := 'Set next step on invoice ' || v_inv || ': ' || left(p_params->>'next_step', 120);
  ELSIF p_op = 'update_status' THEN
    -- Anti-hallucination + money floor: closed enum, and ANY status change on an
    -- invoice is destructive → always human-gated (never auto-executes).
    IF NOT (p_params->>'to_status' IN ('open','paid','partial','overdue','void')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_status', 'detail', 'to_status must be one of: open, paid, partial, overdue, void');
    END IF;
    v_destructive := true;
    v_composed := jsonb_build_object('to_status', p_params->>'to_status');
    v_label := 'Change invoice status'; v_summary := 'Move invoice ' || v_inv || ' to status "' || (p_params->>'to_status') || '"';
  END IF;

  SELECT public.decide_action_execution(v_tenant, v_label, 'billing', v_destructive, p_de_id) INTO v_decision;

  INSERT INTO invoice_writeback_requests (tenant_id, de_id, invoice_id, objective_id, op, composed, request_summary, status, created_by)
  VALUES (v_tenant, p_de_id, p_invoice_id, p_objective_id, p_op, v_composed, v_summary, 'pending_approval', auth.uid())
  RETURNING id INTO v_req;

  IF (v_decision->>'decision') = 'auto_executed' THEN
    PERFORM public.apply_invoice_writeback_internal(v_req);
    UPDATE invoice_writeback_requests SET status = 'auto_applied', decided_at = now() WHERE id = v_req AND status = 'applied';
    RETURN jsonb_build_object('ok', true, 'gated', false, 'applied', true, 'request_id', v_req);
  END IF;

  INSERT INTO human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
  VALUES (v_tenant, 'action_approval', 'Approve invoice write-back — ' || v_label || ' (' || v_inv || ')',
          (v_decision->>'reasoning') || ' Preview: ' || v_summary, 'de', 'invoice_writeback_requests', v_req, 'pending')
  RETURNING id INTO v_task;
  UPDATE invoice_writeback_requests SET task_id = v_task WHERE id = v_req;
  RETURN jsonb_build_object('ok', true, 'gated', true, 'task_id', v_task, 'request_id', v_req, 'reasoning', v_decision->>'reasoning');
END; $function$;

CREATE OR REPLACE FUNCTION public.propose_learned_behavior(p_cluster_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cluster        record;
  v_de_name        text;
  v_rep_inquiry    text;
  v_existing_rule  record;
  v_avg_confidence numeric;
  v_proposed       jsonb;
  v_title          text;
  v_detail         text;
  v_task_id        uuid;
begin
  select * into v_cluster from de_learned_behavior_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'open' then
    return jsonb_build_object('ok', false, 'error', 'not_open');
  end if;

  select name into v_de_name from digital_employees where id = v_cluster.de_id;
  select inquiry into v_rep_inquiry from evidence_runs where id = v_cluster.representative_run_id;

  select round(avg(erd.confidence)) into v_avg_confidence
  from de_learned_behavior_cluster_members m
  join evidence_run_decisions erd on erd.evidence_run_id = m.evidence_run_id
  where m.cluster_id = p_cluster_id;

  if v_cluster.verdict_type = 'correction' then
    v_proposed := jsonb_build_object(
      'action', 'insert_guardrail_rule',
      'rule_type', 'blocked_phrase',
      'suggested_pattern', left(regexp_replace(lower(coalesce(v_rep_inquiry, '')), '[^a-z0-9 ]', '', 'g'), 80),
      'severity', 'warning',
      'rationale', format('%s similar inquiries from %s were reviewed and corrected by a human within the current window (average confidence %s%%).',
        v_cluster.member_count, coalesce(v_de_name, 'this DE'), coalesce(v_avg_confidence, 0))
    );
    v_title := format('Learned behavior: %s keeps getting corrected on a recurring question', coalesce(v_de_name, 'a DE'));
    v_detail := format('%s similar questions were routed for review and a human corrected the answer each time — a candidate for a new guardrail rule.', v_cluster.member_count);
  else
    select * into v_existing_rule from guardrail_rules where id = v_cluster.guardrail_rule_id;
    v_proposed := jsonb_build_object(
      'action', 'loosen_guardrail_rule',
      'guardrail_rule_id', v_cluster.guardrail_rule_id,
      'current_rule_label', v_existing_rule.rule,
      'current_pattern', v_existing_rule.pattern,
      'rationale', format('%s similar inquiries from %s matched the guardrail "%s" and a human approved the answer every time within the current window (average confidence %s%%) — this rule may be too strict for this pattern.',
        v_cluster.member_count, coalesce(v_de_name, 'this DE'), coalesce(v_existing_rule.rule, '(rule)'), coalesce(v_avg_confidence, 0))
    );
    v_title := format('Learned behavior: %s is being routed for review needlessly', coalesce(v_de_name, 'a DE'));
    v_detail := format('%s similar questions were routed for review by the guardrail "%s," and a human approved the answer every time — a candidate for loosening that rule.', v_cluster.member_count, coalesce(v_existing_rule.rule, '(rule)'));
  end if;

  insert into human_tasks (
    tenant_id, type, title, detail, source, related_table, related_id, status
  ) values (
    v_cluster.tenant_id, 'training_feedback', v_title, v_detail, 'system',
    'de_learned_behavior_clusters', p_cluster_id, 'pending'
  ) returning id into v_task_id;

  update de_learned_behavior_clusters
  set status = 'proposed', proposed_rule = v_proposed, human_task_id = v_task_id,
      pre_fix_avg_confidence = v_avg_confidence, updated_at = now()
  where id = p_cluster_id;

  perform append_audit_event_internal(
    v_cluster.tenant_id, 'DreamTeam', 'system',
    format('Automatic learned-behavior detection flagged a recurring pattern (%s similar decisions, %s) for %s — "%s"',
      v_cluster.member_count, v_cluster.verdict_type, coalesce(v_de_name, 'a DE'), v_title),
    'config_change',
    jsonb_build_object('kind', 'learned_behavior_detected', 'cluster_id', p_cluster_id, 'task_id', v_task_id, 'verdict_type', v_cluster.verdict_type)
  );

  return jsonb_build_object('ok', true, 'task_id', v_task_id, 'proposed_rule', v_proposed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.propose_opportunity_writeback(p_de_id uuid, p_objective_id uuid, p_opportunity_id uuid, p_op text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_de_name text; v_opp_name text;
  v_destructive boolean; v_label text; v_composed jsonb; v_summary text;
  v_req uuid; v_task uuid; v_decision jsonb;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_op NOT IN ('log_activity','set_next_step','update_stage') THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_op'); END IF;

  SELECT tenant_id, coalesce(persona_name, name) INTO v_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member'); END IF;

  SELECT coalesce(name, company_name, 'opportunity') INTO v_opp_name FROM opportunities WHERE id = p_opportunity_id AND tenant_id = v_tenant;
  IF v_opp_name IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'opportunity_not_in_tenant'); END IF;

  IF p_op = 'log_activity' THEN
    IF coalesce(p_params->>'summary','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'summary_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('summary', left(p_params->>'summary', 2000), 'activity_kind', coalesce(nullif(left(p_params->>'activity_kind',40),''),'note'));
    v_label := 'Log an activity'; v_summary := 'Log activity on ' || v_opp_name || ': ' || left(p_params->>'summary', 120);
  ELSIF p_op = 'set_next_step' THEN
    IF coalesce(p_params->>'next_step','') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'next_step_required'); END IF;
    v_destructive := false;
    v_composed := jsonb_build_object('next_step', left(p_params->>'next_step', 500), 'next_step_date', nullif(p_params->>'next_step_date',''));
    v_label := 'Set the next step'; v_summary := 'Set next step on ' || v_opp_name || ': ' || left(p_params->>'next_step', 120);
  ELSIF p_op = 'update_stage' THEN
    -- Anti-hallucination: the target stage must be a REAL configured pipeline stage.
    IF NOT EXISTS (SELECT 1 FROM tenant_pipeline_stages s WHERE s.tenant_id = v_tenant AND s.stage_key = p_params->>'to_stage') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_stage', 'detail', 'to_stage must be an existing pipeline stage_key');
    END IF;
    v_destructive := true;
    v_composed := jsonb_build_object('to_stage', p_params->>'to_stage');
    v_label := 'Change opportunity stage'; v_summary := 'Move ' || v_opp_name || ' to stage "' || (p_params->>'to_stage') || '"';
  END IF;

  SELECT public.decide_action_execution(v_tenant, v_label, 'crm', v_destructive, p_de_id) INTO v_decision;

  INSERT INTO opportunity_writeback_requests (tenant_id, de_id, opportunity_id, objective_id, op, composed, request_summary, status, created_by)
  VALUES (v_tenant, p_de_id, p_opportunity_id, p_objective_id, p_op, v_composed, v_summary, 'pending_approval', auth.uid())
  RETURNING id INTO v_req;

  IF (v_decision->>'decision') = 'auto_executed' THEN
    PERFORM public.apply_opportunity_writeback_internal(v_req);
    UPDATE opportunity_writeback_requests SET status = 'auto_applied', decided_at = now() WHERE id = v_req AND status = 'applied';
    BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de', 'Pipeline write-back APPLIED — ' || v_summary, 'connector_action',
      jsonb_build_object('kind','opportunity_writeback','op',p_op,'request_id',v_req,'opportunity_id',p_opportunity_id,'auto',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'gated', false, 'applied', true, 'request_id', v_req);
  END IF;

  INSERT INTO human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
  VALUES (v_tenant, 'action_approval', 'Approve pipeline write-back — ' || v_label || ' (' || v_opp_name || ')',
          (v_decision->>'reasoning') || ' Preview: ' || v_summary, 'de', 'opportunity_writeback_requests', v_req, 'pending')
  RETURNING id INTO v_task;
  UPDATE opportunity_writeback_requests SET task_id = v_task WHERE id = v_req;

  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de', 'Pipeline write-back GATED — ' || v_summary || ': ' || (v_decision->>'reasoning'), 'approval',
    jsonb_build_object('kind','opportunity_writeback_gated','op',p_op,'request_id',v_req,'task_id',v_task,'decision',v_decision->>'decision'));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'gated', true, 'task_id', v_task, 'request_id', v_req, 'reasoning', v_decision->>'reasoning');
END; $function$;

CREATE OR REPLACE FUNCTION public.propose_system_writeback(p_de_id uuid, p_system_key text, p_entity_ref text, p_op text, p_params jsonb DEFAULT '{}'::jsonb, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s de_connected_systems; v_tenant uuid; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member'); END IF;
  SELECT * INTO s FROM de_connected_systems WHERE de_id = p_de_id AND system_key = p_system_key AND active;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_not_configured'); END IF;
  IF NOT s.can_write THEN RETURN jsonb_build_object('ok', false, 'error', 'write_not_allowed'); END IF;

  IF s.write_registry = 'account' THEN
    RETURN public.propose_account_writeback(p_de_id, p_objective_id, p_entity_ref::uuid, p_op, p_params);
  ELSIF s.write_registry = 'opportunity' THEN
    RETURN public.propose_opportunity_writeback(p_de_id, p_objective_id, p_entity_ref::uuid, p_op, p_params);
  ELSIF s.write_registry = 'invoice' THEN
    RETURN public.propose_invoice_writeback(p_de_id, p_objective_id, p_entity_ref::uuid, p_op, p_params);
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'write_registry_not_supported', 'write_registry', s.write_registry);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.provision_onboarding_architect(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_demo constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_enabled boolean;
  v_conn uuid;
  v_de uuid;
  v_charter text := $charter$You are the DreamTeam Onboarding Architect — a master of the DreamTeam AI platform whose job is to set customers up quickly and correctly.

WHAT DREAMTEAM IS: an operating system for AI "Digital Employees" (DEs) that add a work-and-judgment layer on top of a company's existing systems — never replacing them. The building blocks you configure:
- Digital Employee (DE): an AI employee for a role (e.g. Support, Billing). It answers ONLY from its knowledge and acts ONLY through approved tools. New DEs start "designed"/"supervised" and must be taken through lifecycle gates by a human before they go live.
- Knowledge base: documents a DE answers from (grounded + cited; it won't invent facts).
- Playbook: a repeatable, auditable procedure a DE follows for a task.
- Specialist desk: a deep-expertise reference a DE can consult.
- Connector: a link to one of the customer's systems (helpdesk, CRM, etc.). Credentials are added by a human, never by you.
- Guardrail: a rule that blocks unsafe answers/actions. Trust dial: how much autonomy a DE has (starts supervised).

YOUR TOOLS (all changes are routed to a human for approval — you PROPOSE, a human APPROVES, then it is built):
- create_digital_employee — add a DE for a role.
- draft_playbook — draft a procedure for a DE to follow.
- create_specialist — add a specialist desk.
- propose_connector — propose connecting one of the customer's systems (a human authenticates it).

HOW TO ONBOARD A CUSTOMER: understand their business and what they want their AI workforce to do. Propose the SMALLEST sensible setup that meets the need — usually one or two DEs plus a playbook for their most common request. Name things in the customer's own language. Do not over-build (don't create employees or playbooks they didn't ask for). Anything you submit is a proposal a human reviews.

SAFETY: never handle credentials. If a request is unclear or risky, ask a human instead of guessing. When you have submitted the setup you were asked for, call mark_goal_complete — do not wait for approval outcomes.$charter$;
begin
  if p_tenant_id is null or p_tenant_id = v_demo then
    return jsonb_build_object('ok', false, 'skipped', 'demo_or_null');
  end if;
  if not exists (select 1 from tenants where id = p_tenant_id) then
    return jsonb_build_object('ok', false, 'skipped', 'no_tenant');
  end if;

  select coalesce((select default_enabled from feature_registry where key = 'onboarding_architect'), true)
    into v_enabled;
  if not v_enabled then return jsonb_build_object('ok', true, 'skipped', 'flag_off'); end if;

  -- Self-connector (idempotent)
  select id into v_conn from connectors
    where tenant_id = p_tenant_id and provider = 'dreamteam' limit 1;
  if v_conn is null then
    insert into connectors (tenant_id, provider, base_url, category, status, display_name)
    values (p_tenant_id, 'dreamteam', 'https://dreamteam.internal', 'platform_admin', 'connected', 'DreamTeam AI (self)')
    returning id into v_conn;
  end if;

  -- The Architect DE (idempotent by name). Charter lives in purpose_statement
  -- (the agentic loop injects it) AND description (shown in the UI).
  select id into v_de from digital_employees
    where tenant_id = p_tenant_id and name = 'DreamTeam Onboarding Architect' limit 1;
  if v_de is null then
    insert into digital_employees (tenant_id, name, persona_name, category, department,
      model_id, lifecycle_status, status, trust_level, description, purpose_statement)
    values (p_tenant_id, 'DreamTeam Onboarding Architect', 'Ada', 'Customer', 'Onboarding',
      'claude-sonnet-5', 'published', 'idle', 'supervised',
      'Configures DreamTeam for you — proposes new employees, playbooks, specialists and connectors from your requirements. Every change is human-approved.',
      v_charter)
    returning id into v_de;
  else
    update digital_employees set purpose_statement = v_charter
      where id = v_de and coalesce(purpose_statement, '') = '';
  end if;

  -- write_back grant on the self-connector (idempotent)
  if not exists (
    select 1 from data_access_grants
    where tenant_id = p_tenant_id and subject_kind = 'de' and subject_id = v_de
      and resource_kind = 'connector' and resource_id = v_conn
  ) then
    insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_id, permission, note)
    values (p_tenant_id, 'de', v_de, 'connector', v_conn, 'write_back', 'onboarding architect self-management');
  end if;

  -- Ensure an agentic policy row exists so the loop is enabled.
  insert into agentic_step_policies (tenant_id, enabled)
  values (p_tenant_id, true)
  on conflict (tenant_id) do nothing;

  return jsonb_build_object('ok', true, 'connector_id', v_conn, 'de_id', v_de);
end;
$function$;

CREATE OR REPLACE FUNCTION public.provision_starter_de_internal(p_tenant_id uuid, p_feature_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_catalog_id  text;
  v_name        text;
  v_persona     text;
  v_description text;
  v_category    text;
  v_department  text;
  v_source_cat  text;
  v_playbook_key  text;
  v_playbook_name text;
  v_playbook_desc text;
  v_event_key   text;
  v_steps       jsonb;
  v_de_id       uuid;
  v_playbook_id uuid;
begin
  if p_feature_key = 'account_de' then
    v_catalog_id := 'starter_account_de';
    v_name := 'Account Success DE';
    v_persona := 'Riley';
    v_description := 'Watches account health and flags at-risk accounts for a human to follow up on. Starts with read/check-in access to CRM only — no financial systems.';
    v_category := 'Customer';
    v_department := 'Account Success';
    v_source_cat := 'crm';
    v_playbook_key := 'account_at_risk_checkin';
    v_playbook_name := 'Account At-Risk Check-In';
    v_playbook_desc := 'Fires when an account''s computed health flips to at-risk. Notices the signal and hands a follow-up checklist to a human — does not act on its own.';
    v_event_key := 'account_at_risk';
    v_steps := '[
      {"key":"check_account","label":"Check account","params":{}},
      {"key":"checklist","label":"Human follow-up","params":{"items":["Review why this account went at-risk","Reach out to the account contact","Decide whether a retention offer or escalation is needed"]}},
      {"key":"complete","label":"Done","params":{}}
    ]'::jsonb;
  elsif p_feature_key = 'finance_de' then
    v_catalog_id := 'starter_finance_de';
    v_name := 'Finance DE';
    v_persona := 'Morgan';
    v_description := 'Watches overdue invoices and flags them for a human to follow up on. Starts with access to financial records only — no CRM/relationship data.';
    v_category := 'Internal';
    v_department := 'Finance';
    v_source_cat := 'erp_financials';
    v_playbook_key := 'invoice_overdue_followup';
    v_playbook_name := 'Overdue Invoice Follow-Up';
    v_playbook_desc := 'Fires when an invoice goes overdue. Notices the signal and hands a follow-up checklist to a human — does not send anything on its own.';
    v_event_key := 'invoice_overdue';
    v_steps := '[
      {"key":"check_account","label":"Check account","params":{}},
      {"key":"checklist","label":"Human follow-up","params":{"items":["Review the overdue invoice","Reach out about payment","Decide whether a reminder or escalation is appropriate"]}},
      {"key":"complete","label":"Done","params":{}}
    ]'::jsonb;
  else
    return null; -- not a DE-provisioning feature — nothing to do
  end if;

  select id into v_de_id from digital_employees where tenant_id = p_tenant_id and catalog_id = v_catalog_id;

  if v_de_id is null then
    select id into v_de_id from digital_employees
    where tenant_id = p_tenant_id and name = v_name and catalog_id is null
    order by created_at asc
    limit 1;
  end if;

  if v_de_id is not null then
    update digital_employees
    set status = 'active', lifecycle_status = 'published', catalog_id = coalesce(catalog_id, v_catalog_id)
    where id = v_de_id;
  else
    insert into digital_employees (
      tenant_id, catalog_id, name, persona_name, description, category, department,
      status, lifecycle_status, trust_level, confidence_threshold, required_approval, tags, owner_id
    ) values (
      p_tenant_id, v_catalog_id, v_name, v_persona, v_description, v_category, v_department,
      'active', 'published', 'supervised', 75, false, array['auto_provisioned'], null
    )
    returning id into v_de_id;
  end if;

  insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_category, permission, granted_by, note)
  values (p_tenant_id, 'de', v_de_id, 'category', v_source_cat, 'write_back', null,
    'Starter DE default access — provisioned automatically when this feature was turned on')
  on conflict (tenant_id, subject_kind, subject_id, resource_kind, coalesce(resource_id::text, resource_category))
  do update set permission = excluded.permission;

  insert into playbook_definitions (tenant_id, key, name, description, version, status, trigger_type, de_id, steps)
  values (p_tenant_id, v_playbook_key, v_playbook_name, v_playbook_desc, 1, 'published', 'event', v_de_id, v_steps)
  on conflict (tenant_id, key) do update set status = 'published', steps = excluded.steps, de_id = excluded.de_id
  returning id into v_playbook_id;

  if v_playbook_id is null then
    select id into v_playbook_id from playbook_definitions where tenant_id = p_tenant_id and key = v_playbook_key;
  end if;

  insert into playbook_versions (definition_id, version, steps, published_by)
  select v_playbook_id, 1, v_steps, null
  where not exists (select 1 from playbook_versions where definition_id = v_playbook_id);

  insert into de_playbook_charter (tenant_id, de_id, playbook_id, priority, active)
  values (p_tenant_id, v_de_id, v_playbook_id, 50, true)
  on conflict (de_id, playbook_id) do update set active = true, priority = 50;

  if not exists (
    select 1 from playbook_event_rules
    where tenant_id = p_tenant_id and definition_id = v_playbook_id and event_key = v_event_key
  ) then
    insert into playbook_event_rules (tenant_id, definition_id, event_key, params, cooldown_hours, active)
    values (p_tenant_id, v_playbook_id, v_event_key, '{}'::jsonb, 24, true);
  else
    update playbook_event_rules set active = true
    where tenant_id = p_tenant_id and definition_id = v_playbook_id and event_key = v_event_key;
  end if;

  -- Migration 108 widened this unique index to (tenant_id,
  -- action_category, coalesce(source_category,''), coalesce(de_id::
  -- text,'')) — this insert already provides a real de_id, so the
  -- fixed ON CONFLICT target correctly matches a PER-DE row here
  -- (not the tenant-wide default row), which is what this function
  -- has always meant to seed.
  insert into trust_policies (tenant_id, de_id, action_category, source_category, baseline_level, current_level, criteria)
  values (
    p_tenant_id, v_de_id, 'action_execute', v_source_cat, 0, 0,
    '{"window_days":30,"min_eval_pass_rate":0.9,"min_eval_samples":0,"min_human_approval_rate":0.9,"min_human_samples":3,"max_guardrail_blocks":0}'::jsonb
  )
  on conflict (tenant_id, action_category, coalesce(source_category, ''), coalesce(de_id::text, '')) do nothing;

  -- Deliberately kept tenant-wide (no de_id), matching this insert's
  -- original, unchanged intent — only the ON CONFLICT target needed
  -- fixing here, not the row's scope. (Unlike trust_policies just
  -- above, which was ALREADY per-DE in the original code.)
  insert into de_autonomy (tenant_id, action_type, source_category, enabled, max_amount_cents, min_confidence)
  values (p_tenant_id, 'action_execute', v_source_cat, false, null, null)
  on conflict (tenant_id, action_type, coalesce(source_category, ''), coalesce(de_id::text, '')) do nothing;

  perform append_audit_event_internal(
    p_tenant_id, 'DreamTeam', 'system',
    format('%s ("%s") provisioned — starter %s access, %s playbook charter, action_execute trust started at level 0 (gated).',
      v_name, v_persona, v_source_cat, v_playbook_name),
    'config_change',
    jsonb_build_object('kind', 'feature_de_provisioned', 'feature_key', p_feature_key, 'de_id', v_de_id, 'playbook_id', v_playbook_id)
  );

  return v_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.provision_tenant_baseline_internal(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_tpl_id uuid; v_seeded_guardrails int := 0; v_seeded_template boolean := false; v_seeded_specialist boolean := false;
begin
  if p_tenant_id is null or p_tenant_id = v_demo_tenant_id then return jsonb_build_object('ok', false, 'error', 'refusing to provision null or the demo tenant'); end if;
  if not exists (select 1 from tenants where id = p_tenant_id) then return jsonb_build_object('ok', false, 'error', 'tenant not found'); end if;

  perform reconcile_tenant_feature(p_tenant_id, fr.key, true) from feature_registry fr where fr.default_enabled = true;

  insert into guardrail_rules (tenant_id, rule, rule_type, pattern, severity, applies_to, active)
  select p_tenant_id, r.rule, r.rule_type, r.pattern, r.severity, 'all', true
  from (values
    ('Explicit escalation demand', 'frustration_signal', 'speak to a manager|speak with a manager|this is unacceptable|totally unacceptable', 'warning'),
    ('Repeated-contact frustration', 'frustration_signal', 'third time i|already told you|i''ve asked this before|keep asking', 'warning'),
    ('Churn/cancellation threat', 'frustration_signal', 'cancel(l)?ing my (subscription|account|plan)|switching to a competitor|find another (provider|vendor)', 'warning'),
    ('Strong negative sentiment', 'frustration_signal', 'worst support|completely useless|waste of (my )?time|ridiculous that', 'warning'),
    ('No unilateral refund promises', 'blocked_phrase', 'refund', 'blocking'),
    ('No legal-threat language in outputs — route to a human', 'blocked_phrase', 'legal action|lawsuit|sue you|attorney|court|legally liable|garnish|seize your assets', 'blocking')
  ) as r(rule, rule_type, pattern, severity)
  where not exists (select 1 from guardrail_rules g where g.tenant_id = p_tenant_id and g.rule = r.rule);
  get diagnostics v_seeded_guardrails = row_count;

  if not exists (select 1 from guardrail_rules g where g.tenant_id = p_tenant_id and g.rule_type = 'require_approval_over_cents') then
    insert into guardrail_rules (tenant_id, rule, rule_type, threshold, severity, applies_to, active)
    values (p_tenant_id, 'Actions over $10,000 always require human approval', 'require_approval_over_cents', 1000000, 'blocking', 'all', true);
    v_seeded_guardrails := v_seeded_guardrails + 1;
  end if;

  if not exists (select 1 from onboarding_templates t where t.tenant_id = p_tenant_id and t.name = 'SaaS onboarding — starter') then
    insert into onboarding_templates (tenant_id, name, description, items)
    values (p_tenant_id, 'SaaS onboarding — starter',
      '10-step implementation checklist: kickoff → data → config → validation → go-live. Sign-off gates on settings, leave rules, UAT, and go-live.',
      '[{"key":"kickoff_call","label":"Kickoff call held","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"Intro call: goals, timeline, points of contact."},{"key":"data_export_received","label":"Data export received from customer","phase":"data","owner_type":"either","requires_signoff":false,"description":"Customer sends their employee/location export (CSV or spreadsheet)."},{"key":"employees_imported","label":"Employees imported","phase":"data","owner_type":"de","requires_signoff":false,"description":"Employee records loaded and normalized in the platform."},{"key":"locations_configured","label":"Locations configured","phase":"config","owner_type":"de","requires_signoff":false,"description":"Sites, time zones, and operating hours set up."},{"key":"settings_review","label":"Account settings reviewed","phase":"config","owner_type":"human","requires_signoff":true,"description":"Human sign-off on core account configuration."},{"key":"leave_rules_configured","label":"Leave rules configured","phase":"config","owner_type":"either","requires_signoff":true,"description":"Accrual, carryover, and approval chains — needs human sign-off."},{"key":"test_scenario_run","label":"Test scenario run","phase":"validation","owner_type":"de","requires_signoff":false,"description":"End-to-end test with sample data."},{"key":"uat_approved","label":"UAT approved by customer","phase":"validation","owner_type":"human","requires_signoff":true,"description":"Customer confirms acceptance testing passed."},{"key":"training_session","label":"Training session delivered","phase":"golive","owner_type":"human","requires_signoff":false,"description":"Admin + end-user training completed."},{"key":"go_live","label":"Go-live","phase":"golive","owner_type":"human","requires_signoff":true,"description":"Production cutover — final human sign-off."}]'::jsonb)
    returning id into v_tpl_id;
    insert into onboarding_template_versions (template_id, tenant_id, version, name, description, items, published_by)
    select v_tpl_id, p_tenant_id, 1, t.name, t.description, t.items, null from onboarding_templates t where t.id = v_tpl_id;
    update onboarding_templates set version = 1, status = 'published' where id = v_tpl_id;
    v_seeded_template := true;
  end if;

  -- Starter Technical Specialist — now a Digital Employee (is_specialist).
  if not exists (select 1 from digital_employees d where d.tenant_id = p_tenant_id and d.is_specialist = true and d.specialist_key = 'technical') then
    insert into digital_employees (tenant_id, name, persona_name, category, is_specialist, specialist_key, description, charter, lifecycle_status, status)
    values (p_tenant_id, 'Technical Specialist', 'Technical Specialist', 'Internal', true, 'technical',
      'Read-only consult desk for deep technical questions.',
      jsonb_build_object('mission', 'Answer only from configured sources; cite everything; escalate when unsure.'), 'active', 'active');
    v_seeded_specialist := true;
  end if;

  if v_seeded_guardrails > 0 or v_seeded_template or v_seeded_specialist then
    perform append_audit_event_internal(p_tenant_id, 'DreamTeam', 'system',
      format('Workspace baseline provisioned — %s starter guardrail(s)%s%s. Connectors are the remaining setup step (they need your own system credentials).',
        v_seeded_guardrails, case when v_seeded_template then ', starter onboarding template' else '' end, case when v_seeded_specialist then ', Technical Specialist' else '' end),
      'config_change', jsonb_build_object('kind', 'tenant_baseline_provisioned', 'guardrails_seeded', v_seeded_guardrails, 'template_seeded', v_seeded_template, 'specialist_seeded', v_seeded_specialist));
  end if;
  return jsonb_build_object('ok', true, 'guardrails_seeded', v_seeded_guardrails, 'template_seeded', v_seeded_template, 'specialist_seeded', v_seeded_specialist);
end; $function$;

CREATE OR REPLACE FUNCTION public.provision_workforce_assistant_internal(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing uuid;
  v_id uuid;
BEGIN
  IF p_tenant_id IS NULL THEN RETURN NULL; END IF;

  SELECT id INTO v_existing FROM digital_employees
   WHERE tenant_id = p_tenant_id AND is_workforce_assistant = true LIMIT 1;
  IF v_existing IS NOT NULL THEN
    -- Idempotent, and self-healing: an employee provisioned before this
    -- migration gets its missing permission the next time this runs.
    INSERT INTO de_autonomy (tenant_id, action_type, source_category, de_id, enabled, min_confidence, max_amount_cents)
    VALUES (p_tenant_id, 'answer_dock', NULL, v_existing, true, 70, NULL)
    ON CONFLICT (tenant_id, action_type, coalesce(source_category, ''), coalesce(de_id::text, ''))
    DO NOTHING;
    RETURN v_existing;
  END IF;

  INSERT INTO digital_employees (
    tenant_id, name, icon, category, task_type, status, lifecycle_status,
    trust_level, model_provider, model_id, escalation_model_id,
    confidence_threshold, escalation_threshold, external_reply_mode,
    availability, is_workforce_assistant, is_product_expert, charter
  ) VALUES (
    p_tenant_id, 'Workforce Assistant', 'D', 'Customer', 'chat', 'active',
    'designed',
    'supervised',
    'anthropic', 'claude-haiku-4-5-20251001', 'claude-sonnet-5',
    75, 60,
    'draft',
    jsonb_build_object('mode', 'always_on'),
    true, true,
    jsonb_build_object(
      'name', 'Workforce Assistant',
      'persona', 'You are a trusted advisor helping this organization hire, improve, and manage their digital workforce. You are an expert on the DreamTeamAI platform.',
      'responsibilities', jsonb_build_array(
        'Help hire new DEs by understanding role requirements',
        'Suggest improvements to underperforming DEs based on metrics',
        'Monitor team performance and provide insights',
        'Help retire DEs and transition knowledge',
        'Train new tenants on DreamTeamAI features'),
      'guardrails', jsonb_build_array(
        'Never auto-approve DE changes without explicit user consent',
        'Always show evidence for recommendations',
        'Prioritize user success over automation',
        'Escalate ambiguous decisions to the tenant admin'))
  )
  RETURNING id INTO v_id;

  -- THE PART MIG 332 MISSED. Without this the employee exists and is mute:
  -- resolve_de_autonomy returns enabled=false, de-answer sets the confidence
  -- floor to 101, and every single message escalates to a human.
  -- answer_dock only — this is an internal advisor, never a public widget.
  INSERT INTO de_autonomy (tenant_id, action_type, source_category, de_id, enabled, min_confidence, max_amount_cents)
  VALUES (p_tenant_id, 'answer_dock', NULL, v_id, true, 70, NULL)
  ON CONFLICT (tenant_id, action_type, coalesce(source_category, ''), coalesce(de_id::text, ''))
  DO NOTHING;

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.prune_otel_spans()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  delete from otel_spans where created_at < now() - interval '30 days';
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_adapter_template(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not exists (
    select 1 from adapter_templates t
    join profiles p on p.tenant_id = t.tenant_id
    where t.id = p_id and t.scope = 'tenant' and p.user_id = auth.uid() and coalesce(p.is_active, true) = true
  ) then
    raise exception 'not a member of this template''s workspace';
  end if;
  update adapter_templates set status = 'published' where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_onboarding_template(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tpl     onboarding_templates;
  v_errors  text[];
  v_version integer;
  v_vid     uuid;
begin
  select * into v_tpl from onboarding_templates where id = p_template_id;
  if not found then
    return jsonb_build_object('error', 'template_not_found');
  end if;
  if not (v_tpl.tenant_id = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin'])) then
    raise exception 'only workspace owners/admins can publish an onboarding template';
  end if;

  v_errors := validate_onboarding_items(v_tpl.items);
  if array_length(v_errors, 1) is not null then
    return jsonb_build_object('errors', to_jsonb(v_errors));
  end if;

  v_version := v_tpl.version + 1;
  insert into onboarding_template_versions (template_id, tenant_id, version, name, description, items, published_by)
  values (v_tpl.id, v_tpl.tenant_id, v_version, v_tpl.name, v_tpl.description, v_tpl.items, auth.uid())
  returning id into v_vid;

  update onboarding_templates
    set version = v_version, status = 'published'
    where id = v_tpl.id;

  perform append_audit_event_internal(
    v_tpl.tenant_id, 'You', 'human',
    format('Onboarding template published — %s v%s (%s items)', v_tpl.name, v_version, jsonb_array_length(v_tpl.items)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_template_publish', 'template_id', v_tpl.id,
                       'version_id', v_vid, 'version', v_version,
                       'item_count', jsonb_array_length(v_tpl.items)));

  return jsonb_build_object('version_id', v_vid, 'version', v_version);
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_platform_shelf_doc(p_doc_id uuid, p_title text, p_content text, p_source_change_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old platform_knowledge_docs; v_new uuid; v_mig text;
BEGIN
  -- 342: the shelf is global. A tenant user editing it would rewrite the
  -- product guide that every OTHER tenant is answered from.
  IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'only platform administrators can publish to the shared shelf';
  END IF;
  SELECT * INTO v_old FROM platform_knowledge_docs WHERE id = p_doc_id AND is_current;
  IF v_old.id IS NULL THEN RAISE EXCEPTION 'shelf document not found or not current'; END IF;
  IF p_content IS NULL OR length(btrim(p_content)) = 0 THEN
    RAISE EXCEPTION 'refusing to publish an empty article';
  END IF;

  SELECT source_ref INTO v_mig FROM platform_kb_changes WHERE id = p_source_change_id;

  UPDATE platform_knowledge_docs SET is_current = false, updated_at = now() WHERE id = p_doc_id;

  INSERT INTO platform_knowledge_docs (
    title, content, topic, tags, authority, is_current, version, previous_version_id,
    source_doc_path, source_migration, last_verified_at, published_at)
  VALUES (
    coalesce(nullif(btrim(p_title), ''), v_old.title), p_content, v_old.topic, v_old.tags,
    v_old.authority, true, v_old.version + 1, v_old.id,
    v_old.source_doc_path, coalesce(v_mig, v_old.source_migration), now(), now())
  RETURNING id INTO v_new;

  -- Carry the chunks forward, flagged for re-embedding. Retrieval keeps working
  -- on the old vectors until the drain catches up rather than going blind.
  INSERT INTO platform_knowledge_chunks (doc_id, chunk_index, content, embedding, reembed_pending)
  SELECT v_new, c.chunk_index, c.content, c.embedding, true
    FROM platform_knowledge_chunks c WHERE c.doc_id = p_doc_id;

  IF p_source_change_id IS NOT NULL THEN
    UPDATE platform_kb_changes
       SET status = 'reviewed', reviewed_at = now(), reviewed_by = auth.uid()
     WHERE id = p_source_change_id;
  END IF;

  RETURN v_new;
END $function$;

CREATE OR REPLACE FUNCTION public.purge_connector_secret(p_connector_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null then
    raise exception 'connector not found';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not (v_tenant = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin']))
  then
    raise exception 'only workspace owners/admins can remove a connector''s credential';
  end if;

  delete from connector_secrets where connector_id = p_connector_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.raise_ops_alert(p_kind text, p_message text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Dedup: one open alert per kind per hour keeps a 5-minute cron from
  -- flooding the table while the condition persists.
  IF EXISTS (
    SELECT 1 FROM ops_alerts
    WHERE kind = p_kind AND resolved_at IS NULL AND created_at > now() - interval '1 hour'
  ) THEN RETURN; END IF;
  INSERT INTO ops_alerts (kind, message, detail) VALUES (p_kind, p_message, coalesce(p_detail, '{}'::jsonb));
END$function$;

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_bucket_key text, p_window_seconds integer, p_max_hits integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window TIMESTAMPTZ := to_timestamp(floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds);
  v_hits INTEGER;
BEGIN
  INSERT INTO rate_limit_counters (bucket_key, window_start, hits)
  VALUES (p_bucket_key, v_window, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = rate_limit_counters.hits + 1
  RETURNING hits INTO v_hits;

  -- Opportunistic GC: ~1% of calls sweep buckets older than an hour.
  IF random() < 0.01 THEN
    DELETE FROM rate_limit_counters WHERE window_start < now() - interval '1 hour';
  END IF;

  RETURN jsonb_build_object('allowed', v_hits <= p_max_hits, 'hits', v_hits);
END$function$;

CREATE OR REPLACE FUNCTION public.read_de_system(p_de_id uuid, p_system_key text, p_entity_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s de_connected_systems; v_tenant uuid; v_sql text; v_row jsonb;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  SELECT * INTO s FROM de_connected_systems WHERE de_id = p_de_id AND system_key = p_system_key AND active;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_not_configured'); END IF;
  IF NOT s.can_read THEN RETURN jsonb_build_object('ok', false, 'error', 'read_not_allowed'); END IF;
  IF s.binding_kind <> 'internal_table' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'connector_read_pending_creds', 'system_key', p_system_key);
  END IF;
  IF NOT (s.source_table = ANY (ARRAY['customer_accounts','opportunities','account_activities','opportunity_activities','invoices','bills','payments','journal_entries'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unsupported_source_table');
  END IF;

  v_sql := format(
    'SELECT to_jsonb(t) - (SELECT coalesce(array_agg(k),ARRAY[]::text[]) FROM (SELECT key AS k FROM jsonb_each(to_jsonb(t)) WHERE key <> ALL (SELECT jsonb_array_elements_text($3))) x) FROM %I t WHERE t.%I = $1::uuid AND t.tenant_id = $2',
    s.source_table, s.id_column);
  EXECUTE v_sql INTO v_row USING p_entity_ref, v_tenant, s.read_fields;
  IF v_row IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'record_not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'system_key', p_system_key, 'record', v_row);
END; $function$;

CREATE OR REPLACE FUNCTION public.read_demo_admin_password()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'vault', 'public'
AS $function$
  select decrypted_secret from vault.decrypted_secrets where name = 'demo_admin_password' limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.reap_stale_computer_use_runtimes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer;
BEGIN
  UPDATE computer_use_runtimes SET active = false
    WHERE active AND (last_seen IS NULL OR last_seen < now() - interval '5 minutes');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END; $function$;

CREATE OR REPLACE FUNCTION public.reap_stale_ingestion_items()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int;
BEGIN
  UPDATE knowledge_ingestion_items
     SET status = CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'queued' END,
         last_error = 'the worker stopped responding part-way through this item',
         error_kind = 'retryable', next_attempt_at = now(), updated_at = now()
   WHERE status = 'running' AND updated_at < now() - interval '30 minutes';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;

CREATE OR REPLACE FUNCTION public.recompute_tenant_ancestry(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current uuid := p_tenant_id;
  v_depth   integer := 0;
  v_parent  uuid;
  v_max_depth constant integer := 10;
begin
  delete from tenant_ancestry where tenant_id = p_tenant_id;

  loop
    insert into tenant_ancestry (tenant_id, ancestor_id, depth)
    values (p_tenant_id, v_current, v_depth)
    on conflict (tenant_id, ancestor_id) do nothing;

    select parent_tenant_id into v_parent from tenants where id = v_current;
    exit when v_parent is null;

    v_depth := v_depth + 1;
    if v_depth > v_max_depth then
      raise exception 'tenant hierarchy exceeds max depth (%) while walking ancestry for % -- a cycle likely slipped past the self-parent guard',
        v_max_depth, p_tenant_id;
    end if;

    v_current := v_parent;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_tenant_feature(p_tenant_id uuid, p_feature_key text, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_feature_key in ('account_de', 'finance_de') then
    if p_enabled then
      perform provision_starter_de_internal(p_tenant_id, p_feature_key);
    else
      perform deprovision_starter_de_internal(p_tenant_id, p_feature_key);
    end if;
  elsif p_feature_key = 'knowledge_gap_detection' then
    if p_enabled then
      insert into knowledge_gap_policies (tenant_id, category, enabled)
      select p_tenant_id, null, true
      where not exists (select 1 from knowledge_gap_policies where tenant_id = p_tenant_id);
    end if;
  elsif p_feature_key = 'agentic_playbook_steps' then
    if p_enabled then
      -- Tenant-default budget envelope (column defaults: 15 iterations,
      -- 100k tokens, $5, 3 no-progress strikes) — soft-disable via
      -- policy.enabled or the flag gate, never destroy tenant config.
      insert into agentic_step_policies (tenant_id)
      select p_tenant_id
      where not exists (select 1 from agentic_step_policies where tenant_id = p_tenant_id);
    end if;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_action_execution(p_tenant_id uuid, p_action_definition_id uuid, p_connector_id uuid, p_subject_kind text, p_subject_id uuid, p_mode text, p_params jsonb, p_decision text, p_destructive boolean, p_idempotent boolean, p_dedupe_key text, p_request_summary text, p_receipt text, p_result jsonb, p_task_title text, p_task_detail text, p_create_task boolean DEFAULT true, p_origin_kind text DEFAULT NULL::text, p_origin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid;
  v_row_id  uuid;
  v_category text;
  v_label    text;
  v_ref      text;
begin
  if p_create_task and p_decision in ('human_gated_destructive', 'human_gated_trust') then
    insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
    values (
      p_tenant_id, 'action_approval',
      coalesce(p_task_title, 'Action awaiting approval'),
      coalesce(p_task_detail, ''), 'de', 'action_executions', null, 'pending'
    )
    returning id into v_task_id;
  end if;

  insert into action_executions (
    tenant_id, action_definition_id, connector_id, subject_kind, subject_id,
    mode, params, decision, destructive, idempotent, dedupe_key,
    request_summary, receipt, result, task_id, origin_kind, origin_id
  ) values (
    p_tenant_id, p_action_definition_id, p_connector_id, p_subject_kind, p_subject_id,
    p_mode, coalesce(p_params, '{}'::jsonb), p_decision, coalesce(p_destructive, true), coalesce(p_idempotent, false), p_dedupe_key,
    coalesce(p_request_summary, ''), p_receipt, p_result, v_task_id, p_origin_kind, p_origin_id
  )
  returning id into v_row_id;

  if v_task_id is not null then
    update human_tasks set related_id = v_row_id where id = v_task_id;
  end if;

  if p_mode = 'execute' and p_subject_id is not null then
    select category into v_category from action_definitions where id = p_action_definition_id;
    select label into v_label from action_definitions where id = p_action_definition_id;
    v_ref := coalesce(
      nullif(p_params->>'external_ref', ''),
      nullif(p_params->>'account_name', ''),
      nullif(p_params->>'account_ref', '')
    );
    if v_category is not null and v_ref is not null then
      perform record_de_experience(
        p_tenant_id, p_subject_kind, p_subject_id, v_category, v_ref,
        format('Considered action "%s" (%s)', coalesce(v_label, 'action'), coalesce(p_request_summary, '')),
        format('Decision: %s', p_decision),
        coalesce(p_receipt, case
          when p_decision in ('human_gated_destructive', 'human_gated_trust') then 'Awaiting human approval — not yet executed.'
          when p_decision = 'failed' then 'Attempted but failed — see result for detail.'
          else 'No receipt recorded.'
        end),
        null, v_row_id
      );
    end if;
  end if;

  return jsonb_build_object('id', v_row_id, 'task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_action_rollback(p_original_execution_id uuid, p_receipt text, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_orig action_executions;
  v_new  uuid;
begin
  select * into v_orig from action_executions where id = p_original_execution_id;
  if v_orig.id is null then raise exception 'original execution not found'; end if;

  insert into action_executions (
    tenant_id, action_definition_id, connector_id, subject_kind, subject_id,
    mode, params, decision, destructive, idempotent, dedupe_key,
    request_summary, receipt, result, rollback_of
  ) values (
    v_orig.tenant_id, v_orig.action_definition_id, v_orig.connector_id, v_orig.subject_kind, v_orig.subject_id,
    'execute', v_orig.params, 'executed_after_approval', v_orig.destructive, v_orig.idempotent, null,
    'Rollback of execution ' || p_original_execution_id::text, p_receipt, p_result, p_original_execution_id
  ) returning id into v_new;

  update action_executions
     set rolled_back_at = now(), rollback_receipt = p_receipt
   where id = p_original_execution_id;
  return v_new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_after_metrics(p_amendment_id uuid, p_after_metrics jsonb, p_replay_score_before numeric DEFAULT NULL::numeric, p_replay_score_after numeric DEFAULT NULL::numeric, p_confidence_delta numeric DEFAULT NULL::numeric, p_escalation_rate_delta numeric DEFAULT NULL::numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE amendment_metrics
  SET after_metrics = p_after_metrics,
      replay_score_before = p_replay_score_before,
      replay_score_after = p_replay_score_after,
      confidence_delta = p_confidence_delta,
      escalation_rate_delta = p_escalation_rate_delta,
      adopted_at = now(),
      updated_at = now()
  WHERE amendment_id = p_amendment_id AND tenant_id = v_tenant_id;
  RETURN json_build_object('ok', true, 'adopted_at', now()::text);
END$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_before_metrics(p_amendment_id uuid, p_entity_kind text, p_entity_id uuid, p_before_metrics jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_metric_id UUID;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  INSERT INTO amendment_metrics (tenant_id, amendment_id, entity_kind, entity_id, before_metrics)
  VALUES (v_tenant_id, p_amendment_id, p_entity_kind, p_entity_id, p_before_metrics)
  ON CONFLICT DO NOTHING
  RETURNING metric_id INTO v_metric_id;
  RETURN json_build_object('ok', true, 'metric_id', v_metric_id);
END$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_fitness(p_tenant_id uuid, p_amendment_id uuid, p_entity_kind text, p_entity_id uuid, p_before_metrics jsonb, p_after_metrics jsonb, p_score_before numeric, p_score_after numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO amendment_metrics (
    tenant_id, amendment_id, entity_kind, entity_id,
    before_metrics, after_metrics, replay_score_before, replay_score_after, adopted_at
  )
  VALUES (
    p_tenant_id, p_amendment_id, p_entity_kind, p_entity_id,
    coalesce(p_before_metrics, '{}'::jsonb), p_after_metrics, p_score_before, p_score_after, now()
  )
  ON CONFLICT (amendment_id) DO UPDATE SET
    before_metrics      = coalesce(excluded.before_metrics, amendment_metrics.before_metrics),
    after_metrics       = excluded.after_metrics,
    replay_score_before = excluded.replay_score_before,
    replay_score_after  = excluded.replay_score_after,
    adopted_at          = now(),
    updated_at          = now();
  RETURN jsonb_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_billable_outcome(p_tenant_id uuid, p_de_id uuid, p_conversation_id uuid, p_kind text, p_source text DEFAULT 'chat'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_price integer := 0; v_billable boolean := false; v_id uuid;
  v_status text := 'free'; v_settle_after timestamptz := null;
  v_deferred boolean := (select value = 'true' from platform_config where key = 'metering_deferred_settlement_enabled');
  v_window numeric := coalesce((select value from platform_config where key = 'metering_settle_window_hours')::numeric, 72);
begin
  if p_kind not in ('resolution', 'escalation') then raise exception 'kind must be resolution|escalation'; end if;
  if p_conversation_id is null then return jsonb_build_object('recorded', false, 'reason', 'no_conversation'); end if;
  v_deferred := coalesce(v_deferred, false);

  if p_kind = 'resolution' then
    select coalesce((select price_per_resolution_cents from tenant_outcome_pricing where tenant_id = p_tenant_id), 99)
      into v_price;
    if exists (select 1 from billable_outcomes where conversation_id = p_conversation_id and kind = 'escalation') then
      v_billable := false; v_price := 0; v_status := 'unbilled';           -- escalated first: never bills
    elsif v_deferred then
      v_billable := false; v_status := 'pending'; v_settle_after := now() + make_interval(hours => v_window);
    else
      v_billable := true;  v_status := 'confirmed';                        -- LEGACY bill-on-answer (flag OFF)
    end if;
  else
    -- Escalation after a resolution: reverse it. MUST catch PENDING too, so the
    -- settle cron can never later confirm a conversation the human took over.
    update billable_outcomes set billable = false, unit_price_cents = 0, status = 'unbilled', settled_at = now()
     where conversation_id = p_conversation_id and kind = 'resolution' and status in ('pending','confirmed');
    v_billable := false; v_status := 'free';
  end if;

  insert into billable_outcomes (tenant_id, de_id, conversation_id, kind, source, billable, unit_price_cents, status, settle_after, settled_at)
  values (p_tenant_id, p_de_id, p_conversation_id, p_kind,
          case when p_source in ('chat','widget','a2a','orchestrate') then p_source else 'chat' end,
          v_billable, v_price, v_status, v_settle_after,
          case when v_status in ('confirmed','free','unbilled') then now() else null end)
  on conflict do nothing
  returning id into v_id;

  return jsonb_build_object('recorded', v_id is not null, 'billable', v_billable, 'unit_price_cents', v_price, 'status', v_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_de_experience(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_external_ref text, p_what_happened text, p_decision_made text, p_outcome text, p_source_evidence_run_id uuid, p_source_action_execution_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_id uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_memory') then
    return null;
  end if;

  if p_subject_kind is null or p_subject_id is null or p_category is null or p_external_ref is null or p_external_ref = '' then
    return null; -- honest no-op: an experience fact needs a resolvable subject + category + external_ref
  end if;
  insert into de_experience (
    tenant_id, subject_kind, subject_id, category, external_ref,
    fact_summary, source_evidence_run_id, source_action_execution_id
  ) values (
    p_tenant_id, p_subject_kind, p_subject_id, p_category, p_external_ref,
    jsonb_build_object(
      'what_happened', p_what_happened,
      'decision_made', p_decision_made,
      'outcome', p_outcome
    ),
    p_source_evidence_run_id, p_source_action_execution_id
  )
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_de_spend(p_tenant_id uuid, p_de_id uuid, p_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(p_cents, 0) <= 0 THEN RETURN; END IF;
  INSERT INTO de_spend_ledger (tenant_id, de_id, period_kind, period_key, cents)
    VALUES (p_tenant_id, p_de_id, 'day', to_char(current_date, 'YYYY-MM-DD'), p_cents)
    ON CONFLICT (tenant_id, de_id, period_kind, period_key)
      DO UPDATE SET cents = de_spend_ledger.cents + excluded.cents, updated_at = now();
  INSERT INTO de_spend_ledger (tenant_id, de_id, period_kind, period_key, cents)
    VALUES (p_tenant_id, p_de_id, 'month', to_char(current_date, 'YYYY-MM'), p_cents)
    ON CONFLICT (tenant_id, de_id, period_kind, period_key)
      DO UPDATE SET cents = de_spend_ledger.cents + excluded.cents, updated_at = now();
END; $function$;

CREATE OR REPLACE FUNCTION public.record_de_token_usage(p_tenant_id uuid, p_de_id uuid, p_model_id text, p_input_tokens integer, p_output_tokens integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'record_de_token_usage is service-role only';
  end if;
  insert into de_token_usage (tenant_id, de_id, model_id, input_tokens, output_tokens)
  values (p_tenant_id, p_de_id, p_model_id, coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0));
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_deliverable(p_de_id uuid, p_objective_id uuid, p_title text, p_kind text, p_content text, p_format text DEFAULT 'markdown'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de_name text; v_id uuid; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id, coalesce(persona_name, name) INTO v_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  IF coalesce(p_title,'') = '' OR coalesce(p_content,'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'title_and_content_required');
  END IF;
  INSERT INTO de_deliverables (tenant_id, de_id, objective_id, title, kind, content, format)
  VALUES (v_tenant, p_de_id, p_objective_id, left(p_title,200),
          CASE WHEN p_kind IN ('report','summary','memo','analysis','review') THEN p_kind ELSE 'report' END,
          p_content, coalesce(nullif(p_format,''),'markdown'))
  RETURNING id INTO v_id;
  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
    v_de_name || ' produced a ' || p_kind || ' for review — "' || left(p_title,120) || '"', 'playbook_step',
    jsonb_build_object('kind','deliverable_produced','deliverable_id',v_id,'objective_id',p_objective_id,'title',p_title));
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('ok', true, 'deliverable_id', v_id);
END; $function$;

CREATE OR REPLACE FUNCTION public.record_improvement_replay(p_improvement_id uuid, p_replay jsonb, p_passed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update de_improvements
     set replay = p_replay,
         status = case when p_passed then 'replayed' else 'failed_replay' end,
         updated_at = now()
   where id = p_improvement_id and status in ('proposed','replayed','failed_replay');
  if not found then raise exception 'improvement not found or already in review/applied'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_inquiry_decision(p_tenant_id uuid, p_evidence_run_id uuid, p_connector_id uuid, p_external_ref text, p_source text, p_decision text, p_confidence integer, p_guardrail_rule_id uuid, p_trust_level integer, p_reasoning text, p_inquiry_title text, p_source_category text DEFAULT NULL::text, p_frustration_score integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid;
  v_row_id  uuid;
  v_run     record;
  v_subject_kind text;
  v_subject_id   uuid;
  v_ref     text;
begin
  if p_decision = 'needs_review' then
    insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
    values (
      p_tenant_id, 'inquiry_review',
      format('Review inquiry — %s', left(coalesce(p_inquiry_title, '(no subject)'), 120)),
      p_reasoning, 'de', 'evidence_runs', p_evidence_run_id, 'pending'
    )
    returning id into v_task_id;
  end if;

  insert into evidence_run_decisions (
    tenant_id, evidence_run_id, connector_id, external_ref, source, decision,
    confidence, guardrail_rule_id, trust_level, reasoning, human_task_id, source_category,
    frustration_score
  ) values (
    p_tenant_id, p_evidence_run_id, p_connector_id, p_external_ref, p_source, p_decision,
    p_confidence, p_guardrail_rule_id, p_trust_level, p_reasoning, v_task_id, p_source_category,
    p_frustration_score
  )
  on conflict (evidence_run_id) do update set
    decision = excluded.decision, confidence = excluded.confidence,
    guardrail_rule_id = excluded.guardrail_rule_id, trust_level = excluded.trust_level,
    reasoning = excluded.reasoning, human_task_id = coalesce(evidence_run_decisions.human_task_id, excluded.human_task_id),
    source_category = coalesce(excluded.source_category, evidence_run_decisions.source_category),
    frustration_score = coalesce(excluded.frustration_score, evidence_run_decisions.frustration_score)
  returning id into v_row_id;

  -- ── DE MEMORY (migration 044) — unchanged from prior definition ──
  select de_id, specialist_id, account_ref into v_run from evidence_runs where id = p_evidence_run_id;
  if v_run.de_id is not null then
    v_subject_kind := 'de'; v_subject_id := v_run.de_id;
  elsif v_run.specialist_id is not null then
    v_subject_kind := 'specialist'; v_subject_id := v_run.specialist_id;
  end if;
  v_ref := coalesce(nullif(p_external_ref, ''), nullif(v_run.account_ref, ''));

  if v_subject_id is not null and p_source_category is not null and v_ref is not null then
    perform record_de_experience(
      p_tenant_id, v_subject_kind, v_subject_id, p_source_category, v_ref,
      format('%s inquiry via %s (source: %s)', initcap(replace(p_source_category, '_', ' ')), coalesce(p_inquiry_title, '(untitled)'), p_source),
      format('Decision: %s%s', p_decision, case when p_confidence is not null then format(' (confidence %s%%)', p_confidence) else '' end),
      p_reasoning,
      p_evidence_run_id, null
    );
  end if;

  return jsonb_build_object('id', v_row_id, 'human_task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_knowledge_citations(p_tenant_id uuid, p_doc_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_tenant_id IS NULL OR p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN; END IF;

  INSERT INTO knowledge_doc_usage_daily (tenant_id, doc_id, usage_date, cited_count)
  SELECT d.tenant_id, d.id, current_date, 1
    FROM knowledge_docs d
   WHERE d.id = ANY (p_doc_ids) AND d.tenant_id = p_tenant_id
  ON CONFLICT (tenant_id, doc_id, usage_date)
  DO UPDATE SET cited_count = knowledge_doc_usage_daily.cited_count + 1;

  UPDATE knowledge_docs
     SET citation_count = coalesce(citation_count, 0) + 1, last_cited_at = now()
   WHERE id = ANY (p_doc_ids) AND tenant_id = p_tenant_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_knowledge_conflict(p_tenant_id uuid, p_chunk_a uuid, p_doc_a uuid, p_chunk_b uuid, p_doc_b uuid, p_relation text, p_distance real, p_signal jsonb DEFAULT '{}'::jsonb, p_confidence real DEFAULT NULL::real)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lo_chunk uuid; v_lo_doc uuid; v_hi_chunk uuid; v_hi_doc uuid; v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'record_knowledge_conflict: service role only'; END IF;
  IF p_relation NOT IN ('near_duplicate', 'potential_conflict') THEN RAISE EXCEPTION 'bad relation'; END IF;
  -- Canonical ordering so a pair is stored once regardless of probe direction.
  IF p_chunk_a <= p_chunk_b THEN
    v_lo_chunk := p_chunk_a; v_lo_doc := p_doc_a; v_hi_chunk := p_chunk_b; v_hi_doc := p_doc_b;
  ELSE
    v_lo_chunk := p_chunk_b; v_lo_doc := p_doc_b; v_hi_chunk := p_chunk_a; v_hi_doc := p_doc_a;
  END IF;
  INSERT INTO knowledge_conflicts (tenant_id, chunk_a_id, doc_a_id, chunk_b_id, doc_b_id,
                                   relation, cosine_distance, signal, confidence)
  VALUES (p_tenant_id, v_lo_chunk, v_lo_doc, v_hi_chunk, v_hi_doc,
          p_relation, p_distance, coalesce(p_signal, '{}'), p_confidence)
  ON CONFLICT (tenant_id, chunk_a_id, chunk_b_id, relation) DO UPDATE
    SET cosine_distance = excluded.cosine_distance, signal = excluded.signal,
        confidence = excluded.confidence, updated_at = now()
    WHERE knowledge_conflicts.status = 'open'   -- never resurrect a resolved/dismissed pair
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_kpi_reading(p_de_id uuid, p_metric_key text, p_value numeric, p_as_of date DEFAULT CURRENT_DATE, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;
  INSERT INTO de_kpi_readings (tenant_id, de_id, metric_key, value, as_of, recorded_by, note)
  VALUES (v_tenant, p_de_id, p_metric_key, p_value, coalesce(p_as_of, current_date), auth.uid(), p_note)
  RETURNING id INTO v_id;
  RETURN v_id;
END$function$;

CREATE OR REPLACE FUNCTION public.record_migration_applied(p_filename text, p_checksum text, p_applied_by text DEFAULT 'db-query.mjs'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_prev text; v_was text;
BEGIN
  IF p_filename IS NULL OR btrim(p_filename) = '' THEN RAISE EXCEPTION 'filename required'; END IF;
  IF p_checksum IS NULL OR btrim(p_checksum) = '' THEN RAISE EXCEPTION 'checksum required'; END IF;

  SELECT checksum, provenance INTO v_prev, v_was
    FROM schema_migrations WHERE filename = p_filename;

  INSERT INTO schema_migrations (filename, checksum, applied_at, applied_by, provenance)
  VALUES (p_filename, p_checksum, now(), p_applied_by, 'applied_by_runner')
  ON CONFLICT (filename) DO UPDATE
    SET checksum = excluded.checksum, applied_at = now(),
        applied_by = excluded.applied_by, provenance = 'applied_by_runner';

  RETURN jsonb_build_object(
    'ok', true,
    'filename', p_filename,
    -- Re-applying a file whose content changed is the dangerous case; say so.
    'reapplied', v_prev IS NOT NULL,
    'content_changed_since_last_apply', v_prev IS NOT NULL AND v_prev <> p_checksum,
    'previous_provenance', v_was);
END $function$;

CREATE OR REPLACE FUNCTION public.record_platform_kb_change(p_source_kind text, p_source_ref text, p_title text, p_body text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_clean text; v_query tsquery;
BEGIN
  INSERT INTO platform_kb_changes (source_kind, source_ref, title, body)
  VALUES (coalesce(p_source_kind,'migration'), p_source_ref, p_title, coalesce(p_body,''))
  ON CONFLICT (source_kind, source_ref) DO UPDATE
    SET title = excluded.title, body = excluded.body
  RETURNING id INTO v_id;

  DELETE FROM platform_kb_change_impacts WHERE change_id = v_id;

  v_clean := regexp_replace(coalesce(p_title,'') || ' ' || left(coalesce(p_body,''), 3000), '[^a-zA-Z ]', ' ', 'g');
  v_clean := trim(regexp_replace(v_clean, '\s+', ' ', 'g'));
  IF v_clean = '' THEN RETURN v_id; END IF;

  -- Distinct stemmed lexemes, stopwords already removed by to_tsvector, OR'd.
  SELECT to_tsquery('english', string_agg(quote_literal(lexeme), ' | '))
    INTO v_query
    FROM (SELECT DISTINCT lexeme FROM unnest(to_tsvector('english', v_clean))
           WHERE length(lexeme) > 3 LIMIT 120) z;
  IF v_query IS NULL THEN RETURN v_id; END IF;

  INSERT INTO platform_kb_change_impacts (change_id, doc_id, rank)
  SELECT v_id, d.id, ts_rank(d.search_tsv, v_query)
    FROM platform_knowledge_docs d
   WHERE d.is_current AND d.published_at IS NOT NULL
     AND d.search_tsv @@ v_query
   ORDER BY 3 DESC
   LIMIT 5;

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_platform_knowledge_citations(p_doc_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN; END IF;
  INSERT INTO platform_knowledge_usage_daily (doc_id, usage_date, cited_count)
  SELECT d.id, current_date, 1
    FROM platform_knowledge_docs d
   WHERE d.id = ANY(p_doc_ids)
  ON CONFLICT (doc_id, usage_date)
  DO UPDATE SET cited_count = platform_knowledge_usage_daily.cited_count + 1;
END $function$;

CREATE OR REPLACE FUNCTION public.redact_old_adjudications()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_n int;
BEGIN
  PERFORM set_config('app.allow_adjudication_redact', 'on', true);
  WITH upd AS (
    UPDATE guardrail_adjudications
       SET content_preview = NULL, question_preview = NULL, matched_text = NULL, rationale = NULL
     WHERE created_at < now() - interval '90 days'
       AND (content_preview IS NOT NULL OR question_preview IS NOT NULL
            OR matched_text IS NOT NULL OR rationale IS NOT NULL)
    RETURNING 1)
  SELECT count(*) INTO v_n FROM upd;
  DELETE FROM guardrail_adjudication_cache WHERE expires_at < now();
  RETURN v_n;
END $function$;

CREATE OR REPLACE FUNCTION public.redeem_platform_invite(p_invite_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := btrim(coalesce(p_invite_code, ''));
  v_invite platform_invites;
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if v_code = '' then
    raise exception 'an invite code is required';
  end if;

  select * into v_invite from platform_invites where invite_code = v_code for update;
  if not found then
    raise exception 'invite code not recognized';
  end if;

  if v_invite.status = 'redeemed' then
    raise exception 'this invite has already been redeemed';
  end if;
  if v_invite.status = 'revoked' then
    raise exception 'this invite has been revoked';
  end if;

  if not exists (select 1 from profiles where user_id = v_user) then
    raise exception 'no profile found for this account -- sign up normally first, confirm your email, then redeem this invite';
  end if;

  update profiles
  set layer = 'platform', role = v_invite.role, tenant_id = null, updated_at = now()
  where user_id = v_user;

  update platform_invites
  set status = 'redeemed', redeemed_at = now(), redeemed_by = v_user
  where id = v_invite.id;

  return jsonb_build_object('ok', true, 'role', v_invite.role, 'layer', 'platform');
end;
$function$;

CREATE OR REPLACE FUNCTION public.register_computer_use_runtime(p_name text, p_endpoint text, p_kind text DEFAULT 'browser'::text, p_engine text DEFAULT 'browser_dom'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'register_computer_use_runtime is service-role only'; END IF;
  -- Upsert by name so a restarting worker keeps its identity.
  SELECT id INTO v_id FROM computer_use_runtimes WHERE name = p_name LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO computer_use_runtimes (name, endpoint, kind, engine, active, last_seen)
      VALUES (p_name, p_endpoint, coalesce(p_kind,'browser'), coalesce(p_engine,'browser_dom'), true, now())
      RETURNING id INTO v_id;
  ELSE
    UPDATE computer_use_runtimes SET endpoint = p_endpoint, kind = coalesce(p_kind,'browser'),
      engine = coalesce(p_engine,'browser_dom'), active = true, last_seen = now() WHERE id = v_id;
  END IF;
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.reject_draft(p_draft_id uuid, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE draft_responses
  SET
    status = 'rejected',
    rejected_at = now(),
    rejected_by = v_user_id
  WHERE draft_id = p_draft_id
    AND tenant_id = current_setting('app.current_tenant_id')::uuid;

  RETURN json_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_entity_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update workforce_entity_amendments set status = 'rejected' where id = p_id and status <> 'applied';
  return jsonb_build_object('ok', true); end; $function$;

CREATE OR REPLACE FUNCTION public.reject_improvement(p_improvement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from de_improvements where id = p_improvement_id;
  if v_tenant is null then raise exception 'improvement not found'; end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;
  update de_improvements set status = 'rejected', updated_at = now()
   where id = p_improvement_id and status in ('review_pending','replayed');
  if not found then raise exception 'improvement not in a rejectable state'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_knowledge_revision(p_request_id uuid, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_req           record;
  v_actor_name    text;
begin
  select * into v_req from knowledge_revision_requests where id = p_request_id;
  if v_req.id is null then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;
  if v_req.status <> 'pending_approval' then
    return jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_req.status);
  end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_req.tenant_id then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select coalesce(full_name, 'A reviewer') into v_actor_name from profiles where user_id = v_user;
  v_actor_name := coalesce(v_actor_name, 'A reviewer');

  update knowledge_revision_requests
    set status = 'rejected', decided_by = v_user, decided_at = now()
    where id = p_request_id;

  perform append_audit_event(
    v_req.tenant_id, v_actor_name, case when v_user is null then 'system' else 'human' end,
    v_actor_name || ' rejected a proposed knowledge revision — "' || v_req.proposed_title || '"'
      || case when coalesce(p_reason, '') <> '' then ' (' || p_reason || ')' else '' end,
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_rejected', 'revision_request_id', p_request_id, 'reason', coalesce(p_reason, ''))
  );

  -- Additive: a rejected gap-triggered proposal reopens its cluster
  -- rather than dead-ending it — the underlying pattern may still be
  -- real even if this particular draft wasn't the right fix.
  update knowledge_gap_clusters
  set status = 'open', revision_request_id = null, updated_at = now()
  where revision_request_id = p_request_id and status = 'revision_requested';

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_learned_behavior(p_cluster_id uuid, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_cluster       record;
begin
  select * into v_cluster from de_learned_behavior_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'proposed' then
    return jsonb_build_object('ok', false, 'error', 'not_proposed');
  end if;

  select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
  if v_caller_tenant is distinct from v_cluster.tenant_id then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;
  if not v_is_active then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  if v_cluster.human_task_id is not null then
    update human_tasks set status = 'rejected', decided_by = v_user, decided_at = now() where id = v_cluster.human_task_id;
  end if;

  update de_learned_behavior_clusters
  set status = 'open', human_task_id = null, updated_at = now()
  where id = p_cluster_id;

  perform append_audit_event(
    v_cluster.tenant_id, coalesce((select full_name from profiles where user_id = v_user), 'A reviewer'), 'human',
    format('Rejected a proposed learned behavior (%s)%s', v_cluster.verdict_type,
      case when coalesce(p_reason, '') <> '' then ' (' || p_reason || ')' else '' end),
    'config_change',
    jsonb_build_object('kind', 'learned_behavior_rejected', 'cluster_id', p_cluster_id, 'reason', coalesce(p_reason, ''))
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_playbook_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update playbook_amendments set status = 'rejected' where id = p_id and status <> 'applied';
  return jsonb_build_object('ok', true);
end; $function$;

CREATE OR REPLACE FUNCTION public.reject_subtenant_request(p_request_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req tenant_provisioning_requests;
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may reject a tenant provisioning request';
  end if;

  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a rejection reason is required';
  end if;

  select * into v_req from tenant_provisioning_requests where id = p_request_id for update;
  if not found then
    raise exception 'provisioning request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request has already been decided (status=%)', v_req.status;
  end if;

  update tenant_provisioning_requests
  set status = 'rejected', reviewed_by = auth.uid(), decided_at = now(), rejection_reason = btrim(p_reason)
  where id = p_request_id;

  if v_req.proposed_parent_tenant_id is not null and exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_req.proposed_parent_tenant_id
  ) then
    perform append_audit_event(
      v_req.proposed_parent_tenant_id, 'Platform admin', 'human',
      format('Sub-tenant request "%s" rejected — %s', v_req.proposed_name, btrim(p_reason)),
      'config_change',
      jsonb_build_object('kind', 'tenant_provisioning_rejected', 'request_id', p_request_id,
        'proposed_name', v_req.proposed_name, 'reason', btrim(p_reason), 'rejected_by', auth.uid(),
        'requested_by', v_req.requested_by_user_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'rejected', true, 'reason', btrim(p_reason));
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_group_member(p_group_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_group int; v_name text; v_who text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  -- Removing is revoking, so the same ceiling applies in reverse: you cannot
  -- strip access you could not have granted.
  v_group := public.knowledge_group_max_level(p_group_id);
  IF v_group > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: "%" carries access above your level', v_name;
  END IF;

  SELECT coalesce(full_name, 'a teammate') INTO v_who FROM profiles WHERE user_id = p_user_id;
  DELETE FROM knowledge_principal_group_members WHERE group_id = p_group_id AND user_id = p_user_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Removed %s from the group "%s"', coalesce(v_who,'someone'), v_name), 'access_control',
    jsonb_build_object('group_id', p_group_id, 'user_id', p_user_id));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.remove_team_member(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot remove yourself here';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can remove a teammate';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner cannot be removed -- transfer ownership first';
  end if;

  update profiles set is_active = false, tenant_id = null where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    'Team member removed',
    'config_change',
    jsonb_build_object('kind', 'team_member_removed', 'target_user_id', p_target_user_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_tenant_ip_allowlist_entry(p_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id into v_tenant from tenant_ip_allowlist_entries where id = p_entry_id;
  if v_tenant is null then
    raise exception 'IP range not found';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = v_tenant
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can remove an IP range';
  end if;

  delete from tenant_ip_allowlist_entries where id = p_entry_id;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    'IP range removed from allowlist',
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_entry_removed', 'entry_id', p_entry_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.rename_knowledge_collection(p_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF knowledge_my_admin_level(p_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: organising knowledge requires knowledge manager';
  END IF;
  UPDATE knowledge_collections
     SET name = coalesce(nullif(btrim(p_name),''), name),
         description = nullif(btrim(coalesce(p_description,'')),''),
         updated_at = now()
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.rename_principal_group(p_group_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF public.knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'group_not_found';
  END IF;

  UPDATE knowledge_principal_groups
     SET name = coalesce(nullif(btrim(p_name), ''), name),
         description = nullif(btrim(coalesce(p_description,'')), ''),
         updated_at = now()
   WHERE id = p_group_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.render_playbook_structure(p_steps jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select string_agg(
    s.ord || '. ' || coalesce(s.elem->>'label', s.elem->>'key', 'step') ||
    case s.elem->>'key'
      when 'instruction'     then coalesce(' — ' || (s.elem->'params'->>'body_md'), '')
      when 'checklist'       then ' — checklist: ' || coalesce((select string_agg(i.value #>> '{}', '; ')
                                                                from jsonb_array_elements(s.elem->'params'->'items') i), '')
      when 'decision'        then ' — DECISION: if ' || coalesce(s.elem->'params'->>'on','(prior step)') || ' '
                                    || coalesce(s.elem->'params'->>'operator','') || ' ' || coalesce(s.elem->'params'->>'value','')
                                    || ' then ' || coalesce(jsonb_array_length(s.elem->'then_steps')::text,'0') || ' step(s), else '
                                    || coalesce(jsonb_array_length(s.elem->'else_steps')::text,'0')
      when 'human_approval'  then ' — GATE: pause here for human approval before continuing'
      when 'guardrail_check' then ' — GUARDRAIL CHECK: ' || coalesce(s.elem->'params'->>'check','')
      when 'consult_specialist' then ' — CONSULT a specialist: ' || coalesce(s.elem->'params'->>'question_template','')
      when 'check_knowledge' then ' — CHECK KNOWLEDGE for: ' || coalesce(s.elem->'params'->>'query_template','')
      when 'agentic_step'    then ' — JUDGMENT STEP (use tools to): ' || coalesce(s.elem->'params'->>'instructions', s.elem->'params'->>'goal_template','')
      when 'custom_step'     then ' — JUDGMENT STEP (use tools to): ' || coalesce(s.elem->'params'->>'instructions', s.elem->'params'->>'goal_template','')
      when 'connector_action' then ' — ACTION: ' || coalesce(
                                      s.elem->'params'->>'action_key',
                                      nullif((s.elem->'params'->>'provider') || '.' || (s.elem->'params'->>'op'), '.'),
                                      nullif((s.elem->'params'->>'category') || '.' || (s.elem->'params'->>'op'), '.'),
                                      'connector action') || ' (routed through the approval/guardrail gates)'
      when 'generate_invoice' then ' — ACTION: generate an invoice (gated for approval)'
      when 'update_record'   then ' — ACTION: update a record (gated)'
      when 'wait'            then ' — WAIT ' || coalesce(s.elem->'params'->>'duration_minutes','?') || ' minutes, then resume'
      when 'complete'        then ' — (procedure ends here)'
      else ''
    end, E'\n' order by s.ord)
  from jsonb_array_elements(p_steps) with ordinality as s(elem, ord);
$function$;

CREATE OR REPLACE FUNCTION public.request_de_task(p_from_de_id uuid, p_to_de_id uuid, p_title text, p_context text DEFAULT NULL::text, p_expected_output text DEFAULT NULL::text, p_urgency text DEFAULT 'normal'::text, p_due_date date DEFAULT NULL::date, p_related_table text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_to_tenant uuid; v_from_name text; v_to_name text;
  v_existing uuid; v_open_pair int; v_req uuid; v_obj uuid; v_title text;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  v_title := left(btrim(coalesce(p_title,'')), 200);
  IF v_title = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'title_required'); END IF;
  IF p_to_de_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'to_de_required'); END IF;
  IF p_from_de_id IS NOT NULL AND p_from_de_id = p_to_de_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_self_assignment');
  END IF;

  SELECT tenant_id, coalesce(persona_name, name) INTO v_to_tenant, v_to_name FROM digital_employees WHERE id = p_to_de_id;
  IF v_to_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'target_not_found'); END IF;
  v_tenant := v_to_tenant;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  -- (B) HUMAN path is admin-only.
  IF p_from_de_id IS NULL AND NOT v_is_service
     AND NOT public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted',
      'detail', 'Only workspace owners/admins can assign tasks to an employee.');
  END IF;

  -- (C) SINGLE-HOP backstop: a task opened FROM a de_task case cannot re-delegate.
  IF p_from_de_id IS NOT NULL AND p_related_table = 'de_objectives' AND p_related_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM de_objectives o WHERE o.id = p_related_id AND o.entity_kind = 'de_task') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'chain_too_deep',
      'detail', 'A delegated task cannot itself be delegated onward.');
  END IF;

  IF p_from_de_id IS NOT NULL THEN
    SELECT coalesce(persona_name, name) INTO v_from_name FROM digital_employees WHERE id = p_from_de_id AND tenant_id = v_tenant;
    IF v_from_name IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'requester_not_in_tenant'); END IF;
    IF NOT EXISTS (SELECT 1 FROM de_consultation_grants g
      WHERE g.tenant_id = v_tenant AND g.requester_de_id = p_from_de_id AND g.target_de_id = p_to_de_id AND g.active) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_permitted',
        'detail', 'No active collaboration grant from the requesting employee to the target. A tenant admin configures these.');
    END IF;
    IF EXISTS (SELECT 1 FROM de_task_requests r
      WHERE r.tenant_id = v_tenant AND r.from_de_id = p_to_de_id AND r.to_de_id = p_from_de_id
        AND lower(r.title) = lower(v_title) AND r.status IN ('requested','accepted','in_progress')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'circular', 'detail', 'A reverse task on the same subject is already open.');
    END IF;
    SELECT count(*) INTO v_open_pair FROM de_task_requests r
      WHERE r.tenant_id = v_tenant AND r.from_de_id = p_from_de_id AND r.to_de_id = p_to_de_id
        AND r.status IN ('requested','accepted','in_progress');
    IF v_open_pair >= 20 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'too_many_open', 'detail', 'Too many open tasks to this employee already.');
    END IF;
  ELSE
    v_from_name := 'You';
  END IF;

  SELECT id INTO v_existing FROM de_task_requests r
    WHERE r.tenant_id = v_tenant AND r.to_de_id = p_to_de_id
      AND coalesce(r.from_de_id::text,'human') = coalesce(p_from_de_id::text,'human')
      AND lower(r.title) = lower(v_title) AND r.status IN ('requested','accepted','in_progress')
    ORDER BY r.created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'deduped', true, 'request_id', v_existing);
  END IF;

  INSERT INTO de_task_requests (tenant_id, from_de_id, to_de_id, title, context, expected_output, urgency, due_date, related_table, related_id, created_by)
  VALUES (v_tenant, p_from_de_id, p_to_de_id, v_title, left(p_context, 4000), left(p_expected_output, 2000),
          CASE WHEN p_urgency IN ('low','normal','high','urgent') THEN p_urgency ELSE 'normal' END,
          p_due_date, p_related_table, p_related_id, auth.uid())
  RETURNING id INTO v_req;

  INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
  VALUES (v_tenant, p_to_de_id, left('Task from ' || coalesce(v_from_name,'a colleague') || ': ' || v_title, 200),
          'Assigned by ' || coalesce(v_from_name,'a colleague') || '. ' || coalesce(left(p_context,1000),'')
            || coalesce(E'\nExpected: ' || left(p_expected_output,500), ''),
          'de_task', v_req::text, 'open',
          CASE p_urgency WHEN 'urgent' THEN 5 WHEN 'high' THEN 30 ELSE 60 END,
          p_due_date::timestamptz,
          jsonb_build_object('source','cross_de_task','request_id',v_req,'from_de_id',p_from_de_id,'urgency',p_urgency))
  RETURNING id INTO v_obj;
  UPDATE de_task_requests SET objective_id = v_obj WHERE id = v_req;

  BEGIN PERFORM append_audit_event_internal(v_tenant, coalesce(v_from_name,'You'), CASE WHEN p_from_de_id IS NULL THEN 'human' ELSE 'de' END,
    coalesce(v_from_name,'You') || ' assigned a task to ' || v_to_name || ' — "' || v_title || '"', 'de_consultation',
    jsonb_build_object('kind','de_task_assigned','request_id',v_req,'from_de_id',p_from_de_id,'to_de_id',p_to_de_id,'objective_id',v_obj));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'request_id', v_req, 'objective_id', v_obj);
END; $function$;

CREATE OR REPLACE FUNCTION public.request_subtenant(p_parent_tenant_id uuid, p_name text, p_industry text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user       uuid := auth.uid();
  v_role       text;
  v_caller_tenant uuid;
  v_is_active  boolean;
  v_parent     tenants;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.provision');
  v_slug       text;
  v_base_slug  text;
  v_suffix     int := 0;
  v_tenant     tenants;
  v_request_id uuid;
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if coalesce(btrim(p_name), '') = '' then
    raise exception 'proposed tenant name is required';
  end if;

  if p_parent_tenant_id is null then
    if not v_is_platform then
      raise exception 'only a platform admin with tenant-provisioning access may create a new top-level tenant';
    end if;
  else
    if p_parent_tenant_id = v_demo_tenant_id then
      raise exception 'the demo tenant cannot be used as a parent tenant';
    end if;

    select * into v_parent from tenants where id = p_parent_tenant_id;
    if not found then
      raise exception 'parent tenant not found';
    end if;

    select role, tenant_id, coalesce(is_active, true) into v_role, v_caller_tenant, v_is_active from profiles where user_id = v_user;

    if not v_is_platform then
      if v_caller_tenant is distinct from p_parent_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
        raise exception 'only an owner or admin of the parent tenant may request a sub-tenant';
      end if;
      if not v_is_active then
        raise exception 'account is deactivated';
      end if;
    end if;
  end if;

  if v_is_platform or (p_parent_tenant_id is not null and v_parent.allow_self_serve_subtenants) then
    v_base_slug := lower(regexp_replace(btrim(p_name), '[^a-zA-Z0-9]+', '-', 'g'));
    v_base_slug := trim(both '-' from v_base_slug);
    if coalesce(v_base_slug, '') = '' then
      v_base_slug := 'org';
    end if;
    v_slug := v_base_slug;
    while exists (select 1 from tenants where slug = v_slug) loop
      v_suffix := v_suffix + 1;
      v_slug := v_base_slug || '-' || v_suffix::text;
    end loop;

    insert into tenants (name, slug, industry, plan, status, settings, parent_tenant_id, trial_ends_at)
    values (btrim(p_name), v_slug, nullif(btrim(coalesce(p_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, p_parent_tenant_id, now() + interval '14 days')
    returning * into v_tenant;

    insert into tenant_provisioning_requests
      (requested_by_user_id, proposed_parent_tenant_id, proposed_name, proposed_industry, status, reviewed_by, decided_at, created_tenant_id)
    values
      (v_user, p_parent_tenant_id, btrim(p_name), p_industry, 'approved', v_user, now(), v_tenant.id)
    returning id into v_request_id;

    return jsonb_build_object('ok', true, 'path', 'self_serve', 'tenant_id', v_tenant.id, 'slug', v_tenant.slug, 'request_id', v_request_id);
  end if;

  insert into tenant_provisioning_requests
    (requested_by_user_id, proposed_parent_tenant_id, proposed_name, proposed_industry, status)
  values
    (v_user, p_parent_tenant_id, btrim(p_name), p_industry, 'pending')
  returning id into v_request_id;

  return jsonb_build_object('ok', true, 'path', 'pending_platform_approval', 'request_id', v_request_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.request_trust_promotion(p_policy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy   trust_policies;
  v_evidence jsonb;
  v_task_id  uuid;
  v_label    text;
begin
  select * into v_policy from trust_policies where id = p_policy_id;
  if not found then
    raise exception 'trust policy not found';
  end if;
  if not exists (select 1 from profiles where user_id = auth.uid() and tenant_id = v_policy.tenant_id) then
    raise exception 'not a member of this tenant';
  end if;
  if v_policy.status <> 'active' then
    raise exception 'trust policy is paused';
  end if;
  if v_policy.current_level >= 3 then
    raise exception 'already at the highest trust level';
  end if;
  if v_policy.pending_task_id is not null
     and exists (select 1 from human_tasks where id = v_policy.pending_task_id and status = 'pending') then
    raise exception 'a promotion request is already awaiting approval';
  end if;

  v_evidence := trust_evidence_for(v_policy);
  if not coalesce((v_evidence->>'eligible')::boolean, false) then
    raise exception 'not eligible for promotion — evidence does not yet meet the policy criteria';
  end if;

  v_label := replace(v_policy.action_category, '_', ' ');
  insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
  values (
    v_policy.tenant_id, 'trust_promotion',
    format('Trust promotion — %s to level %s', v_label, v_policy.current_level + 1),
    format('Evidence met all criteria: %s. Approving widens autonomy one step — still capped by guardrails.',
      (select string_agg(x->>'detail', ' · ') from jsonb_array_elements(v_evidence->'criteria') x)),
    'system', 'trust_policies', v_policy.id
  )
  returning id into v_task_id;

  update trust_policies
  set pending_task_id = v_task_id,
      pending_evidence = v_evidence,
      requested_by = auth.uid(),
      requested_at = now()
  where id = v_policy.id;

  perform append_audit_event(
    v_policy.tenant_id, 'Trust engine', 'system',
    format('Trust promotion requested — %s level %s → %s (evidence eligible)',
      v_label, v_policy.current_level, v_policy.current_level + 1),
    'config_change',
    jsonb_build_object('kind', 'trust_promotion_requested', 'policy_id', v_policy.id,
      'action_category', v_policy.action_category, 'from_level', v_policy.current_level,
      'to_level', v_policy.current_level + 1, 'task_id', v_task_id,
      'requested_by', auth.uid(), 'evidence', v_evidence)
  );

  return jsonb_build_object('ok', true, 'task_id', v_task_id, 'evidence', v_evidence);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reset_de_config_to_template(p_de_id uuid, p_template_key text DEFAULT 'support-de-template'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  DELETE FROM config_schema_instances
  WHERE de_id = p_de_id AND tenant_id = v_tenant_id AND template_key = p_template_key;
  RETURN json_build_object('ok', true, 'reset', true);
END$function$;

CREATE OR REPLACE FUNCTION public.resolve_access(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_connector_id uuid, p_needed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_category text;
  v_has      text;
  v_via      text;
begin
  select category into v_category from connectors
   where id = p_connector_id and tenant_id = p_tenant_id;
  if v_category is null then
    return jsonb_build_object('allowed', false, 'reason', 'connector_not_found', 'needed', p_needed, 'has', null, 'via', null);
  end if;

  -- 1. connector-specific grant wins
  select permission into v_has from data_access_grants
   where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
     and resource_kind = 'connector' and resource_id = p_connector_id;
  if v_has is not null then
    v_via := 'connector';
  else
    -- 2. category-level grant
    select permission into v_has from data_access_grants
     where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
       and resource_kind = 'category' and resource_category = v_category;
    if v_has is not null then v_via := 'category'; end if;
  end if;

  -- 3. default deny
  if v_has is null then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant', 'needed', p_needed, 'has', null, 'via', null);
  end if;

  if access_permission_level(v_has) >= access_permission_level(p_needed) then
    return jsonb_build_object('allowed', true, 'reason', 'granted', 'needed', p_needed, 'has', v_has, 'via', v_via);
  end if;
  return jsonb_build_object('allowed', false, 'reason', 'insufficient_permission', 'needed', p_needed, 'has', v_has, 'via', v_via);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_account_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r account_writeback_requests; v_res jsonb;
BEGIN
  SELECT * INTO r FROM account_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;

  IF p_decision = 'approved' THEN
    v_res := public.apply_account_writeback_internal(r.id);
    UPDATE account_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human',
      'Write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','account_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE account_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_case_await(p_tenant_id uuid, p_objective_id uuid, p_awaiting_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer := 0;
BEGIN
  UPDATE de_case_events
     SET status = 'resolved', decided_at = now()
   WHERE tenant_id = p_tenant_id AND objective_id = p_objective_id
     AND status = 'pending' AND awaiting_ref IS NOT NULL AND awaiting_ref = p_awaiting_ref;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n > 0 THEN
    -- The reply came — wake the case now so the DE processes it.
    UPDATE de_objectives SET status = 'open', next_wake_at = now(), updated_at = now()
     WHERE id = p_objective_id AND tenant_id = p_tenant_id AND status NOT IN ('achieved','abandoned');
  END IF;
  RETURN jsonb_build_object('ok', true, 'resolved', v_n);
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_category_access(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_needed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_has jsonb := '[]'::jsonb;
  v_via text;
  v_lvl integer := -1;
  v_row record;
begin
  -- 1. Any connector-specific grant on a connector OF this category —
  --    take the HIGHEST permission level found (mirrors "specific beats
  --    general" from resolve_access, generalized across all connectors
  --    of the category rather than just one).
  for v_row in
    select g.permission from data_access_grants g
    join connectors c on c.id = g.resource_id and c.tenant_id = p_tenant_id and c.category = p_category
    where g.tenant_id = p_tenant_id and g.subject_kind = p_subject_kind and g.subject_id = p_subject_id
      and g.resource_kind = 'connector'
  loop
    if access_permission_level(v_row.permission) > v_lvl then
      v_lvl := access_permission_level(v_row.permission);
      v_via := 'connector';
    end if;
  end loop;

  -- 2. Category-level grant, only if no connector-specific grant beat it.
  if v_lvl < 0 then
    select permission into v_row from data_access_grants
     where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
       and resource_kind = 'category' and resource_category = p_category;
    if found then
      v_lvl := access_permission_level(v_row.permission);
      v_via := 'category';
    end if;
  end if;

  if v_lvl < 0 then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant', 'needed', p_needed, 'has', null, 'via', null);
  end if;
  if v_lvl >= access_permission_level(p_needed) then
    return jsonb_build_object('allowed', true, 'reason', 'granted', 'needed', p_needed, 'via', v_via);
  end if;
  return jsonb_build_object('allowed', false, 'reason', 'insufficient_permission', 'needed', p_needed, 'via', v_via);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_continuity_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r continuity_writeback_requests; v_res jsonb;
BEGIN
  SELECT * INTO r FROM continuity_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    v_res := public.apply_continuity_writeback_internal(r.id);
    UPDATE continuity_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human', 'Continuity write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','continuity_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE continuity_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_de_archetype(p_de_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select archetype_key from digital_employees where id = p_de_id),
    (select catalog_id from digital_employees where id = p_de_id),
    (select archetype_key from role_certifications
      where de_id = p_de_id and archetype_key is not null
      order by created_at desc limit 1)
  );
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_autonomy(p_tenant_id uuid, p_action_type text, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text)
 RETURNS TABLE(enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_row de_autonomy;
  v_gated boolean := false;
begin
  -- Records gate (mig 258): a gated employee is supervised regardless of
  -- what the trust dial says — chat drafts to a human, actions block to a
  -- human. Checked first so every precedence branch below inherits it.
  if p_de_id is not null then
    select g.gated into v_gated from public.de_records_gate(p_tenant_id, p_de_id) g;
  end if;

  if p_de_id is not null and p_source_category is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and source_category = p_source_category
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  if p_de_id is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and source_category is null
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  if p_source_category is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id is null and source_category = p_source_category
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  select * into v_row from de_autonomy
  where tenant_id = p_tenant_id and action_type = p_action_type
    and de_id is null and source_category is null
  limit 1;
  if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;

  return query select false, null::bigint, null::integer;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_escalation(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(frustration_threshold integer, always_escalate_topics text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce(
      (select r.frustration_threshold from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id = p_de_id and p_de_id is not null and r.frustration_threshold is not null),
      (select r.frustration_threshold from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id is null and r.frustration_threshold is not null),
      80
    ) as frustration_threshold,
    coalesce(
      (select nullif(r.always_escalate_topics, '{}') from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id = p_de_id and p_de_id is not null),
      (select nullif(r.always_escalate_topics, '{}') from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id is null),
      '{}'::text[]
    ) as always_escalate_topics;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_exception(p_id uuid, p_status text, p_outcome text DEFAULT NULL::text, p_learned boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and not exists (
      select 1 from de_exceptions e join profiles p on p.user_id = auth.uid()
      where e.id = p_id and (p.tenant_id = e.tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized';
  end if;
  update de_exceptions
     set status = p_status, outcome = p_outcome, learned = coalesce(p_learned, false),
         decided_by = auth.uid(), decided_at = now()
   where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_model_for_task(p_de_id uuid, p_task_class text DEFAULT 'standard'::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_arch text; v_model text;
begin
  select catalog_id into v_arch from digital_employees where id = p_de_id;
  select model_id into v_model from de_model_routes
    where scope = 'de' and de_id = p_de_id and task_class = p_task_class limit 1;
  if v_model is not null then return v_model; end if;
  select model_id into v_model from de_model_routes
    where scope = 'archetype' and archetype_key = v_arch and task_class = p_task_class limit 1;
  if v_model is not null then return v_model; end if;
  select coalesce(model_id, 'claude-sonnet-5') into v_model from digital_employees where id = p_de_id;
  return coalesce(v_model, 'claude-sonnet-5');
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_specialist_internal(p_tenant_id uuid, p_de_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select d.specialist_key
  from de_specialist_assignments a
  join digital_employees d on d.id = a.specialist_de_id
  where a.tenant_id = p_tenant_id and a.de_id = p_de_id and d.status = 'active'
  order by a.rank limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_exception(p_exception_id uuid, p_decision text, p_final_treatment text, p_approver uuid, p_approver_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ex      public.exceptions%rowtype;
  v_caller_tenant uuid;
  v_evidence_id uuid;
  v_source  text;
  v_new_status text;
begin
  if p_decision not in ('approved','rejected') then
    raise exception 'invalid decision %', p_decision;
  end if;

  select * into v_ex from public.exceptions where id = p_exception_id;
  if not found then raise exception 'exception not found'; end if;

  -- Tenant guard: caller must belong to the exception's tenant (or be platform admin).
  v_caller_tenant := public.auth_tenant_id();
  if v_caller_tenant is distinct from v_ex.tenant_id and not public.is_platform_admin() then
    raise exception 'cross-tenant access denied';
  end if;

  if v_ex.status <> 'open' then
    raise exception 'exception already %', v_ex.status;
  end if;

  -- Build source-evidence pointer string from the offending object
  v_source := coalesce(v_ex.ref_table,'n/a')||':'||coalesce(v_ex.ref_id::text,'n/a')
              ||' | type='||v_ex.exception_type||' | amount='||coalesce(v_ex.amount::text,'n/a');

  v_new_status := case when p_decision='approved' then 'approved' else 'rejected' end;

  update public.exceptions
     set status = v_new_status,
         resolved_by = p_approver,
         resolved_at = now(),
         final_treatment = p_final_treatment
   where id = p_exception_id;

  insert into public.audit_evidence
    (tenant_id, workspace_id, exception_id, action, source_evidence, ai_reasoning, confidence, approver, approver_name, final_treatment)
  values
    (v_ex.tenant_id, v_ex.workspace_id, v_ex.id, p_decision, v_source, v_ex.ai_reasoning, v_ex.confidence, p_approver, p_approver_name, p_final_treatment)
  returning id into v_evidence_id;

  return v_evidence_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_experience(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_external_ref text, p_limit integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_verdict jsonb;
  v_rows    jsonb;
begin
  if p_external_ref is null or p_external_ref = '' then
    return jsonb_build_object('allowed', true, 'rows', '[]'::jsonb);
  end if;

  v_verdict := resolve_category_access(p_tenant_id, p_subject_kind, p_subject_id, p_category, 'search');
  if not coalesce((v_verdict->>'allowed')::boolean, false) then
    return jsonb_build_object('allowed', false, 'reason', v_verdict->>'reason', 'rows', '[]'::jsonb);
  end if;

  select coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb) into v_rows
  from (
    select id, fact_summary, source_evidence_run_id, source_action_execution_id, created_at
    from de_experience
    where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
      and category = p_category and external_ref = p_external_ref
    order by created_at desc
    limit greatest(1, least(p_limit, 10))
  ) e;

  return jsonb_build_object('allowed', true, 'rows', v_rows);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_invoice_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r invoice_writeback_requests;
BEGIN
  SELECT * INTO r FROM invoice_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    PERFORM public.apply_invoice_writeback_internal(r.id);
    UPDATE invoice_writeback_requests SET decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE invoice_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_knowledge_conflict(p_conflict_id uuid, p_resolution text, p_authoritative_doc_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c knowledge_conflicts%ROWTYPE; v_winner uuid; v_loser uuid;
BEGIN
  -- FOR UPDATE serializes concurrent resolves so the nudge applies exactly once
  -- (the second caller re-reads the committed status and returns already_resolved).
  SELECT * INTO v_c FROM knowledge_conflicts WHERE id = p_conflict_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  -- Must be an admin/owner of the conflict's OWN tenant. Canonical NULL-safe idiom
  -- (mig 105): positive equality fails CLOSED on a NULL tenant, and ties the role
  -- check to this conflict's tenant (closes the remote-access NOT-IN-NULL path).
  IF NOT (v_c.tenant_id = auth_tenant_id()
          AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF v_c.status <> 'open' THEN RETURN jsonb_build_object('ok', false, 'error', 'already_resolved'); END IF;
  IF p_resolution NOT IN ('resolved_pick_a', 'resolved_pick_b', 'merged', 'dismissed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_resolution'); END IF;
  -- Authoritative doc, if given, MUST be one of the two in the pair.
  IF p_authoritative_doc_id IS NOT NULL AND p_authoritative_doc_id NOT IN (v_c.doc_a_id, v_c.doc_b_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'authoritative_not_in_pair'); END IF;

  UPDATE knowledge_conflicts
     SET status = p_resolution, authoritative_doc_id = p_authoritative_doc_id,
         decided_by = auth.uid(), decided_at = now(),
         signal = signal || jsonb_build_object('note', p_note)
   WHERE id = p_conflict_id;

  -- One-tier, clamped authority nudge — winner up, loser down — scoped to exactly
  -- the two docs in this pair AND the tenant. Only when a side is picked.
  IF p_resolution IN ('resolved_pick_a', 'resolved_pick_b') THEN
    v_winner := CASE p_resolution WHEN 'resolved_pick_a' THEN v_c.doc_a_id ELSE v_c.doc_b_id END;
    v_loser  := CASE p_resolution WHEN 'resolved_pick_a' THEN v_c.doc_b_id ELSE v_c.doc_a_id END;
    UPDATE knowledge_docs SET authority = least(100, authority + 1)
      WHERE id = v_winner AND tenant_id = v_c.tenant_id;
    UPDATE knowledge_docs SET authority = greatest(0, authority - 1)
      WHERE id = v_loser AND tenant_id = v_c.tenant_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'status', p_resolution);
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_my_de_autonomy(p_action_type text, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text)
 RETURNS TABLE(enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then
    raise exception 'not a member of any tenant';
  end if;
  return query select * from resolve_de_autonomy(v_tenant, p_action_type, p_de_id, p_source_category);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_onboarding_signoff(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task      human_tasks;
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_key       text;
  v_completed boolean := false;
begin
  if p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('error', 'invalid_decision');
  end if;

  select * into v_task from human_tasks where id = p_task_id;
  if not found or v_task.related_table <> 'onboarding_projects' or v_task.related_id is null then
    return jsonb_build_object('error', 'not_an_onboarding_task');
  end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_task.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;

  select * into v_proj from onboarding_projects where id = v_task.related_id::uuid;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'signoff_task_id' = p_task_id::text then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_for_task_not_found'); end if;
  v_key := v_item->>'key';

  if v_item->>'status' = 'signed_off' then
    return jsonb_build_object('error', 'already_signed_off');
  end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = v_key limit 1;

  if p_decision = 'approved' then
    v_item := v_item || jsonb_build_object('status', 'signed_off', 'signed_off_by', auth.uid(), 'signed_off_at', now());
  else
    v_item := v_item || jsonb_build_object('status', 'in_progress',
      'note', trim(coalesce(v_item->>'note', '') || ' · Sign-off rejected — rework needed.', ' ·'),
      'signoff_task_id', null);
  end if;

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = v_proj.id;

  perform append_audit_event_internal(
    v_task.tenant_id, 'You', 'human',
    format('Onboarding sign-off %s — %s (%s)', p_decision, coalesce(v_def->>'label', v_key), v_proj.name),
    'approval',
    jsonb_build_object('kind', 'onboarding_signoff', 'project_id', v_proj.id,
                       'item_key', v_key, 'task_id', p_task_id, 'decision', p_decision));

  if p_decision = 'approved' then
    v_completed := onboarding_check_complete(v_proj.id);
  end if;

  return jsonb_build_object('project_id', v_proj.id, 'item_key', v_key,
                            'decision', p_decision, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_opportunity_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r opportunity_writeback_requests; v_res jsonb;
BEGIN
  SELECT * INTO r FROM opportunity_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    v_res := public.apply_opportunity_writeback_internal(r.id);
    UPDATE opportunity_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human', 'Pipeline write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','opportunity_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE opportunity_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_platform_capability(p_user_id uuid, p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_layer  text;
  v_role   text;
  v_active boolean;
  v_override text;
  v_role_default boolean;
begin
  select layer, role, coalesce(is_active, true) into v_layer, v_role, v_active
  from profiles where user_id = p_user_id;

  if v_layer is distinct from 'platform' or not coalesce(v_active, false) then
    return false;
  end if;

  select effect into v_override
  from platform_capability_grants
  where user_id = p_user_id and capability = p_capability;

  if v_override = 'grant' then return true; end if;
  if v_override = 'deny' then return false; end if;

  -- Role defaults — the fallback when no explicit override exists.
  -- platform_super_admin: everything (matches today's real behavior
  -- exactly, since is_platform_admin() has never differentiated).
  -- platform_support: what a support function actually needs —
  -- remote access to help a customer, cross-tenant task visibility,
  -- tenant/audit visibility — not tenant/team/billing control.
  -- platform_billing: visibility + LLM-provider-key control — not
  -- remote access or team power.
  v_role_default := case v_role
    when 'platform_super_admin' then true
    when 'platform_support' then p_capability in
      ('tenants.view', 'remote_access.use', 'remote_access.audit', 'support.cross_tenant')
    when 'platform_billing' then p_capability in
      ('tenants.view', 'remote_access.audit', 'billing.manage')
    else false
  end;

  return coalesce(v_role_default, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_remote_access_tenant(p_operator_user_id uuid, p_asserted_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.tenant_id
  from platform_access_events e
  where e.operator_user_id = p_operator_user_id
    and e.event = 'start'
    and e.tenant_id = p_asserted_tenant_id
    and e.created_at > now() - interval '12 hours'
    and exists (
      select 1 from profiles p
      where p.user_id = p_operator_user_id and p.layer = 'platform' and coalesce(p.is_active, true) = true
    )
    and e.id = (
      select e2.id from platform_access_events e2
      where e2.operator_user_id = p_operator_user_id
      order by e2.created_at desc
      limit 1
    )
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_specialist_de(p_ref uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT id FROM digital_employees WHERE id = p_ref AND is_specialist;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_work_item_framing(p_tenant_id uuid, p_category text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select template from work_item_framing where scope = 'tenant' and tenant_id = p_tenant_id and category = p_category),
    (select template from work_item_framing where scope = 'platform' and category = p_category),
    'New {category} item needs review: {title} — {snippet}'
  );
$function$;

CREATE OR REPLACE FUNCTION public.respond_de_task(p_request_id uuid, p_status text, p_result text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r de_task_requests; v_to_name text; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_status NOT IN ('accepted','in_progress','completed','declined','failed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  SELECT * INTO r FROM de_task_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF NOT v_is_service AND r.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  IF r.status IN ('completed','declined','failed') THEN
    RETURN jsonb_build_object('ok', true, 'already', r.status);
  END IF;

  SELECT coalesce(persona_name, name) INTO v_to_name FROM digital_employees WHERE id = r.to_de_id;
  UPDATE de_task_requests
     SET status = p_status,
         result = coalesce(left(p_result, 4000), result),
         responded_at = coalesce(responded_at, now()),
         completed_at = CASE WHEN p_status IN ('completed','declined','failed') THEN now() ELSE completed_at END
   WHERE id = p_request_id;

  -- Reflect terminal states onto the receiver's case so the work engine closes it.
  -- §3 W4: 'completed' → 'achieved' now routes through conclude_objective_verified
  -- (assess + log + withhold-on-enforce); 'declined'/'failed' → 'blocked' unchanged.
  IF p_status IN ('completed','declined','failed') AND r.objective_id IS NOT NULL THEN
    IF p_status = 'completed' THEN
      PERFORM public.conclude_objective_verified(r.tenant_id, r.objective_id, 'achieved', 'cross-DE task completed');
    ELSE
      UPDATE de_objectives SET status = 'blocked' WHERE id = r.objective_id;
    END IF;
  END IF;

  BEGIN PERFORM append_audit_event_internal(r.tenant_id, coalesce(v_to_name,'DE'), 'de',
    coalesce(v_to_name,'DE') || ' marked task "' || r.title || '" as ' || p_status, 'de_consultation',
    jsonb_build_object('kind','de_task_response','request_id',r.id,'status',p_status));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', p_status);
END; $function$;

CREATE OR REPLACE FUNCTION public.resume_digital_employee(p_de_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_actor_name text;
  v_back_to text;
begin
  if p_note is null or trim(p_note) = '' then
    raise exception 'resuming requires a note on what was investigated/remediated';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can resume a Digital Employee';
  end if;
  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_de.lifecycle_status <> 'paused' then raise exception 'this employee is not paused'; end if;

  -- Return to the stage the employee paused FROM (the last pause
  -- event's from_stage) — falling back to 'assigned' if history is
  -- missing. Open development items pull it to 'improving' on the next
  -- sync, matching §8's "returns to Active or Improving".
  select from_stage into v_back_to from de_lifecycle_events
  where tenant_id = v_tenant and de_id = p_de_id and to_stage = 'paused'
  order by created_at desc limit 1;
  v_back_to := coalesce(v_back_to, 'assigned');

  select full_name into v_actor_name from profiles where user_id = auth.uid();

  update digital_employees set lifecycle_status = v_back_to, status = 'active', updated_at = now()
  where id = p_de_id;

  insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_id, actor_label, note)
  values (v_tenant, p_de_id, 'paused', v_back_to, auth.uid(), coalesce(v_actor_name, 'A workspace admin'), p_note);

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor_name, 'A workspace admin'), 'human',
    format('%s resumed to %s — "%s"', v_de.name, v_back_to, left(p_note, 200)),
    'config_change',
    jsonb_build_object('kind', 'de_resumed', 'de_id', p_de_id, 'to', v_back_to, 'note', p_note)
  );

  return jsonb_build_object('ok', true, 'stage', v_back_to);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_playbook_on_task(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_run     playbook_runs;
  v_steps   jsonb;
  v_acct    text;
  v_inv     record;
  v_now     text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  i         integer;
  v_step    jsonb;
  v_key     text;
  v_params  jsonb;
  v_ctx     jsonb;
  v_text    text;
  v_tbl     text;
  v_set     text;
  v_detail  text;
  v_gate_key text;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected';
  end if;

  select * into v_run
  from playbook_runs
  where waiting_task_id = p_task_id
    and status = 'waiting_approval'
  limit 1;

  if not found then
    return jsonb_build_object('resumed', false, 'reason', 'no_waiting_run');
  end if;

  if coalesce(auth.role(), '') <> 'service_role' and not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_run.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;

  v_steps := v_run.steps;
  v_ctx   := coalesce(v_run.context, '{}'::jsonb);
  v_acct  := coalesce(nullif(v_ctx->>'account_name', ''),
             coalesce(nullif(split_part(v_steps->0->>'detail', ' · ', 1), ''), 'account'));

  -- ══════════════════════════════════════════════════════════
  -- LEGACY PATH: renewal_v1 (no definition) — unchanged behavior
  -- ══════════════════════════════════════════════════════════
  if v_run.definition_id is null then
    if p_decision = 'rejected' then
      v_steps := jsonb_set(v_steps, '{3,status}', '"cancelled"');
      v_steps := jsonb_set(v_steps, '{3,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{3,detail}', '"Rejected by human reviewer"');
      for i in 4 .. jsonb_array_length(v_steps) - 1 loop
        if v_steps->i->>'status' = 'pending' then
          v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
        end if;
      end loop;
      update playbook_runs
        set status = 'cancelled', current_step = 3, steps = v_steps, waiting_task_id = null
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Renewal DE', 'de',
        format('Renewal playbook [%s] — run cancelled (approval rejected)', v_acct),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'task_id', p_task_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'cancelled');
    end if;

    v_steps := jsonb_set(v_steps, '{3,status}', '"done"');
    v_steps := jsonb_set(v_steps, '{3,at}', to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, '{3,detail}', '"Approved by human reviewer"');
    perform append_audit_event(
      v_run.tenant_id, 'Renewal DE', 'de',
      format('Renewal playbook [%s] — step "Human approval" done: Approved by human reviewer', v_acct),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'step_key', 'human_approval', 'step_status', 'done', 'task_id', p_task_id)
    );

    select id, amount_cents into v_inv
    from renewal_invoices
    where tenant_id = v_run.tenant_id and account_id = v_run.account_id
    order by created_at desc
    limit 1;

    if v_inv.id is not null then
      update renewal_invoices set status = 'sent', cadence_stage = 1 where id = v_inv.id;
      v_steps := jsonb_set(v_steps, '{4,status}', '"done"');
      v_steps := jsonb_set(v_steps, '{4,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{4,detail}',
        to_jsonb(format('Invoice $%s sent · cadence Day-0 started', to_char(round(v_inv.amount_cents / 100.0), 'FM999,999,999'))));
      perform append_audit_event(
        v_run.tenant_id, 'Renewal DE', 'de',
        format('Renewal playbook [%s] — step "Send invoice" done: %s', v_acct, v_steps->4->>'detail'),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_key', 'mark_sent', 'step_status', 'done', 'invoice_id', v_inv.id)
      );
      insert into activity_events (tenant_id, actor, actor_type, event_type, text)
      values (v_run.tenant_id, 'Renewal DE', 'de', 'resolved',
        format('Renewal playbook sent invoice — %s ($%s), dunning cadence started',
          v_acct, to_char(round(v_inv.amount_cents / 100.0), 'FM999,999,999')));
    else
      v_steps := jsonb_set(v_steps, '{4,status}', '"skipped"');
      v_steps := jsonb_set(v_steps, '{4,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{4,detail}', '"Invoice not found for cadence update"');
    end if;

    v_steps := jsonb_set(v_steps, '{5,status}', '"done"');
    v_steps := jsonb_set(v_steps, '{5,at}', to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, '{5,detail}', '"Run completed"');

    update playbook_runs
      set status = 'completed', current_step = 5, steps = v_steps, waiting_task_id = null
      where id = v_run.id;

    perform append_audit_event(
      v_run.tenant_id, 'Renewal DE', 'de',
      format('Renewal playbook [%s] — run completed end-to-end', v_acct),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'invoice_id', v_inv.id, 'amount_cents', v_inv.amount_cents, 'resumed_by', 'resume_playbook_on_task')
    );

    return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');
  end if;

  -- ══════════════════════════════════════════════════════════
  -- DEFINITION PATH: SQL advances guardrail_check / update_record /
  -- log_activity / complete natively. ANY other step (connector_action,
  -- instruction, decision, checklist, wait, sub_playbook, consult) parks
  -- the run in 'resume_pending' — the HTTP executor finishes it.
  -- ══════════════════════════════════════════════════════════
  i := v_run.current_step;  -- index of the gate step (human_approval or checklist)
  v_gate_key := coalesce(v_steps->i->>'key', 'human_approval');

  if p_decision = 'rejected' then
    v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
    v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, array[i::text, 'detail'],
      (case when v_gate_key = 'checklist' then '"Checklist rejected by human reviewer"' else '"Rejected by human reviewer"' end)::jsonb);
    for i in v_run.current_step + 1 .. jsonb_array_length(v_steps) - 1 loop
      if v_steps->i->>'status' = 'pending' then
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
      end if;
    end loop;
    update playbook_runs
      set status = 'cancelled', steps = v_steps, waiting_task_id = null
      where id = v_run.id;
    perform append_audit_event(
      v_run.tenant_id, 'Playbook DE', 'de',
      format('Playbook [%s] — run cancelled (%s rejected)', v_acct,
        case when v_gate_key = 'checklist' then 'checklist' else 'approval' end),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'task_id', p_task_id, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
    );
    return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'cancelled');
  end if;

  -- Approved: gate step done. If the gate approved an invoice, send it.
  v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
  v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
  v_steps := jsonb_set(v_steps, array[i::text, 'detail'],
    (case when v_gate_key = 'checklist' then '"Checklist completed — all items confirmed by a human"' else '"Approved by human reviewer"' end)::jsonb);
  perform append_audit_event(
    v_run.tenant_id, 'Playbook DE', 'de',
    format('Playbook [%s] — step "%s" done: %s', v_acct,
      case when v_gate_key = 'checklist' then 'Checklist' else 'Human approval' end,
      case when v_gate_key = 'checklist' then 'all items confirmed' else 'approved' end),
    'playbook_step',
    jsonb_build_object('run_id', v_run.id, 'step_key', v_gate_key, 'step_status', 'done', 'task_id', p_task_id, 'definition_id', v_run.definition_id)
  );
  if v_gate_key = 'human_approval' and (v_ctx->>'invoice_id') is not null then
    update renewal_invoices set status = 'sent', cadence_stage = 1
      where id = (v_ctx->>'invoice_id')::uuid and status = 'awaiting_approval';
  end if;

  -- Walk the remaining steps.
  i := v_run.current_step + 1;
  while i <= jsonb_array_length(v_steps) - 1 loop
    v_step   := v_steps->i;
    v_key    := v_step->>'key';
    v_params := coalesce(v_step->'params', '{}'::jsonb);

    if v_key = 'guardrail_check' then
      v_detail := format('Re-checked invoice threshold post-approval — amount $%s (approved by human)',
        to_char(round(coalesce((v_ctx->>'invoice_amount_cents')::bigint, 0) / 100.0), 'FM999,999,999'));
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_detail));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Guardrail check" done: %s', v_acct, v_detail),
        'guardrail_check',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id, 'result', 'passed_post_approval')
      );

    elsif v_key = 'update_record' then
      v_tbl := v_params->>'table';
      v_set := v_params#>>'{set,status}';
      v_detail := null;
      if v_tbl = 'renewal_invoices' and v_set in ('sent', 'paid') and (v_ctx->>'invoice_id') is not null then
        update renewal_invoices set status = v_set where id = (v_ctx->>'invoice_id')::uuid;
        v_detail := format('renewal_invoices.status → %s', v_set);
      elsif v_tbl = 'support_tickets' and v_set in ('open', 'pending', 'resolved', 'escalated') and (v_ctx->>'ticket_id') is not null then
        update support_tickets set status = v_set where id = (v_ctx->>'ticket_id')::uuid and tenant_id = v_run.tenant_id;
        v_detail := format('support_tickets.status → %s', v_set);
      end if;
      if v_detail is null then
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"skipped"');
        v_steps := jsonb_set(v_steps, array[i::text, 'detail'], '"skipped: no target record in run context"');
      else
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
        v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_detail));
      end if;
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Update record" %s', v_acct, coalesce(v_detail, 'skipped: no target record')),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id)
      );

    elsif v_key = 'log_activity' then
      v_text := coalesce(v_params->>'text_template', 'Playbook step executed');
      v_text := replace(v_text, '{{account.name}}', coalesce(v_ctx->>'account_name', 'account'));
      v_text := replace(v_text, '{{invoice.amount}}',
        '$' || to_char(round(coalesce((v_ctx->>'invoice_amount_cents')::bigint, 0) / 100.0), 'FM999,999,999'));
      v_text := replace(v_text, '{{run.id}}', v_run.id::text);
      insert into activity_events (tenant_id, actor, actor_type, event_type, text)
      values (v_run.tenant_id, 'Playbook DE', 'de', 'resolved', v_text);
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_text));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Log activity" done: %s', v_acct, v_text),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id)
      );

    elsif v_key = 'complete' then
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], '"Run completed"');
      update playbook_runs
        set status = 'completed', current_step = i, steps = v_steps, waiting_task_id = null, context = v_ctx
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — run completed end-to-end', v_acct),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');

    else
      -- Needs the HTTP executor (connector_action, instruction, decision,
      -- checklist, wait, sub_playbook, consult_specialist, …) — park the
      -- run; the edge function's 'advance' action finishes it.
      update playbook_runs
        set status = 'resume_pending', current_step = i, steps = v_steps, waiting_task_id = null, context = v_ctx
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — approved; parked at "%s" step for HTTP advance', v_acct, v_key),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'step_key', v_key, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'resume_pending', 'needs_http', true);
    end if;

    i := i + 1;
  end loop;

  -- No explicit complete step (validation requires one, but be safe).
  update playbook_runs
    set status = 'completed', current_step = jsonb_array_length(v_steps) - 1, steps = v_steps, waiting_task_id = null, context = v_ctx
    where id = v_run.id;
  return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');
end;
$function$;

CREATE OR REPLACE FUNCTION public.retire_playbook_knowledge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'archived' and coalesce(old.status, '') <> 'archived' then
    update knowledge_docs
      set is_current = false
      where tenant_id = new.tenant_id
        and external_ref = 'playbook:' || new.id::text;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.retry_ingestion_job(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_lvl int; v_retried int; v_terminal int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_ingestion_jobs WHERE id = p_job_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'job_not_found';
  END IF;

  -- Retrying creates documents, so it needs the same right as creating the job.
  SELECT coalesce(max(knowledge_permission_rank(g.permission)), 0) INTO v_lvl
    FROM knowledge_access_grants g
   WHERE g.tenant_id = v_tenant AND g.resource_type = 'workspace'
     AND knowledge_grant_matches_caller(g);
  IF v_lvl < 2 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: retrying an import requires contributor';
  END IF;

  SELECT count(*) INTO v_terminal FROM knowledge_ingestion_items
   WHERE job_id = p_job_id AND status = 'failed' AND error_kind = 'terminal';

  UPDATE knowledge_ingestion_items
     SET status = 'queued', attempts = 0, next_attempt_at = now(),
         last_error = NULL, error_kind = NULL, updated_at = now()
   WHERE job_id = p_job_id AND status = 'failed' AND error_kind IS DISTINCT FROM 'terminal';
  GET DIAGNOSTICS v_retried = ROW_COUNT;

  -- Reopen the job so the rollup can close it again honestly.
  IF v_retried > 0 THEN
    UPDATE knowledge_ingestion_jobs
       SET status = 'running', finished_at = NULL
     WHERE id = p_job_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'retried', v_retried, 'not_retryable', v_terminal);
END $function$;

CREATE OR REPLACE FUNCTION public.review_de_incident(p_incident_id uuid, p_status text, p_resolution_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_incidents;
begin
  if p_status not in ('reviewed', 'closed', 'open') then
    raise exception 'status must be reviewed, closed, or open';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can review incidents';
  end if;

  select * into v_row from de_incidents where id = p_incident_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'incident not found in this workspace'; end if;

  update de_incidents set
    status = p_status,
    resolution_note = coalesce(p_resolution_note, resolution_note),
    reviewed_by = auth.uid(),
    reviewed_at = now()
  where id = p_incident_id
  returning * into v_row;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Incident %s — %s%s', p_status, v_row.title,
      case when p_resolution_note is not null and p_resolution_note <> '' then format(' ("%s")', left(p_resolution_note, 160)) else '' end),
    'config_change',
    jsonb_build_object('kind', 'incident_review', 'incident_id', p_incident_id, 'status', p_status, 'incident_kind', v_row.kind)
  );

  return jsonb_build_object('ok', true, 'status', v_row.status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_access_grant(p_subject_kind text, p_subject_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_category text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_user uuid := auth.uid(); v_role text; v_is_active boolean; v_before text; v_subject_label text; v_resource_label text;
begin
  if v_user is not null then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'no_tenant'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'admin_role_required'); end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then return jsonb_build_object('ok', false, 'error', 'admin_role_required'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'admin_role_required');
  else
    -- specialist subjects are digital_employees now (subject_id = DE id)
    select tenant_id into v_tenant from digital_employees where id = p_subject_id;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;
  end if;

  select name into v_subject_label from digital_employees where id = p_subject_id and tenant_id = v_tenant;
  v_resource_label := case when p_resource_kind = 'connector'
    then coalesce((select display_name from connectors where id = p_resource_id and tenant_id = v_tenant), 'connector')
    else 'all ' || p_resource_category || ' systems' end;

  delete from data_access_grants
   where tenant_id = v_tenant and subject_kind = p_subject_kind and subject_id = p_subject_id
     and resource_kind = p_resource_kind
     and coalesce(resource_id::text, resource_category) = coalesce(p_resource_id::text, p_resource_category)
  returning permission into v_before;

  if v_before is null then return jsonb_build_object('ok', true, 'removed', false, 'note', 'no grant existed — already default-deny'); end if;

  perform append_audit_event(v_tenant,
    coalesce((select full_name from profiles where user_id = v_user), 'service'),
    case when v_user is null then 'system' else 'human' end,
    'Data access grant REVOKED — ' || coalesce(v_subject_label, 'subject') || ' on ' || v_resource_label || ': ' || v_before || ' → none (default-deny)',
    'access_control',
    jsonb_build_object('kind', 'access_grant_changed', 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_subject_label,
      'resource_kind', p_resource_kind, 'resource_id', p_resource_id, 'resource_category', p_resource_category, 'resource_label', v_resource_label, 'before', v_before, 'after', null));
  return jsonb_build_object('ok', true, 'removed', true, 'before', v_before);
end; $function$;

CREATE OR REPLACE FUNCTION public.revoke_de_certification(p_cert_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_certifications;
  v_actor text;
  v_de_name text;
begin
  if p_reason is null or trim(p_reason) = '' then raise exception 'a revocation reason is required'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can revoke a certification';
  end if;
  update de_certifications set status = 'revoked', revoked_reason = trim(p_reason)
  where id = p_cert_id and tenant_id = v_tenant and status = 'active'
  returning * into v_row;
  if v_row.id is null then raise exception 'active certification not found in this workspace'; end if;

  select name into v_de_name from digital_employees where id = v_row.de_id;
  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s certification (%s) REVOKED — %s', coalesce(v_de_name, 'employee'), v_row.cert_type, left(trim(p_reason), 200)),
    'config_change',
    jsonb_build_object('kind', 'de_certification_revoked', 'cert_id', p_cert_id, 'de_id', v_row.de_id)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_de_delegation_token(p_token_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'revoke_de_delegation_token is service-role only';
  end if;
  update de_delegation_tokens set revoked_at = now() where id = p_token_id and revoked_at is null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_knowledge_access(p_grant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_g knowledge_access_grants; v_my int; v_space uuid; v_admins int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_g FROM knowledge_access_grants WHERE id = p_grant_id AND tenant_id = v_tenant;
  IF v_g.id IS NULL THEN RAISE EXCEPTION 'grant_not_found'; END IF;

  v_space := CASE WHEN v_g.resource_type = 'collection' THEN v_g.resource_id END;
  v_my := public.knowledge_my_admin_level(v_space);
  IF v_my < 5 THEN
    RAISE EXCEPTION 'insufficient_permission: changing who can see knowledge requires knowledge manager';
  END IF;
  -- Symmetric with granting: you cannot remove an access level you could not
  -- have handed out. Otherwise a knowledge manager can demote an owner.
  IF knowledge_permission_rank(v_g.permission) > v_my THEN
    RAISE EXCEPTION 'insufficient_permission: that grant is above your level';
  END IF;

  -- Never leave a workspace with nobody who can administer it.
  IF v_g.permission = 'workspace_admin' THEN
    SELECT count(*) INTO v_admins FROM knowledge_access_grants
     WHERE tenant_id = v_tenant AND permission = 'workspace_admin' AND id <> p_grant_id;
    IF v_admins = 0 THEN
      RAISE EXCEPTION 'that is the last full-access grant in this workspace — add another before removing it';
    END IF;
  END IF;

  DELETE FROM knowledge_access_grants WHERE id = p_grant_id;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('Removed %s access', v_g.permission),
    'access_control',
    jsonb_build_object('grant_id', p_grant_id, 'resource_type', v_g.resource_type,
                       'resource_id', v_g.resource_id, 'permission', v_g.permission,
                       'principal_type', v_g.principal_type));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.revoke_platform_capability_grant(p_target_user_id uuid, p_capability text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s permissions';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own permissions here';
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if p_capability = 'team.manage'
     and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  delete from platform_capability_grants where user_id = p_target_user_id and capability = p_capability;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'capability', p_capability, 'reverted_to_role_default', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_platform_invite(p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite platform_invites;
begin
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may revoke a platform invite';
  end if;

  select * into v_invite from platform_invites where id = p_invite_id for update;
  if not found then
    raise exception 'invite not found';
  end if;
  if v_invite.status <> 'pending' then
    raise exception 'this invite is already % and cannot be revoked', v_invite.status;
  end if;

  update platform_invites set status = 'revoked' where id = p_invite_id;

  return jsonb_build_object('ok', true, 'invite_id', p_invite_id, 'status', 'revoked');
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_tenant_api_key(p_key_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id, name into v_tenant, v_name from tenant_api_keys where id = p_key_id;
  if v_tenant is null then
    raise exception 'API key not found';
  end if;

  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = v_tenant
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can revoke an API key';
  end if;

  update tenant_api_keys set revoked_at = now() where id = p_key_id and revoked_at is null;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('API key revoked: %s', v_name),
    'config_change',
    jsonb_build_object('kind', 'api_key_revoked', 'key_id', p_key_id, 'name', v_name)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.rotate_widget_identity_secret(p_widget_key_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret text; v_is_new boolean;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'widget_key_not_found');
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT (v_tenant = public.auth_tenant_id()
              AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  v_secret := encode(gen_random_bytes(32), 'hex');   -- 256-bit, 64 hex chars
  SELECT NOT EXISTS (SELECT 1 FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id) INTO v_is_new;
  INSERT INTO widget_key_secrets (widget_key_id, tenant_id, secret)
  VALUES (p_widget_key_id, v_tenant, v_secret)
  ON CONFLICT (widget_key_id) DO UPDATE SET secret = EXCLUDED.secret, rotated_at = now();
  RETURN jsonb_build_object('ok', true, 'secret', v_secret, 'is_new', v_is_new);
END $function$;

CREATE OR REPLACE FUNCTION public.run_analytics_query(p_tenant_id uuid, p_key text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null
     and not exists (select 1 from profiles p where p.user_id = auth.uid()
                       and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized for this tenant';
  end if;
  return case p_key
    when 'de_workload'   then public.analytics_de_workload(p_tenant_id, (p_params->>'de_id')::uuid)
    when 'action_volume' then public.analytics_action_volume(p_tenant_id, coalesce((p_params->>'days')::int, 30))
    else jsonb_build_object('error', 'unknown_query_key', 'key', p_key)
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_case_timeline(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e de_case_events; v_fired integer := 0;
BEGIN
  FOR e IN
    SELECT * FROM de_case_events
    WHERE status = 'pending' AND fire_at <= now()
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
    ORDER BY fire_at LIMIT 500
  LOOP
    UPDATE de_case_events SET status = 'fired', decided_at = now() WHERE id = e.id;

    -- Re-open the case with the continuation instruction attached, so de-work
    -- resumes the motion where it paused.
    UPDATE de_objectives
       SET status = CASE WHEN status IN ('achieved','abandoned') THEN status ELSE 'open' END,
           next_wake_at = now(),
           description = coalesce(description,'') || E'\n\n[Follow-up ' || to_char(now(),'Mon DD') || ']: '
             || coalesce(nullif(e.instruction,''),
                  CASE WHEN e.awaiting_ref IS NOT NULL THEN 'No reply received by the deadline — continue the motion.' ELSE 'Scheduled continuation — continue the motion.' END),
           updated_at = now()
     WHERE id = e.objective_id;

    BEGIN
      PERFORM append_audit_event_internal(e.tenant_id,
        (SELECT coalesce(persona_name, name) FROM digital_employees WHERE id = e.de_id), 'de',
        'Case resumed — ' || e.kind || (CASE WHEN e.awaiting_ref IS NOT NULL THEN ' (no reply by deadline)' ELSE '' END)
          || ': ' || left(coalesce(e.instruction,'continue the motion'), 120),
        'playbook_step',
        jsonb_build_object('kind','case_continuation_fired','event_id',e.id,'objective_id',e.objective_id,'continuation_kind',e.kind));
    EXCEPTION WHEN OTHERS THEN NULL; END;

    v_fired := v_fired + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'fired', v_fired);
END; $function$;

CREATE OR REPLACE FUNCTION public.run_reply_mode_gate_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de record;
  v_g record;
  v_m record;
  v_reason text;
  v_demoted integer := 0;
  v_name text;
begin
  for v_de in
    select d.id, d.tenant_id, coalesce(d.persona_name, d.name) as name
      from digital_employees d
      join tenants t on t.id = d.tenant_id
     where d.external_reply_mode = 'auto'
       and coalesce(d.lifecycle_status, 'active') not in ('paused', 'retired', 'archived')
       and t.status in ('active', 'trial')
  loop
    v_reason := null;

    select * into v_g from public.de_records_gate(v_de.tenant_id, v_de.id);
    if v_g.gated then
      v_reason := 'records gate: ' || array_to_string(v_g.reasons, ', ');
    end if;

    if v_reason is null and exists (
      select 1 from de_incidents i
       where i.tenant_id = v_de.tenant_id and i.de_id = v_de.id
         and i.status = 'open' and i.severity = 'critical'
    ) then
      v_reason := 'an open critical incident';
    end if;

    if v_reason is null then
      select * into v_m from get_de_performance_metrics(v_de.tenant_id, 8) m
       where m.de_id = v_de.id limit 1;
      if found and coalesce(v_m.total_decisions, 0) >= 10
         and (v_m.escalation_rate > 50 or v_m.error_rate > 15) then
        v_reason := format('degraded 8-week metrics (escalation %s%%, errors %s%%)',
                           round(coalesce(v_m.escalation_rate, 0)), round(coalesce(v_m.error_rate, 0)));
      end if;
    end if;

    if v_reason is null then continue; end if;

    if exists (
      select 1 from human_tasks t
       where t.tenant_id = v_de.tenant_id and t.de_id = v_de.id
         and t.type = 'trust_demotion_notice'
         and t.created_at > now() - interval '7 days'
    ) then continue; end if;

    update digital_employees set external_reply_mode = 'draft', updated_at = now()
     where id = v_de.id;

    insert into human_tasks (tenant_id, de_id, type, source, title, detail)
    values (v_de.tenant_id, v_de.id, 'trust_demotion_notice', 'de',
      format('%s moved to draft-for-approval — %s', v_de.name, v_reason),
      format('%s was auto-answering customers, but their employment record no longer supports it: %s. '
             || 'Every reply now waits for your approval. To restore auto-answering, resolve the underlying record '
             || '(re-certify / close the incident / improve the metrics) and flip the mode back on the employee''s Channels settings — '
             || 'that restoration is deliberately a human decision.', v_de.name, v_reason));

    perform append_audit_event_internal(
      v_de.tenant_id, 'Records gate', 'system',
      format('%s demoted from auto-answer to draft-for-approval — %s', v_de.name, v_reason),
      'config_change',
      jsonb_build_object('kind', 'reply_mode_demotion', 'de_id', v_de.id, 'reason', v_reason));

    insert into activity_events (tenant_id, actor, actor_type, event_type, text)
    values (v_de.tenant_id, v_de.name, 'de', 'config_change',
      format('Moved to draft-for-approval by the records gate — %s', v_reason));

    v_demoted := v_demoted + 1;
  end loop;

  return jsonb_build_object('demoted', v_demoted);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_work_watchers(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  w work_watchers; v_new integer; v_total integer := 0; v_watchers integer := 0;
  v_obj_id uuid; v_inserted boolean; r record; v_h integer; v_occ text;
  v_title text; v_de_name text; v_src text; v_date_field text; v_motion text;
  v_cat watch_source_catalog; v_row jsonb; v_id text; v_where text; v_sql text;
  v_field text; v_op text; v_vt text; v_cast text; v_datef text; v_label text; v_subject jsonb; v_cap int;
BEGIN
  FOR w IN SELECT * FROM work_watchers WHERE active AND kind <> 'inbox'
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id) ORDER BY created_at
  LOOP
    v_new := 0; v_watchers := v_watchers + 1;
    v_src := coalesce(w.config->>'source','customer_accounts');
    SELECT coalesce(persona_name, name) INTO v_de_name FROM digital_employees WHERE id = w.de_id;

    BEGIN
    -- ── date_horizon ──
    IF w.kind = 'date_horizon' AND v_src = 'customer_accounts' THEN
      FOR r IN
        SELECT ca.id, ca.name, ca.renewal_date, ca.arr_cents, ca.health_score,
               (ca.renewal_date - current_date) AS days_left
        FROM customer_accounts ca
        WHERE ca.tenant_id = w.tenant_id AND ca.renewal_date IS NOT NULL AND ca.renewal_date >= current_date
          AND (w.config->'status_filter' IS NULL OR ca.status IN (SELECT jsonb_array_elements_text(w.config->'status_filter')))
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[90,60,30]'::jsonb)))::int AS h) hs WHERE h >= r.days_left;
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || r.renewal_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day checkpoint, renews ' || to_char(r.renewal_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' renews on ' || r.renewal_date::text || ' (' || r.days_left || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          'customer_account', r.id::text, 'open', v_h, r.renewal_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,
            'subject', jsonb_build_object('name', r.name, 'renewal_date', r.renewal_date, 'arr_cents', r.arr_cents, 'health_score', r.health_score))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    ELSIF w.kind = 'date_horizon' AND v_src = 'opportunities' THEN
      FOR r IN
        SELECT o.id, coalesce(o.name, o.company_name, 'opportunity') AS name, o.close_date, o.amount_cents, o.stage,
               (o.close_date - current_date) AS days_left
        FROM opportunities o
        WHERE o.tenant_id = w.tenant_id AND o.close_date IS NOT NULL AND o.close_date >= current_date AND o.closed_at IS NULL
          AND (w.config->'stage_filter' IS NULL OR o.stage IN (SELECT jsonb_array_elements_text(w.config->'stage_filter')))
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[30,14,7]'::jsonb)))::int AS h) hs WHERE h >= r.days_left;
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || r.close_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day, closes ' || to_char(r.close_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: opportunity ' || r.name || ' is in stage "' || coalesce(r.stage,'?') || '" and closes on ' || r.close_date::text || ' (' || r.days_left || ' days out). Advance it per the playbook.',
          'opportunity', r.id::text, 'open', v_h, r.close_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,
            'subject', jsonb_build_object('name', r.name, 'close_date', r.close_date, 'amount_cents', r.amount_cents, 'stage', r.stage))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── NEW: date_horizon on commercial_agreements (configurable date_field) ──
    -- Opens a de_objectives case AND its typed continuity_cases facet, stamped
    -- with the motion (explicit config override, else derived from the date_field).
    ELSIF w.kind = 'date_horizon' AND v_src = 'commercial_agreements' THEN
      v_date_field := coalesce(w.config->>'date_field','renewal_date');
      FOR r IN
        SELECT sub.* FROM (
          SELECT a.id, coalesce(a.counterparty_name, a.title) AS name, a.account_id, a.party_side,
                 a.baseline_value_cents, a.status, a.agreement_type,
                 (CASE v_date_field
                    WHEN 'renewal_date'            THEN a.renewal_date
                    WHEN 'notice_deadline'         THEN a.notice_deadline
                    WHEN 'warranty_expiry'         THEN a.warranty_expiry
                    WHEN 'next_reorder_date'       THEN a.next_reorder_date
                    WHEN 'cancellation_deadline'   THEN a.cancellation_deadline
                    WHEN 'pricing_notice_deadline' THEN a.pricing_notice_deadline
                    WHEN 'replacement_date'        THEN a.replacement_date
                    ELSE a.renewal_date END) AS target_date
          FROM commercial_agreements a
          WHERE a.tenant_id = w.tenant_id
            AND (w.config->'status_filter' IS NULL OR a.status IN (SELECT jsonb_array_elements_text(w.config->'status_filter')))
        ) sub
        WHERE sub.target_date IS NOT NULL AND sub.target_date >= current_date
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[90,60,30]'::jsonb)))::int AS h) hs WHERE h >= (r.target_date - current_date);
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || v_date_field || '|' || r.target_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;

        v_motion := coalesce(nullif(w.config->>'motion',''),
          CASE v_date_field
            WHEN 'renewal_date'            THEN 'renew'
            WHEN 'notice_deadline'         THEN 'renew'
            WHEN 'warranty_expiry'         THEN 'replace'
            WHEN 'next_reorder_date'       THEN 'reorder'
            WHEN 'replacement_date'        THEN 'replace'
            WHEN 'cancellation_deadline'   THEN 'renew'
            WHEN 'pricing_notice_deadline' THEN 'renegotiate'
            ELSE 'renew' END);

        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day, ' || v_date_field || ' ' || to_char(r.target_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' — ' || v_motion || ' motion. The ' || replace(v_date_field,'_',' ')
            || ' is ' || r.target_date::text || ' (' || (r.target_date - current_date) || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          'commercial_agreement', r.id::text, 'open', v_h, r.target_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,'motion',v_motion,'date_field',v_date_field,
            'subject', jsonb_build_object('name', r.name, 'agreement_type', r.agreement_type, 'party_side', r.party_side,
              'target_date', r.target_date, 'baseline_value_cents', r.baseline_value_cents))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;

        -- The typed facet: exactly one per case, driven off the SAME objective.
        INSERT INTO continuity_cases (objective_id, tenant_id, de_id, agreement_id, account_id, motion, stage_key, party_side, baseline_cents)
        VALUES (v_obj_id, w.tenant_id, w.de_id, r.id, r.account_id, v_motion, 'discovered', coalesce(r.party_side,'sell'), r.baseline_value_cents)
        ON CONFLICT (objective_id) DO NOTHING;
        INSERT INTO continuity_case_events (tenant_id, objective_id, to_stage, motion, actor_kind, summary, detail)
        VALUES (w.tenant_id, v_obj_id, 'discovered', v_motion, 'system',
          'Case opened by Book of Work — ' || v_motion || ' on ' || r.name || ' (' || replace(v_date_field,'_',' ') || ')',
          jsonb_build_object('watcher_id', w.id, 'date_field', v_date_field, 'horizon_days', v_h));
        v_new := v_new + 1;
      END LOOP;


    -- GENERIC date_horizon (catalog-driven; any non-legacy source)
    ELSIF w.kind = 'date_horizon' THEN
      SELECT * INTO v_cat FROM watch_source_catalog WHERE source_key = v_src AND active AND NOT legacy_bespoke;
      IF v_cat.source_key IS NULL THEN CONTINUE; END IF;
      v_datef := coalesce(w.config->>'date_field',
                   (SELECT column_name FROM watch_source_fields WHERE source_key = v_src AND role='date' ORDER BY column_name LIMIT 1));
      IF v_datef IS NULL OR NOT EXISTS (SELECT 1 FROM watch_source_fields WHERE source_key=v_src AND role='date' AND column_name=v_datef) THEN CONTINUE; END IF;
      v_cap := least(coalesce((w.config->>'max_per_run')::int, 1000), 1000);
      v_where := format('%I = $1 AND %I IS NOT NULL AND %I >= current_date', v_cat.tenant_column, v_datef, v_datef)
                 || build_base_predicates(v_cat.base_predicates)
                 || format(' AND ($2::text[] IS NULL OR %I = ANY($2))', v_cat.status_column);
      v_sql := format('SELECT %I::text AS _id, to_jsonb(t.*) AS _row FROM %I t WHERE %s ORDER BY %I LIMIT %s',
                      v_cat.id_column, v_cat.table_name, v_where, v_datef, v_cap);
      FOR r IN EXECUTE v_sql USING w.tenant_id,
                 CASE WHEN w.config ? 'status_filter' THEN ARRAY(SELECT jsonb_array_elements_text(w.config->'status_filter')) ELSE NULL::text[] END
      LOOP
        v_row := r._row; v_id := r._id;
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days', v_cat.default_horizons)))::int AS h) hs WHERE h >= ((v_row->>v_datef)::date - current_date);
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := v_id || '|' || v_datef || '|' || (v_row->>v_datef) || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, v_id, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_label := watcher_label(v_cat.label_columns, v_row, v_cat.entity_kind, v_id);
        v_subject := jsonb_object_agg_subset(v_row, v_cat.subject_columns);
        v_title := w.label || ' — ' || v_label || ' (' || v_h || '-day, ' || replace(v_datef,'_',' ') || ' ' || to_char((v_row->>v_datef)::date,'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title,200),
          'Opened by the Book of Work: ' || v_label || ' — ' || replace(v_datef,'_',' ') || ' is ' || (v_row->>v_datef) || ' (' || (((v_row->>v_datef)::date - current_date)) || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          v_cat.entity_kind, v_id, 'open', v_h, (v_row->>v_datef)::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'watch_source',v_src,'date_field',v_datef,'horizon_days',v_h,'subject', v_subject))
        RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id=v_obj_id WHERE watcher_id=w.id AND occurrence_key=v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── state_condition ──
    ELSIF w.kind = 'state_condition' AND v_src = 'customer_accounts' THEN
      FOR r IN
        SELECT ca.id, ca.name, ca.health_score, ca.status, ca.arr_cents, ca.tier
        FROM customer_accounts ca WHERE ca.tenant_id = w.tenant_id
          AND CASE w.config->>'field'
                WHEN 'health_score' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN ca.health_score < (w.config->>'value')::numeric WHEN 'lte' THEN ca.health_score <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN ca.health_score > (w.config->>'value')::numeric WHEN 'gte' THEN ca.health_score >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN ca.health_score = (w.config->>'value')::numeric ELSE ca.health_score <> (w.config->>'value')::numeric END
                WHEN 'arr_cents' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN ca.arr_cents < (w.config->>'value')::numeric WHEN 'lte' THEN ca.arr_cents <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN ca.arr_cents > (w.config->>'value')::numeric WHEN 'gte' THEN ca.arr_cents >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN ca.arr_cents = (w.config->>'value')::numeric ELSE ca.arr_cents <> (w.config->>'value')::numeric END
                WHEN 'status' THEN CASE w.config->>'op' WHEN 'eq' THEN ca.status = w.config->>'value' ELSE ca.status <> w.config->>'value' END
                WHEN 'tier' THEN CASE w.config->>'op' WHEN 'eq' THEN ca.tier = w.config->>'value' ELSE ca.tier <> w.config->>'value' END
                ELSE false END
      LOOP
        v_occ := r.id::text || '|' || (w.config->>'field') || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name;
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' matched "' || (w.config->>'field') || ' ' || (w.config->>'op') || ' ' || (w.config->>'value') || '". Assess and work per the playbook.',
          'customer_account', r.id::text, 'open', 2,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'condition', w.config,
            'subject', jsonb_build_object('name', r.name, 'health_score', r.health_score, 'status', r.status))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    ELSIF w.kind = 'state_condition' AND v_src = 'opportunities' THEN
      FOR r IN
        SELECT o.id, coalesce(o.name, o.company_name, 'opportunity') AS name, o.stage, o.amount_cents, o.close_date
        FROM opportunities o WHERE o.tenant_id = w.tenant_id AND o.closed_at IS NULL
          AND CASE w.config->>'field'
                WHEN 'amount_cents' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN o.amount_cents < (w.config->>'value')::numeric WHEN 'lte' THEN o.amount_cents <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN o.amount_cents > (w.config->>'value')::numeric WHEN 'gte' THEN o.amount_cents >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN o.amount_cents = (w.config->>'value')::numeric ELSE o.amount_cents <> (w.config->>'value')::numeric END
                WHEN 'stage' THEN CASE w.config->>'op' WHEN 'eq' THEN o.stage = w.config->>'value' ELSE o.stage <> w.config->>'value' END
                ELSE false END
      LOOP
        v_occ := r.id::text || '|' || (w.config->>'field') || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name;
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: opportunity ' || r.name || ' matched "' || (w.config->>'field') || ' ' || (w.config->>'op') || ' ' || (w.config->>'value') || '". Advance it per the playbook.',
          'opportunity', r.id::text, 'open', 2,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'condition', w.config,
            'subject', jsonb_build_object('name', r.name, 'stage', r.stage, 'amount_cents', r.amount_cents, 'close_date', r.close_date))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;


    -- GENERIC state_condition (catalog-driven; any non-legacy source)
    ELSIF w.kind = 'state_condition' THEN
      SELECT * INTO v_cat FROM watch_source_catalog WHERE source_key = v_src AND active AND NOT legacy_bespoke;
      IF v_cat.source_key IS NULL THEN CONTINUE; END IF;
      v_field := w.config->>'field'; v_op := w.config->>'op';
      SELECT value_type INTO v_vt FROM watch_source_fields WHERE source_key=v_src AND role='state' AND column_name=v_field AND v_op = ANY (allowed_ops);
      IF v_vt IS NULL THEN CONTINUE; END IF;
      v_cast := CASE WHEN v_vt = 'numeric' THEN '::numeric' ELSE '' END;
      v_where := format('%I = $1', v_cat.tenant_column) || build_base_predicates(v_cat.base_predicates)
                 || format(' AND %I %s $2%s', v_field, sql_op(v_op), v_cast)
                 || format(' AND NOT EXISTS (SELECT 1 FROM work_watcher_matches m WHERE m.watcher_id = $3 AND m.subject_ref = t.%I::text)', v_cat.id_column);
      v_sql := format('SELECT %I::text AS _id, to_jsonb(t.*) AS _row FROM %I t WHERE %s', v_cat.id_column, v_cat.table_name, v_where);
      FOR r IN EXECUTE v_sql USING w.tenant_id, (w.config->>'value'), w.id
      LOOP
        v_row := r._row; v_id := r._id;
        v_occ := v_id || '|' || v_field || v_op || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, v_id, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_label := watcher_label(v_cat.label_columns, v_row, v_cat.entity_kind, v_id);
        v_subject := jsonb_object_agg_subset(v_row, v_cat.subject_columns);
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, plan)
        VALUES (w.tenant_id, w.de_id, left(w.label || ' — ' || v_label,200),
          'Opened by the Book of Work: ' || v_label || ' matched "' || v_field || ' ' || v_op || ' ' || (w.config->>'value') || '". Assess and work per the playbook.',
          v_cat.entity_kind, v_id, 'open', 2,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'watch_source',v_src,'condition',w.config,'subject', v_subject))
        RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id=v_obj_id WHERE watcher_id=w.id AND occurrence_key=v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── metric_threshold (unchanged from mig 220) ──
    ELSIF w.kind = 'metric_threshold' THEN
      SELECT k.metric_key AS mkey, k.value, k.as_of INTO r
      FROM de_kpi_readings k WHERE k.tenant_id = w.tenant_id AND k.de_id = w.de_id AND k.metric_key = w.config->>'metric_key'
      ORDER BY k.as_of DESC, k.created_at DESC LIMIT 1;
      IF r.mkey IS NOT NULL AND ((w.config->>'op' = 'lt' AND r.value < (w.config->>'value')::numeric) OR (w.config->>'op' = 'gt' AND r.value > (w.config->>'value')::numeric)) THEN
        v_occ := r.mkey || '|' || r.as_of::text || '|' || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.mkey, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        IF v_inserted THEN
          INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, plan)
          VALUES (w.tenant_id, w.de_id, left(w.label || ' — ' || r.mkey || ' at ' || r.value, 200),
            'Opened by the Book of Work: metric "' || r.mkey || '" read ' || r.value || ' on ' || r.as_of || ', crossing the ' || (w.config->>'op') || ' ' || (w.config->>'value') || ' line. Investigate per the playbook.',
            'metric', r.mkey, 'open', 2,
            jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'reading', jsonb_build_object('metric_key', r.mkey, 'value', r.value, 'as_of', r.as_of))
          ) RETURNING id INTO v_obj_id;
          UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
          v_new := v_new + 1;
        END IF;
      END IF;

    -- ── schedule (unchanged from mig 220) ──
    ELSIF w.kind = 'schedule' THEN
      IF w.next_fire_at IS NULL THEN
        UPDATE work_watchers SET next_fire_at = now() + make_interval(mins => (w.config->>'interval_minutes')::int) WHERE id = w.id;
      ELSIF now() >= w.next_fire_at THEN
        v_occ := to_char(w.next_fire_at, 'YYYY-MM-DD"T"HH24:MI');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, 'schedule', v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        IF v_inserted THEN
          INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, plan)
          VALUES (w.tenant_id, w.de_id, left(w.label, 200),
            'Opened by the Book of Work on schedule (' || coalesce(w.description, w.label) || '). Run the recurring motion per the playbook.',
            'schedule', v_occ, 'open', 3, jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'fired_at', now())
          ) RETURNING id INTO v_obj_id;
          UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
          v_new := v_new + 1;
        END IF;
        UPDATE work_watchers SET next_fire_at = now() + make_interval(mins => (w.config->>'interval_minutes')::int) WHERE id = w.id;
      END IF;
    END IF;
    EXCEPTION WHEN OTHERS THEN
      BEGIN PERFORM append_audit_event_internal(w.tenant_id, 'system', 'system',
        'Book of Work watcher "' || w.label || '" errored and was skipped this tick', 'playbook_step',
        jsonb_build_object('kind','book_of_work_error','watcher_id', w.id, 'error', SQLERRM));
      EXCEPTION WHEN OTHERS THEN NULL; END;
      CONTINUE;
    END;

    UPDATE work_watchers SET last_run_at = now(), last_match_count = v_new WHERE id = w.id;
    v_total := v_total + v_new;
    IF v_new > 0 THEN
      BEGIN PERFORM append_audit_event_internal(w.tenant_id, coalesce(v_de_name, 'DE'), 'de',
          coalesce(v_de_name, 'DE') || ' found ' || v_new || ' new work item(s) via Book of Work watcher "' || w.label || '"',
          'playbook_step', jsonb_build_object('kind','book_of_work','watcher_id', w.id, 'watcher_kind', w.kind, 'new_cases', v_new));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'watchers_run', v_watchers, 'cases_opened', v_total);
END; $function$;

CREATE OR REPLACE FUNCTION public.sample_messages_for_online_eval(p_limit integer DEFAULT 5, p_window_minutes integer DEFAULT 90, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, tenant_id uuid, de_id uuid, conversation_id uuid, question text, answer text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select m.id, m.tenant_id, c.de_id, m.conversation_id,
         -- the most recent customer turn before this answer
         (select um.content from de_messages um
           where um.conversation_id = m.conversation_id and um.role = 'user' and um.created_at <= m.created_at
           order by um.created_at desc limit 1) as question,
         m.content as answer
  from de_messages m
  join de_conversations c on c.id = m.conversation_id
  where m.role = 'assistant'
    and m.delivery = 'sent'                     -- only answers a customer actually received
    and not m.escalated
    and m.created_at >= now() - make_interval(mins => greatest(5, p_window_minutes))
    and (p_tenant_id is null or m.tenant_id = p_tenant_id)
    and not exists (select 1 from eval_judgments j where j.message_id = m.id)
    and exists (select 1 from de_messages um where um.conversation_id = m.conversation_id and um.role = 'user' and um.created_at <= m.created_at)
  order by m.created_at desc
  limit greatest(1, least(50, p_limit));
$function$;

CREATE OR REPLACE FUNCTION public.save_adapter_template(p_name text, p_description text, p_category text, p_definition jsonb, p_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_id uuid;
  v_op record;
  v_legal jsonb := '{
    "crm":            ["search_accounts","get_account","search_conversations","search_opportunities"],
    "helpdesk":       ["search_tickets","get_ticket","search_articles"],
    "knowledge_base": ["search_articles","get_article"],
    "erp_financials": ["search_invoices","get_invoice"],
    "billing":        ["get_subscription","search_invoices"],
    "payroll_hcm":    ["get_employee","search_time_off"],
    "pos":            ["search_orders","get_order"],
    "product_system": ["get_record","search_records"],
    "other":          ["get_record","search_records"]
  }'::jsonb;
  v_auth_type text;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    v_tenant := p_tenant_id;
  else
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid();
    if v_is_active is false then
      raise exception 'account is deactivated';
    end if;
    v_tenant := auth_tenant_id();
  end if;
  if v_tenant is null then
    raise exception 'no tenant — sign in as a workspace member (or pass p_tenant_id with the service role)';
  end if;

  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'template needs a name';
  end if;
  if not (v_legal ? p_category) then
    raise exception 'unknown category "%"', p_category;
  end if;

  v_auth_type := p_definition #>> '{auth,type}';
  if v_auth_type is null or v_auth_type not in ('api_key_header','bearer','basic','oauth2_client_credentials','none') then
    raise exception 'definition.auth.type must be one of api_key_header, bearer, basic, oauth2_client_credentials, none';
  end if;
  if v_auth_type = 'api_key_header' and coalesce(p_definition #>> '{auth,header_name}', '') = '' then
    raise exception 'API-key auth needs auth.header_name (which header carries the key)';
  end if;
  if v_auth_type = 'oauth2_client_credentials' and coalesce(p_definition #>> '{auth,token_url}', '') = '' then
    raise exception 'OAuth2 client-credentials auth needs auth.token_url';
  end if;
  if coalesce(p_definition ->> 'base_url_template', '') !~ '^https?://' then
    raise exception 'definition.base_url_template must be a full URL starting with https://';
  end if;
  if p_definition -> 'ops' is null or p_definition -> 'ops' = '{}'::jsonb then
    raise exception 'bind at least one operation (definition.ops is empty)';
  end if;
  for v_op in select key, value from jsonb_each(p_definition -> 'ops') loop
    if not (v_legal -> p_category) ? v_op.key then
      raise exception '"%" is not a legal operation for the % category — legal ops: %',
        v_op.key, p_category, (select string_agg(x, ', ') from jsonb_array_elements_text(v_legal -> p_category) x);
    end if;
    if v_op.value #> '{response,items_path}' is null then
      raise exception 'operation "%": response.items_path is required — where in the response do the results live? Use "" if the response root is the list', v_op.key;
    end if;
    if coalesce(v_op.value #>> '{response,id_path}', '') = '' then
      raise exception 'operation "%": response.id_path is required (which field is the record id?)', v_op.key;
    end if;
    if coalesce(v_op.value #>> '{response,title_path}', '') = '' then
      raise exception 'operation "%": response.title_path is required (which field is the title?)', v_op.key;
    end if;
    if coalesce(v_op.value ->> 'method', '') not in ('GET','POST') then
      raise exception 'operation "%": method must be GET or POST', v_op.key;
    end if;
    if coalesce(v_op.value ->> 'path_template', '') !~ '^/' then
      raise exception 'operation "%": path_template must start with "/"', v_op.key;
    end if;
  end loop;
  if coalesce(p_definition #>> '{test_op,op}', '') = '' then
    raise exception 'definition.test_op is required — which operation proves the connection works?';
  end if;
  if p_definition -> 'ops' -> (p_definition #>> '{test_op,op}') is null then
    raise exception 'test_op "%" is not one of the bound operations', p_definition #>> '{test_op,op}';
  end if;

  if p_id is not null then
    update adapter_templates
      set name = trim(p_name), description = coalesce(p_description, ''),
          category = p_category, definition = p_definition
      where id = p_id and scope = 'tenant' and tenant_id = v_tenant
      returning id into v_id;
    if v_id is null then
      raise exception 'template not found in your workspace (platform templates cannot be edited — save a copy instead)';
    end if;
  else
    insert into adapter_templates (scope, tenant_id, name, description, category, definition, created_by)
    values ('tenant', v_tenant, trim(p_name), coalesce(p_description, ''), p_category, p_definition, auth.uid())
    returning id into v_id;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_de_config(p_de_id uuid, p_template_key text, p_values jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_user_id UUID := auth.uid();
  v_instance_id UUID;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  -- DE must belong to the caller's tenant
  PERFORM 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'de_not_in_tenant'; END IF;

  INSERT INTO config_schema_instances (tenant_id, de_id, template_key, values, updated_by)
  VALUES (v_tenant_id, p_de_id, p_template_key, p_values, v_user_id)
  ON CONFLICT (tenant_id, de_id, template_key)
  DO UPDATE SET values = EXCLUDED.values, updated_at = now(), updated_by = v_user_id
  RETURNING instance_id INTO v_instance_id;

  RETURN json_build_object('ok', true, 'instance_id', v_instance_id, 'updated_at', now()::text);
END$function$;

CREATE OR REPLACE FUNCTION public.schedule_case_continuation(p_objective_id uuid, p_kind text, p_fire_at timestamp with time zone, p_instruction text DEFAULT ''::text, p_awaiting_ref text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de uuid; v_event uuid; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_kind NOT IN ('wait','follow_up') THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_kind'); END IF;
  IF p_fire_at IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'fire_at_required'); END IF;

  SELECT tenant_id, de_id INTO v_tenant, v_de FROM de_objectives WHERE id = p_objective_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'objective_not_found'); END IF;
  -- A JWT caller must be a member of the case's tenant; service role (de-work,
  -- playbook-execute) is trusted with an explicit objective it already resolved.
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  INSERT INTO de_case_events (tenant_id, de_id, objective_id, kind, fire_at, awaiting_ref, instruction, payload, created_by)
  VALUES (v_tenant, v_de, p_objective_id, p_kind, p_fire_at, p_awaiting_ref, left(coalesce(p_instruction,''), 2000), coalesce(p_payload,'{}'::jsonb), auth.uid())
  RETURNING id INTO v_event;

  -- Park the case: it sleeps until the continuation is due. de-work only
  -- re-plans status='open' cases, so an in_progress case is left alone.
  UPDATE de_objectives
     SET status = CASE WHEN status IN ('achieved','abandoned') THEN status ELSE 'in_progress' END,
         next_wake_at = p_fire_at,
         updated_at = now()
   WHERE id = p_objective_id;

  BEGIN
    PERFORM append_audit_event_internal(v_tenant,
      (SELECT coalesce(persona_name, name) FROM digital_employees WHERE id = v_de), 'de',
      'Case paused — ' || p_kind || (CASE WHEN p_awaiting_ref IS NOT NULL THEN ' awaiting reply' ELSE '' END)
        || ' until ' || to_char(p_fire_at, 'Mon DD HH24:MI') || ': ' || left(coalesce(p_instruction,''), 120),
      'playbook_step',
      jsonb_build_object('kind','case_continuation_scheduled','event_id',v_event,'objective_id',p_objective_id,'continuation_kind',p_kind,'fire_at',p_fire_at,'awaiting_ref',p_awaiting_ref));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'event_id', v_event, 'fire_at', p_fire_at);
END; $function$;

CREATE OR REPLACE FUNCTION public.score_frustration_internal(p_tenant_id uuid, p_text text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rule   record;
  v_text   text := lower(coalesce(p_text, ''));
  v_frag   text;
  v_hit    boolean;
  v_score  integer := 0;
begin
  for v_rule in
    select id, pattern from guardrail_rules
    where tenant_id = p_tenant_id and active and rule_type = 'frustration_signal'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        v_score := v_score + 25;
        exit;
      end if;
    end loop;
  end loop;

  return least(100, v_score);
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge(p_tenant_id uuid, p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, title text, body text, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public._assert_caller_tenant(p_tenant_id);
  return query
  select ka.id, ka.title, ka.body,
    ts_rank(
      to_tsvector('english', coalesce(ka.title,'') || ' ' || coalesce(ka.body,'')),
      plainto_tsquery('english', p_query)
    )::float as similarity
  from knowledge_articles ka
  where ka.tenant_id = p_tenant_id
    and ka.status = 'published'
    and to_tsvector('english', coalesce(ka.title,'') || ' ' || coalesce(ka.body,''))
        @@ plainto_tsquery('english', p_query)
  order by similarity desc
  limit p_limit;
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge(p_tenant_id uuid, p_query text, p_audience text DEFAULT NULL::text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, title text, summary text, body text, audience text, category text, tags text[], rank real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select ka.id, ka.title, ka.summary, ka.body, ka.audience, ka.category, ka.tags,
         ts_rank(ka.search_tsv, websearch_to_tsquery('english', p_query)) as rank
  from public.knowledge_articles ka
  where ka.tenant_id = p_tenant_id
    and (
      (auth.uid() is not null and p_tenant_id in (select tenant_id from public.profiles where user_id = auth.uid() and coalesce(is_active, true) = true))
      or (auth.uid() is null and coalesce(auth.role(), '') = 'service_role')
    )
    and ka.status = 'published'
    and (p_audience is null or ka.audience = p_audience or ka.audience = 'all')
    and ka.search_tsv @@ websearch_to_tsquery('english', p_query)
  order by rank desc
  limit greatest(p_limit, 1);
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge_docs(p_query text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_source text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_collection_id uuid DEFAULT NULL::uuid, p_current_only boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_lifecycle text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, title text, preview text, tags text[], source text, visibility text, share_archetype_key text, authority integer, last_verified_at timestamp with time zone, is_current boolean, chunk_count integer, embedded_count integer, updated_at timestamp with time zone, citation_count integer, last_cited_at timestamp with time zone, lifecycle_status text, verification_state text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
BEGIN
  IF v_tenant IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH filtered AS (
    SELECT d.* FROM knowledge_docs d
     WHERE d.tenant_id = v_tenant
       AND (NOT p_current_only OR d.is_current)
       AND (p_source     IS NULL OR d.source = p_source)
       AND (p_visibility IS NULL OR d.visibility = p_visibility)
       AND (p_tags       IS NULL OR d.tags && p_tags)
       AND (p_lifecycle  IS NULL OR d.lifecycle_status = p_lifecycle)
       AND (p_collection_id IS NULL OR EXISTS (
              -- Closure, not the direct junction: selecting a Space now finds
              -- documents filed anywhere beneath it, which is what clicking a
              -- folder means to a human.
              SELECT 1 FROM knowledge_doc_access_paths ap
               WHERE ap.doc_id = d.id AND ap.collection_id = p_collection_id))
       AND (v_q IS NULL OR d.search_tsv @@ websearch_to_tsquery('english', v_q))
  ), counted AS (SELECT count(*) AS n FROM filtered)
  SELECT f.id, f.title, left(coalesce(f.content, ''), 200) AS preview, f.tags, f.source, f.visibility,
         f.share_archetype_key, f.authority, f.last_verified_at, f.is_current,
         coalesce(f.chunk_count, 0), coalesce(f.embedded_count, 0), f.updated_at,
         coalesce(f.citation_count, 0), f.last_cited_at,
         f.lifecycle_status,
         public.knowledge_verification_state(f.*),
         (SELECT n FROM counted) AS total_count
    FROM filtered f
   ORDER BY
     CASE WHEN v_q IS NULL THEN 0 ELSE ts_rank(f.search_tsv, websearch_to_tsquery('english', v_q)) END DESC,
     f.updated_at DESC
   LIMIT greatest(1, least(200, coalesce(p_limit, 50)))
  OFFSET greatest(0, coalesce(p_offset, 0));
END $function$;

CREATE OR REPLACE FUNCTION public.seed_default_grants(p_subject_kind text, p_subject_id uuid, p_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_label text; v_pairs text[][]; v_pair text[]; v_seeded integer := 0;
begin
  if p_subject_kind in ('de', 'specialist') then
    select tenant_id, name into v_tenant, v_label from digital_employees where id = p_subject_id;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
  end if;
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;

  v_pairs := case p_domain
    when 'support'   then array[['helpdesk','read'], ['knowledge_base','read'], ['product_system','read']]
    when 'technical' then array[['helpdesk','read'], ['knowledge_base','read'], ['product_system','read'], ['crm','read']]
    when 'sales'     then array[['crm','read'], ['knowledge_base','read']]
    when 'finance'   then array[['erp_financials','read'], ['billing','read'], ['crm','search']]
    else null end;
  if v_pairs is null then return jsonb_build_object('ok', false, 'error', 'unknown_domain', 'detail', 'domain must be one of: support, technical, sales, finance'); end if;

  foreach v_pair slice 1 in array v_pairs loop
    insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_category, permission, granted_by, note)
    values (v_tenant, p_subject_kind, p_subject_id, 'category', v_pair[1], v_pair[2], null, 'seeded default (' || p_domain || ') — editable like any grant')
    on conflict (tenant_id, subject_kind, subject_id, resource_kind, coalesce(resource_id::text, resource_category)) do nothing;
    if found then v_seeded := v_seeded + 1; end if;
  end loop;

  begin
  perform append_audit_event(v_tenant, 'DreamTeam', 'system',
    'Default data-access grants seeded for ' || coalesce(v_label, 'subject') || ' (' || p_domain || ' domain): ' || v_seeded || ' category grant(s). No financial, billing or payroll access is ever granted by default.',
    'access_control', jsonb_build_object('kind', 'access_grant_changed', 'seeded', v_seeded, 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_label, 'domain', p_domain));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'seeded', v_seeded, 'domain', p_domain);
end; $function$;

CREATE OR REPLACE FUNCTION public.send_human_reply(p_conversation_id uuid, p_content text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_id uuid;
begin
  if coalesce(trim(p_content), '') = '' then raise exception 'empty_message'; end if;
  v_tenant := _assert_conv_member(p_conversation_id);
  insert into de_messages (tenant_id, conversation_id, role, content, confidence, escalated, delivery)
  values (v_tenant, p_conversation_id, 'assistant', p_content, 100, false, 'sent')
  returning id into v_id;
  update de_conversations set owner_user_id = coalesce(owner_user_id, auth.uid()), status = 'human_owned', last_message_at = now()
  where id = p_conversation_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_access_grant(p_subject_kind text, p_subject_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_category text, p_permission text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_user uuid := auth.uid(); v_role text; v_is_active boolean; v_before text; v_grant_id uuid; v_subject_label text; v_resource_label text;
begin
  if v_user is not null then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'no_tenant'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.'); end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.');
  else
    select tenant_id into v_tenant from digital_employees where id = p_subject_id;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;
  end if;

  if p_subject_kind in ('de', 'specialist') then
    select name into v_subject_label from digital_employees where id = p_subject_id and tenant_id = v_tenant;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
  end if;
  if v_subject_label is null then return jsonb_build_object('ok', false, 'error', 'subject_not_in_tenant'); end if;

  if p_resource_kind = 'connector' then
    select display_name into v_resource_label from connectors where id = p_resource_id and tenant_id = v_tenant;
    if v_resource_label is null then return jsonb_build_object('ok', false, 'error', 'connector_not_in_tenant'); end if;
  elsif p_resource_kind = 'category' then
    v_resource_label := 'all ' || p_resource_category || ' systems';
  else
    return jsonb_build_object('ok', false, 'error', 'bad_resource_kind');
  end if;

  if access_permission_level(p_permission) = 0 then return jsonb_build_object('ok', false, 'error', 'bad_permission'); end if;

  select permission into v_before from data_access_grants
   where tenant_id = v_tenant and subject_kind = p_subject_kind and subject_id = p_subject_id and resource_kind = p_resource_kind
     and coalesce(resource_id::text, resource_category) = coalesce(p_resource_id::text, p_resource_category);

  insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_id, resource_category, permission, granted_by, note)
  values (v_tenant, p_subject_kind, p_subject_id, p_resource_kind,
     case when p_resource_kind = 'connector' then p_resource_id else null end,
     case when p_resource_kind = 'category' then p_resource_category else null end,
     p_permission, v_user, coalesce(p_note, ''))
  on conflict (tenant_id, subject_kind, subject_id, resource_kind, coalesce(resource_id::text, resource_category))
  do update set permission = excluded.permission, granted_by = excluded.granted_by, note = excluded.note, updated_at = now()
  returning id into v_grant_id;

  perform append_audit_event(v_tenant,
    coalesce((select full_name from profiles where user_id = v_user), 'service'),
    case when v_user is null then 'system' else 'human' end,
    'Data access grant changed — ' || v_subject_label || ' on ' || v_resource_label || ': ' || coalesce(v_before, 'none') || ' → ' || p_permission ||
      case when coalesce(p_note, '') <> '' then ' (' || p_note || ')' else '' end,
    'access_control', jsonb_build_object('kind', 'access_grant_changed', 'grant_id', v_grant_id, 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_subject_label,
      'resource_kind', p_resource_kind, 'resource_id', p_resource_id, 'resource_category', p_resource_category, 'resource_label', v_resource_label, 'before', v_before, 'after', p_permission));
  return jsonb_build_object('ok', true, 'grant_id', v_grant_id, 'before', v_before, 'after', p_permission);
end; $function$;

CREATE OR REPLACE FUNCTION public.set_connector_ingest_config(p_connector_id uuid, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null or v_tenant <> auth_tenant_id()
     or not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'only workspace owners/admins can change a connector''s ingest settings';
  end if;
  update connectors
     set config = coalesce(config, '{}'::jsonb) || jsonb_build_object('ingest', coalesce(p_config, '{}'::jsonb))
   where id = p_connector_id;
end $function$;

CREATE OR REPLACE FUNCTION public.set_connector_schedule(p_connector_id uuid, p_enabled boolean, p_interval_mins integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM connectors WHERE id = p_connector_id;
  IF v_tenant IS NULL OR v_tenant IS DISTINCT FROM public.auth_tenant_id()
     OR NOT public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  UPDATE connectors
     SET scheduled_sync_enabled = coalesce(p_enabled, false),
         sync_interval_mins     = greatest(60, coalesce(p_interval_mins, 1440))
   WHERE id = p_connector_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.set_connector_secret(p_connector_id uuid, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null then
    raise exception 'connector not found';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not (v_tenant = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin']))
  then
    raise exception 'only workspace owners/admins can set a connector''s credential';
  end if;

  insert into connector_secrets (connector_id, secret)
  values (p_connector_id, p_secret)
  on conflict (connector_id) do update
    set secret = excluded.secret, updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_connector_secret_sysadmin(p_connector_id uuid, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare v_existing uuid;
begin
  select secret_id into v_existing from connector_secrets where connector_id = p_connector_id;
  if v_existing is null then
    insert into connector_secrets (connector_id, secret_id, updated_at)
      values (p_connector_id, vault.create_secret(p_secret, 'connector_secret:' || p_connector_id, 'OAuth tokens via oauth-callback'), now());
  else
    perform vault.update_secret(v_existing, p_secret);
    update connector_secrets set updated_at = now() where connector_id = p_connector_id;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.set_conversation_fact(p_tenant_id uuid, p_conversation_id uuid, p_fact_key text, p_fact_value jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_id uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_memory') then
    return null;
  end if;

  insert into conversation_facts (tenant_id, conversation_id, fact_key, fact_value)
  values (p_tenant_id, p_conversation_id, p_fact_key, p_fact_value)
  on conflict (conversation_id, fact_key) do update set
    fact_value = excluded.fact_value,
    updated_at = now()
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_config(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid, p_config jsonb)
 RETURNS TABLE(config_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, schema_id uuid, data jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config_id UUID;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO de_config (config_id, tenant_id, entity_kind, entity_id, data, updated_by)
  VALUES (gen_random_uuid(), p_tenant_id, p_entity_kind, p_entity_id, p_config, auth.uid())
  ON CONFLICT (tenant_id, entity_kind, entity_id)
  DO UPDATE SET data = p_config, updated_at = NOW(), updated_by = auth.uid()
  RETURNING de_config.config_id INTO v_config_id;
  RETURN QUERY SELECT * FROM de_config dc WHERE dc.config_id = v_config_id;
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_custom_escalation_rules(p_de_id uuid, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN RAISE EXCEPTION 'insufficient_role'; END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;
  IF jsonb_typeof(p_rules) <> 'array' THEN RAISE EXCEPTION 'rules_must_be_an_array'; END IF;

  INSERT INTO de_escalation_rules (tenant_id, de_id, custom_rules, updated_by, updated_at)
  VALUES (v_tenant, p_de_id, p_rules, auth.uid(), now())
  ON CONFLICT (de_id) DO UPDATE
    SET custom_rules = excluded.custom_rules, updated_by = excluded.updated_by, updated_at = now();

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human', 'Escalation rules updated', 'config_change',
    jsonb_build_object('de_id', p_de_id, 'rule_count', jsonb_array_length(p_rules))
  );
  RETURN jsonb_build_object('ok', true, 'rule_count', jsonb_array_length(p_rules));
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_escalation_rules(p_de_id uuid DEFAULT NULL::uuid, p_frustration_threshold integer DEFAULT NULL::integer, p_topics text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de_name text := 'workspace default';
  v_topics text[] := coalesce(p_topics, '{}'::text[]);
begin
  if p_frustration_threshold is not null and (p_frustration_threshold < 0 or p_frustration_threshold > 100) then
    raise exception 'frustration threshold must be between 0 and 100';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set escalation rules';
  end if;

  if p_de_id is not null then
    select name into v_de_name from digital_employees where id = p_de_id and tenant_id = v_tenant;
    if v_de_name is null then raise exception 'employee not found in this workspace'; end if;
  end if;

  if p_frustration_threshold is null and array_length(v_topics, 1) is null then
    delete from de_escalation_rules
    where tenant_id = v_tenant and coalesce(de_id::text, '') = coalesce(p_de_id::text, '');
    perform append_audit_event_internal(
      v_tenant, 'You', 'human',
      format('Escalation rules for %s cleared — falls back to the shared default', v_de_name),
      'config_change',
      jsonb_build_object('kind', 'escalation_rules_cleared', 'de_id', p_de_id)
    );
    return jsonb_build_object('ok', true, 'cleared', true);
  end if;

  insert into de_escalation_rules (tenant_id, de_id, frustration_threshold, always_escalate_topics, updated_by)
  values (v_tenant, p_de_id, p_frustration_threshold, v_topics, auth.uid())
  on conflict (tenant_id, coalesce(de_id::text, ''))
  do update set frustration_threshold = excluded.frustration_threshold,
                always_escalate_topics = excluded.always_escalate_topics,
                updated_by = excluded.updated_by,
                updated_at = now();

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Escalation rules for %s set — frustration threshold %s, %s always-escalate topic(s)',
      v_de_name,
      coalesce(p_frustration_threshold::text, 'inherited'),
      coalesce(array_length(v_topics, 1), 0)),
    'config_change',
    jsonb_build_object('kind', 'escalation_rules_set', 'de_id', p_de_id,
      'frustration_threshold', p_frustration_threshold, 'topics', v_topics)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_external_reply_mode(p_de_id uuid, p_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_mode not in ('draft', 'auto') then raise exception 'mode must be draft or auto'; end if;
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'digital_employee_not_found'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  update digital_employees set external_reply_mode = p_mode where id = p_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_kpi(p_de_id uuid, p_metric_key text, p_name text, p_target numeric, p_direction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de_name text;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set KPIs';
  end if;
  select name into v_de_name from digital_employees
  where id = p_de_id and tenant_id = v_tenant and lifecycle_status not in ('retired', 'archived');
  if v_de_name is null then raise exception 'employee not found in this workspace (or retired)'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();

  if p_target is null then
    delete from de_kpis where tenant_id = v_tenant and de_id = p_de_id and metric_key = p_metric_key;
    perform append_audit_event_internal(
      v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
      format('%s KPI removed (%s)', v_de_name, p_metric_key),
      'config_change',
      jsonb_build_object('kind', 'de_kpi_removed', 'de_id', p_de_id, 'metric_key', p_metric_key)
    );
    return jsonb_build_object('ok', true, 'removed', true);
  end if;

  if p_direction not in ('higher', 'lower') then raise exception 'direction must be higher or lower'; end if;
  if p_name is null or trim(p_name) = '' then raise exception 'a KPI needs a name'; end if;

  insert into de_kpis (tenant_id, de_id, name, metric_key, target, direction, owner_user_id)
  values (v_tenant, p_de_id, trim(p_name), p_metric_key, p_target, p_direction, auth.uid())
  on conflict (tenant_id, de_id, metric_key)
  do update set name = excluded.name, target = excluded.target, direction = excluded.direction;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s KPI set — "%s": %s %s %s', v_de_name, trim(p_name), p_metric_key,
      case when p_direction = 'higher' then '≥' else '≤' end, p_target),
    'config_change',
    jsonb_build_object('kind', 'de_kpi_set', 'de_id', p_de_id, 'metric_key', p_metric_key, 'target', p_target)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_mission_state(p_mission_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_status text; v_next text;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  SELECT status INTO v_status FROM de_missions
   WHERE id = p_mission_id AND tenant_id = v_tenant FOR UPDATE;
  IF v_status IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  v_next := CASE
    WHEN p_action = 'pause'  AND v_status IN ('approved','running') THEN 'paused'
    WHEN p_action = 'resume' AND v_status = 'paused'                THEN 'running'
    WHEN p_action = 'cancel' AND v_status IN ('draft','awaiting_approval',
                                              'approved','running','paused')
                                                                    THEN 'cancelled'
    ELSE NULL END;
  IF v_next IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_transition',
                              'from', v_status, 'action', p_action);
  END IF;
  UPDATE de_missions SET status = v_next, updated_at = now(),
         finished_at = CASE WHEN v_next = 'cancelled' THEN now() ELSE finished_at END
   WHERE id = p_mission_id;

  IF v_next = 'paused' THEN
    UPDATE work_watchers SET active = false, updated_at = now()
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
  ELSIF v_next = 'running' AND p_action = 'resume' THEN
    UPDATE work_watchers SET active = true, updated_at = now()
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
  ELSIF v_next = 'cancelled' THEN
    -- stop future ticks FIRST (matches cascade-cleans work_watcher_matches),
    -- then unwind queued/open work — same order the adversary asked for.
    DELETE FROM work_watchers
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
    UPDATE de_work_items w SET status = 'cancelled', updated_at = now()
      FROM de_objectives o
     WHERE w.objective_id = o.id AND o.mission_id = p_mission_id
       AND w.tenant_id = v_tenant AND w.status = 'queued';
    UPDATE de_objectives SET status = 'abandoned', updated_at = now()
     WHERE mission_id = p_mission_id AND status IN ('open','in_progress','blocked');
  END IF;
  RETURN jsonb_build_object('ok', true, 'status', v_next);
END $function$;

CREATE OR REPLACE FUNCTION public.set_de_objective_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null then
    if not exists (select 1 from de_objectives o join profiles p on p.user_id = auth.uid()
                    where o.id = p_id and (p.tenant_id = o.tenant_id or p.layer = 'platform')) then
      raise exception 'not authorized';
    end if;
  end if;
  update de_objectives set status = p_status, updated_at = now() where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_operate_login(p_system_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_existing uuid; v_new uuid;
BEGIN
  SELECT tenant_id, login_secret_id INTO v_tenant, v_existing
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF nullif(btrim(coalesce(p_secret,'')),'') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'secret_required');
  END IF;

  IF v_existing IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing, p_secret);
  ELSE
    v_new := vault.create_secret(p_secret, 'de_operate_login:' || p_system_id, 'DE Browser Operator UI login (mig 244)');
    UPDATE de_connected_systems SET login_secret_id = v_new WHERE id = p_system_id;
  END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.set_de_skill_proficiency(p_de_id uuid, p_skill_key text, p_proficiency integer, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_is_custom boolean;
  v_rater text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;

  SELECT (tenant_id IS NOT NULL) INTO v_is_custom
    FROM skill_catalog
   WHERE skill_key = p_skill_key AND (tenant_id IS NULL OR tenant_id = v_tenant);
  IF v_is_custom IS NULL THEN RAISE EXCEPTION 'unknown_skill: %', p_skill_key; END IF;

  -- The guarantee that makes built-in proficiency trustworthy.
  IF NOT v_is_custom THEN
    RAISE EXCEPTION 'builtin_skill_is_evidence_assessed: % cannot be set by hand', p_skill_key;
  END IF;

  IF p_proficiency IS NOT NULL AND (p_proficiency < 1 OR p_proficiency > 5) THEN
    RAISE EXCEPTION 'proficiency must be between 1 and 5';
  END IF;

  SELECT coalesce(full_name, 'a workspace admin') INTO v_rater FROM profiles WHERE user_id = auth.uid();

  INSERT INTO de_skills (tenant_id, de_id, skill_key, proficiency, sample_size, signal_value, detail, assessed_at)
  VALUES (
    v_tenant, p_de_id, p_skill_key, p_proficiency, 0, NULL,
    CASE WHEN p_proficiency IS NULL
      THEN 'Not rated yet — this skill is rated by a person, not measured automatically.'
      ELSE format('Rated %s by %s%s', p_proficiency, v_rater,
                  CASE WHEN coalesce(p_note,'') <> '' THEN ' — ' || p_note ELSE '' END)
    END,
    now()
  )
  ON CONFLICT (de_id, skill_key) DO UPDATE
    SET proficiency = excluded.proficiency,
        detail      = excluded.detail,
        assessed_at = now();

  RETURN jsonb_build_object('ok', true, 'skill_key', p_skill_key, 'proficiency', p_proficiency);
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_specialist(p_de_id uuid, p_rank smallint, p_specialist_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de digital_employees; v_sp digital_employees;
begin
  if p_rank not in (1, 2) then raise exception 'rank must be 1 (primary) or 2 (secondary)'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can assign specialists'; end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;

  if p_specialist_id is null then
    delete from de_specialist_assignments where tenant_id = v_tenant and de_id = p_de_id and rank = p_rank;
    perform append_audit_event_internal(v_tenant, 'You', 'human',
      format('%s''s %s specialist cleared', v_de.name, case when p_rank = 1 then 'primary' else 'secondary' end),
      'config_change', jsonb_build_object('kind', 'de_specialist_cleared', 'de_id', p_de_id, 'rank', p_rank));
    return jsonb_build_object('ok', true, 'cleared', true);
  end if;

  select * into v_sp from digital_employees where id = p_specialist_id and tenant_id = v_tenant and is_specialist = true;
  if v_sp.id is null then raise exception 'specialist not found in this workspace'; end if;

  delete from de_specialist_assignments where tenant_id = v_tenant and de_id = p_de_id and specialist_de_id = p_specialist_id and rank <> p_rank;

  insert into de_specialist_assignments (tenant_id, de_id, specialist_de_id, rank, created_by)
  values (v_tenant, p_de_id, p_specialist_id, p_rank, auth.uid())
  on conflict (tenant_id, de_id, rank)
  do update set specialist_de_id = excluded.specialist_de_id, created_by = excluded.created_by, created_at = now();

  perform append_audit_event_internal(v_tenant, 'You', 'human',
    format('%s assigned as %s''s %s specialist', coalesce(v_sp.persona_name, v_sp.name), v_de.name, case when p_rank = 1 then 'primary' else 'secondary' end),
    'config_change', jsonb_build_object('kind', 'de_specialist_assigned', 'de_id', p_de_id, 'specialist_de_id', p_specialist_id, 'rank', p_rank));
  return jsonb_build_object('ok', true, 'specialist', coalesce(v_sp.persona_name, v_sp.name), 'rank', p_rank);
end; $function$;

CREATE OR REPLACE FUNCTION public.set_de_supervisor(p_de_id uuid, p_enable boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'digital employee not found'; end if;
  if not (public.is_platform_admin()
          or (v_tenant = public.auth_tenant_id()
              and public.auth_has_tenant_role(array['tenant_owner','tenant_admin']))) then
    raise exception 'only a workspace owner/admin can designate a supervisor';
  end if;
  if p_enable then
    -- Clear the current supervisor first (the partial unique index would
    -- otherwise reject a second true row), then set this one.
    update digital_employees set is_supervisor = false
     where tenant_id = v_tenant and is_supervisor and id <> p_de_id;
    update digital_employees set is_supervisor = true where id = p_de_id;
  else
    update digital_employees set is_supervisor = false where id = p_de_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_doc_lifecycle(p_doc_id uuid, p_owner_user_id uuid DEFAULT NULL::uuid, p_review_interval_days integer DEFAULT NULL::integer, p_authority integer DEFAULT NULL::integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  UPDATE knowledge_docs SET
    owner_user_id        = p_owner_user_id,
    review_interval_days = CASE WHEN p_review_interval_days IS NULL THEN NULL
                                ELSE greatest(1, p_review_interval_days) END,
    authority            = CASE WHEN p_authority IS NULL THEN authority
                                ELSE greatest(0, least(100, p_authority)) END,
    expires_at           = p_expires_at,
    updated_at           = now()
   WHERE id = p_doc_id AND tenant_id = v_tenant;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.set_doc_scope(p_doc_id uuid, p_subjects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid(); v_caller_tenant uuid; v_is_active boolean;
  v_doc_tenant uuid; v_doc_title text; v_before text; v_after text; v_archetype text;
  v_subj jsonb; v_kind text; v_sid uuid; v_label text; v_labels text[] := '{}'; v_count integer := 0;
begin
  select tenant_id, title, visibility, share_archetype_key
    into v_doc_tenant, v_doc_title, v_before, v_archetype
    from knowledge_docs where id = p_doc_id;
  if v_doc_tenant is null then return jsonb_build_object('ok', false, 'error', 'doc_not_found'); end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_doc_tenant then return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.');
  end if;

  if p_subjects is null or jsonb_typeof(p_subjects) <> 'array' then return jsonb_build_object('ok', false, 'error', 'bad_subjects', 'detail', 'p_subjects must be a JSON array of {kind, id}.'); end if;

  for v_subj in select * from jsonb_array_elements(p_subjects) loop
    v_kind := v_subj->>'kind';
    begin v_sid := (v_subj->>'id')::uuid; exception when others then return jsonb_build_object('ok', false, 'error', 'bad_subject_id'); end;
    if v_kind in ('de', 'specialist') then
      select name into v_label from digital_employees where id = v_sid and tenant_id = v_doc_tenant;
    elsif v_kind = 'de_team' then
      -- 363: a team of employees is an audience. Still tenant-checked, so a
      -- team id from another workspace cannot be attached.
      select name into v_label from workforce_teams where id = v_sid and tenant_id = v_doc_tenant;
    else
      return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
    end if;
    if v_label is null then return jsonb_build_object('ok', false, 'error', 'subject_not_in_tenant', 'detail', v_kind || ' ' || v_sid || ' is not in this workspace.'); end if;
    v_labels := array_append(v_labels, v_label || ' (' || v_kind || ')');
    v_count := v_count + 1;
  end loop;

  delete from knowledge_doc_scopes where doc_id = p_doc_id;
  for v_subj in select * from jsonb_array_elements(p_subjects) loop
    insert into knowledge_doc_scopes (tenant_id, doc_id, subject_kind, subject_id)
    values (v_doc_tenant, p_doc_id, v_subj->>'kind', (v_subj->>'id')::uuid)
    on conflict (doc_id, subject_kind, subject_id) do nothing;
  end loop;

  -- 363: THE CLOBBER FIX. Clearing the subject list on an archetype-shared
  -- document used to drop it to 'tenant', silently WIDENING its audience to
  -- every employee. It now returns to 'role', which is where it came from.
  v_after := case
    when v_count > 0 then 'scoped'
    when v_before = 'role' and v_archetype is not null then 'role'
    else 'tenant' end;
  update knowledge_docs set visibility = v_after where id = p_doc_id;

  begin
    perform append_audit_event(v_doc_tenant,
      coalesce((select full_name from profiles where user_id = v_user), 'service'),
      case when v_user is null then 'system' else 'human' end,
      'Knowledge scope changed — "' || v_doc_title || '": ' || v_before || ' → ' || v_after ||
        case when v_count > 0 then ' (only ' || array_to_string(v_labels, ', ') || ' will use this document)'
             when v_after = 'role' then ' (shared with the ' || v_archetype || ' role)'
             else ' (all digital employees will use this document)' end,
      'access_control', jsonb_build_object('kind', 'knowledge_scope_changed', 'doc_id', p_doc_id, 'doc_title', v_doc_title, 'before', v_before, 'after', v_after, 'subjects', p_subjects, 'subject_labels', v_labels));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'visibility', v_after, 'subjects', v_count);
end; $function$;

CREATE OR REPLACE FUNCTION public.set_improvement_publish_scope(p_improvement_id uuid, p_scope text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp de_improvements;
begin
  if p_scope not in ('de','role') then raise exception 'invalid scope %', p_scope; end if;
  select * into imp from de_improvements where id = p_improvement_id for update;
  if imp.id is null then raise exception 'improvement not found'; end if;
  if auth.uid() is not null and not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = imp.tenant_id)) then
    raise exception 'not authorized';
  end if;
  if imp.status = 'applied' then raise exception 'improvement already published — scope is locked'; end if;
  if imp.status = 'rejected' then raise exception 'improvement was rejected'; end if;
  update de_improvements set publish_scope = p_scope, updated_at = now() where id = p_improvement_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_knowledge_freshness_config(p_key text, p_value numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin() THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;
  IF p_key NOT IN ('knowledge.freshness_weight', 'knowledge.freshness_halflife_days', 'knowledge.freshness_expired_penalty') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_key');
  END IF;
  IF p_value IS NULL OR p_value < 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_value'); END IF;
  -- platform_config.value is a plain text column; store the number as text.
  INSERT INTO platform_config (key, value) VALUES (p_key, p_value::text)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
  RETURN jsonb_build_object('ok', true, 'key', p_key, 'value', p_value);
END $function$;

CREATE OR REPLACE FUNCTION public.set_knowledge_lifecycle(p_doc_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_doc knowledge_docs;
  v_level int;
  v_needed int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_status NOT IN ('draft','in_review','published','archived') THEN
    RAISE EXCEPTION 'unknown lifecycle state: %', p_status;
  END IF;

  SELECT * INTO v_doc FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant;
  IF v_doc.id IS NULL THEN RAISE EXCEPTION 'document_not_found'; END IF;

  -- Publishing and archiving are governance acts; drafting is authorship.
  v_needed := CASE WHEN p_status IN ('published','archived') THEN 4 ELSE 2 END;
  v_level := knowledge_effective_level(p_doc_id);
  IF v_level < v_needed THEN
    RAISE EXCEPTION 'insufficient_permission: % requires %, you have level %',
      p_status, CASE WHEN v_needed = 4 THEN 'publisher' ELSE 'contributor' END, v_level;
  END IF;

  UPDATE knowledge_docs SET lifecycle_status = p_status WHERE id = p_doc_id;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('%s moved to %s — %s', left(coalesce(v_doc.title,'a document'), 80), p_status, coalesce(p_note,'no note')),
    'approval',
    jsonb_build_object('doc_id', p_doc_id, 'from', v_doc.lifecycle_status, 'to', p_status));

  RETURN jsonb_build_object('ok', true, 'from', v_doc.lifecycle_status, 'to', p_status);
END $function$;

CREATE OR REPLACE FUNCTION public.set_learned_action_status(p_tenant_id uuid, p_action_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int;
BEGIN
  IF p_status NOT IN ('active', 'draft', 'disabled') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  -- Publishing hands a write tool to the whole workforce: owners/admins only.
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = auth.uid() AND p.tenant_id = p_tenant_id
       AND (p.layer = 'platform' OR p.role IN ('tenant_owner', 'tenant_admin'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  UPDATE action_definitions
     SET status = p_status, updated_at = now()
   WHERE id = p_action_id AND tenant_id = p_tenant_id
     AND scope = 'tenant' AND provider = 'learned_http';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found_or_not_learned'); END IF;
  RETURN jsonb_build_object('ok', true, 'status', p_status);
END $function$;

CREATE OR REPLACE FUNCTION public.set_oauth_app(p_provider text, p_client_id text, p_client_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_platform_admin() then
    raise exception 'only platform admins can configure OAuth apps';
  end if;
  if p_provider !~ '^[a-z0-9_]+$' then
    raise exception 'invalid provider';
  end if;
  perform platform_config_set(jsonb_build_object(
    'oauth:' || p_provider || ':client_id', coalesce(p_client_id, ''),
    'oauth:' || p_provider || ':client_secret', coalesce(p_client_secret, '')
  ));
end $function$;

CREATE OR REPLACE FUNCTION public.set_onboarding_project_status(p_project_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj onboarding_projects;
begin
  if p_status not in ('active', 'on_hold', 'cancelled') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_proj.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;
  if v_proj.status = 'completed' then
    return jsonb_build_object('error', 'project_completed');
  end if;
  if v_proj.status = p_status then
    return jsonb_build_object('status', p_status);
  end if;

  update onboarding_projects set status = p_status where id = p_project_id;

  perform append_audit_event_internal(
    v_proj.tenant_id, 'You', 'human',
    format('Onboarding project %s — %s', case p_status when 'cancelled' then 'cancelled'
           when 'on_hold' then 'put on hold' else 'reactivated' end, v_proj.name),
    'config_change',
    jsonb_build_object('kind', 'onboarding_project_' || p_status, 'project_id', p_project_id,
                       'old_status', v_proj.status, 'new_status', p_status));

  return jsonb_build_object('status', p_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_platform_capability_grant(p_target_user_id uuid, p_capability text, p_effect text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
  v_grant platform_capability_grants;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s permissions';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own permissions here';
  end if;
  if p_effect not in ('grant', 'deny') then
    raise exception 'effect must be grant or deny';
  end if;
  if p_capability not in (
    'tenants.view', 'tenants.manage', 'tenants.provision',
    'remote_access.use', 'remote_access.audit',
    'team.manage', 'billing.manage', 'support.cross_tenant'
  ) then
    raise exception 'unrecognized capability: %', p_capability;
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if p_capability = 'team.manage' and p_effect = 'deny'
     and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  insert into platform_capability_grants (user_id, capability, effect, granted_by, note)
  values (p_target_user_id, p_capability, p_effect, auth.uid(), coalesce(p_note, ''))
  on conflict (user_id, capability) do update
    set effect = excluded.effect, granted_by = excluded.granted_by,
        note = excluded.note, updated_at = now()
  returning * into v_grant;

  return jsonb_build_object('ok', true, 'grant', to_jsonb(v_grant));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_platform_team_active(p_target_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s active status';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own active status here';
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if not p_is_active and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  update profiles set is_active = p_is_active where user_id = p_target_user_id;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'is_active', p_is_active);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_rule_adjudicable(p_rule_id uuid, p_on boolean, p_justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule  guardrail_rules;
  v_actor text;
BEGIN
  SELECT * INTO v_rule FROM guardrail_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN RAISE EXCEPTION 'guardrail rule not found'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = auth.uid()
       AND (p.layer = 'platform'
            OR (p.tenant_id = v_rule.tenant_id AND p.role IN ('tenant_owner','tenant_admin'))))
  THEN RAISE EXCEPTION 'only workspace owners/admins can change what a machine may overrule'; END IF;

  IF v_rule.severity <> 'blocking' OR v_rule.rule_type NOT IN ('blocked_phrase','blocked_topic') THEN
    RAISE EXCEPTION 'only blocking phrase/topic rules can be adjudicated';
  END IF;

  IF p_on THEN
    IF p_justification IS NULL OR length(btrim(p_justification)) < 40 THEN
      RAISE EXCEPTION 'a written justification of at least 40 characters is required to let a machine overrule this rule';
    END IF;
    -- Compliance-pack rules are described by this product as un-toggleable.
    -- That promise now also covers "un-clearable": the same owner-only escape
    -- hatch detach_compliance_pack requires (160:108) applies here.
    IF v_rule.compliance_pack_key IS NOT NULL
       AND coalesce(current_setting('app.allow_compliance_change', true), '') <> 'on' THEN
      RAISE EXCEPTION 'rule "%" comes from the % compliance pack — making it machine-clearable is an explicit compliance decision and requires the owner override', v_rule.rule, v_rule.compliance_pack_key;
    END IF;

    INSERT INTO guardrail_rule_adjudicable (tenant_id, rule_id, granted_by, justification)
    VALUES (v_rule.tenant_id, p_rule_id, auth.uid(), btrim(p_justification))
    ON CONFLICT (tenant_id, rule_id) DO UPDATE
      SET justification = excluded.justification, granted_by = excluded.granted_by, granted_at = now();
  ELSE
    DELETE FROM guardrail_rule_adjudicable WHERE tenant_id = v_rule.tenant_id AND rule_id = p_rule_id;
  END IF;

  SELECT full_name INTO v_actor FROM profiles WHERE user_id = auth.uid();
  -- Same transaction as the row write: the grant and its record commit together.
  PERFORM append_audit_event_internal(
    v_rule.tenant_id, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s: guardrail rule "%s" %s machine-clearable',
           CASE WHEN p_on THEN 'GRANTED' ELSE 'REVOKED' END, v_rule.rule,
           CASE WHEN p_on THEN 'is now' ELSE 'is no longer' END),
    'guardrail_adjudication',
    jsonb_build_object('kind', CASE WHEN p_on THEN 'adjudicable_granted' ELSE 'adjudicable_revoked' END,
                       'rule_id', p_rule_id, 'rule', v_rule.rule, 'pattern', v_rule.pattern,
                       'compliance_pack_key', v_rule.compliance_pack_key,
                       'justification', btrim(coalesce(p_justification, '')))
  );
  RETURN jsonb_build_object('rule_id', p_rule_id, 'adjudicable', p_on);
END $function$;

CREATE OR REPLACE FUNCTION public.set_space_restricted(p_space_id uuid, p_restricted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_name text; v_reachable int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_collections
   WHERE id = p_space_id AND tenant_id = v_tenant AND is_space;
  IF v_name IS NULL THEN RAISE EXCEPTION 'space_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(p_space_id);
  IF v_my < 5 THEN
    RAISE EXCEPTION 'insufficient_permission: locking a space requires knowledge manager';
  END IF;

  UPDATE knowledge_collections SET is_restricted = p_restricted, updated_at = now()
   WHERE id = p_space_id;

  -- Locking a space with no explicit grants makes it reachable by nobody but
  -- platform staff. That is a legitimate thing to want, and a terrible thing to
  -- do BY ACCIDENT, so it is reported rather than silently done.
  v_reachable := 0;
  IF p_restricted THEN
    SELECT count(*) INTO v_reachable FROM knowledge_access_grants
     WHERE tenant_id = v_tenant AND resource_type = 'collection' AND resource_id = p_space_id;
  END IF;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('%s the space "%s"', CASE WHEN p_restricted THEN 'Restricted' ELSE 'Opened' END, v_name),
    'access_control',
    jsonb_build_object('space_id', p_space_id, 'restricted', p_restricted));

  RETURN jsonb_build_object('ok', true, 'restricted', p_restricted, 'explicit_grants', v_reachable);
END $function$;

CREATE OR REPLACE FUNCTION public.set_specialist_source_secret(p_source_id uuid, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_existing uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not exists (
    select 1 from specialist_sources s
    join digital_employees d on d.id = s.specialist_de_id
    join profiles p on p.tenant_id = d.tenant_id
    where s.id = p_source_id and p.user_id = auth.uid() and coalesce(p.is_active, true) = true
  ) then
    raise exception 'not a member of this source''s tenant';
  end if;

  select secret_id into v_existing from specialist_source_secrets where source_id = p_source_id;
  if v_existing is not null then
    perform vault.update_secret(v_existing, p_secret);
    update specialist_source_secrets set updated_at = now() where source_id = p_source_id;
  else
    insert into specialist_source_secrets (source_id, secret_id, updated_at)
    values (p_source_id, vault.create_secret(p_secret, 'specialist_source_secret:' || p_source_id, 'Set via set_specialist_source_secret'), now());
  end if;
end; $function$;

CREATE OR REPLACE FUNCTION public.set_support_conversation_state(p_conversation_id uuid, p_status text DEFAULT NULL::text, p_priority text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  v_tenant := _assert_conv_member(p_conversation_id);
  if p_status is not null and p_status not in ('ai_handling','needs_human','human_owned','resolved') then raise exception 'bad_status'; end if;
  if p_priority is not null and p_priority not in ('low','normal','high','urgent') then raise exception 'bad_priority'; end if;
  update de_conversations
    set status = coalesce(p_status, status), priority = coalesce(p_priority, priority), last_message_at = now()
  where id = p_conversation_id;
  if p_status = 'resolved' then
    update human_tasks
       set status = 'approved', decided_by = auth.uid(), decided_at = now(), updated_at = now()
     where tenant_id = v_tenant and related_table = 'de_conversations'
       and related_id = p_conversation_id and type = 'escalation' and status = 'pending';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_team_member_status(p_target_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own active status here';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s status';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner cannot be deactivated';
  end if;

  update profiles set is_active = p_is_active where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    case when p_is_active then 'Team member reactivated' else 'Team member deactivated' end,
    'config_change',
    jsonb_build_object('kind', 'team_status_change', 'target_user_id', p_target_user_id, 'is_active', p_is_active)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_branding(p_accent_hex text, p_surface_key text DEFAULT 'midnight'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_hex text;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF p_surface_key NOT IN ('midnight','graphite') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_surface');
  END IF;
  v_hex := nullif(lower(btrim(coalesce(p_accent_hex,''))), '');
  IF v_hex IS NOT NULL AND v_hex !~ '^#[0-9a-f]{6}$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'accent_must_be_hex6');
  END IF;
  INSERT INTO tenant_branding (tenant_id, accent_hex, surface_key, updated_at)
  VALUES (v_tenant, v_hex, p_surface_key, now())
  ON CONFLICT (tenant_id) DO UPDATE
    SET accent_hex = excluded.accent_hex, surface_key = excluded.surface_key, updated_at = now();
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_comms_settings(p_from_email text, p_from_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin_role_required');
  END IF;
  IF coalesce(p_from_email,'') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_email');
  END IF;
  INSERT INTO tenant_comms_settings (tenant_id, from_email, from_name, updated_by, updated_at)
  VALUES (v_tenant, lower(trim(p_from_email)), nullif(trim(coalesce(p_from_name,'')),''), auth.uid(), now())
  ON CONFLICT (tenant_id) DO UPDATE SET from_email = excluded.from_email, from_name = excluded.from_name, updated_by = excluded.updated_by, updated_at = now();
  RETURN jsonb_build_object('ok', true, 'from_email', lower(trim(p_from_email)));
END; $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_feature_override(p_tenant_id uuid, p_feature_key text, p_enabled boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may set a tenant feature override';
  end if;

  if not exists (select 1 from feature_registry where key = p_feature_key) then
    raise exception 'unknown feature key: %', p_feature_key;
  end if;

  insert into tenant_feature_overrides (tenant_id, feature_key, enabled, set_by, note, updated_at)
  values (p_tenant_id, p_feature_key, p_enabled, auth.uid(), p_note, now())
  on conflict (tenant_id, feature_key)
  do update set enabled = excluded.enabled, set_by = excluded.set_by, note = excluded.note, updated_at = now();

  perform reconcile_tenant_feature(p_tenant_id, p_feature_key, p_enabled);

  if exists (select 1 from profiles where user_id = auth.uid() and tenant_id = p_tenant_id) then
    perform append_audit_event(
      p_tenant_id, 'Platform admin', 'human',
      format('Feature "%s" set to %s for this tenant', p_feature_key, case when p_enabled then 'ON' else 'OFF' end),
      'config_change',
      jsonb_build_object('kind', 'tenant_feature_override_set', 'feature_key', p_feature_key,
        'enabled', p_enabled, 'set_by', auth.uid(), 'note', p_note)
    );
  end if;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_ip_allowlist_enabled(p_tenant_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can change the IP allowlist';
  end if;
  if p_enabled and not exists (select 1 from tenant_ip_allowlist_entries where tenant_id = p_tenant_id) then
    raise exception 'add at least one IP range before turning this on -- otherwise every sign-in would be blocked';
  end if;

  insert into tenant_ip_allowlists (tenant_id, enabled, updated_by)
  values (p_tenant_id, p_enabled, auth.uid())
  on conflict (tenant_id) do update set enabled = excluded.enabled, updated_at = now(), updated_by = excluded.updated_by;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('IP allowlist %s', case when p_enabled then 'enabled' else 'disabled' end),
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_toggled', 'enabled', p_enabled)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_monthly_budget(p_tenant_id uuid, p_budget integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_max_self_serve_budget constant integer := 10000000; -- 100x the 100k default; revisit once real plan-based billing exists
  v_caller_tenant uuid;
  v_role text;
  v_is_active boolean;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.manage');
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s budget cannot be changed';
  end if;
  if p_budget is null or p_budget < 0 then
    raise exception 'budget must be a non-negative number';
  end if;

  if not v_is_platform then
    select tenant_id, role, coalesce(is_active, true) into v_caller_tenant, v_role, v_is_active
    from profiles where user_id = auth.uid();

    if v_caller_tenant is distinct from p_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only an owner or admin of this organization may change the token budget';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;

    -- Self-serve (non-platform-admin) callers are capped. A platform
    -- admin (tenants.manage) can still set a higher budget by hand for
    -- a legitimate enterprise customer who genuinely needs more.
    if p_budget > v_max_self_serve_budget then
      raise exception 'requested budget exceeds the self-serve limit (%); contact DreamTeam AI to raise it', v_max_self_serve_budget;
    end if;
  end if;

  update tenants set monthly_token_budget = p_budget, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'monthly_token_budget', p_budget);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_plan(p_tenant_id uuid, p_plan text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_found boolean;
  v_new_budget integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant-management access may change a tenant''s plan';
  end if;
  if p_plan not in ('starter', 'growth', 'enterprise') then
    raise exception 'unrecognized plan: %', p_plan;
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s plan cannot be changed';
  end if;

  select true into v_found from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  v_new_budget := case p_plan
    when 'starter' then 100000
    when 'growth' then 500000
    when 'enterprise' then 2000000
  end;

  update tenants set plan = p_plan, monthly_token_budget = v_new_budget, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'plan', p_plan, 'monthly_token_budget', v_new_budget);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_self_serve(p_tenant_id uuid, p_allow boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_found boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant-management access may change this setting';
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s settings cannot be changed';
  end if;

  select true into v_found from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  update tenants set allow_self_serve_subtenants = p_allow, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'allow_self_serve_subtenants', p_allow);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_session_policy(p_tenant_id uuid, p_timeout_minutes integer, p_mfa_required boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can change the session policy';
  end if;
  if p_timeout_minutes not in (60, 240, 480, 1440) then
    raise exception 'timeout_minutes must be one of 60, 240, 480, 1440';
  end if;

  insert into tenant_session_policies (tenant_id, timeout_minutes, mfa_required, updated_by)
  values (p_tenant_id, p_timeout_minutes, p_mfa_required, auth.uid())
  on conflict (tenant_id) do update
    set timeout_minutes = excluded.timeout_minutes,
        mfa_required = excluded.mfa_required,
        updated_at = now(),
        updated_by = excluded.updated_by;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('Session policy updated: %s min timeout, MFA %s', p_timeout_minutes, case when p_mfa_required then 'required' else 'optional' end),
    'config_change',
    jsonb_build_object('kind', 'session_policy_updated', 'timeout_minutes', p_timeout_minutes, 'mfa_required', p_mfa_required)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_status(p_tenant_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_found boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant-management access may change a tenant''s status';
  end if;
  if p_status not in ('active', 'trial', 'suspended') then
    raise exception 'unrecognized tenant status: %', p_status;
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s status cannot be changed';
  end if;

  select true into v_found from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  update tenants set status = p_status, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'status', p_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_widget_key_de(p_widget_key_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_n int;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'key_not_found'); END IF;

  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles p WHERE p.user_id = auth.uid() AND p.tenant_id = v_tenant
      AND (p.layer = 'platform' OR p.role IN ('tenant_owner', 'tenant_admin'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  IF p_de_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM digital_employees d WHERE d.id = p_de_id AND d.tenant_id = v_tenant
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'de_not_in_tenant');
  END IF;

  UPDATE widget_keys SET de_id = p_de_id WHERE id = p_widget_key_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_n > 0, 'de_id', p_de_id);
END $function$;

CREATE OR REPLACE FUNCTION public.set_workforce_team_member(p_team_id uuid, p_de_id uuid, p_fallback_rank integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_team workforce_teams;
  v_de_name text;
  v_holder text;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can manage workforce teams';
  end if;

  select * into v_team from workforce_teams where id = p_team_id and tenant_id = v_tenant;
  if v_team.id is null then raise exception 'team not found in this workspace'; end if;

  select name into v_de_name from digital_employees
  where id = p_de_id and tenant_id = v_tenant and lifecycle_status not in ('retired', 'archived');
  if v_de_name is null then raise exception 'employee not found in this workspace (or retired)'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();

  if p_fallback_rank is null then
    delete from workforce_team_members where team_id = p_team_id and de_id = p_de_id;
    perform append_audit_event_internal(
      v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
      format('%s removed from workforce team "%s"', v_de_name, v_team.name),
      'config_change',
      jsonb_build_object('kind', 'workforce_team_member_removed', 'team_id', p_team_id, 'de_id', p_de_id)
    );
    return jsonb_build_object('ok', true, 'removed', true);
  end if;

  if p_fallback_rank < 1 then raise exception 'fallback rank must be 1 or higher (1 = primary responder)'; end if;

  -- Explicit rank-conflict message beats a raw unique-violation error.
  select de.name into v_holder
  from workforce_team_members m join digital_employees de on de.id = m.de_id
  where m.team_id = p_team_id and m.fallback_rank = p_fallback_rank and m.de_id <> p_de_id;
  if v_holder is not null then
    raise exception 'rank % is already held by % — move them first or pick another rank', p_fallback_rank, v_holder;
  end if;

  insert into workforce_team_members (tenant_id, team_id, de_id, fallback_rank)
  values (v_tenant, p_team_id, p_de_id, p_fallback_rank)
  on conflict (team_id, de_id) do update set fallback_rank = excluded.fallback_rank;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s set as %s on workforce team "%s"', v_de_name,
      case when p_fallback_rank = 1 then 'primary responder' else format('backup #%s', p_fallback_rank - 1) end,
      v_team.name),
    'config_change',
    jsonb_build_object('kind', 'workforce_team_member_set', 'team_id', p_team_id, 'de_id', p_de_id, 'fallback_rank', p_fallback_rank)
  );
  return jsonb_build_object('ok', true, 'fallback_rank', p_fallback_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION public.settle_billable_outcomes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  with due as (
    select r.id,
      (exists (select 1 from billable_outcomes e where e.conversation_id = r.conversation_id and e.kind='escalation')
       or exists (select 1 from de_conversations c where c.id = r.conversation_id
                    and (c.csat_score = -1 or c.status = 'human_owned'))
       or exists (select 1 from de_messages m where m.conversation_id = r.conversation_id
                    and m.role = 'user' and m.created_at > r.occurred_at)   -- customer wrote back = not resolved
      ) as reversed
    from billable_outcomes r
    where r.kind = 'resolution' and r.status = 'pending' and r.settle_after <= now()
  )
  update billable_outcomes b set
    status           = case when d.reversed then 'unbilled' else 'confirmed' end,
    billable         = not d.reversed,
    unit_price_cents = case when d.reversed then 0 else b.unit_price_cents end,
    settled_at       = now()
  from due d where b.id = d.id;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.snapshot_all_de_kpi_readings()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d record; v_total int := 0; v_des int := 0;
begin
  for d in
    select id from digital_employees
     where coalesce(lifecycle_status, 'active') not in ('retired', 'archived')
  loop
    begin
      v_total := v_total + public.snapshot_de_kpi_readings(d.id);   -- per-DE isolation
      v_des := v_des + 1;
    exception when others then
      raise warning 'snapshot_de_kpi_readings(%) failed: %', d.id, sqlerrm;
    end;
  end loop;
  -- Retention: system snapshots are cheap to recompute; keep 180 days.
  delete from de_kpi_readings where source = 'system' and as_of < current_date - 180;
  return jsonb_build_object('des', v_des, 'written', v_total);
end $function$;

CREATE OR REPLACE FUNCTION public.snapshot_de_kpi_readings(p_de_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid; m record; v_csat numeric; v_vals jsonb;
  rec record; v_last numeric; v_written int := 0;
begin
  -- Cron-safe: resolves tenant from the DE; never calls auth.uid()/auth_tenant_id().
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return 0; end if;

  -- Platform conversation/perf arm — reproduced VERBATIM from get_de_kpi_status
  -- (mig 263:58-72). CSAT sample count is unused here (no fallback), so omitted.
  select * into m from get_de_performance_metrics(v_tenant, 13) where de_id = p_de_id;
  select round(100.0 * count(*) filter (where csat_score = 1) / nullif(count(*) filter (where csat_submitted_at is not null), 0), 1)
    into v_csat
  from de_conversations where tenant_id = v_tenant and de_id = p_de_id;

  v_vals := jsonb_strip_nulls(jsonb_build_object(
    'resolution_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.resolution_rate end,
    'avg_confidence',         case when coalesce(m.total_decisions, 0) >= 1 then m.avg_confidence end,
    'escalation_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.escalation_rate end,
    'error_rate',             case when coalesce(m.total_runs, 0) >= 1 then m.error_rate end,
    'csat_pct',               v_csat,
    'high_frustration_count', case when coalesce(m.total_decisions, 0) >= 1 then m.high_frustration_count::numeric end,
    'total_decisions',        coalesce(m.total_decisions, 0)::numeric
  ));

  -- Target set S = configured KPI targets ∪ active metric_threshold watcher keys
  -- for this DE. For each, resolve the PLATFORM value (computed v_vals, else the
  -- action arm from mig 263:85-100) — NEVER the manual fallback.
  for rec in
    with s as (
      select distinct mk from (
        select metric_key mk from de_kpis where de_id = p_de_id and metric_key is not null
        union
        select config->>'metric_key' from work_watchers
          where de_id = p_de_id and kind = 'metric_threshold' and active
            and config->>'metric_key' is not null
      ) u
    )
    select s.mk as metric_key,
           coalesce(
             (v_vals->>s.mk)::numeric,
             (select case when coalesce(cat.source_config->>'agg', 'count') = 'auto_rate'
                          then round(100.0 * count(*) filter (where ae.decision = 'auto_executed') / nullif(count(*), 0), 1)
                          else count(*)::numeric end
                from action_executions ae
                left join action_definitions ad on ad.id = ae.action_definition_id
               where cat.source = 'action'
                 and ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
                 and ae.rollback_of is null and ae.created_at >= now() - interval '91 days'
                 and (coalesce(cat.source_config->>'category', '') = '' or ad.category = cat.source_config->>'category')
                 and (coalesce(cat.source_config->>'action_label', '') = '' or ad.label = cat.source_config->>'action_label'))
           ) as val
    from s
    left join kpi_metric_catalog cat
      on cat.metric_key = s.mk and (cat.tenant_id is null or cat.tenant_id = v_tenant)
  loop
    if rec.val is null then continue; end if;                      -- fix #2: NOT NULL guard
    select value into v_last from de_kpi_readings
      where de_id = p_de_id and metric_key = rec.metric_key and source = 'system'
      order by as_of desc, created_at desc limit 1;
    if v_last is not distinct from rec.val then continue; end if;  -- fix #1: value-change only
    insert into de_kpi_readings (tenant_id, de_id, metric_key, value, as_of, recorded_by, source)
    values (v_tenant, p_de_id, rec.metric_key, rec.val, current_date, null, 'system')
    on conflict (de_id, metric_key, as_of) where source = 'system'  -- fix #2: partial-index predicate
      do update set value = excluded.value, created_at = now();
    v_written := v_written + 1;
  end loop;
  return v_written;
end $function$;

CREATE OR REPLACE FUNCTION public.sql_op(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' WHEN 'gt' THEN '>'
               WHEN 'gte' THEN '>=' WHEN 'eq' THEN '=' WHEN 'neq' THEN '<>'
               ELSE '=' END $function$;

CREATE OR REPLACE FUNCTION public.stale_humanize_interval(p_span interval)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when extract(epoch from p_span) >= 86400 then
      round(extract(epoch from p_span) / 86400.0, 1)::text || ' day' || case when round(extract(epoch from p_span) / 86400.0, 1) = 1 then '' else 's' end
    when extract(epoch from p_span) >= 3600 then
      round(extract(epoch from p_span) / 3600.0, 1)::text || ' hour' || case when round(extract(epoch from p_span) / 3600.0, 1) = 1 then '' else 's' end
    else
      greatest(1, round(extract(epoch from p_span) / 60.0))::text || ' minute' ||
        case when greatest(1, round(extract(epoch from p_span) / 60.0)) = 1 then '' else 's' end
  end;
$function$;

CREATE OR REPLACE FUNCTION public.stale_upsert_escalation(p_tenant_id uuid, p_target_kind text, p_target_id uuid, p_tier text, p_task_title text, p_task_detail text, p_related_table text, p_related_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid;
  v_esc_id  uuid;
begin
  -- Cooldown/dedup: if an OPEN escalation already exists for this
  -- exact (tenant, target_kind, target_id, tier), do nothing — this
  -- is what stops the same stale item re-firing every 5-minute tick.
  if exists (
    select 1 from staleness_escalations
    where tenant_id = p_tenant_id and target_kind = p_target_kind
      and target_id = p_target_id and tier = p_tier and resolved_at is null
  ) then
    return null;
  end if;

  insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
  values (p_tenant_id, 'escalation', p_task_title, p_task_detail, 'system', p_related_table, p_related_id, 'pending')
  returning id into v_task_id;

  insert into staleness_escalations (tenant_id, target_kind, target_id, tier, human_task_id)
  values (p_tenant_id, p_target_kind, p_target_id, p_tier, v_task_id)
  returning id into v_esc_id;

  perform append_audit_event_internal(
    p_tenant_id, 'System', 'system',
    format('Staleness watchdog: %s escalation — %s', p_tier, p_task_title),
    'escalated',
    jsonb_build_object('kind', 'staleness_escalation', 'target_kind', p_target_kind,
                       'target_id', p_target_id, 'tier', p_tier, 'human_task_id', v_task_id)
  );

  return v_esc_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_gap_cluster_on_apply()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'applied' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.gap_cluster_id IS NOT NULL THEN
    UPDATE knowledge_gap_clusters
       SET fix_applied_at = coalesce(fix_applied_at, now()), updated_at = now()
     WHERE id = NEW.gap_cluster_id AND tenant_id = NEW.tenant_id;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.stamp_objective_mission_from_watcher()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_mid uuid; v_wid text;
BEGIN
  IF NEW.mission_id IS NULL AND jsonb_typeof(NEW.plan) = 'object' THEN
    v_wid := NEW.plan->>'watcher_id';
    IF v_wid ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT mission_id INTO v_mid FROM work_watchers
        WHERE id = v_wid::uuid AND tenant_id = NEW.tenant_id;
      IF v_mid IS NOT NULL THEN NEW.mission_id := v_mid; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.start_platform_remote_access(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session uuid := gen_random_uuid();
  v_operator_name text;
  v_tenant tenants;
begin
  if not resolve_platform_capability(auth.uid(), 'remote_access.use') then
    raise exception 'only a platform team member with remote access may start a remote access session';
  end if;

  if exists (select 1 from auth.mfa_factors where user_id = auth.uid() and status = 'verified') then
    if coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then
      raise exception 'Please verify your two-factor authentication code to use Remote Access.';
    end if;
  end if;

  select * into v_tenant from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  select full_name into v_operator_name from profiles where user_id = auth.uid();

  insert into platform_access_events (tenant_id, operator_user_id, operator_name, event, session_key, detail)
  values (p_tenant_id, auth.uid(), coalesce(v_operator_name, 'Platform admin'), 'start', v_session,
    jsonb_build_object('tenant_name', v_tenant.name));

  return jsonb_build_object('ok', true, 'session_key', v_session, 'tenant_id', p_tenant_id, 'tenant_name', v_tenant.name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_csat(p_conversation_id uuid, p_tenant_id uuid, p_score integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_score not in (1, -1) then
    raise exception 'score must be 1 or -1';
  end if;

  update de_conversations
    set csat_score = p_score, csat_submitted_at = now()
    where id = p_conversation_id and tenant_id = p_tenant_id;

  if not found then
    raise exception 'conversation not found for this tenant';
  end if;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_draft_for_review(p_de_id uuid, p_conversation_id uuid, p_user_question text, p_draft_content text, p_confidence numeric DEFAULT NULL::numeric, p_sources jsonb DEFAULT '[]'::jsonb, p_review_timeout_minutes integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_draft_id UUID;
  v_tenant_id UUID;
BEGIN
  v_tenant_id := current_setting('app.current_tenant_id')::uuid;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'app.current_tenant_id not set';
  END IF;

  INSERT INTO draft_responses (
    tenant_id,
    de_id,
    conversation_id,
    user_question,
    draft_content,
    confidence,
    sources,
    expires_at
  ) VALUES (
    v_tenant_id,
    p_de_id,
    p_conversation_id,
    p_user_question,
    p_draft_content,
    p_confidence,
    COALESCE(p_sources, '[]'::jsonb),
    now() + (p_review_timeout_minutes || ' minutes')::interval
  )
  RETURNING draft_id INTO v_draft_id;

  RETURN json_build_object(
    'draft_id', v_draft_id,
    'de_id', p_de_id,
    'conversation_id', p_conversation_id,
    'user_question', p_user_question,
    'draft_content', p_draft_content,
    'confidence', p_confidence,
    'sources', COALESCE(p_sources, '[]'::jsonb),
    'created_at', now()::text,
    'expires_at', (now() + (p_review_timeout_minutes || ' minutes')::interval)::text
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.submit_evidence_feedback(p_evidence_run_id uuid, p_verdict text, p_notes text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user           uuid := auth.uid();
  v_tenant         uuid;
  v_caller_tenant  uuid;
  v_is_active      boolean;
  v_run            record;
  v_feedback_id    uuid;
  v_revision_id    uuid;
  v_task_id        uuid;
  v_source_doc_id  uuid;
  v_current_title  text;
  v_current_body   text;
  v_gap_lines      text := '';
  v_step           jsonb;
  v_citation       jsonb;
  v_proposed_title text;
  v_proposed_body  text;
  v_reviewer_name  text;
begin
  if p_verdict not in ('accurate', 'needs_improvement', 'inaccurate') then
    return jsonb_build_object('ok', false, 'error', 'bad_verdict');
  end if;

  select * into v_run from evidence_runs where id = p_evidence_run_id;
  if v_run.id is null then
    return jsonb_build_object('ok', false, 'error', 'evidence_run_not_found');
  end if;
  v_tenant := v_run.tenant_id;

  -- Membership guard (JWT path); a genuine service_role connection is
  -- also trusted (same test append_audit_event / set_doc_scope use).
  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_tenant then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select full_name into v_reviewer_name from profiles where user_id = v_user;
  v_reviewer_name := coalesce(v_reviewer_name, 'A reviewer');

  insert into evidence_feedback (tenant_id, evidence_run_id, reviewer_user_id, verdict, notes)
  values (v_tenant, p_evidence_run_id, v_user, p_verdict, coalesce(p_notes, ''))
  returning id into v_feedback_id;

  perform append_audit_event(
    v_tenant, v_reviewer_name, case when v_user is null then 'system' else 'human' end,
    v_reviewer_name || ' marked evidence run evidence as "' || p_verdict || '"'
      || case when coalesce(p_notes, '') <> '' then ' — "' || p_notes || '"' else '' end,
    'evidence_step',
    jsonb_build_object('kind', 'evidence_feedback_submitted', 'evidence_run_id', p_evidence_run_id,
      'feedback_id', v_feedback_id, 'verdict', p_verdict, 'notes', coalesce(p_notes, ''))
  );

  if p_verdict = 'accurate' then
    return jsonb_build_object('ok', true, 'feedback_id', v_feedback_id, 'revision_request_id', null, 'task_id', null);
  end if;

  -- ── Build the template-composed proposed revision ──
  -- Try to find an existing knowledge doc this evidence run cited, so
  -- the revision proposes an edit rather than always a fresh doc.
  select (c->>'ref')::uuid into v_source_doc_id
  from jsonb_array_elements(v_run.steps) s,
       jsonb_array_elements(s->'citations') c
  where s->>'kind' = 'knowledge_search' and c->>'system' = 'DreamTeam knowledge'
  limit 1;

  if v_source_doc_id is not null then
    select title, content into v_current_title, v_current_body
      from knowledge_docs where id = v_source_doc_id and tenant_id = v_tenant and is_current;
  end if;

  -- Gap lines: every non-"ok" or human-flagged step, plain-language.
  for v_step in select * from jsonb_array_elements(v_run.steps) loop
    if (v_step->>'outcome') in ('failed', 'skipped_not_connected', 'denied_no_access') then
      v_gap_lines := v_gap_lines || '- ' || coalesce(v_step->>'summary', v_step->>'kind') || E'\n';
    end if;
  end loop;

  v_proposed_title := coalesce(v_current_title, 'Follow-up: ' || left(v_run.inquiry, 80));
  v_proposed_body := coalesce(v_current_body, '') || E'\n\n'
    || '## Reviewer feedback (' || p_verdict || ')' || E'\n'
    || coalesce(nullif(p_notes, ''), '(no note provided)') || E'\n\n'
    || '## Evidence gaps noted at review time' || E'\n'
    || case when v_gap_lines = '' then '(no gaps recorded in the evidence trail)' || E'\n' else v_gap_lines end
    || E'\n## Source inquiry' || E'\n' || v_run.inquiry;

  insert into knowledge_revision_requests (
    tenant_id, source_doc_id, evidence_run_id, feedback_id,
    proposed_title, proposed_body_md, status, created_by
  ) values (
    v_tenant, v_source_doc_id, p_evidence_run_id, v_feedback_id,
    v_proposed_title, v_proposed_body, 'pending_approval', v_user
  ) returning id into v_revision_id;

  insert into human_tasks (
    tenant_id, type, title, detail, source, related_table, related_id, status
  ) values (
    v_tenant, 'knowledge_revision',
    'Review proposed knowledge update: ' || v_proposed_title,
    'Evidence run flagged "' || p_verdict || '" — a knowledge revision has been drafted for review.',
    'system', 'knowledge_revision_requests', v_revision_id, 'pending'
  ) returning id into v_task_id;

  perform append_audit_event(
    v_tenant, v_reviewer_name, case when v_user is null then 'system' else 'human' end,
    'Knowledge revision proposed from evidence feedback — "' || v_proposed_title || '"',
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_requested', 'revision_request_id', v_revision_id,
      'evidence_run_id', p_evidence_run_id, 'feedback_id', v_feedback_id, 'task_id', v_task_id,
      'source_doc_id', v_source_doc_id)
  );

  return jsonb_build_object('ok', true, 'feedback_id', v_feedback_id,
    'revision_request_id', v_revision_id, 'task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.suggest_de_amendments(p_de_id uuid, p_metric_type text DEFAULT 'csat'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tenant_id UUID;
  v_de_name TEXT;
  v_current_csat NUMERIC;
  v_escalation_rate NUMERIC;
  v_suggestion TEXT;
  v_confidence_score NUMERIC;
BEGIN
  SELECT tenant_id, name INTO v_tenant_id, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'DE not found'; END IF;
  IF NOT (v_tenant_id = auth_tenant_id() AND auth_has_tenant_role(array['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN RAISE EXCEPTION 'Unauthorized'; END IF;

  SELECT COALESCE(AVG(score), 0) INTO v_current_csat FROM csat_surveys WHERE de_id = p_de_id AND created_at > now() - '30 days'::interval;
  SELECT COALESCE(COUNT(*)::NUMERIC / NULLIF((SELECT COUNT(*) FROM action_executions WHERE de_id = p_de_id AND created_at > now() - '30 days'::interval), 0) * 100, 0) INTO v_escalation_rate FROM action_executions WHERE de_id = p_de_id AND status = 'escalated' AND created_at > now() - '30 days'::interval;

  v_confidence_score := 0.7;
  IF p_metric_type = 'csat' AND v_current_csat < 80 THEN
    v_suggestion := 'CSAT ' || ROUND(v_current_csat, 1) || '%. Suggested: increase empathy.';
    v_confidence_score := 0.75;
  ELSIF p_metric_type = 'escalation' AND v_escalation_rate > 15 THEN
    v_suggestion := 'Escalation ' || ROUND(v_escalation_rate, 1) || '% (goal <5%). Suggested: expand actions.';
    v_confidence_score := 0.80;
  ELSE
    v_suggestion := 'DE performing well.';
    v_confidence_score := 0.90;
  END IF;

  RETURN json_build_object('de_id', p_de_id, 'de_name', v_de_name, 'suggestion', v_suggestion, 'metric_type', p_metric_type, 'current_csat', ROUND(v_current_csat, 1), 'current_escalation_rate', ROUND(v_escalation_rate, 1), 'confidence_score', v_confidence_score, 'recommendation', CASE WHEN v_confidence_score >= 0.75 THEN 'HIGH' WHEN v_confidence_score >= 0.5 THEN 'MEDIUM' ELSE 'LOW' END, 'generated_at', now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_amendment_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'playbook_amendments' and NEW.status in ('approved','rejected')
     and OLD.status is distinct from NEW.status then
    begin
      if NEW.status = 'approved' then
        perform public.apply_playbook_amendment(NEW.related_id);
      else
        perform public.reject_playbook_amendment(NEW.related_id);
      end if;
    exception when others then
      -- never let a failed apply roll back the human's decision
      raise warning 'sync_amendment_decision: % for amendment %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end; $function$;

CREATE OR REPLACE FUNCTION public.sync_computer_use_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'computer_use_tasks' and NEW.status in ('approved', 'rejected')
     and OLD.status is distinct from NEW.status then
    update computer_use_tasks
       set status = case when NEW.status = 'approved' then 'approved' else 'rejected' end,
           updated_at = now()
     where id = NEW.related_id and status = 'pending_approval';
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_lifecycle_auto_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select de.id, de.tenant_id, de.name from digital_employees de
    where de.lifecycle_status = 'assigned'
      and exists (select 1 from evidence_runs er where er.tenant_id = de.tenant_id and er.de_id = de.id)
  loop
    update digital_employees set lifecycle_status = 'active', updated_at = now() where id = v_row.id;
    insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_label, note)
    values (v_row.tenant_id, v_row.id, 'assigned', 'active', 'system', 'First live execution observed — activated automatically.');
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('activated', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_lifecycle_from_development(p_de_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de digital_employees;
  v_open_count integer;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return; end if;

  select count(*) into v_open_count from de_development_items
  where de_id = p_de_id and status in ('proposed', 'in_progress');

  if v_open_count > 0 and v_de.lifecycle_status = 'active' then
    update digital_employees set lifecycle_status = 'improving', updated_at = now() where id = p_de_id;
  elsif v_open_count = 0 and v_de.lifecycle_status = 'improving' then
    update digital_employees set lifecycle_status = 'active', updated_at = now() where id = p_de_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_task_from_objective()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.entity_kind = 'de_task'
     AND NEW.status IN ('achieved','blocked') THEN
    UPDATE de_task_requests
       SET status       = CASE WHEN NEW.status = 'achieved' THEN 'completed' ELSE 'failed' END,
           completed_at = coalesce(completed_at, now()),
           responded_at = coalesce(responded_at, now())
     WHERE objective_id = NEW.id
       AND status IN ('requested','accepted','in_progress');
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.sync_entity_amendment_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'workforce_entity_amendments' and NEW.status in ('approved','rejected')
     and OLD.status is distinct from NEW.status then
    begin
      if NEW.status = 'approved' then perform public.apply_entity_amendment(NEW.related_id);
      else perform public.reject_entity_amendment(NEW.related_id); end if;
    exception when others then
      raise warning 'sync_entity_amendment_decision: % for %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end; $function$;

CREATE OR REPLACE FUNCTION public.sync_improvement_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'de_improvements' and NEW.status in ('approved', 'rejected')
     and OLD.status is distinct from NEW.status then
    begin
      if NEW.status = 'approved' then
        perform public.apply_improvement(NEW.related_id);
      else
        perform public.reject_improvement(NEW.related_id);
      end if;
    exception when others then
      -- Never roll back the human's decision; leave the improvement in
      -- review_pending where it is visibly stuck rather than silently lost.
      raise warning 'sync_improvement_decision: % for improvement %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_outbound_draft_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
