CREATE OR REPLACE FUNCTION public.tenant_ancestors(p_tenant_id uuid)
 RETURNS TABLE(tenant_id uuid, depth integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not caller_has_tenant_relationship(p_tenant_id) then
    raise exception 'not authorized to view ancestors of this tenant';
  end if;
  return query
    select ta.ancestor_id, ta.depth
    from tenant_ancestry ta
    where ta.tenant_id = p_tenant_id and ta.ancestor_id <> p_tenant_id
    order by ta.depth, ta.ancestor_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_descendants(p_tenant_id uuid)
 RETURNS TABLE(tenant_id uuid, depth integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not caller_has_tenant_relationship(p_tenant_id) then
    raise exception 'not authorized to view descendants of this tenant';
  end if;
  return query
    select ta.tenant_id, ta.depth
    from tenant_ancestry ta
    where ta.ancestor_id = p_tenant_id and ta.tenant_id <> p_tenant_id
    order by ta.depth, ta.tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_inbox_watch_state(p_tenant_id uuid, p_connector_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  insert into inbox_watch_state (tenant_id, connector_id, last_polled_at)
  values (p_tenant_id, p_connector_id, now())
  on conflict (tenant_id, connector_id) do update set last_polled_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.transfer_tenant_ownership(p_new_owner_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_active boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_new_owner_user_id then
    raise exception 'you are already the owner';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role <> 'tenant_owner' then
    raise exception 'only the current workspace owner can transfer ownership';
  end if;

  select tenant_id, coalesce(is_active, true) into v_target_tenant, v_target_active
  from profiles where user_id = p_new_owner_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'the new owner must already be a member of this workspace';
  end if;
  if not v_target_active then
    raise exception 'the new owner must be an active team member';
  end if;

  update profiles set role = 'tenant_admin' where user_id = auth.uid();
  update profiles set role = 'tenant_owner' where user_id = p_new_owner_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    'Workspace ownership transferred',
    'config_change',
    jsonb_build_object('kind', 'ownership_transfer', 'previous_owner', auth.uid(), 'new_owner', p_new_owner_user_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_provision_onboarding_architect()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  begin
    perform provision_onboarding_architect(new.id);
  exception when others then
    null; -- best-effort; tenant creation must always succeed
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_recompute_tenant_ancestry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_descendant uuid;
begin
  perform recompute_tenant_ancestry(NEW.id);

  if TG_OP = 'UPDATE' and NEW.parent_tenant_id is distinct from OLD.parent_tenant_id then
    for v_descendant in
      select tenant_id from tenant_ancestry where ancestor_id = NEW.id and tenant_id <> NEW.id
    loop
      perform recompute_tenant_ancestry(v_descendant);
    end loop;
  end if;

  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_support_sentiment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(NEW.role, '') <> 'user' THEN RETURN NEW; END IF;
  BEGIN
    UPDATE de_conversations
       SET sentiment = public.classify_sentiment_text(NEW.content)
     WHERE id = NEW.conversation_id;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- sentiment must never block a customer message landing
  END;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.trg_triage_support_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_conv de_conversations; v_first boolean; v_cls jsonb;
BEGIN
  IF coalesce(NEW.role,'') <> 'user' THEN RETURN NEW; END IF;
  BEGIN
    -- Only the FIRST user message triages the conversation.
    SELECT count(*) = 1 INTO v_first FROM de_messages
      WHERE conversation_id = NEW.conversation_id AND role = 'user';
    IF NOT v_first THEN RETURN NEW; END IF;

    SELECT * INTO v_conv FROM de_conversations WHERE id = NEW.conversation_id;
    IF v_conv.id IS NULL OR v_conv.category IS NOT NULL THEN RETURN NEW; END IF;  -- don't override

    v_cls := public.classify_support_text(v_conv.tenant_id, coalesce(v_conv.subject,'') || ' ' || coalesce(NEW.content,''));
    UPDATE de_conversations
       SET category   = v_cls->>'category',
           severity   = v_cls->>'severity',
           priority   = v_cls->>'priority',
           triaged_at = now()
     WHERE id = NEW.conversation_id AND category IS NULL;
  EXCEPTION WHEN OTHERS THEN
    -- Triage must never block a customer message landing.
    NULL;
  END;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.trust_apply_level(p_tenant_id uuid, p_category text, p_level integer, p_actor uuid, p_source_category text DEFAULT NULL::text, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_s jsonb := trust_level_settings(p_category, p_level);
begin
  insert into de_autonomy (tenant_id, action_type, source_category, de_id, enabled, max_amount_cents, min_confidence, updated_by)
  values (
    p_tenant_id, p_category, p_source_category, p_de_id,
    (v_s->>'enabled')::boolean,
    nullif(v_s->>'max_amount_cents', '')::bigint,
    nullif(v_s->>'min_confidence', '')::integer,
    p_actor
  )
  on conflict (tenant_id, action_type, coalesce(source_category, ''), coalesce(de_id::text, '')) do update set
    enabled          = excluded.enabled,
    max_amount_cents = excluded.max_amount_cents,
    min_confidence   = excluded.min_confidence,
    updated_by       = excluded.updated_by,
    updated_at       = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_check_eval_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rate   numeric;
  v_policy record;
begin
  if new.finished_at is null or new.status not in ('passed', 'failed') or coalesce(new.total, 0) = 0 then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.finished_at is not null then
    return new; -- only fire on the completion transition
  end if;

  v_rate := new.passed::numeric / new.total;
  begin
    for v_policy in
      select * from trust_policies
      where tenant_id = new.tenant_id and status = 'active' and current_level > baseline_level
        and v_rate < coalesce((criteria->>'min_eval_pass_rate')::numeric, 0.9)
    loop
      perform trust_demote(
        new.tenant_id, v_policy.action_category,
        format('evaluation pass rate fell to %s%% — below the %s%% floor',
          round(v_rate * 100), round(coalesce((v_policy.criteria->>'min_eval_pass_rate')::numeric, 0.9) * 100)),
        jsonb_build_object('eval_run_id', new.id, 'passed', new.passed, 'total', new.total, 'pass_rate', round(v_rate, 4)),
        v_policy.de_id, v_policy.source_category
      );
    end loop;
  exception when others then
    raise warning 'trust_check_eval_regression: %', sqlerrm;
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_check_guardrail_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy record;
begin
  if new.category <> 'guardrail_block' then
    return new;
  end if;
  begin
    for v_policy in
      select * from trust_policies
      where tenant_id = new.tenant_id and status = 'active' and current_level > baseline_level
        and coalesce((criteria->>'max_guardrail_blocks')::integer, 0) = 0
    loop
      perform trust_demote(
        new.tenant_id, v_policy.action_category,
        'a guardrail block occurred — zero-tolerance policy',
        jsonb_build_object('audit_event_id', new.id, 'blocked_action', new.action),
        v_policy.de_id, v_policy.source_category
      );
    end loop;
  exception when others then
    raise warning 'trust_check_guardrail_block: %', sqlerrm;
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_demote(p_tenant_id uuid, p_category text, p_reason text, p_evidence jsonb, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy trust_policies;
  v_new    integer;
  v_label  text;
begin
  -- Target the EXACT policy (per-DE + per-source), not an arbitrary tenant/
  -- category row. NULL de_id / source_category match the tenant-wide policy.
  select * into v_policy
  from trust_policies
  where tenant_id = p_tenant_id and action_category = p_category
    and de_id is not distinct from p_de_id
    and source_category is not distinct from p_source_category
    and status = 'active' and current_level > baseline_level
  for update;
  if not found then
    return;
  end if;

  v_new := greatest(v_policy.current_level - 1, v_policy.baseline_level);
  v_label := replace(p_category, '_', ' ');

  -- GI-3: demote at the SAME scope the promotion was granted at.
  perform trust_apply_level(p_tenant_id, p_category, v_new, null, p_source_category, p_de_id);
  update trust_policies
  set current_level = v_new,
      pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
  where id = v_policy.id;

  perform append_audit_event(
    p_tenant_id, 'Trust engine', 'system',
    format('Trust demoted — %s level %s → %s (%s). Demotion is automatic and immediate.',
      v_label, v_policy.current_level, v_new, p_reason),
    'config_change',
    jsonb_build_object('kind', 'trust_demoted', 'policy_id', v_policy.id,
      'action_category', p_category, 'de_id', p_de_id, 'from_level', v_policy.current_level,
      'to_level', v_new, 'reason', p_reason, 'evidence', p_evidence)
  );

  insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
  values (
    p_tenant_id, 'trust_demotion_notice',
    format('Trust reduced — %s dropped to level %s', v_label, v_new),
    format('Reason: %s. The dial was lowered automatically to stay safe. Approve to acknowledge — trust can be re-earned through the same evidence path.', p_reason),
    'system', 'trust_policies', v_policy.id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_level_settings(p_category text, p_level integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_level <= 0 then jsonb_build_object('enabled', false, 'max_amount_cents', null, 'min_confidence', null)
    when p_category = 'invoice_auto_send' then jsonb_build_object(
      'enabled', true,
      'max_amount_cents', (array[100000, 500000, 1000000])[least(p_level, 3)],
      'min_confidence', null)
    when p_category = 'action_execute' then jsonb_build_object(
      'enabled', true, 'max_amount_cents', null, 'min_confidence', null)
    else jsonb_build_object(
      'enabled', true,
      'max_amount_cents', null,
      'min_confidence', (array[90, 75, 60])[least(p_level, 3)])
  end;
$function$;

CREATE OR REPLACE FUNCTION public.unassign_doc_collection(p_doc_id uuid, p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  -- The original did not even check the document existed.
  IF NOT EXISTS (SELECT 1 FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;

  -- 359: THE BYPASS THIS CLOSES. Un-filing rebuilds the ancestry closure, which
  -- nulls restricted_space_id, which lets the workspace-wide grant reach a
  -- document that was in a locked room. Unrestricted by any policy, because
  -- this function is SECURITY DEFINER.
  IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN
    IF public.knowledge_effective_level(p_doc_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need edit access to that document');
    END IF;
    IF public.knowledge_my_admin_level(p_collection_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need access to the space you are removing it from');
    END IF;
  END IF;

  DELETE FROM knowledge_doc_collections
   WHERE tenant_id = v_tenant AND doc_id = p_doc_id AND collection_id = p_collection_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.update_custom_metric(p_metric_id uuid, p_updates jsonb)
 RETURNS TABLE(metric_id uuid, tenant_id uuid, name text, key text, type text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT cm.tenant_id INTO v_owner FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'metric_not_found'; END IF;
  PERFORM public._assert_caller_tenant(v_owner);

  UPDATE customer_metrics cm
  SET name = COALESCE((p_updates->>'name')::TEXT, cm.name),
      description = COALESCE((p_updates->>'description')::TEXT, cm.description),
      unit = COALESCE((p_updates->>'unit')::TEXT, cm.unit),
      thresholds = COALESCE((p_updates->'thresholds')::JSONB, cm.thresholds)
  WHERE cm.metric_id = p_metric_id;

  RETURN QUERY SELECT cm.metric_id, cm.tenant_id, cm.name, cm.key, cm.type, cm.created_at
  FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
END$function$;

CREATE OR REPLACE FUNCTION public.update_onboarding_item(p_project_id uuid, p_key text, p_status text DEFAULT NULL::text, p_assignee text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_old       text;
  v_task_id   uuid;
  v_acct_name text;
  v_completed boolean := false;
  v_signoff   boolean;
begin
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_proj.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;
  if v_proj.status <> 'active' then
    return jsonb_build_object('error', 'project_not_active');
  end if;
  if p_status is not null and p_status not in ('pending', 'in_progress', 'done', 'blocked') then
    return jsonb_build_object('error', 'invalid_status');
  end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = p_key limit 1;
  if v_def is null then return jsonb_build_object('error', 'item_not_found'); end if;
  v_signoff := coalesce((v_def->>'requires_signoff')::boolean, false);

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'key' = p_key then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_state_missing'); end if;
  v_old := v_item->>'status';

  if v_old = 'signed_off' then
    return jsonb_build_object('error', 'item_already_signed_off');
  end if;

  if p_assignee is not null then v_item := v_item || jsonb_build_object('assignee', nullif(trim(p_assignee), '')); end if;
  if p_note is not null then v_item := v_item || jsonb_build_object('note', p_note); end if;

  if p_status is not null and p_status <> v_old then
    v_item := v_item || jsonb_build_object('status', p_status);
    if p_status = 'done' then
      v_item := v_item || jsonb_build_object('done_at', now());
      if v_signoff then
        insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
        values (v_proj.tenant_id, 'review_gate',
                format('Onboarding sign-off — %s · %s', v_def->>'label', v_proj.name),
                format('Item "%s" is marked done and needs a human sign-off before the project can complete.', v_def->>'label'),
                'system', 'onboarding_projects', p_project_id)
        returning id into v_task_id;
        v_item := v_item || jsonb_build_object('signoff_task_id', v_task_id);
      end if;
    end if;

    select name into v_acct_name from customer_accounts where id = v_proj.account_id;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (v_proj.tenant_id, v_proj.account_id, 'You', 'human',
            case when p_status = 'blocked' then 'escalated' else 'config_change' end,
            format('Onboarding — %s: %s → %s%s (%s)', v_def->>'label', v_old, p_status,
                   case when v_task_id is not null then ' · awaiting sign-off' else '' end,
                   coalesce(v_acct_name, v_proj.name)));
  end if;

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = p_project_id;

  -- non-signoff items can complete the project directly
  if p_status = 'done' and not v_signoff then
    v_completed := onboarding_check_complete(p_project_id);
  end if;

  select to_jsonb(p.*) into v_item from onboarding_projects p where p.id = p_project_id;
  return jsonb_build_object('project', v_item, 'signoff_task_id', v_task_id, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_platform_team_role(p_target_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s role';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own role here';
  end if;
  if p_new_role not in ('platform_super_admin', 'platform_support', 'platform_billing') then
    raise exception 'unrecognized platform role: %', p_new_role;
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  update profiles set role = p_new_role where user_id = p_target_user_id;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'role', p_new_role);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_team_member_department(p_target_user_id uuid, p_department text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s department';
  end if;

  select tenant_id into v_target_tenant from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;

  update profiles set department = p_department where user_id = p_target_user_id;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_team_member_role(p_target_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'use a different flow to change your own role';
  end if;
  if p_new_role in ('tenant_owner', 'dt_super_admin', 'dt_god_access', 'dt_support', 'dt_billing', 'platform_super_admin', 'platform_support', 'platform_billing') then
    raise exception 'use transfer_tenant_ownership to hand off ownership; this function cannot grant owner or platform-tier roles';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s role';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner''s role can only be changed by transferring ownership';
  end if;

  update profiles set role = p_new_role where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    format('Team member role changed to %s', p_new_role),
    'config_change',
    jsonb_build_object('kind', 'team_role_change', 'target_user_id', p_target_user_id, 'new_role', p_new_role)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_billing(p_tenant_id uuid, p_billing_config jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  INSERT INTO tenant_billing_config (
    tenant_id, sophie_config_cost, amendment_journeys_cost,
    metrics_tracking_cost, reply_mode_cost, hosted_chat_cost,
    cost_per_1k_responses, cost_per_amendment, cost_per_de,
    billing_email, payment_method
  ) VALUES (
    p_tenant_id,
    COALESCE((p_billing_config->>'sophie_config_cost')::numeric, 100),
    COALESCE((p_billing_config->>'amendment_cost')::numeric, 50),
    COALESCE((p_billing_config->>'metrics_cost')::numeric, 75),
    COALESCE((p_billing_config->>'reply_mode_cost')::numeric, 150),
    COALESCE((p_billing_config->>'hosted_chat_cost')::numeric, 200),
    COALESCE((p_billing_config->>'cost_per_1k_responses')::numeric, 0.50),
    COALESCE((p_billing_config->>'cost_per_amendment')::numeric, 5),
    COALESCE((p_billing_config->>'cost_per_de')::numeric, 20),
    p_billing_config->>'billing_email',
    COALESCE(p_billing_config->>'payment_method', 'invoice')
  )
  ON CONFLICT (tenant_id)
  DO UPDATE SET
    sophie_config_cost = EXCLUDED.sophie_config_cost,
    amendment_journeys_cost = EXCLUDED.amendment_journeys_cost,
    metrics_tracking_cost = EXCLUDED.metrics_tracking_cost,
    reply_mode_cost = EXCLUDED.reply_mode_cost,
    hosted_chat_cost = EXCLUDED.hosted_chat_cost,
    cost_per_1k_responses = EXCLUDED.cost_per_1k_responses,
    cost_per_amendment = EXCLUDED.cost_per_amendment,
    cost_per_de = EXCLUDED.cost_per_de,
    billing_email = EXCLUDED.billing_email,
    payment_method = EXCLUDED.payment_method,
    updated_at = now();

  RETURN json_build_object('ok', true, 'updated_at', now()::text);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_features(p_tenant_id uuid, p_features jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID;
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  v_user_id := auth.uid();

  INSERT INTO tenant_feature_toggles (
    tenant_id, sophie_config_enabled, amendment_journeys_enabled,
    metrics_tracking_enabled, reply_mode_enabled, hosted_chat_enabled,
    amendment_replay_testing, trust_adaptive_execution, playbook_mining,
    updated_by
  ) VALUES (
    p_tenant_id,
    COALESCE(p_features->>'sophie_config_enabled', 'true')::boolean,
    COALESCE(p_features->>'amendment_journeys_enabled', 'true')::boolean,
    COALESCE(p_features->>'metrics_tracking_enabled', 'true')::boolean,
    COALESCE(p_features->>'reply_mode_enabled', 'true')::boolean,
    COALESCE(p_features->>'hosted_chat_enabled', 'true')::boolean,
    COALESCE(p_features->>'replay_testing', 'false')::boolean,
    COALESCE(p_features->>'trust_adaptive', 'false')::boolean,
    COALESCE(p_features->>'playbook_mining', 'false')::boolean,
    v_user_id
  )
  ON CONFLICT (tenant_id)
  DO UPDATE SET
    sophie_config_enabled = EXCLUDED.sophie_config_enabled,
    amendment_journeys_enabled = EXCLUDED.amendment_journeys_enabled,
    metrics_tracking_enabled = EXCLUDED.metrics_tracking_enabled,
    reply_mode_enabled = EXCLUDED.reply_mode_enabled,
    hosted_chat_enabled = EXCLUDED.hosted_chat_enabled,
    amendment_replay_testing = EXCLUDED.amendment_replay_testing,
    trust_adaptive_execution = EXCLUDED.trust_adaptive_execution,
    playbook_mining = EXCLUDED.playbook_mining,
    updated_at = now(),
    updated_by = v_user_id;

  RETURN json_build_object('ok', true, 'updated_at', now()::text);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_general_settings(p_tenant_id uuid, p_name text, p_industry text, p_accent_color text, p_vocabulary jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_caller_tenant uuid;
  v_role text;
  v_is_active boolean;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.manage');
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s settings cannot be changed';
  end if;
  if coalesce(btrim(p_name), '') = '' then
    raise exception 'organization name is required';
  end if;
  if p_vocabulary is not null and jsonb_typeof(p_vocabulary) <> 'object' then
    raise exception 'vocabulary must be a JSON object';
  end if;

  if not v_is_platform then
    select tenant_id, role, coalesce(is_active, true) into v_caller_tenant, v_role, v_is_active
    from profiles where user_id = auth.uid();

    if v_caller_tenant is distinct from p_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only an owner or admin of this organization may change these settings';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
  end if;

  update tenants
  set name = btrim(p_name), industry = nullif(btrim(coalesce(p_industry, '')), ''),
      accent_color = p_accent_color,
      vocabulary = coalesce(p_vocabulary, vocabulary),
      updated_at = now()
  where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_commercial_agreement(p_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_counterparty_name text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_party_side text DEFAULT 'sell'::text, p_agreement_type text DEFAULT 'subscription'::text, p_status text DEFAULT 'active'::text, p_baseline_value_cents bigint DEFAULT NULL::bigint, p_auto_renew boolean DEFAULT false, p_notice_period_days integer DEFAULT NULL::integer, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_renewal_date date DEFAULT NULL::date, p_notice_deadline date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_id uuid;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF p_id IS NULL AND (length(btrim(coalesce(p_title,''))) < 2
       OR length(btrim(coalesce(p_counterparty_name,''))) < 2) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'title_and_counterparty_required');
  END IF;
  IF p_account_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM customer_accounts WHERE id = p_account_id AND tenant_id = v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_account');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO commercial_agreements (
      tenant_id, title, counterparty_name, account_id, party_side, agreement_type,
      status, baseline_value_cents, auto_renew, notice_period_days,
      start_date, end_date, renewal_date, notice_deadline, created_by)
    VALUES (
      v_tenant, btrim(p_title), btrim(p_counterparty_name), p_account_id, p_party_side,
      p_agreement_type, p_status, p_baseline_value_cents, coalesce(p_auto_renew,false),
      p_notice_period_days, p_start_date, p_end_date, p_renewal_date, p_notice_deadline,
      auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE commercial_agreements SET
      title = coalesce(btrim(p_title), title),
      counterparty_name = coalesce(btrim(p_counterparty_name), counterparty_name),
      account_id = coalesce(p_account_id, account_id),
      party_side = coalesce(p_party_side, party_side),
      agreement_type = coalesce(p_agreement_type, agreement_type),
      status = coalesce(p_status, status),
      baseline_value_cents = coalesce(p_baseline_value_cents, baseline_value_cents),
      auto_renew = coalesce(p_auto_renew, auto_renew),
      notice_period_days = coalesce(p_notice_period_days, notice_period_days),
      start_date = coalesce(p_start_date, start_date),
      end_date = coalesce(p_end_date, end_date),
      renewal_date = coalesce(p_renewal_date, renewal_date),
      notice_deadline = coalesce(p_notice_deadline, notice_deadline),
      updated_at = now()
    WHERE id = p_id AND tenant_id = v_tenant
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  END IF;

  BEGIN
    PERFORM public.append_audit_event(
      p_tenant_id => v_tenant, p_actor => 'You', p_actor_type => 'human',
      p_action => CASE WHEN p_id IS NULL THEN 'Agreement created — "' || btrim(p_title) || '"'
                       ELSE 'Agreement updated — ' || v_id::text END,
      p_category => 'config_change',
      p_detail => jsonb_build_object('kind','commercial_agreement','agreement_id', v_id));
  EXCEPTION WHEN OTHERS THEN NULL; -- audit best-effort; the write itself stands
  END;
  RETURN jsonb_build_object('ok', true, 'agreement_id', v_id);
EXCEPTION WHEN check_violation THEN
  RETURN jsonb_build_object('ok', false, 'error', 'invalid_value: ' || SQLERRM);
END $function$;

CREATE OR REPLACE FUNCTION public.upsert_de_objective(p_de_id uuid, p_title text, p_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_priority integer DEFAULT 3, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid; v_de_name text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  SELECT name INTO v_de_name FROM digital_employees
   WHERE id = p_de_id AND tenant_id = v_tenant;
  IF v_de_name IS NULL THEN RAISE EXCEPTION 'de_not_found'; END IF;
  IF coalesce(trim(p_title), '') = '' THEN RAISE EXCEPTION 'an objective needs a title'; END IF;
  IF p_priority IS NOT NULL AND (p_priority < 1 OR p_priority > 5) THEN
    RAISE EXCEPTION 'priority must be between 1 and 5';
  END IF;

  IF p_id IS NULL THEN
    -- description is NOT NULL on this table; default it to the title rather
    -- than forcing the caller to type boilerplate.
    INSERT INTO de_objectives (tenant_id, de_id, title, description, priority, due_at, status, created_by)
    VALUES (v_tenant, p_de_id, trim(p_title), coalesce(p_description, trim(p_title)),
            coalesce(p_priority, 3), p_due_at, coalesce(p_status, 'open'), auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE de_objectives SET
      title       = trim(p_title),
      description = coalesce(p_description, description),
      priority    = coalesce(p_priority, priority),
      due_at      = p_due_at,
      status      = coalesce(p_status, status),
      updated_at  = now()
    WHERE id = p_id AND tenant_id = v_tenant AND de_id = p_de_id
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'objective_not_found'; END IF;
  END IF;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('%s objective %s — "%s"', v_de_name,
           CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END, trim(p_title)),
    'config_change',
    jsonb_build_object('de_id', p_de_id, 'objective_id', v_id, 'status', coalesce(p_status, 'open'))
  );
  RETURN v_id;
END$function$;

CREATE OR REPLACE FUNCTION public.upsert_de_operate_binding(p_de_id uuid, p_system_id uuid, p_system_key text, p_label text, p_can_operate boolean, p_operate_domain text DEFAULT NULL::text, p_connector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_key text; v_label text; v_domain text; v_id uuid;
  v_conn_tenant uuid; v_has_conn_url boolean := false;
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  v_domain := public.normalize_operate_domain(p_operate_domain);

  -- A linked connector must belong to this tenant; note whether it yields a host.
  IF p_connector_id IS NOT NULL THEN
    SELECT tenant_id, (public.normalize_operate_domain(base_url) IS NOT NULL)
      INTO v_conn_tenant, v_has_conn_url FROM connectors WHERE id = p_connector_id;
    IF v_conn_tenant IS NULL OR v_conn_tenant <> v_tenant THEN
      RETURN jsonb_build_object('ok', false, 'error', 'connector_not_in_tenant');
    END IF;
  END IF;

  -- Operable systems MUST resolve to a domain (else the bridge can't allowlist).
  IF p_can_operate AND v_domain IS NULL AND NOT v_has_conn_url THEN
    RETURN jsonb_build_object('ok', false, 'error', 'operate_domain_required');
  END IF;

  IF p_system_id IS NOT NULL THEN
    -- Update the operate fields on an existing binding (keep its read config).
    UPDATE de_connected_systems
       SET label          = coalesce(nullif(btrim(p_label),''), label),
           can_operate    = p_can_operate,
           operate_domain = v_domain,
           connector_id   = p_connector_id,
           active         = true
     WHERE id = p_system_id AND de_id = p_de_id AND tenant_id = v_tenant
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  ELSE
    -- Create a new operate-only binding.
    v_key := nullif(btrim(p_system_key), '');
    IF v_key IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_key_required'); END IF;
    v_label := coalesce(nullif(btrim(p_label),''), v_key);
    IF EXISTS (SELECT 1 FROM de_connected_systems WHERE de_id = p_de_id AND system_key = v_key) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'system_key_exists');
    END IF;
    INSERT INTO de_connected_systems (
      tenant_id, de_id, system_key, label, binding_kind, source_table,
      can_read, can_write, can_verify, can_operate, operate_domain, connector_id, active
    ) VALUES (
      v_tenant, p_de_id, v_key, v_label, 'connector', NULL,
      false, false, false, p_can_operate, v_domain, p_connector_id, true
    ) RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'system_id', v_id,
    'resolved_domain', public.operate_domain_of((SELECT t FROM de_connected_systems t WHERE t.id = v_id)));
END; $function$;

CREATE OR REPLACE PROCEDURE public.upsert_de_skill(IN p_tenant_id uuid, IN p_de_id uuid, IN p_skill_key text, IN p_prof integer, IN p_sample integer, IN p_value numeric, IN p_detail text, INOUT p_prev integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $procedure$
declare
  v_name text;
begin
  select proficiency into p_prev from de_skills
  where tenant_id = p_tenant_id and de_id = p_de_id and skill_key = p_skill_key;

  insert into de_skills (tenant_id, de_id, skill_key, proficiency, sample_size, signal_value, detail, assessed_at)
  values (p_tenant_id, p_de_id, p_skill_key, p_prof, p_sample, p_value, p_detail, now())
  on conflict (tenant_id, de_id, skill_key)
  do update set proficiency = excluded.proficiency, sample_size = excluded.sample_size,
                signal_value = excluded.signal_value, detail = excluded.detail, assessed_at = now();

  -- §4.4: a material change in a skill's proficiency emits a
  -- skill_updated event. Only a real level change (both sides
  -- non-null and different) counts — first assessment / evidence
  -- appearing is noted but not spammed as a "change".
  if p_prev is not null and p_prof is not null and p_prev <> p_prof then
    select name into v_name from skill_catalog where skill_key = p_skill_key;
    perform append_audit_event_internal(
      p_tenant_id, 'Skills assessment', 'system',
      format('%s proficiency changed from level %s to level %s', coalesce(v_name, p_skill_key), p_prev, p_prof),
      'config_change',
      jsonb_build_object('kind', 'skill_updated', 'de_id', p_de_id, 'skill_key', p_skill_key, 'from', p_prev, 'to', p_prof)
    );
  end if;
end;
$procedure$;

CREATE OR REPLACE FUNCTION public.upsert_inbox_watch_state(p_tenant_id uuid, p_connector_id uuid, p_external_ref text, p_timestamp timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  insert into inbox_watch_state (tenant_id, connector_id, last_seen_external_ref, last_seen_timestamp, last_polled_at)
  values (p_tenant_id, p_connector_id, p_external_ref, p_timestamp, now())
  on conflict (tenant_id, connector_id) do update set
    last_seen_external_ref = excluded.last_seen_external_ref,
    last_seen_timestamp = excluded.last_seen_timestamp,
    last_polled_at = now(),
    updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_kpi_metric(p_metric_key text, p_label text, p_direction text DEFAULT 'higher'::text, p_unit text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN RAISE EXCEPTION 'insufficient_role'; END IF;
  IF p_metric_key !~ '^[a-z0-9_]{2,60}$' THEN
    RAISE EXCEPTION 'metric_key must be lowercase letters, numbers and underscores';
  END IF;
  -- A tenant may not shadow a built-in key; that would silently change
  -- which value the computed lookup returns.
  IF EXISTS (SELECT 1 FROM kpi_metric_catalog WHERE tenant_id IS NULL AND metric_key = p_metric_key) THEN
    RAISE EXCEPTION 'metric_key_reserved: % is a built-in metric', p_metric_key;
  END IF;

  INSERT INTO kpi_metric_catalog (tenant_id, metric_key, label, direction, unit, description, source)
  VALUES (v_tenant, p_metric_key, p_label, coalesce(p_direction,'higher'), p_unit, p_description, 'manual')
  ON CONFLICT (tenant_id, metric_key) WHERE tenant_id IS NOT NULL
  DO UPDATE SET label = excluded.label, direction = excluded.direction,
                unit = excluded.unit, description = excluded.description
  RETURNING id INTO v_id;
  RETURN v_id;
END$function$;

CREATE OR REPLACE FUNCTION public.upsert_tenant_skill(p_skill_key text, p_name text, p_category text, p_description text DEFAULT NULL::text, p_signal_label text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_key text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN RAISE EXCEPTION 'insufficient_role'; END IF;
  IF p_skill_key !~ '^[a-z0-9_]{2,60}$' THEN
    RAISE EXCEPTION 'skill_key must be lowercase letters, numbers and underscores';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM skill_categories WHERE key = p_category AND (tenant_id IS NULL OR tenant_id = v_tenant)
  ) THEN
    RAISE EXCEPTION 'unknown_skill_category: %', p_category;
  END IF;

  -- Namespaced so one tenant's "refunds" never collides with another's.
  v_key := 't' || substr(replace(v_tenant::text, '-', ''), 1, 8) || '_' || p_skill_key;

  -- description / signal_label are NOT NULL on this table; fall back to the
  -- name rather than making the caller supply boilerplate.
  INSERT INTO skill_catalog (tenant_id, skill_key, name, category, description, signal_label, higher_is_better, min_sample, sort_order)
  VALUES (v_tenant, v_key, p_name, p_category,
          coalesce(nullif(p_description, ''), p_name),
          coalesce(nullif(p_signal_label, ''), 'Assessed from work signals'),
          true, 5, 500)
  ON CONFLICT (skill_key) DO UPDATE
    SET name = excluded.name, category = excluded.category,
        description = excluded.description, signal_label = excluded.signal_label
    WHERE skill_catalog.tenant_id = v_tenant;   -- never overwrite a built-in
  RETURN v_key;
END$function$;

CREATE OR REPLACE FUNCTION public.validate_onboarding_items(p_items jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_errors text[] := '{}';
  v_item   jsonb;
  v_verify jsonb;
  v_keys   text[] := '{}';
  v_key    text;
  v_n      integer;
  v_match  text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return array['items must be a JSON array'];
  end if;
  v_n := jsonb_array_length(p_items);
  if v_n < 1 then v_errors := v_errors || 'template needs at least 1 item'; end if;
  if v_n > 50 then v_errors := v_errors || 'template cannot exceed 50 items'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_key := coalesce(v_item->>'key', '');
    if v_key = '' then
      v_errors := v_errors || 'every item needs a non-empty key';
    elsif v_key = any(v_keys) then
      v_errors := v_errors || format('duplicate item key "%s"', v_key);
    end if;
    v_keys := v_keys || v_key;
    if coalesce(v_item->>'label', '') = '' then
      v_errors := v_errors || format('item "%s" needs a label', v_key);
    end if;
    if coalesce(v_item->>'phase', '') not in ('kickoff', 'data', 'config', 'validation', 'golive') then
      v_errors := v_errors || format('item "%s" has an invalid phase', v_key);
    end if;
    if coalesce(v_item->>'owner_type', '') not in ('human', 'de', 'either') then
      v_errors := v_errors || format('item "%s" has an invalid owner_type', v_key);
    end if;
    if coalesce((v_item->>'requires_signoff')::boolean, false)
       and coalesce(v_item->>'owner_type', '') = 'de' then
      v_errors := v_errors || format('sign-off item "%s" must be owned by human or either — a DE cannot sign off its own work', v_key);
    end if;

    v_verify := v_item->'verify';
    if v_verify is not null and jsonb_typeof(v_verify) = 'object' then
      if coalesce(v_item->>'owner_type', '') = 'human' then
        v_errors := v_errors || format('item "%s" is human-owned — automated verification only applies to de/either items', v_key);
      end if;
      if coalesce(v_verify->>'category', '') not in
        ('crm', 'helpdesk', 'knowledge_base', 'erp_financials', 'billing', 'payroll_hcm', 'pos', 'product_system', 'other') then
        v_errors := v_errors || format('item "%s" has an invalid verify.category', v_key);
      end if;
      if coalesce(v_verify->>'op', '') = '' then
        v_errors := v_errors || format('item "%s" needs a verify.op', v_key);
      end if;
      v_match := coalesce(v_verify->>'match', '');
      if v_match not in ('exists', 'contains') then
        v_errors := v_errors || format('item "%s" has an invalid verify.match (must be exists or contains)', v_key);
      end if;
      if v_match = 'contains' and coalesce(v_verify->>'contains_text', '') = '' then
        v_errors := v_errors || format('item "%s" verify.match=contains needs contains_text', v_key);
      end if;
      if coalesce(v_verify->>'query_template', '') = '' and coalesce(v_verify->>'ref_template', '') = '' then
        v_errors := v_errors || format('item "%s" needs a verify.query_template or verify.ref_template', v_key);
      end if;
    end if;
  end loop;

  if not exists (
    select 1 from jsonb_array_elements(p_items) i where i->>'phase' = 'golive'
  ) then
    v_errors := v_errors || 'template needs at least one go-live phase item';
  end if;

  return v_errors;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_watcher_config(p_kind text, p_config jsonb, p_tenant_id uuid, p_de_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c    jsonb := coalesce(p_config, '{}'::jsonb);
  src  text  := coalesce(p_config->>'source', 'customer_accounts');
  s    watch_source_catalog;
  f    watch_source_fields;
  v_op text := coalesce(c->>'op', '');
  v_datef text;
  v_grant_ok boolean;
BEGIN
  IF p_kind IN ('date_horizon','state_condition') THEN
    SELECT * INTO s FROM watch_source_catalog WHERE source_key = src AND active;
    IF s.source_key IS NULL THEN
      RETURN format('There is no watchable source called "%s" here.', src);
    END IF;
    IF NOT (p_kind = ANY (s.supports_kinds)) THEN
      RETURN format('"%s" can''t be watched by %s.', src, replace(p_kind, '_', ' '));
    END IF;

    IF p_kind = 'date_horizon' THEN
      v_datef := coalesce(c->>'date_field',
                   (SELECT column_name FROM watch_source_fields
                     WHERE source_key = src AND role = 'date' ORDER BY column_name LIMIT 1));
      IF v_datef IS NULL OR NOT EXISTS (
           SELECT 1 FROM watch_source_fields
            WHERE source_key = src AND role = 'date' AND column_name = v_datef) THEN
        RETURN format('"%s" isn''t a date we can count down to on %s.',
                      coalesce(c->>'date_field', '(none)'), src);
      END IF;
      IF c ? 'horizons_days' AND jsonb_typeof(c->'horizons_days') <> 'array' THEN
        RETURN 'Reminder windows must be a list like [90, 60, 30].';
      END IF;

    ELSE  -- state_condition
      SELECT * INTO f FROM watch_source_fields
        WHERE source_key = src AND role = 'state' AND column_name = c->>'field';
      IF f.column_name IS NULL THEN
        RETURN format('"%s" isn''t a state we can watch on %s.',
                      coalesce(c->>'field', '(none)'), src);
      END IF;
      IF NOT (v_op = ANY (f.allowed_ops)) THEN
        RETURN format('"%s" can''t be compared with "%s".', f.column_name, v_op);
      END IF;
      IF c->>'value' IS NULL THEN RETURN 'This condition needs a value.'; END IF;
      IF f.value_type = 'numeric' AND (c->>'value') !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RETURN format('"%s" needs a number.', f.column_name);
      END IF;
    END IF;

    IF s.require_domain_grant THEN
      SELECT EXISTS (SELECT 1 FROM data_access_grants g
                      WHERE g.tenant_id = p_tenant_id AND g.subject_kind = 'de'
                        AND g.subject_id = p_de_id
                        AND g.resource_category = s.domain_category)
        INTO v_grant_ok;
      IF NOT v_grant_ok THEN
        RETURN format('This employee isn''t cleared to work %s.',
                      coalesce(s.domain_category, src));
      END IF;
    END IF;

  ELSIF p_kind = 'metric_threshold' THEN
    IF c->>'metric_key' IS NULL THEN RETURN 'A metric watcher needs a metric.'; END IF;
    IF NOT (v_op IN ('lt','gt'))  THEN RETURN 'A metric watcher uses above/below only.'; END IF;
    IF c->>'value' IS NULL        THEN RETURN 'A metric watcher needs a threshold.'; END IF;
  ELSIF p_kind = 'schedule' THEN
    IF coalesce((c->>'interval_minutes')::int, 0) < 60 THEN
      RETURN 'A recurring schedule must run at least hourly.';
    END IF;
  ELSE
    RETURN format('"%s" isn''t an installable watcher kind.', p_kind);
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.validate_work_watcher()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_err text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.config IS NOT DISTINCT FROM OLD.config
     AND NEW.kind   IS NOT DISTINCT FROM OLD.kind THEN
    RETURN NEW;  -- only active/next_fire_at/bookkeeping changed → no re-validation
  END IF;
  v_err := public.validate_watcher_config(NEW.kind, NEW.config, NEW.tenant_id, NEW.de_id);
  IF v_err IS NOT NULL THEN
    RAISE EXCEPTION '%', v_err;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.verify_and_bind_widget_identity(p_widget_key_id uuid, p_conversation_id uuid, p_end_user_ref text, p_account_ref text, p_user_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_tenant uuid; v_secret text; v_canon text; v_expected text; v_provided text;
  v_key text; v_account_id uuid; v_existing text; v_r bytea; v_ok boolean;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id AND active;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'unknown_widget_key');
  END IF;

  SELECT secret INTO v_secret FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id;
  IF v_secret IS NULL THEN
    -- No identity verification configured for this widget → legitimately
    -- unverified (expected, silent). Answers still flow; no identity memory.
    RETURN jsonb_build_object('verified', false, 'reason', 'no_secret');
  END IF;

  v_provided := lower(btrim(coalesce(p_user_hash, '')));
  IF v_provided = '' THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'no_hash');
  END IF;

  v_key := nullif(lower(btrim(coalesce(p_end_user_ref, ''))), '');
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'blank_ref');
  END IF;

  -- canonical(end_user_ref, account_ref) — account_ref BOUND into the signature
  v_canon := 'dtwidget.v1' || chr(10)
             || 'euid=' || b64url(p_end_user_ref) || chr(10)
             || 'acct=' || b64url(coalesce(p_account_ref, ''));
  v_expected := lower(encode(hmac(v_canon, v_secret, 'sha256'::text), 'hex'));

  -- constant-time compare via double-HMAC with a per-call random key: timing
  -- reveals nothing about v_expected because both sides are blinded by v_r.
  v_r := gen_random_bytes(32);
  v_ok := length(v_provided) = 64
          AND hmac(decode(v_provided, 'hex'), v_r, 'sha256'::text) = hmac(decode(v_expected, 'hex'), v_r, 'sha256'::text);
  IF NOT v_ok THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'mismatch');
  END IF;

  -- account_id resolved ONLY from the tenant allow-list, keyed on the verified ref
  SELECT account_id INTO v_account_id FROM customer_account_contacts
    WHERE tenant_id = v_tenant AND lower(btrim(end_user_ref)) = v_key;

  -- immutable bind: never rebind a conversation already carrying a DIFFERENT key
  SELECT verified_identity_key INTO v_existing FROM de_conversations
    WHERE id = p_conversation_id AND tenant_id = v_tenant;
  IF v_existing IS NOT NULL AND v_existing <> v_key THEN
    -- possible hijack (someone else's verified thread) → deny memory this turn
    RETURN jsonb_build_object('verified', false, 'reason', 'identity_conflict');
  END IF;
  IF v_existing IS NULL THEN
    UPDATE de_conversations
       SET identity_verified = true, verified_identity_key = v_key,
           identity_method = 'widget_hmac',
           account_id = COALESCE(account_id, v_account_id)
     WHERE id = p_conversation_id AND tenant_id = v_tenant;
  ELSIF v_account_id IS NOT NULL THEN
    -- same identity already bound; fill account_id if it wasn't set before
    UPDATE de_conversations SET account_id = COALESCE(account_id, v_account_id)
     WHERE id = p_conversation_id AND tenant_id = v_tenant;
  END IF;

  RETURN jsonb_build_object(
    'verified', true,
    'method', 'widget_hmac',
    'verified_key', v_key,
    'memory_ref', 'widget_hmac:' || v_key,   -- method-namespaced (no cross-method stitch)
    'account_id', v_account_id);
END $function$;

CREATE OR REPLACE FUNCTION public.verify_audit_chain(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  r          record;
  v_prev     text := '';
  v_expected text;
  v_checked  integer := 0;
  v_is_active boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() and tenant_id = p_tenant_id;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;

  for r in
    select * from audit_events
    where tenant_id = p_tenant_id
    order by created_at asc, id asc
  loop
    v_expected := encode(digest(
      v_prev || r.tenant_id::text || coalesce(r.action, '') ||
      coalesce(r.detail::text, '{}') || r.created_at::text,
      'sha256'), 'hex');
    if r.prev_hash <> v_prev or r.hash <> v_expected then
      return jsonb_build_object('intact', false, 'checked', v_checked, 'broken_at', r.id);
    end if;
    v_prev := r.hash;
    v_checked := v_checked + 1;
  end loop;

  return jsonb_build_object('intact', true, 'checked', v_checked, 'broken_at', null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_de_delegation_token(p_raw text, p_required_scope text, p_expected_de uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_row de_delegation_tokens;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'verify_de_delegation_token is service-role only';
  end if;
  update de_delegation_tokens
     set used_count = used_count + 1
   where token_hash = encode(digest(coalesce(p_raw, ''), 'sha256'), 'hex')
     and revoked_at is null
     and expires_at > now()
     and used_count < max_uses
     and p_required_scope = any(scopes)
     and (p_expected_de is null or de_id = p_expected_de)
   returning * into v_row;
  if v_row.id is null then return jsonb_build_object('valid', false); end if;
  return jsonb_build_object('valid', true, 'tenant_id', v_row.tenant_id, 'de_id', v_row.de_id,
                            'scopes', v_row.scopes, 'token_id', v_row.id,
                            'originating_kind', v_row.originating_kind, 'originating_ref', v_row.originating_ref);
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_de_system(p_de_id uuid, p_system_key text, p_entity_ref text, p_expectation jsonb, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_read jsonb; v_actual jsonb; v_matched boolean := true; v_diffs jsonb := '[]'::jsonb;
  k text; v_exp text; v_act text; v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  v_read := public.read_de_system(p_de_id, p_system_key, p_entity_ref);
  IF (v_read->>'ok') <> 'true' THEN RETURN v_read; END IF;
  v_actual := v_read->'record';

  FOR k IN SELECT jsonb_object_keys(p_expectation) LOOP
    v_exp := p_expectation->>k;
    v_act := v_actual->>k;
    IF v_exp IS DISTINCT FROM v_act THEN
      v_matched := false;
      v_diffs := v_diffs || jsonb_build_object('field', k, 'expected', v_exp, 'actual', v_act);
    END IF;
  END LOOP;

  INSERT INTO de_system_verifications (tenant_id, de_id, objective_id, system_key, entity_ref, expectation, actual, matched)
  VALUES (v_tenant, p_de_id, p_objective_id, p_system_key, p_entity_ref, p_expectation, v_actual, v_matched);

  RETURN jsonb_build_object('ok', true, 'matched', v_matched, 'diffs', v_diffs, 'actual', v_actual);
END; $function$;

CREATE OR REPLACE FUNCTION public.verify_embed_token(p_token text, p_tenant_id uuid, p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_token_hash TEXT;
BEGIN
  v_token_hash := encode(digest(p_token, 'sha256'), 'hex');

  -- Verify token exists, is valid, and matches tenant+DE
  PERFORM 1 FROM embed_tokens
  WHERE token_hash = v_token_hash
    AND tenant_id = p_tenant_id
    AND de_id = p_de_id
    AND expires_at > now();

  IF FOUND THEN
    -- Update used_at timestamp
    UPDATE embed_tokens
    SET used_at = now()
    WHERE token_hash = v_token_hash;

    RETURN json_build_object('valid', true);
  ELSE
    RETURN json_build_object('valid', false);
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.verify_extraction_result(p_id uuid, p_corrections jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null then
    if not exists (select 1 from extraction_results r join profiles p on p.user_id = auth.uid()
                    where r.id = p_id and (p.tenant_id = r.tenant_id or p.layer = 'platform')) then
      raise exception 'not authorized';
    end if;
  end if;
  update extraction_results
     set extracted = coalesce(p_corrections, extracted),
         verified = true, verified_by = auth.uid(), verified_at = now()
   where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_tenant_api_key(p_raw_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_key text;
  v_hash text;
  v_row tenant_api_keys;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'verify_tenant_api_key is service-role only';
  end if;

  v_key := p_raw_key;
  if v_key like 'dt_live_%' then
    v_key := substr(v_key, 9);
  end if;
  v_hash := encode(digest(v_key, 'sha256'), 'hex');

  select * into v_row from tenant_api_keys where key_hash = v_hash;
  if v_row.id is null or v_row.revoked_at is not null then
    return jsonb_build_object('valid', false);
  end if;

  update tenant_api_keys set last_used_at = now() where id = v_row.id;

  return jsonb_build_object('valid', true, 'tenant_id', v_row.tenant_id, 'scopes', v_row.scopes, 'key_id', v_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.visible_knowledge_docs(p_tenant_id uuid, p_subject_kind text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, title text, content text, tags text[], visibility text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_archetype text;
begin
  perform public._assert_caller_tenant(p_tenant_id);
  v_archetype := case when p_subject_kind = 'de' and p_subject_id is not null then resolve_de_archetype(p_subject_id) end;
  return query
  select d.id, d.title, d.content, d.tags, d.visibility
  from knowledge_docs d
  where d.tenant_id = p_tenant_id
    and d.is_current and d.lifecycle_status = 'published'
    and (
      d.visibility = 'tenant'
      or (p_subject_kind is not null and p_subject_id is not null and exists (
            select 1 from knowledge_doc_scopes s
            where s.doc_id = d.id
              and ((s.subject_kind = p_subject_kind and s.subject_id = p_subject_id)
                or (p_subject_kind = 'de' and s.subject_kind = 'de_team'
                    and exists (select 1 from workforce_team_members m
                                 where m.team_id = s.subject_id and m.de_id = p_subject_id)))))
      or (d.visibility = 'role' and v_archetype is not null and d.share_archetype_key = v_archetype)
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.watcher_label(cols text[], row_j jsonb, kind text, id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE c text; BEGIN
  FOREACH c IN ARRAY cols LOOP
    IF nullif(row_j->>c,'') IS NOT NULL THEN RETURN row_j->>c; END IF;
  END LOOP;
  RETURN replace(initcap(replace(kind,'_',' ')),' ','') || ' ' || left(id,8);
END $function$;

CREATE OR REPLACE FUNCTION public.widget_identity_configured(p_widget_key_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_has boolean; v_rot timestamptz;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'widget_key_not_found'); END IF;
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT (v_tenant = public.auth_tenant_id()
              AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin','tenant_manager'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  SELECT EXISTS (SELECT 1 FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id),
         (SELECT rotated_at FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id)
    INTO v_has, v_rot;
  RETURN jsonb_build_object('ok', true, 'configured', coalesce(v_has, false), 'rotated_at', v_rot);
END $function$;


