  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "resource_type" text NOT NULL,
  "resource_id" uuid,
  "principal_type" text NOT NULL,
  "principal_user_id" uuid,
  "principal_group_id" uuid,
  "principal_role" text,
  "permission" text NOT NULL,
  "granted_by" uuid,
  "note" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT knowledge_access_grants_permission_check CHECK ((permission = ANY (ARRAY['viewer'::text, 'contributor'::text, 'editor'::text, 'publisher'::text, 'knowledge_manager'::text, 'workspace_admin'::text]))),
  CONSTRAINT knowledge_access_grants_principal_type_check CHECK ((principal_type = ANY (ARRAY['everyone'::text, 'role'::text, 'group'::text, 'user'::text, 'guest'::text]))),
  CONSTRAINT knowledge_access_grants_resource_type_check CHECK ((resource_type = ANY (ARRAY['workspace'::text, 'collection'::text, 'document'::text]))),
  CONSTRAINT knowledge_grants_principal_shape CHECK ((((principal_type = 'everyone'::text) AND (principal_user_id IS NULL) AND (principal_group_id IS NULL) AND (principal_role IS NULL)) OR ((principal_type = ANY (ARRAY['user'::text, 'guest'::text])) AND (principal_user_id IS NOT NULL) AND (principal_group_id IS NULL) AND (principal_role IS NULL)) OR ((principal_type = 'group'::text) AND (principal_group_id IS NOT NULL) AND (principal_user_id IS NULL) AND (principal_role IS NULL)) OR ((principal_type = 'role'::text) AND (principal_role IS NOT NULL) AND (principal_user_id IS NULL) AND (principal_group_id IS NULL)))),
  CONSTRAINT knowledge_grants_resource_shape CHECK ((((resource_type = 'workspace'::text) AND (resource_id IS NULL)) OR ((resource_type <> 'workspace'::text) AND (resource_id IS NOT NULL)))),
  CONSTRAINT knowledge_access_grants_pkey PRIMARY KEY (id)
);
