  CONSTRAINT workforce_baselines_avg_fte_cost_monthly_usd_check CHECK (((avg_fte_cost_monthly_usd IS NULL) OR (avg_fte_cost_monthly_usd > (0)::numeric))),
  CONSTRAINT workforce_baselines_conversation_minutes_check CHECK (((conversation_minutes IS NULL) OR (conversation_minutes > (0)::numeric))),
  CONSTRAINT workforce_baselines_inquiry_minutes_check CHECK (((inquiry_minutes IS NULL) OR (inquiry_minutes > (0)::numeric))),
  CONSTRAINT workforce_baselines_pkey PRIMARY KEY (tenant_id)
);
CREATE TABLE IF NOT EXISTS public.workforce_entity_amendments (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "entity_kind" text NOT NULL,
  "entity_id" uuid NOT NULL,
  "trigger_reason" text NOT NULL,
  "current_config" jsonb NOT NULL,
  "proposed_config" jsonb NOT NULL,
  "rationale" text DEFAULT ''::text NOT NULL,
  "redline" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "replay_result" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "status" text DEFAULT 'review_pending'::text NOT NULL,
  "model_id" text,
  "input_tokens" integer DEFAULT 0 NOT NULL,
  "output_tokens" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT workforce_entity_amendments_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['de'::text, 'specialist'::text]))),
  CONSTRAINT workforce_entity_amendments_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review_pending'::text, 'approved'::text, 'rejected'::text, 'applied'::text]))),
  CONSTRAINT workforce_entity_amendments_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.workforce_entity_studies (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "entity_kind" text NOT NULL,
  "entity_id" uuid NOT NULL,
  "brief_text" text NOT NULL,
  "report" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "model_id" text,
  "input_tokens" integer DEFAULT 0 NOT NULL,
  "output_tokens" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT workforce_entity_studies_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['de'::text, 'specialist'::text]))),
  CONSTRAINT workforce_entity_studies_pkey PRIMARY KEY (id),
  CONSTRAINT workforce_entity_studies_entity_kind_entity_id_key UNIQUE (entity_kind, entity_id)
);
CREATE TABLE IF NOT EXISTS public.workforce_teams (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "name" text NOT NULL,
  "purpose" text DEFAULT ''::text NOT NULL,
  "status" text DEFAULT 'active'::text NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT workforce_teams_status_check CHECK ((status = ANY (ARRAY['active'::text, 'archived'::text]))),
  CONSTRAINT workforce_teams_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.workforce_team_members (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "team_id" uuid NOT NULL,
  "de_id" uuid NOT NULL,
  "fallback_rank" integer NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT workforce_team_members_fallback_rank_check CHECK ((fallback_rank >= 1)),
  CONSTRAINT workforce_team_members_pkey PRIMARY KEY (id),
  CONSTRAINT workforce_team_members_team_id_de_id_key UNIQUE (team_id, de_id),
  CONSTRAINT workforce_team_members_team_id_fallback_rank_key UNIQUE (team_id, fallback_rank)
);
CREATE TABLE IF NOT EXISTS public.workspaces (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "name" text NOT NULL,
  "slug" text NOT NULL,
  "description" text DEFAULT ''::text NOT NULL,
  "icon" text DEFAULT '⊞'::text NOT NULL,
  "color" text DEFAULT '#6366f1'::text NOT NULL,
  "status" text DEFAULT 'active'::text NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT workspaces_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text]))),
  CONSTRAINT workspaces_pkey PRIMARY KEY (id),
  CONSTRAINT workspaces_tenant_id_slug_key UNIQUE (tenant_id, slug)
);

